async fn start_email_auth(
    State(state): State<AppState>,
    Json(request): Json<StartEmailAuthRequest>,
) -> std::result::Result<(StatusCode, Json<StartEmailAuthResponse>), ApiError> {
    let email = validate_auth_email(&request.email)?;
    let service = email_otp_service()?;
    let now = Utc::now();
    if let Some(existing) =
        reusable_email_challenge(&state, &email, request.purpose.clone(), now).await?
    {
        record_auth_audit_event(
            &state,
            AUTH_AUDIT_EMAIL_START,
            AuthAuditOutcome::Succeeded,
            None,
            None,
            Some(existing.email_normalized.clone()),
            request.device_fingerprint.clone(),
            json!({
                "purpose": existing.purpose.as_str(),
                "challenge_id": existing.id.to_string(),
                "reused": true
            }),
        )
        .await;
        return Ok((
            StatusCode::OK,
            Json(StartEmailAuthResponse {
                challenge_id: existing.id,
                email: existing.email_normalized,
                purpose: existing.purpose,
                expires_at: existing.expires_at,
                resend_after_seconds: resend_after_seconds(existing.created_at, now),
            }),
        ));
    }
    enforce_email_challenge_rate_limit(
        &state,
        &email,
        request.purpose.clone(),
        request.device_fingerprint.clone(),
        now,
        AUTH_AUDIT_EMAIL_START,
    )
    .await?;
    let mut prepared = service.prepare_challenge(&email, request.purpose.clone(), now);
    prepared.challenge.metadata = auth_challenge_metadata(request.device_fingerprint.as_deref());
    send_verification_email(&prepared.email).map_err(|error| {
        tracing::error!(%error, "verification code email send failed");
        ApiError::internal(
            "email_send_failed",
            "验证码发送失败，请稍后再试".to_string(),
        )
    })?;
    let challenge = state
        .storage
        .email_verification_challenges()
        .create(state.tenant_id, prepared.challenge)
        .await
        .map_err(ApiError::from_storage)?;
    record_auth_audit_event(
        &state,
        AUTH_AUDIT_EMAIL_START,
        AuthAuditOutcome::Succeeded,
        None,
        None,
        Some(challenge.email_normalized.clone()),
        request.device_fingerprint,
        json!({
            "purpose": challenge.purpose.as_str(),
            "challenge_id": challenge.id.to_string(),
            "reused": false
        }),
    )
    .await;

    Ok((
        StatusCode::CREATED,
        Json(StartEmailAuthResponse {
            challenge_id: challenge.id,
            email: challenge.email_normalized,
            purpose: challenge.purpose,
            expires_at: challenge.expires_at,
            resend_after_seconds: Some(60),
        }),
    ))
}

async fn verify_email_auth(
    State(state): State<AppState>,
    Json(request): Json<VerifyEmailAuthRequest>,
) -> std::result::Result<(StatusCode, HeaderMap, Json<VerifyEmailAuthResponse>), ApiError> {
    let email = validate_auth_email(&request.email)?;
    validate_required("code", &request.code)?;
    let now = Utc::now();
    let device_fingerprint = request.device_fingerprint.clone();
    if !email_auth_verify_creates_session_for_purpose(&request.purpose) {
        record_auth_audit_event(
            &state,
            AUTH_AUDIT_EMAIL_VERIFY,
            AuthAuditOutcome::Failed,
            None,
            None,
            Some(email),
            device_fingerprint,
            json!({
                "purpose": request.purpose.as_str(),
                "reason": "verification_purpose_not_login_capable"
            }),
        )
        .await;
        return Err(ApiError::bad_request(
            "verification_purpose_not_login_capable",
            "该验证码用途不能用于登录，请重新获取登录验证码".to_string(),
        ));
    }
    let Some(challenge) = state
        .storage
        .email_verification_challenges()
        .latest_active_by_email_and_purpose(state.tenant_id, &email, request.purpose.clone())
        .await
        .map_err(ApiError::from_storage)?
    else {
        record_auth_audit_event(
            &state,
            AUTH_AUDIT_EMAIL_VERIFY,
            AuthAuditOutcome::Failed,
            None,
            None,
            Some(email),
            device_fingerprint,
            json!({
                "purpose": request.purpose.as_str(),
                "reason": "verification_challenge_not_found"
            }),
        )
        .await;
        return Err(ApiError::bad_request(
            "verification_challenge_not_found",
            "没有找到可用验证码，请重新获取".to_string(),
        ));
    };
    match email_otp_service()?.verify_challenge(&challenge, &request.code, now) {
        OtpVerificationStatus::Valid => {
            state
                .storage
                .email_verification_challenges()
                .mark_consumed(state.tenant_id, challenge.id, now)
                .await
                .map_err(ApiError::from_storage)?;
        }
        OtpVerificationStatus::Invalid => {
            state
                .storage
                .email_verification_challenges()
                .increment_attempt_count(state.tenant_id, challenge.id)
                .await
                .map_err(ApiError::from_storage)?;
            record_auth_audit_event(
                &state,
                AUTH_AUDIT_EMAIL_VERIFY,
                AuthAuditOutcome::Failed,
                None,
                None,
                Some(email),
                device_fingerprint,
                json!({
                    "purpose": request.purpose.as_str(),
                    "challenge_id": challenge.id.to_string(),
                    "reason": "verification_code_invalid",
                    "attempt_count_before": challenge.attempt_count
                }),
            )
            .await;
            return Err(ApiError::bad_request(
                "verification_code_invalid",
                "验证码不正确".to_string(),
            ));
        }
        OtpVerificationStatus::Expired => {
            record_auth_audit_event(
                &state,
                AUTH_AUDIT_EMAIL_VERIFY,
                AuthAuditOutcome::Failed,
                None,
                None,
                Some(email),
                device_fingerprint,
                json!({
                    "purpose": request.purpose.as_str(),
                    "challenge_id": challenge.id.to_string(),
                    "reason": "verification_code_expired"
                }),
            )
            .await;
            return Err(ApiError::bad_request(
                "verification_code_expired",
                "验证码已过期，请重新获取".to_string(),
            ));
        }
        OtpVerificationStatus::Consumed => {
            record_auth_audit_event(
                &state,
                AUTH_AUDIT_EMAIL_VERIFY,
                AuthAuditOutcome::Failed,
                None,
                None,
                Some(email),
                device_fingerprint,
                json!({
                    "purpose": request.purpose.as_str(),
                    "challenge_id": challenge.id.to_string(),
                    "reason": "verification_code_consumed"
                }),
            )
            .await;
            return Err(ApiError::bad_request(
                "verification_code_consumed",
                "验证码已使用，请重新获取".to_string(),
            ));
        }
        OtpVerificationStatus::AttemptsExceeded => {
            record_auth_audit_event(
                &state,
                AUTH_AUDIT_EMAIL_VERIFY,
                AuthAuditOutcome::Failed,
                None,
                None,
                Some(email),
                device_fingerprint,
                json!({
                    "purpose": request.purpose.as_str(),
                    "challenge_id": challenge.id.to_string(),
                    "reason": "verification_code_attempts_exceeded",
                    "attempt_count_before": challenge.attempt_count
                }),
            )
            .await;
            return Err(ApiError::bad_request(
                "verification_code_attempts_exceeded",
                "验证码尝试次数过多，请重新获取".to_string(),
            ));
        }
    }

    let user = state
        .storage
        .users()
        .ensure_by_email(state.tenant_id, &email, Some(&email))
        .await
        .map_err(ApiError::from_storage)?;
    let (session, session_token) = create_auth_session(
        &state,
        &user,
        AuthSessionMethod::EmailCode,
        request.device_fingerprint,
    )
    .await?;
    record_auth_audit_event(
        &state,
        AUTH_AUDIT_EMAIL_VERIFY,
        AuthAuditOutcome::Succeeded,
        Some(user.id),
        Some(session.id),
        Some(user.email.clone()),
        Some(session.device_fingerprint.clone()),
        json!({
            "purpose": request.purpose.as_str(),
            "challenge_id": challenge.id.to_string(),
            "auth_method": session.auth_method.as_str()
        }),
    )
    .await;

    Ok((
        StatusCode::CREATED,
        set_session_cookie_headers(&session_token)?,
        Json(VerifyEmailAuthResponse {
            user: to_auth_user_view(&user, true),
            session: to_auth_session_view(&session, &user.email),
            active_secret_binding_ids: Vec::new(),
        }),
    ))
}

async fn login_with_local_key(
    State(state): State<AppState>,
    Json(request): Json<KeyLoginRequest>,
) -> std::result::Result<(StatusCode, HeaderMap, Json<KeyLoginResponse>), ApiError> {
    let email = validate_auth_email(&request.email)?;
    validate_required("local_key", &request.local_key)?;
    let fingerprint = local_key_fingerprint(&request.local_key);
    let device_fingerprint = request.device_fingerprint.clone();
    let bindings = state
        .storage
        .secret_bindings()
        .list_by_fingerprint(state.tenant_id, &fingerprint)
        .await
        .map_err(ApiError::from_storage)?;
    if bindings.is_empty() {
        record_auth_audit_event(
            &state,
            AUTH_AUDIT_KEY_LOGIN,
            AuthAuditOutcome::Failed,
            None,
            None,
            Some(email),
            device_fingerprint,
            json!({
                "reason": "invalid_local_key",
                "matched_binding_count": 0
            }),
        )
        .await;
        return Err(ApiError::unauthorized(
            "invalid_local_key",
            "邮箱或密钥不匹配".to_string(),
        ));
    }
    let matched_binding_count = bindings.len();
    let active_secret_binding_ids = bindings
        .iter()
        .map(|binding| binding.id)
        .collect::<Vec<_>>();
    let user = state
        .storage
        .users()
        .ensure_by_email(state.tenant_id, &email, Some(&email))
        .await
        .map_err(ApiError::from_storage)?;
    let user = state
        .storage
        .users()
        .update_primary_secret_fingerprint(state.tenant_id, user.id, &fingerprint, Utc::now())
        .await
        .map_err(ApiError::from_storage)?
        .unwrap_or(user);
    let (session, session_token) = create_auth_session(
        &state,
        &user,
        AuthSessionMethod::EmailKey,
        request.device_fingerprint,
    )
    .await?;
    record_auth_audit_event(
        &state,
        AUTH_AUDIT_KEY_LOGIN,
        AuthAuditOutcome::Succeeded,
        Some(user.id),
        Some(session.id),
        Some(user.email.clone()),
        Some(session.device_fingerprint.clone()),
        json!({
            "auth_method": session.auth_method.as_str(),
            "matched_binding_count": matched_binding_count
        }),
    )
    .await;

    Ok((
        StatusCode::CREATED,
        set_session_cookie_headers(&session_token)?,
        Json(KeyLoginResponse {
            user: to_auth_user_view(&user, true),
            session: to_auth_session_view(&session, &user.email),
            active_secret_binding_ids,
        }),
    ))
}

async fn get_auth_session(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> std::result::Result<Json<AuthSessionResponse>, ApiError> {
    let Some((user, session)) = current_auth_session(&state, &headers).await? else {
        return Ok(Json(AuthSessionResponse {
            user: None,
            session: None,
        }));
    };

    Ok(Json(AuthSessionResponse {
        user: Some(to_auth_user_view(&user, true)),
        session: Some(to_auth_session_view(&session, &user.email)),
    }))
}

async fn list_auth_audit_events(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<AuthAuditEventsQuery>,
) -> std::result::Result<Json<Vec<AuthAuditEventView>>, ApiError> {
    let Some((user, session)) = current_auth_session(&state, &headers).await? else {
        return Err(ApiError::unauthorized(
            "auth_session_required",
            "请先登录账号后再查看安全记录".to_string(),
        ));
    };
    let limit = query
        .limit
        .unwrap_or(AUTH_AUDIT_EVENTS_DEFAULT_LIMIT)
        .clamp(1, AUTH_AUDIT_EVENTS_MAX_LIMIT);
    let events = state
        .storage
        .auth_audit_events()
        .list_recent_for_user(state.tenant_id, user.id, limit)
        .await
        .map_err(ApiError::from_storage)?;

    Ok(Json(
        events
            .into_iter()
            .map(|event| to_auth_audit_event_view(event, session.id))
            .collect(),
    ))
}

async fn logout_auth_session(
    State(state): State<AppState>,
    headers: HeaderMap,
) -> std::result::Result<(HeaderMap, Json<LogoutResponse>), ApiError> {
    let mut revoked = false;
    if let Some(session_token) = auth_session_token_from_headers(&headers) {
        if let Some(session) = state
            .storage
            .user_sessions()
            .get_by_token_hash(state.tenant_id, &auth_session_token_hash(&session_token))
            .await
            .map_err(ApiError::from_storage)?
        {
            state
                .storage
                .user_sessions()
                .revoke(state.tenant_id, session.id, Utc::now())
                .await
                .map_err(ApiError::from_storage)?;
            record_auth_audit_event(
                &state,
                AUTH_AUDIT_LOGOUT,
                AuthAuditOutcome::Succeeded,
                Some(session.user_id),
                Some(session.id),
                None,
                Some(session.device_fingerprint),
                json!({ "revoked": true }),
            )
            .await;
            revoked = true;
        }
    }

    Ok((
        clear_session_cookie_headers()?,
        Json(LogoutResponse { revoked }),
    ))
}

async fn rotate_local_key(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(request): Json<KeyRotateRequest>,
) -> std::result::Result<Json<KeyRotateResponse>, ApiError> {
    validate_required("new_local_key", &request.new_local_key)?;
    let Some((user, session)) = current_auth_session(&state, &headers).await? else {
        return Err(ApiError::unauthorized(
            "auth_session_required",
            "请先登录后再更换密钥".to_string(),
        ));
    };
    let fingerprint = local_key_fingerprint(&request.new_local_key);
    let user = state
        .storage
        .users()
        .update_primary_secret_fingerprint(state.tenant_id, user.id, &fingerprint, Utc::now())
        .await
        .map_err(ApiError::from_storage)?
        .unwrap_or(user);
    let active_secret_binding_ids = state
        .storage
        .secret_bindings()
        .list_by_fingerprint(state.tenant_id, &fingerprint)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .map(|binding| binding.id)
        .collect::<Vec<_>>();
    record_auth_audit_event(
        &state,
        AUTH_AUDIT_KEY_ROTATE,
        AuthAuditOutcome::Succeeded,
        Some(user.id),
        Some(session.id),
        Some(user.email.clone()),
        request
            .device_fingerprint
            .or_else(|| Some(session.device_fingerprint.clone())),
        json!({
            "matched_binding_count": active_secret_binding_ids.len()
        }),
    )
    .await;

    Ok(Json(KeyRotateResponse {
        user: to_auth_user_view(&user, true),
        primary_secret_fingerprint: fingerprint,
        active_secret_binding_ids,
    }))
}

async fn bind_auth_email(
    State(state): State<AppState>,
    Json(request): Json<BindEmailRequest>,
) -> std::result::Result<(StatusCode, Json<BindEmailResponse>), ApiError> {
    let email = validate_auth_email(&request.email)?;
    let now = Utc::now();
    if let Some(existing) =
        reusable_email_challenge(&state, &email, AuthChallengePurpose::BindEmail, now).await?
    {
        record_auth_audit_event(
            &state,
            AUTH_AUDIT_EMAIL_BIND_START,
            AuthAuditOutcome::Succeeded,
            None,
            None,
            Some(existing.email_normalized.clone()),
            request.device_fingerprint.clone(),
            json!({
                "challenge_id": existing.id.to_string(),
                "reused": true
            }),
        )
        .await;
        return Ok((
            StatusCode::OK,
            Json(BindEmailResponse {
                challenge_id: existing.id,
                email: existing.email_normalized,
                expires_at: existing.expires_at,
            }),
        ));
    }
    enforce_email_challenge_rate_limit(
        &state,
        &email,
        AuthChallengePurpose::BindEmail,
        request.device_fingerprint.clone(),
        now,
        AUTH_AUDIT_EMAIL_BIND_START,
    )
    .await?;
    let mut prepared =
        email_otp_service()?.prepare_challenge(&email, AuthChallengePurpose::BindEmail, now);
    prepared.challenge.metadata = auth_challenge_metadata(request.device_fingerprint.as_deref());
    send_verification_email(&prepared.email).map_err(|error| {
        tracing::error!(%error, "bind-email verification email send failed");
        ApiError::internal(
            "email_send_failed",
            "验证码发送失败，请稍后再试".to_string(),
        )
    })?;
    let challenge = state
        .storage
        .email_verification_challenges()
        .create(state.tenant_id, prepared.challenge)
        .await
        .map_err(ApiError::from_storage)?;
    record_auth_audit_event(
        &state,
        AUTH_AUDIT_EMAIL_BIND_START,
        AuthAuditOutcome::Succeeded,
        None,
        None,
        Some(challenge.email_normalized.clone()),
        request.device_fingerprint,
        json!({
            "challenge_id": challenge.id.to_string(),
            "reused": false
        }),
    )
    .await;

    Ok((
        StatusCode::CREATED,
        Json(BindEmailResponse {
            challenge_id: challenge.id,
            email: challenge.email_normalized,
            expires_at: challenge.expires_at,
        }),
    ))
}

async fn claim_local_data(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(request): Json<ClaimLocalDataRequest>,
) -> std::result::Result<Json<ClaimLocalDataResponse>, ApiError> {
    validate_required("fingerprint", &request.fingerprint)?;
    let Some((user, session)) = current_auth_session(&state, &headers).await? else {
        return Err(ApiError::unauthorized(
            "auth_session_required",
            "请先登录账号后再认领本地密钥数据".to_string(),
        ));
    };
    let fingerprint = request.fingerprint.trim();
    let bindings = state
        .storage
        .secret_bindings()
        .list_by_fingerprint(state.tenant_id, fingerprint)
        .await
        .map_err(ApiError::from_storage)?;
    let active_secret_binding_ids = bindings
        .iter()
        .map(|binding| binding.id)
        .collect::<Vec<_>>();
    let mut claimed_datasets = Vec::new();
    let mut skipped_owned_dataset_count = 0usize;
    let mut seen_dataset_ids = HashSet::new();

    for binding in bindings {
        if !seen_dataset_ids.insert(binding.dataset_id) {
            continue;
        }
        let Some(dataset) = state
            .storage
            .datasets()
            .get_by_id(state.tenant_id, binding.dataset_id)
            .await
            .map_err(ApiError::from_storage)?
        else {
            continue;
        };
        match dataset.owner_user_id {
            None => {
                if let Some(updated) = state
                    .storage
                    .datasets()
                    .update_owner_user_id(state.tenant_id, dataset.id, user.id)
                    .await
                    .map_err(ApiError::from_storage)?
                {
                    claimed_datasets.push(dataset_summary(updated, None));
                }
            }
            Some(owner_user_id) if owner_user_id == user.id => {
                claimed_datasets.push(dataset_summary(dataset, None));
            }
            Some(_) => {
                skipped_owned_dataset_count += 1;
            }
        }
    }
    if !active_secret_binding_ids.is_empty() {
        state
            .storage
            .users()
            .update_primary_secret_fingerprint(state.tenant_id, user.id, fingerprint, Utc::now())
            .await
            .map_err(ApiError::from_storage)?;
    }
    record_auth_audit_event(
        &state,
        AUTH_AUDIT_LOCAL_DATA_CLAIM,
        AuthAuditOutcome::Succeeded,
        Some(user.id),
        Some(session.id),
        Some(user.email.clone()),
        Some(session.device_fingerprint),
        json!({
            "matched_binding_count": active_secret_binding_ids.len(),
            "claimed_dataset_count": claimed_datasets.len(),
            "skipped_owned_dataset_count": skipped_owned_dataset_count
        }),
    )
    .await;

    Ok(Json(ClaimLocalDataResponse {
        user: to_auth_user_view(&user, true),
        claimed_datasets,
        active_secret_binding_ids,
        skipped_owned_dataset_count,
    }))
}

async fn record_auth_audit_event(
    state: &AppState,
    event_name: &'static str,
    outcome: AuthAuditOutcome,
    user_id: Option<UserId>,
    session_id: Option<UserSessionId>,
    email_normalized: Option<String>,
    device_fingerprint: Option<String>,
    metadata: Value,
) {
    if let Err(error) = state
        .storage
        .auth_audit_events()
        .create(
            state.tenant_id,
            NewAuthAuditEvent {
                user_id,
                session_id,
                email_normalized,
                event_name: event_name.to_string(),
                outcome,
                ip_hash: None,
                device_fingerprint: trim_optional(device_fingerprint),
                metadata,
                created_at: Utc::now(),
            },
        )
        .await
    {
        tracing::warn!(%error, %event_name, "auth audit event persistence failed");
    }
}

fn email_otp_service() -> std::result::Result<EmailOtpService, ApiError> {
    EmailOtpService::new(auth_env(
        "AUTH_EMAIL_OTP_PEPPER",
        DEFAULT_AUTH_EMAIL_OTP_PEPPER,
    ))
    .map_err(|error| ApiError::internal("auth_config_invalid", error.to_string()))
}

async fn reusable_email_challenge(
    state: &AppState,
    email_normalized: &str,
    purpose: AuthChallengePurpose,
    now: DateTime<Utc>,
) -> std::result::Result<Option<EmailVerificationChallenge>, ApiError> {
    let challenge = state
        .storage
        .email_verification_challenges()
        .latest_active_by_email_and_purpose(state.tenant_id, email_normalized, purpose)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(challenge.filter(|challenge| {
        challenge.expires_at > now
            && (challenge.created_at + Duration::seconds(AUTH_EMAIL_RESEND_AFTER_SECONDS)) > now
    }))
}

async fn enforce_email_challenge_rate_limit(
    state: &AppState,
    email_normalized: &str,
    purpose: AuthChallengePurpose,
    device_fingerprint: Option<String>,
    now: DateTime<Utc>,
    audit_event_name: &'static str,
) -> std::result::Result<(), ApiError> {
    let since = now - Duration::minutes(AUTH_EMAIL_RATE_LIMIT_WINDOW_MINUTES);
    let email_count = state
        .storage
        .email_verification_challenges()
        .count_created_since_by_email_and_purpose(
            state.tenant_id,
            email_normalized,
            purpose.clone(),
            since,
        )
        .await
        .map_err(ApiError::from_storage)?;
    if email_count >= AUTH_EMAIL_RATE_LIMIT_MAX_PER_EMAIL {
        record_auth_audit_event(
            state,
            audit_event_name,
            AuthAuditOutcome::Failed,
            None,
            None,
            Some(email_normalized.to_string()),
            device_fingerprint,
            json!({
                "purpose": purpose.as_str(),
                "reason": "email_challenge_rate_limited",
                "window_minutes": AUTH_EMAIL_RATE_LIMIT_WINDOW_MINUTES,
                "observed_count": email_count,
                "limit": AUTH_EMAIL_RATE_LIMIT_MAX_PER_EMAIL
            }),
        )
        .await;
        return Err(ApiError::too_many_requests(
            "email_challenge_rate_limited",
            "验证码请求过于频繁，请稍后再试".to_string(),
        ));
    }

    if let Some(device) = trim_optional(device_fingerprint.clone()) {
        let device_count = state
            .storage
            .email_verification_challenges()
            .count_created_since_by_device_and_purpose(
                state.tenant_id,
                &device,
                purpose.clone(),
                since,
            )
            .await
            .map_err(ApiError::from_storage)?;
        if device_count >= AUTH_EMAIL_RATE_LIMIT_MAX_PER_DEVICE {
            record_auth_audit_event(
                state,
                audit_event_name,
                AuthAuditOutcome::Failed,
                None,
                None,
                Some(email_normalized.to_string()),
                Some(device),
                json!({
                    "purpose": purpose.as_str(),
                    "reason": "device_challenge_rate_limited",
                    "window_minutes": AUTH_EMAIL_RATE_LIMIT_WINDOW_MINUTES,
                    "observed_count": device_count,
                    "limit": AUTH_EMAIL_RATE_LIMIT_MAX_PER_DEVICE
                }),
            )
            .await;
            return Err(ApiError::too_many_requests(
                "email_challenge_rate_limited",
                "验证码请求过于频繁，请稍后再试".to_string(),
            ));
        }
    }

    Ok(())
}

async fn create_auth_session(
    state: &AppState,
    user: &User,
    auth_method: AuthSessionMethod,
    device_fingerprint: Option<String>,
) -> std::result::Result<(UserSession, String), ApiError> {
    let now = Utc::now();
    let session_token = new_auth_session_token();
    let session = state
        .storage
        .user_sessions()
        .create(
            state.tenant_id,
            NewUserSession {
                user_id: user.id,
                device_fingerprint: normalize_device_fingerprint(device_fingerprint),
                session_token_hash: auth_session_token_hash(&session_token),
                auth_method,
                expires_at: now + Duration::days(AUTH_SESSION_TTL_DAYS),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    Ok((session, session_token))
}

pub(crate) async fn current_auth_session(
    state: &AppState,
    headers: &HeaderMap,
) -> std::result::Result<Option<(User, UserSession)>, ApiError> {
    let Some(session_token) = auth_session_token_from_headers(headers) else {
        return Ok(None);
    };
    let Some(session) = state
        .storage
        .user_sessions()
        .get_by_token_hash(state.tenant_id, &auth_session_token_hash(&session_token))
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(None);
    };
    let now = Utc::now();
    if session.revoked_at.is_some() || session.expires_at <= now {
        return Ok(None);
    }
    let Some(user) = state
        .storage
        .users()
        .get_by_id(state.tenant_id, session.user_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(None);
    };
    Ok(Some((user, session)))
}

async fn current_auth_user_id(
    state: &AppState,
    headers: &HeaderMap,
) -> std::result::Result<Option<UserId>, ApiError> {
    Ok(current_auth_session(state, headers)
        .await?
        .map(|(user, _session)| user.id))
}

