async fn search_dataset_retrieval_with_state(
    state: &AppState,
    dataset_id: DatasetId,
    query: &str,
    limit: Option<usize>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
) -> std::result::Result<RetrievalSearchResponse, ApiError> {
    validate_required("query", query)?;

    load_visible_dataset_for_user(
        state,
        dataset_id,
        active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    let limit = normalize_retrieval_search_limit(limit);
    let evidences = match retrieval_search_backend() {
        RetrievalSearchBackend::PostgresLexical => state
            .storage
            .retrieval_evidences()
            .search_lexical_retrieval_evidences(LexicalRetrievalQuery {
                tenant_id: state.tenant_id,
                dataset_id,
                query: query.to_string(),
                document_ids: Vec::new(),
                owner_user_id: current_user_id,
                limit,
                candidate_limit: retrieval_search_candidate_limit(limit),
            })
            .await
            .map_err(ApiError::from_storage)?,
        RetrievalSearchBackend::LegacyScan => state
            .storage
            .retrieval_evidences()
            .list_latest_by_dataset_scope(
                state.tenant_id,
                dataset_id,
                retrieval_search_scan_limit(limit),
            )
            .await
            .map_err(ApiError::from_storage)?,
    };
    let evidences = filter_retrieval_evidences_for_visible_documents(
        state,
        dataset_id,
        evidences,
        current_user_id,
    )
    .await?;

    Ok(RetrievalSearchResponse {
        hits: search_retrieval_hits(&evidences, query, limit),
    })
}

