async fn create_chat_session(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(dataset_id): Path<String>,
    Json(request): Json<CreateChatSessionRequest>,
) -> std::result::Result<(StatusCode, Json<CreateChatSessionResponse>), ApiError> {
    let dataset_id = parse_dataset_id(&dataset_id)?;
    validate_required("prompt", &request.prompt)?;

    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let dataset = load_visible_dataset_for_user(
        &state,
        dataset_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    let local_thread_id = trim_optional(request.local_thread_id.clone());
    let latest_memory_directory =
        latest_visible_memory_directory_for_user(&state, dataset.id, current_user_id).await?;
    let latest_dataset_output = state
        .storage
        .dataset_outputs()
        .list_by_dataset(state.tenant_id, dataset.id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .filter(|entry| owner_user_id_is_visible(entry.owner_user_id, current_user_id))
        .next();
    let chat_session_id = ChatSessionId::new();
    let execution = build_initial_chat_session_execution(
        &state,
        dataset.id,
        chat_session_id,
        &request.prompt,
        current_user_id,
        latest_memory_directory.as_ref(),
        latest_dataset_output.as_ref().map(|entry| entry.id),
    )?;
    let initial_event =
        build_initial_chat_session_event(&execution, chat_session_id, &request.prompt);
    let chat_turn_id = execution
        .context
        .get("chat_turn_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            ApiError::internal(
                "chat_turn_id_missing",
                "chat session execution context missing chat_turn_id".to_string(),
            )
        })?
        .to_string();

    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;

    let session = state
        .storage
        .chat_sessions()
        .create(
            state.tenant_id,
            &NewChatSession {
                id: chat_session_id,
                execution_id: execution.id,
                dataset_id: dataset.id,
                user_id: current_user_id,
                title: trim_optional(request.title.clone())
                    .unwrap_or_else(|| derive_chat_session_title(&request.prompt)),
                latest_memory_directory_id: latest_memory_directory.as_ref().map(|entry| entry.id),
                latest_dataset_output_id: latest_dataset_output.as_ref().map(|entry| entry.id),
                session_manifest: json!({
                    "generator": "chat-session-workflow",
                    "schema_version": "0.3.0",
                    "status": "pending_assistant_reply",
                    "initial_prompt": request.prompt.trim(),
                    "thread_binding": {
                        "local_thread_id": local_thread_id,
                        "codex_thread_id": Value::Null,
                    },
                    "context_binding": "creation_time",
                    "latest_memory_directory_id": latest_memory_directory.as_ref().map(|entry| entry.id),
                    "latest_memory_directory_version_no": latest_memory_directory.as_ref().map(|entry| entry.version_no),
                    "latest_dataset_output_id": latest_dataset_output.as_ref().map(|entry| entry.id),
                    "last_turn": {
                        "turn_id": chat_turn_id,
                    "status": "pending",
                    "stream_mode": "buffered",
                    "provider_request_id": Value::Null,
                    "provider_status": "pending",
                    "finish_reason": Value::Null,
                    "assistant_message_id": Value::Null,
                    "tool_trace_count": 0,
                    "events": [{
                        "kind": "turn_started",
                        "at": execution.created_at,
                        "provider_request_id": Value::Null,
                        "finish_reason": Value::Null,
                        "tool_trace_count": Value::Null,
                    }],
                    "started_at": execution.created_at,
                    "completed_at": Value::Null,
                },
                }),
                created_at: execution.created_at,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .chat_messages()
        .create(
            state.tenant_id,
            &NewChatMessage {
                session_id: session.id,
                role: ChatMessageRole::User,
                turn_index: 0,
                content: request.prompt.trim().to_string(),
                message_manifest: json!({
                    "source": "user_prompt",
                    "workflow_execution_id": execution.id,
                }),
                created_at: execution.created_at,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal(&state, execution.id, WorkflowSignal::Start).await?;

    Ok((
        StatusCode::CREATED,
        Json(CreateChatSessionResponse {
            chat_session: hydrate_chat_session_view(&state, session).await?,
            workflow_execution: started.execution,
        }),
    ))
}

async fn update_chat_session(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(session_id): Path<String>,
    Json(request): Json<UpdateChatSessionRequest>,
) -> std::result::Result<Json<UpdateChatSessionResponse>, ApiError> {
    let session_id = parse_chat_session_id(&session_id)?;
    let title = trim_optional(request.title).ok_or_else(|| {
        ApiError::bad_request(
            "chat_session_title_required",
            "title is required".to_string(),
        )
    })?;
    validate_required("title", &title)?;

    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_chat_session_for_user(
        &state,
        session_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    let session = state
        .storage
        .chat_sessions()
        .update_title(state.tenant_id, session_id, &title, Utc::now())
        .await
        .map_err(ApiError::from_storage)?;

    Ok(Json(UpdateChatSessionResponse {
        chat_session: hydrate_chat_session_view(&state, session).await?,
    }))
}

async fn append_chat_session_turn(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(session_id): Path<String>,
    Json(request): Json<AppendChatSessionTurnRequest>,
) -> std::result::Result<(StatusCode, Json<AppendChatSessionTurnResponse>), ApiError> {
    let session_id = parse_chat_session_id(&session_id)?;
    validate_required("prompt", &request.prompt)?;

    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let session = load_visible_chat_session_for_user(
        &state,
        session_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    if chat_session_has_in_progress_turn(&session.session_manifest) {
        return Err(ApiError::bad_request(
            "chat_session_turn_in_progress",
            format!("chat session {} already has a turn in progress", session_id),
        ));
    }

    let latest_memory_directory =
        latest_visible_memory_directory_for_user(&state, session.dataset_id, current_user_id)
            .await?;
    let latest_dataset_output = state
        .storage
        .dataset_outputs()
        .list_by_dataset(state.tenant_id, session.dataset_id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .filter(|entry| owner_user_id_is_visible(entry.owner_user_id, current_user_id))
        .next();
    let existing_messages = state
        .storage
        .chat_messages()
        .list_by_session(state.tenant_id, session.id)
        .await
        .map_err(ApiError::from_storage)?;
    let next_turn_index = existing_messages
        .iter()
        .map(|message| message.turn_index)
        .max()
        .map_or(0, |turn_index| turn_index + 1);
    let execution = build_initial_chat_session_execution(
        &state,
        session.dataset_id,
        session.id,
        &request.prompt,
        current_user_id,
        latest_memory_directory.as_ref(),
        latest_dataset_output.as_ref().map(|entry| entry.id),
    )?;
    let initial_event = build_initial_chat_session_event(&execution, session.id, &request.prompt);
    let chat_turn_id = execution
        .context
        .get("chat_turn_id")
        .and_then(Value::as_str)
        .ok_or_else(|| {
            ApiError::internal(
                "chat_turn_id_missing",
                "chat session execution context missing chat_turn_id".to_string(),
            )
        })?
        .to_string();

    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    let user_message = state
        .storage
        .chat_messages()
        .create(
            state.tenant_id,
            &NewChatMessage {
                session_id: session.id,
                role: ChatMessageRole::User,
                turn_index: next_turn_index,
                content: request.prompt.trim().to_string(),
                message_manifest: json!({
                    "source": "user_prompt",
                    "workflow_execution_id": execution.id,
                    "chat_turn_id": chat_turn_id,
                    "append_turn": true,
                }),
                created_at: execution.created_at,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    let session_manifest = build_pending_chat_session_turn_manifest(
        &session.session_manifest,
        &execution,
        &request.prompt,
        latest_memory_directory.as_ref(),
        latest_dataset_output.as_ref(),
        &chat_turn_id,
    );
    let session = state
        .storage
        .chat_sessions()
        .update_context(
            state.tenant_id,
            session.id,
            latest_memory_directory.as_ref().map(|entry| entry.id),
            latest_dataset_output.as_ref().map(|entry| entry.id),
            &session_manifest,
            execution.created_at,
        )
        .await
        .map_err(ApiError::from_storage)?;
    let started = apply_workflow_signal(&state, execution.id, WorkflowSignal::Start).await?;

    Ok((
        StatusCode::CREATED,
        Json(AppendChatSessionTurnResponse {
            chat_session: hydrate_chat_session_view(&state, session).await?,
            user_message: hydrate_chat_message_view(&state, user_message).await?,
            workflow_execution: started.execution,
        }),
    ))
}

fn sse_stream_response<S>(stream: S) -> Response
where
    S: Stream<Item = std::result::Result<Bytes, Infallible>> + Send + 'static,
{
    Response::builder()
        .status(StatusCode::OK)
        .header(header::CONTENT_TYPE, "text/event-stream; charset=utf-8")
        .header(header::CACHE_CONTROL, "no-cache, no-transform")
        .header(header::CONNECTION, "keep-alive")
        .header("x-accel-buffering", "no")
        .body(Body::from_stream(stream))
        .expect("SSE response should build")
}

async fn append_external_channel_public_stream_event(
    state: &AppState,
    run_id: AssistantRunId,
    event_name: &str,
    dedupe_key: &str,
    payload: Value,
) -> std::result::Result<Value, ApiError> {
    let mut attempt = 0u64;
    loop {
        let result = sqlx::query(
            r#"
            with run_event_lock as (
                select pg_advisory_xact_lock(hashtext($1::text), hashtext($2::text))
            ),
            existing as (
                select event_name, sequence_no, payload
                from assistant_run_events
                where tenant_id = $1
                  and run_id = $2
                  and event_name = $3
                  and payload->>$7 = $4
                order by sequence_no asc
                limit 1
            ),
            next_sequence as (
                select coalesce((
                    select max(sequence_no)
                    from assistant_run_events
                    where tenant_id = $1 and run_id = $2
                ), 0) + 1 as sequence_no
                from run_event_lock
            ),
            inserted as (
                insert into assistant_run_events (
                    tenant_id,
                    run_id,
                    sequence_no,
                    event_name,
                    payload,
                    created_at
                )
                select
                    $1,
                    $2,
                    next_sequence.sequence_no,
                    $3,
                    (
                        $5::jsonb ||
                        jsonb_build_object(
                            'sequence', next_sequence.sequence_no,
                            'event_id', $2::text || ':' || lpad(next_sequence.sequence_no::text, 6, '0'),
                            $7, $4
                        )
                    ),
                    $6
                from next_sequence
                where not exists (select 1 from existing)
                returning event_name, sequence_no, payload
            )
            select event_name, sequence_no, payload from inserted
            union all
            select event_name, sequence_no, payload from existing
            limit 1
            "#,
        )
        .bind(state.tenant_id.0)
        .bind(run_id.0)
        .bind(event_name)
        .bind(dedupe_key)
        .bind(&payload)
        .bind(Utc::now())
        .bind(EXTERNAL_CHANNEL_PUBLIC_STREAM_DEDUPE_KEY)
        .fetch_one(state.storage.pool())
        .await;

        match result {
            Ok(row) => return Ok(external_channel_public_stream_payload(row.get("payload"))),
            Err(error)
                if attempt < 5
                    && external_channel_assistant_run_event_sequence_unique_violation(&error) =>
            {
                attempt += 1;
                tokio::time::sleep(StdDuration::from_millis(5 * attempt)).await;
            }
            Err(error) => return Err(ApiError::from_storage(anyhow::Error::new(error))),
        }
    }
}

fn external_channel_assistant_run_event_sequence_unique_violation(error: &sqlx::Error) -> bool {
    let sqlx::Error::Database(database_error) = error else {
        return false;
    };
    database_error.code().as_deref() == Some("23505")
        && database_error.constraint() == Some("assistant_run_events_run_id_sequence_no_key")
}

async fn persist_external_channel_public_stream_payload_or_original(
    state: &AppState,
    run_id: Option<AssistantRunId>,
    event_name: &str,
    dedupe_key: &str,
    payload: Value,
) -> Value {
    let payload = external_channel_public_stream_payload(payload);
    let Some(run_id) = run_id else {
        return payload;
    };
    match append_external_channel_public_stream_event(
        state,
        run_id,
        event_name,
        dedupe_key,
        payload.clone(),
    )
    .await
    {
        Ok(persisted) => persisted,
        Err(error) => {
            tracing::warn!(
                %error,
                %event_name,
                %run_id,
                "external channel public stream event persistence failed"
            );
            external_channel_public_stream_payload(payload)
        }
    }
}

async fn external_channel_sse_completion_with_done_persisted(
    state: &AppState,
    response: ExternalChannelEventResponse,
    include_done: bool,
) -> String {
    external_channel_sse_completion_with_done_persisted_and_delta(
        state,
        response,
        include_done,
        true,
    )
    .await
}

async fn external_channel_sse_completion_with_done_persisted_and_delta(
    state: &AppState,
    response: ExternalChannelEventResponse,
    include_done: bool,
    emit_text_deltas: bool,
) -> String {
    let emit_static_page_queued_event = response
        .reply
        .card
        .as_ref()
        .and_then(|card| card.get("type"))
        .and_then(Value::as_str)
        == Some("v3_static_page_image2_pipeline");
    let response = external_channel_public_response(response);
    let text = response.reply.text.clone().unwrap_or_default();
    let assistant_run_id = response.assistant_run_id;
    let idempotency_key = response.idempotency_key.clone();
    let conversation_external_id = response.reply.target_conversation_external_id.clone();
    let mut encoded = if emit_text_deltas {
        sse_text_delta_events("external_channel.delta", &text)
    } else {
        String::new()
    };
    if emit_static_page_queued_event {
        let card = response.reply.card.clone();
        let status = card
            .as_ref()
            .and_then(|card| card.get("status"))
            .and_then(Value::as_str)
            .unwrap_or("static_page_generation_queued")
            .to_string();
        let draft_id = card
            .as_ref()
            .and_then(|card| card.get("draft_id"))
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string();
        let data = json!({
            "assistant_run_id": assistant_run_id,
            "idempotency_key": idempotency_key,
            "card": card,
        });
        let payload = external_channel_sse_public_payload(
            assistant_run_id,
            &idempotency_key,
            &conversation_external_id,
            external_channel_static_page_sse_sequence("static_page_generation_queued"),
            "static_page",
            "static_page_generation_queued",
            "静态页/报表页面已进入生成队列。",
            external_channel_card_status_url(response.reply.card.as_ref()),
            external_channel_card_poll_after_seconds(response.reply.card.as_ref()),
            data,
        );
        let dedupe_key = format!("external_channel.static_page_queued:{draft_id}:{status}");
        let payload = persist_external_channel_public_stream_payload_or_original(
            state,
            assistant_run_id,
            "external_channel.static_page_queued",
            &dedupe_key,
            payload,
        )
        .await;
        encoded.push_str(&sse_json_event(
            "external_channel.static_page_queued",
            payload,
        ));
    }
    if external_channel_response_needs_input(&response) {
        let needs_input_text = external_channel_needs_input_sse_text(&response);
        let data = json!({
            "assistant_run_id": assistant_run_id,
            "idempotency_key": idempotency_key,
            "status": "needs_input",
            "card": response.reply.card.clone(),
            "text": needs_input_text,
        });
        let payload = external_channel_sse_public_payload(
            assistant_run_id,
            &idempotency_key,
            &conversation_external_id,
            external_channel_static_page_sse_sequence("needs_input"),
            "needs_input",
            "needs_input",
            &needs_input_text,
            external_channel_card_status_url(response.reply.card.as_ref()),
            external_channel_card_poll_after_seconds(response.reply.card.as_ref()),
            data.clone(),
        );
        let dedupe_key = format!(
            "external_channel.needs_input:{}",
            external_channel_public_stream_dedupe_hash(&data)
        );
        let payload = persist_external_channel_public_stream_payload_or_original(
            state,
            assistant_run_id,
            "external_channel.needs_input",
            &dedupe_key,
            payload,
        )
        .await;
        encoded.push_str(&sse_json_event("external_channel.needs_input", payload));
    }
    let completed_data = external_channel_completed_stream_data(
        &response,
        assistant_run_id,
        &idempotency_key,
        &text,
    );
    let completed_text = completed_data
        .get("text")
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| {
            if text.trim().is_empty() {
                "本轮处理已返回当前结果。".to_string()
            } else {
                text.clone()
            }
        });
    let completed_payload = external_channel_sse_public_payload(
        assistant_run_id,
        &idempotency_key,
        &conversation_external_id,
        external_channel_static_page_sse_sequence("completed"),
        "completed",
        "completed",
        &completed_text,
        None,
        None,
        completed_data.clone(),
    );
    let dedupe_key = format!(
        "external_channel.completed:{}",
        external_channel_public_stream_dedupe_hash(&completed_data)
    );
    let completed_payload = persist_external_channel_public_stream_payload_or_original(
        state,
        assistant_run_id,
        "external_channel.completed",
        &dedupe_key,
        completed_payload,
    )
    .await;
    encoded.push_str(&sse_json_event(
        "external_channel.completed",
        completed_payload,
    ));
    if include_done {
        encoded.push_str(&sse_json_event("done", json!({"ok": true})));
    }
    encoded
}

async fn external_channel_static_page_sse_progress_events_persisted(
    state: &AppState,
    response: ExternalChannelEventResponse,
) -> String {
    let (event_name, payload, text, dedupe_key, run_id) =
        external_channel_static_page_sse_progress_payload(response);
    let payload = persist_external_channel_public_stream_payload_or_original(
        state,
        run_id,
        event_name,
        &dedupe_key,
        payload,
    )
    .await;
    external_channel_sse_event_with_delta(event_name, payload, &text)
}

enum ExternalChannelEventSseState {
    ProcessStarted {
        state: AppState,
        connection_id: String,
        connection: ExternalChannelConnectionSummary,
        message: ExternalBotMessageView,
    },
    Process {
        state: AppState,
        connection_id: String,
        connection: ExternalChannelConnectionSummary,
        message: ExternalBotMessageView,
    },
    ProcessLive {
        state: AppState,
        connection_id: String,
        receiver: tokio::sync::mpsc::UnboundedReceiver<ExternalChannelEventSseWorkerMessage>,
        answer_delta_emitted: bool,
    },
    FollowStaticPage {
        state: AppState,
        connection_id: String,
        run_id: AssistantRunId,
        idempotency_key: String,
        conversation_external_id: String,
        started_at: Instant,
        last_key: String,
        preview_emitted: bool,
    },
    End,
}

struct ExternalChannelStreamedProviderResponse {
    response: LlmResponse,
    deltas: Vec<LlmStreamDelta>,
}

struct ExternalChannelProviderAttemptResult {
    response: LlmResponse,
    deltas: Vec<LlmStreamDelta>,
}

async fn external_channel_event_sse_next(
    state: ExternalChannelEventSseState,
) -> Option<(
    std::result::Result<Bytes, Infallible>,
    ExternalChannelEventSseState,
)> {
    match state {
        ExternalChannelEventSseState::ProcessStarted {
            state,
            connection_id,
            connection,
            message,
        } => {
            let body = external_channel_retrieval_started_sse_event(&message);
            if external_channel_live_answer_stream_enabled() {
                let (sender, receiver) = tokio::sync::mpsc::unbounded_channel();
                let worker_state = state.clone();
                let worker_connection_id = connection_id.clone();
                let worker_connection = connection.clone();
                let worker_message = message.clone();
                let sink = ExternalChannelAnswerDeltaSink::new(sender.clone());
                tokio::spawn(async move {
                    let result = ingest_external_channel_message_with_connection_inner(
                        &worker_state,
                        &worker_connection_id,
                        &worker_connection,
                        worker_message,
                        Some(sink),
                    )
                    .await;
                    let _ = sender.send(ExternalChannelEventSseWorkerMessage::Finished(result));
                });
                return Some((
                    Ok(Bytes::from(body)),
                    ExternalChannelEventSseState::ProcessLive {
                        state,
                        connection_id,
                        receiver,
                        answer_delta_emitted: false,
                    },
                ));
            }
            Some((
                Ok(Bytes::from(body)),
                ExternalChannelEventSseState::Process {
                    state,
                    connection_id,
                    connection,
                    message,
                },
            ))
        }
        ExternalChannelEventSseState::Process {
            state,
            connection_id,
            connection,
            message,
        } => {
            let body = match ingest_external_channel_message_with_connection(
                &state,
                &connection_id,
                &connection,
                message,
            )
            .await
            {
                Ok((_, response)) => {
                    let should_follow = response.assistant_run_id.is_some()
                        && external_channel_response_is_static_page_pipeline(&response);
                    let terminal_static_page =
                        should_follow && external_channel_static_page_sse_is_terminal(&response);
                    let mut encoded = if should_follow {
                        external_channel_static_page_sse_prompt_events(&state, &response).await
                    } else {
                        String::new()
                    };
                    let run_id = response.assistant_run_id;
                    let idempotency_key = response.idempotency_key.clone();
                    let conversation_external_id =
                        response.reply.target_conversation_external_id.clone();
                    let last_key = external_channel_static_page_sse_progress_key(&response);
                    encoded.push_str(
                        &external_channel_sse_completion_with_done_persisted(
                            &state,
                            response,
                            !should_follow || terminal_static_page,
                        )
                        .await,
                    );
                    let next_state = if should_follow && !terminal_static_page {
                        run_id
                            .map(|run_id| ExternalChannelEventSseState::FollowStaticPage {
                                state,
                                connection_id,
                                run_id,
                                idempotency_key,
                                conversation_external_id,
                                started_at: Instant::now(),
                                last_key,
                                preview_emitted: false,
                            })
                            .unwrap_or(ExternalChannelEventSseState::End)
                    } else {
                        ExternalChannelEventSseState::End
                    };
                    return Some((Ok(Bytes::from(encoded)), next_state));
                }
                Err(error) => sse_error_event(error),
            };
            Some((Ok(Bytes::from(body)), ExternalChannelEventSseState::End))
        }
        ExternalChannelEventSseState::ProcessLive {
            state,
            connection_id,
            mut receiver,
            answer_delta_emitted,
        } => match receiver.recv().await {
            Some(ExternalChannelEventSseWorkerMessage::AnswerDelta(body)) => Some((
                Ok(Bytes::from(body)),
                ExternalChannelEventSseState::ProcessLive {
                    state,
                    connection_id,
                    receiver,
                    answer_delta_emitted: true,
                },
            )),
            Some(ExternalChannelEventSseWorkerMessage::Progress(progress)) => {
                let payload = persist_external_channel_public_stream_payload_or_original(
                    &state,
                    Some(progress.run_id),
                    progress.event_name,
                    &progress.dedupe_key,
                    progress.payload,
                )
                .await;
                Some((
                    Ok(Bytes::from(external_channel_sse_event_with_delta(
                        progress.event_name,
                        payload,
                        &progress.display_text,
                    ))),
                    ExternalChannelEventSseState::ProcessLive {
                        state,
                        connection_id,
                        receiver,
                        answer_delta_emitted,
                    },
                ))
            }
            Some(ExternalChannelEventSseWorkerMessage::Finished(result)) => {
                let body = match result {
                    Ok((_, response)) => {
                        let response =
                            match external_channel_response_with_event_static_page_artifact_links(
                                &state,
                                response.clone(),
                            )
                            .await
                            {
                                Ok(response) => response,
                                Err(error) => {
                                    tracing::warn!(
                                        %error,
                                        "external channel live stream static-page event link merge failed"
                                    );
                                    response
                                }
                            };
                        let should_follow = response.assistant_run_id.is_some()
                            && external_channel_response_is_static_page_pipeline(&response);
                        let terminal_static_page = should_follow
                            && external_channel_static_page_sse_is_terminal(&response);
                        let mut encoded = if should_follow {
                            external_channel_static_page_sse_prompt_events(&state, &response).await
                        } else {
                            String::new()
                        };
                        let run_id = response.assistant_run_id;
                        let idempotency_key = response.idempotency_key.clone();
                        let conversation_external_id =
                            response.reply.target_conversation_external_id.clone();
                        let last_key = external_channel_static_page_sse_progress_key(&response);
                        encoded.push_str(
                            &external_channel_sse_completion_with_done_persisted_and_delta(
                                &state,
                                response,
                                !should_follow || terminal_static_page,
                                !answer_delta_emitted,
                            )
                            .await,
                        );
                        let next_state = if should_follow && !terminal_static_page {
                            run_id
                                .map(|run_id| ExternalChannelEventSseState::FollowStaticPage {
                                    state,
                                    connection_id,
                                    run_id,
                                    idempotency_key,
                                    conversation_external_id,
                                    started_at: Instant::now(),
                                    last_key,
                                    preview_emitted: false,
                                })
                                .unwrap_or(ExternalChannelEventSseState::End)
                        } else {
                            ExternalChannelEventSseState::End
                        };
                        return Some((Ok(Bytes::from(encoded)), next_state));
                    }
                    Err(error) => sse_error_event(error),
                };
                Some((Ok(Bytes::from(body)), ExternalChannelEventSseState::End))
            }
            None => Some((
                Ok(Bytes::from(sse_error_event(ApiError::internal(
                    "external_channel_live_stream_closed",
                    "external channel live stream worker closed before returning a result"
                        .to_string(),
                )))),
                ExternalChannelEventSseState::End,
            )),
        },
        ExternalChannelEventSseState::FollowStaticPage {
            state,
            connection_id,
            run_id,
            idempotency_key,
            conversation_external_id,
            started_at,
            last_key,
            preview_emitted,
        } => {
            tokio::time::sleep(external_channel_static_page_sse_poll_interval()).await;
            let response = match load_external_channel_assistant_run_reply_response(
                &state,
                &connection_id,
                run_id,
            )
            .await
            {
                Ok(response) => response,
                Err(error) => {
                    return Some((
                        Ok(Bytes::from(sse_error_event(error))),
                        ExternalChannelEventSseState::End,
                    ));
                }
            };
            let key = external_channel_static_page_sse_progress_key(&response);
            let terminal = external_channel_static_page_sse_is_terminal(&response);
            let timed_out = started_at.elapsed() >= external_channel_static_page_sse_timeout();
            let changed = key != last_key;
            let mut encoded = String::new();
            let mut next_preview_emitted = preview_emitted;
            if !preview_emitted {
                if let Some(preview_events) = external_channel_static_page_sse_preview_ready_events(
                    &state,
                    run_id,
                    &idempotency_key,
                    &conversation_external_id,
                )
                .await
                {
                    encoded.push_str(&preview_events);
                    next_preview_emitted = true;
                }
            }
            if changed || terminal {
                encoded.push_str(
                    &external_channel_static_page_sse_progress_events_persisted(
                        &state,
                        response.clone(),
                    )
                    .await,
                );
            } else {
                let text = "DataMax 正在继续处理，流式连接保持中。";
                let data = json!({
                    "assistant_run_id": run_id,
                    "idempotency_key": idempotency_key.clone(),
                    "status": "processing",
                    "text": text,
                });
                encoded.push_str(&sse_json_event(
                    "external_channel.heartbeat",
                    external_channel_sse_public_payload(
                        Some(run_id),
                        &idempotency_key,
                        &conversation_external_id,
                        external_channel_static_page_sse_sequence("processing"),
                        "static_page",
                        "processing",
                        text,
                        None,
                        Some(
                            external_channel_static_page_sse_poll_interval()
                                .as_secs()
                                .max(1),
                        ),
                        data,
                    ),
                ));
            }
            if terminal {
                encoded.push_str(&sse_json_event("done", json!({"ok": true})));
                return Some((Ok(Bytes::from(encoded)), ExternalChannelEventSseState::End));
            }
            if timed_out {
                encoded.push_str(
                    &external_channel_static_page_sse_continue_polling_event_persisted(
                        &state, response,
                    )
                    .await,
                );
                encoded.push_str(&sse_json_event("done", json!({"ok": true})));
                return Some((Ok(Bytes::from(encoded)), ExternalChannelEventSseState::End));
            }
            Some((
                Ok(Bytes::from(encoded)),
                ExternalChannelEventSseState::FollowStaticPage {
                    state,
                    connection_id,
                    run_id,
                    idempotency_key,
                    conversation_external_id,
                    started_at,
                    last_key: key,
                    preview_emitted: next_preview_emitted,
                },
            ))
        }
        ExternalChannelEventSseState::End => None,
    }
}

async fn external_channel_static_page_sse_preview_ready_events(
    state: &AppState,
    run_id: AssistantRunId,
    idempotency_key: &str,
    conversation_external_id: &str,
) -> Option<String> {
    let events = state
        .storage
        .assistant_runs()
        .list_events(state.tenant_id, run_id)
        .await
        .ok()?;
    let event = events
        .iter()
        .rev()
        .find(|event| event.event_name == "static_page_image_job.preview_ready")?;
    let preview_asset_key = event
        .payload
        .get("preview_asset_key")
        .or_else(|| {
            event
                .payload
                .pointer("/asset_provenance/persistedPreviewAssetKey")
        })
        .or_else(|| {
            event
                .payload
                .pointer("/artifact_manifest/refs/preview_asset_key")
        })
        .and_then(Value::as_str)
        .map(str::to_string);
    let preview_url = preview_asset_key
        .as_deref()
        .and_then(external_channel_static_page_preview_public_url);
    let text = if let Some(preview_url) = preview_url.as_deref() {
        format!("页面可视化预览已生成：{preview_url}。下一步会继续生成最终静态页。")
    } else {
        "页面可视化预览已生成。下一步会继续生成最终静态页。".to_string()
    };
    let mut encoded = sse_text_delta_events("external_channel.delta", &text);
    let data = json!({
        "assistant_run_id": run_id,
        "idempotency_key": idempotency_key,
        "status": "static_page_preview_ready",
        "draft_id": event.payload.get("draft_id").cloned().unwrap_or(Value::Null),
        "preview_url": preview_url.clone(),
        "card": {
            "type": "v3_static_page_pipeline",
            "status": "static_page_preview_ready",
            "draft_id": event.payload.get("draft_id").cloned().unwrap_or(Value::Null),
            "preview_url": preview_url.clone(),
        },
        "text": text.clone(),
    });
    let payload = external_channel_sse_public_payload(
        Some(run_id),
        idempotency_key,
        conversation_external_id,
        external_channel_static_page_sse_sequence("static_page_preview_ready"),
        "static_page",
        "static_page_preview_ready",
        &text,
        None,
        None,
        data,
    );
    let draft_id = event
        .payload
        .get("draft_id")
        .and_then(Value::as_str)
        .unwrap_or_default();
    let dedupe_key = format!(
        "external_channel.static_page_preview_ready:{draft_id}:{}",
        preview_url.as_deref().unwrap_or_default()
    );
    let payload = persist_external_channel_public_stream_payload_or_original(
        state,
        Some(run_id),
        "external_channel.static_page_preview_ready",
        &dedupe_key,
        payload,
    )
    .await;
    encoded.push_str(&sse_json_event(
        "external_channel.static_page_preview_ready",
        payload,
    ));
    Some(encoded)
}

async fn external_channel_static_page_sse_prompt_events(
    state: &AppState,
    response: &ExternalChannelEventResponse,
) -> String {
    let Some(job_id) = response
        .reply
        .card
        .as_ref()
        .and_then(|card| card.get("image_job_id"))
        .and_then(Value::as_str)
        .and_then(|raw| parse_static_page_image_job_id(raw).ok())
    else {
        return String::new();
    };
    let Ok(Some(job)) = state
        .storage
        .static_page_image_jobs()
        .get_by_id(state.tenant_id, job_id)
        .await
        .map_err(ApiError::from_storage)
    else {
        return String::new();
    };
    let summary = external_static_page_image_prompt_payload_summary(&job.image_prompt_payload);
    let prompt_text = external_static_page_image_prompt_text(&summary, "");
    if prompt_text.trim().is_empty() {
        return String::new();
    }
    let display_prompt =
        external_channel_public_text(&truncate_assistant_supply_text(&prompt_text, 360));
    let conversation_external_id = response.reply.target_conversation_external_id.clone();
    let display_text = "DataMax 正在生成页面方案，并会自动继续发布最终页面。";
    let mut encoded = sse_text_delta_events("external_channel.delta", display_text);
    let data = json!({
        "assistant_run_id": response.assistant_run_id,
        "idempotency_key": response.idempotency_key,
        "draft_id": job.draft_id,
        "summary": display_prompt,
        "style_direction": summary.get("style_direction").cloned().unwrap_or(Value::Null),
        "modules": summary.get("modules").cloned().unwrap_or_else(|| json!([])),
        "data_snapshot": summary.get("data_snapshot").cloned().unwrap_or(Value::Null),
        "next_step": "generate_and_publish_static_page",
    });
    let payload = external_channel_sse_public_payload(
        response.assistant_run_id,
        &response.idempotency_key,
        &conversation_external_id,
        external_channel_static_page_sse_sequence("static_page_planning"),
        "static_page",
        "static_page_planning",
        display_text,
        external_channel_card_status_url(response.reply.card.as_ref()),
        external_channel_card_poll_after_seconds(response.reply.card.as_ref()),
        data,
    );
    let dedupe_key = format!("external_channel.static_page_planning:{}", job.draft_id);
    let payload = persist_external_channel_public_stream_payload_or_original(
        state,
        response.assistant_run_id,
        "external_channel.static_page_planning",
        &dedupe_key,
        payload,
    )
    .await;
    encoded.push_str(&sse_json_event(
        "external_channel.static_page_planning",
        payload,
    ));
    encoded
}

async fn external_channel_static_page_sse_continue_polling_event_persisted(
    state: &AppState,
    response: ExternalChannelEventResponse,
) -> String {
    let (payload, text, dedupe_key, run_id) =
        external_channel_static_page_sse_continue_polling_payload(response);
    let payload = persist_external_channel_public_stream_payload_or_original(
        state,
        run_id,
        "external_channel.static_page_continue_polling",
        &dedupe_key,
        payload,
    )
    .await;
    external_channel_sse_event_with_delta(
        "external_channel.static_page_continue_polling",
        payload,
        &text,
    )
}

async fn create_assistant_run_stream(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(request): Json<CreateAssistantRunRequest>,
) -> std::result::Result<Response, ApiError> {
    validate_required("prompt", &request.prompt)?;
    if assistant_run_live_answer_stream_enabled() {
        let (sender, receiver) = tokio::sync::mpsc::unbounded_channel();
        let sink = AssistantRunLiveDeltaSink::new(sender.clone());
        tokio::spawn(async move {
            let result = create_assistant_run_inner(state, headers, request, Some(sink)).await;
            let _ = sender.send(AssistantRunSseWorkerMessage::CreateFinished(result));
        });
        let accepted = create_assistant_run_sse_accepted_event();
        let live_stream = stream::unfold(Some((receiver, false)), |state| async move {
            let Some((mut receiver, answer_delta_emitted)) = state else {
                return None;
            };
            match receiver.recv().await {
                Some(AssistantRunSseWorkerMessage::AnswerDelta(body)) => {
                    Some((Ok(Bytes::from(body)), Some((receiver, true))))
                }
                Some(AssistantRunSseWorkerMessage::CreateFinished(result)) => {
                    let body = match result {
                        Ok((_, Json(response))) => create_assistant_run_sse_completion_with_delta(
                            response,
                            !answer_delta_emitted,
                        ),
                        Err(error) => sse_error_event(error),
                    };
                    Some((Ok(Bytes::from(body)), None))
                }
                Some(AssistantRunSseWorkerMessage::ContinueFinished(_)) => Some((
                    Ok(Bytes::from(sse_error_event(ApiError::internal(
                        "assistant_run_live_stream_unexpected_message",
                        "assistant run live stream received a continue completion".to_string(),
                    )))),
                    None,
                )),
                None => Some((
                    Ok(Bytes::from(sse_error_event(ApiError::internal(
                        "assistant_run_live_stream_closed",
                        "assistant run live stream worker closed before returning a result"
                            .to_string(),
                    )))),
                    None,
                )),
            }
        });
        let stream = stream::iter(vec![Ok(Bytes::from(accepted))]).chain(live_stream);
        return Ok(sse_stream_response(stream));
    }
    let accepted = create_assistant_run_sse_accepted_event();
    let stream = stream::iter(vec![Ok(Bytes::from(accepted))]).chain(stream::once(async move {
        let body = match create_assistant_run_inner(state, headers, request, None).await {
            Ok((_, Json(response))) => create_assistant_run_sse_completion(response),
            Err(error) => sse_error_event(error),
        };
        Ok(Bytes::from(body))
    }));
    Ok(sse_stream_response(stream))
}

async fn create_assistant_run(
    State(state): State<AppState>,
    headers: HeaderMap,
    Json(request): Json<CreateAssistantRunRequest>,
) -> std::result::Result<(StatusCode, Json<CreateAssistantRunResponse>), ApiError> {
    create_assistant_run_inner(state, headers, request, None).await
}

async fn create_assistant_run_inner(
    state: AppState,
    headers: HeaderMap,
    mut request: CreateAssistantRunRequest,
    live_delta_sink: Option<AssistantRunLiveDeltaSink>,
) -> std::result::Result<(StatusCode, Json<CreateAssistantRunResponse>), ApiError> {
    validate_required("prompt", &request.prompt)?;
    let client_scope_candidates = request.scope_candidates.clone();
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let header_local_thread_id = local_thread_id_from_headers(&headers);
    let local_thread_id = request
        .local_thread_id
        .as_ref()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .or_else(|| header_local_thread_id.clone());
    ensure_default_public_datasets(&state.storage, state.tenant_id).await?;
    let visible_datasets = filter_visible_datasets(
        state
            .storage
            .datasets()
            .list_by_tenant(state.tenant_id)
            .await
            .map_err(ApiError::from_storage)?,
        &active_secret_binding_ids,
        current_user_id,
        local_thread_id.as_deref(),
    )
    .into_iter()
    .filter(|dataset| !dataset_is_hidden_from_standard_dataset_list(dataset))
    .collect::<Vec<_>>();
    let visible_datasets =
        enrich_visible_datasets_for_scope_planning(&state, visible_datasets, current_user_id)
            .await?;
    let requested_selected_scope = request.selected_scope.clone();
    let selected_dataset_id = requested_selected_scope
        .as_ref()
        .and_then(selected_dataset_id_from_scope);
    let current_thread_memory_available = if let Some(local_thread_id) = local_thread_id.as_ref() {
        conversation_memory_source_has_visible_items(&state, local_thread_id, current_user_id)
            .await?
    } else {
        false
    };
    let user_context_memory_key =
        current_user_id.map(|user_id| global_user_context_memory_key(state.tenant_id, user_id));
    let user_context_memory_available = if let Some(key) = user_context_memory_key.as_deref() {
        conversation_memory_source_has_visible_items(&state, key, current_user_id).await?
    } else {
        false
    };
    let conversation_memory_available =
        current_thread_memory_available || user_context_memory_available;
    let scope_plan = plan_scope(ScopePlannerInput {
        prompt: &request.prompt,
        visible_datasets: &visible_datasets,
        selected_dataset_id,
        conversation_memory_available,
    });
    let selected_scope = assistant_run_scope_with_requested_document_scope(
        scope_plan.selected_scope.clone(),
        requested_selected_scope.as_ref(),
    );
    let mut selected_scope = assistant_run_scope_with_current_artifact_context(
        selected_scope,
        request.current_artifact.as_ref(),
        &request.prompt,
    );
    let mut scope_candidates = candidates_to_values(&scope_plan.candidates)
        .into_iter()
        .filter(|candidate| {
            candidate.get("type").and_then(Value::as_str) != Some("conversation_memory")
        })
        .collect::<Vec<_>>();
    if selected_scope_requests_conversation_memory(&selected_scope) {
        let mut memory_scope_ids = Vec::new();
        if current_thread_memory_available {
            memory_scope_ids.push(CONVERSATION_MEMORY_SCOPE_CURRENT_THREAD.to_string());
            scope_candidates.push(conversation_memory_scope_candidate_value(
                CONVERSATION_MEMORY_SCOPE_CURRENT_THREAD,
                "本轮对话历史",
                "用户引用了刚才或已有草稿内容",
                "scope_planner",
            ));
        }
        if user_context_memory_available {
            if let Some(key) = user_context_memory_key.as_deref() {
                memory_scope_ids.push(key.to_string());
                scope_candidates.push(conversation_memory_scope_candidate_value(
                    key,
                    "用户历史上下文",
                    "用户引用了历史上下文且存在可见用户记忆",
                    "user_context_scope",
                ));
            }
        }
        set_selected_scope_conversation_memory(&mut selected_scope, memory_scope_ids);
    }
    selected_scope = assistant_run_scope_with_visible_dataset_range(
        selected_scope,
        &visible_datasets,
        &request.prompt,
    );
    scope_candidates.extend(assistant_run_artifact_scope_candidates(
        &client_scope_candidates,
        request.current_artifact.as_ref(),
    ));
    request.scope_candidates = dedupe_assistant_run_scope_candidate_values(scope_candidates)
        .into_iter()
        .take(5)
        .collect();
    request.selected_scope = Some(selected_scope.clone());
    let mut evidence_state = build_assistant_run_evidence_state(
        &state,
        &selected_scope,
        &request.prompt,
        local_thread_id.as_deref(),
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;

    let chat_runtime = resolve_runtime_selection_from_env(
        "ASSISTANT_RUN",
        MODEL_LANE_ASSISTANT_CHAT,
        DEFAULT_ASSISTANT_RUN_RUNTIME_MODEL,
    );
    let react_runtime = resolve_runtime_selection_from_env(
        "ASSISTANT_RUN",
        MODEL_LANE_ASSISTANT_REACT_JSON,
        DEFAULT_ASSISTANT_RUN_RUNTIME_MODEL,
    );
    let scope_candidates = request.scope_candidates.clone();
    let react_enabled = assistant_run_react_enabled_for_scope(
        &react_runtime.mode,
        &selected_scope,
        request.current_artifact.as_ref(),
    );
    let deterministic_scan_direct_answer =
        assistant_run_dataset_entity_scan_direct_answer(&request, &evidence_state);
    let deterministic_scan_direct_answer_available = deterministic_scan_direct_answer.is_some();
    let react_enabled_for_execution = react_enabled && !deterministic_scan_direct_answer_available;
    let runtime_mode_for_trail = if deterministic_scan_direct_answer_available {
        "placeholder".to_string()
    } else if react_enabled_for_execution {
        react_runtime.mode.clone()
    } else {
        chat_runtime.mode.clone()
    };
    let runtime_provider_for_trail = if deterministic_scan_direct_answer_available {
        "platform_direct_answer".to_string()
    } else if react_enabled_for_execution {
        react_runtime.provider.clone()
    } else {
        chat_runtime.provider.clone()
    };
    let runtime_model_for_trail = if deterministic_scan_direct_answer_available {
        "dataset-entity-scan-direct-v1".to_string()
    } else if react_enabled_for_execution {
        react_runtime.model.clone()
    } else {
        chat_runtime.model.clone()
    };
    let now = Utc::now();
    let planned_candidate_count = scope_candidates.len();
    let codex_scope_candidates = scope_candidates.clone();
    let scope_candidates = Value::Array(scope_candidates.clone());
    let context_policy = request
        .context_policy_hint
        .clone()
        .unwrap_or_else(|| build_assistant_run_context_policy(&selected_scope));
    let supplied_evidence_count = assistant_run_evidence_supplied_count(&evidence_state);
    let detail_target_count = assistant_run_detail_target_count(&evidence_state);
    let evidence_trail_label = assistant_run_evidence_trail_label(&evidence_state);
    let mut execution_trail = vec![
        json!({
            "status": "completed",
            "label": "接收用户问题",
            "at": now,
        }),
        json!({
            "status": "completed",
            "label": "规划供料候选",
            "candidate_count": planned_candidate_count,
            "hint": scope_plan.hint,
            "at": now,
        }),
        json!({
            "status": "completed",
            "label": evidence_trail_label,
            "supplied_count": supplied_evidence_count,
            "detail_target_count": detail_target_count,
            "evidence_status": evidence_state.get("status").and_then(Value::as_str).unwrap_or("unknown"),
            "at": now,
        }),
    ];
    let initial_runtime_manifest = json!({
        "status": "running",
        "mode": runtime_mode_for_trail,
        "provider": runtime_provider_for_trail,
        "model": runtime_model_for_trail,
        "react_enabled": react_enabled,
        "react_execution_enabled": react_enabled_for_execution,
        "entrypoint": "create_assistant_run",
    });
    let run = state
        .storage
        .assistant_runs()
        .create(
            state.tenant_id,
            &NewAssistantRun {
                user_id: current_user_id,
                local_thread_id: local_thread_id.clone(),
                user_prompt: request.prompt.trim().to_string(),
                startup_briefing: request
                    .startup_briefing
                    .clone()
                    .unwrap_or_else(|| json!({})),
                selected_scope: selected_scope.clone(),
                scope_candidates: scope_candidates.clone(),
                context_policy: context_policy.clone(),
                evidence_state: evidence_state.clone(),
                service_lane: "ordinary_chat".to_string(),
                execution_trail: Value::Array(execution_trail.clone()),
                output_artifacts: json!([]),
                runtime_manifest: initial_runtime_manifest.clone(),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run.id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.started".to_string(),
                payload: json!({
                    "service_lane": run.service_lane.clone(),
                    "runtime": initial_runtime_manifest,
                    "react_enabled": react_enabled,
                }),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    if let Err(error) = maybe_enqueue_assistant_run_customer_codex_sidecar(
        &state,
        &run,
        &request,
        &selected_scope,
        &evidence_state,
        now,
    )
    .await
    {
        tracing::warn!(
            run_id = %run.id,
            error = ?error,
            "non-blocking Codex sidecar enqueue failed"
        );
    }

    if let Some(artifact) =
        wechat_video_login_handoff_artifact_from_prompt(run.id, &request.prompt, now)
    {
        let answer = wechat_video_login_handoff_answer_text();
        let runtime_manifest = assistant_run_wechat_video_handoff_runtime_manifest("ordinary_chat");
        let mut handoff_execution_trail = execution_trail.clone();
        handoff_execution_trail.push(json!({
            "status": "completed",
            "label": "视频号来源受限 handoff",
            "reason": "login_gated_video_source_not_supported",
            "at": now,
        }));
        let output_artifacts = vec![
            json!({
                "type": "assistant_message",
                "role": ChatMessageRole::Assistant.as_str(),
                "content": answer,
                "source": "wechat_video_login_handoff",
            }),
            json!({
                "type": "html_artifact",
                "id": artifact.id,
                "title": artifact.title,
                "template_id": "wechat_video_login_handoff",
                "content": answer,
            }),
        ];
        state
            .storage
            .assistant_runs()
            .update_runtime_manifest(state.tenant_id, run.id, &runtime_manifest)
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .update_evidence_state(state.tenant_id, run.id, &evidence_state)
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .update_execution_trail(
                state.tenant_id,
                run.id,
                &Value::Array(handoff_execution_trail.clone()),
            )
            .await
            .map_err(ApiError::from_storage)?;
        let run = state
            .storage
            .assistant_runs()
            .attach_output_artifacts(
                state.tenant_id,
                run.id,
                &Value::Array(output_artifacts.clone()),
            )
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.wechat_video_login_handoff_required".to_string(),
                    payload: json!({
                        "reason": "login_gated_video_source_not_supported",
                        "failure_reason": "login_gated_video_source_not_supported",
                        "html_artifacts": [artifact],
                    }),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.completed".to_string(),
                    payload: json!({
                        "service_lane": run.service_lane.clone(),
                        "runtime": runtime_manifest.clone(),
                    }),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        let events = state
            .storage
            .assistant_runs()
            .list_events(state.tenant_id, run.id)
            .await
            .map_err(ApiError::from_storage)?;
        let diagnostics = assistant_run_detail_diagnostics(&run, &events);

        return Ok((
            StatusCode::CREATED,
            Json(CreateAssistantRunResponse {
                assistant_run_id: run.id,
                assistant_message: AssistantRunMessageView {
                    role: ChatMessageRole::Assistant,
                    content: answer,
                },
                runtime: run.runtime_manifest,
                selected_scope,
                scope_candidates: value_array(scope_candidates),
                evidence_state,
                execution_trail: handoff_execution_trail,
                output_artifacts,
                required_confirmations: Vec::new(),
                diagnostics,
            }),
        ));
    }

    if let Some(direct_answer) = assistant_run_xinbai_published_report_link_answer(&request.prompt)
    {
        let runtime_manifest = assistant_run_xinbai_report_link_runtime_manifest("ordinary_chat");
        let mut direct_execution_trail = execution_trail.clone();
        direct_execution_trail.push(json!({
            "status": "completed",
            "label": "复用已发布新百报表链接",
            "public_url": assistant_run_xinbai_published_report_url(),
            "at": now,
        }));
        let output_artifacts =
            assistant_run_xinbai_report_link_output_artifacts(&direct_answer, false);
        state
            .storage
            .assistant_runs()
            .update_runtime_manifest(state.tenant_id, run.id, &runtime_manifest)
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .update_execution_trail(
                state.tenant_id,
                run.id,
                &Value::Array(direct_execution_trail.clone()),
            )
            .await
            .map_err(ApiError::from_storage)?;
        let run = state
            .storage
            .assistant_runs()
            .attach_output_artifacts(
                state.tenant_id,
                run.id,
                &Value::Array(output_artifacts.clone()),
            )
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.xinbai_report_link_direct_answered".to_string(),
                    payload: json!({
                        "source": "curated_xinbai_report_link",
                        "public_url": assistant_run_xinbai_published_report_url(),
                    }),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.completed".to_string(),
                    payload: json!({
                        "service_lane": run.service_lane.clone(),
                        "runtime": runtime_manifest.clone(),
                    }),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        let events = state
            .storage
            .assistant_runs()
            .list_events(state.tenant_id, run.id)
            .await
            .map_err(ApiError::from_storage)?;
        let diagnostics = assistant_run_detail_diagnostics(&run, &events);

        return Ok((
            StatusCode::CREATED,
            Json(CreateAssistantRunResponse {
                assistant_run_id: run.id,
                assistant_message: AssistantRunMessageView {
                    role: ChatMessageRole::Assistant,
                    content: direct_answer,
                },
                runtime: run.runtime_manifest,
                selected_scope,
                scope_candidates: value_array(scope_candidates),
                evidence_state,
                execution_trail: direct_execution_trail,
                output_artifacts,
                required_confirmations: Vec::new(),
                diagnostics,
            }),
        ));
    }

    let react_outcome = if react_enabled_for_execution {
        match run_assistant_run_react_for_create(
            &state,
            &request,
            run.id,
            &selected_scope,
            evidence_state.clone(),
            local_thread_id.as_deref(),
            &active_secret_binding_ids,
            current_user_id,
            &react_runtime.mode,
            &react_runtime.provider,
            &react_runtime.model,
            &chat_runtime,
        )
        .await
        {
            Ok(outcome) => Some(outcome),
            Err(error) => {
                let stage = "react";
                record_assistant_run_create_failure(
                    &state,
                    run.id,
                    &execution_trail,
                    &error,
                    stage,
                )
                .await;
                return Err(assistant_run_create_error_with_run_context(
                    error, run.id, stage,
                ));
            }
        }
    } else {
        None
    };

    let (runtime_manifest, mut react_trail_steps, mut output_artifacts, react_events) =
        match react_outcome {
            Some(outcome) => {
                let mut outcome = outcome;
                evidence_state = outcome.evidence_state.clone();
                if let Some(retry_outcome) =
                    maybe_run_assistant_run_answer_quality_retry_for_artifacts(
                        &state,
                        &request,
                        run.id,
                        &selected_scope,
                        &evidence_state,
                        &outcome.output_artifacts,
                        local_thread_id.as_deref(),
                        &active_secret_binding_ids,
                        current_user_id,
                        &react_runtime,
                        &chat_runtime,
                    )
                    .await?
                {
                    evidence_state = retry_outcome.evidence_state;
                    outcome.runtime_manifest = retry_outcome.runtime_manifest;
                    outcome.execution_trail_steps.push(json!({
                        "status": "completed",
                        "label": "回答质量门禁扩供料",
                        "runtime_mode": react_runtime.mode.as_str(),
                        "provider": react_runtime.provider.as_str(),
                        "model": react_runtime.model.as_str(),
                        "at": Utc::now(),
                    }));
                    outcome
                        .execution_trail_steps
                        .extend(retry_outcome.execution_trail_steps);
                    outcome.output_artifacts = retry_outcome.output_artifacts;
                    outcome.events.extend(retry_outcome.events);
                }
                if let Some(direct_answer) =
                    assistant_run_answer_quality_spreadsheet_controlled_answer(
                        &outcome.evidence_state,
                        &request,
                    )
                {
                    outcome.output_artifacts = assistant_run_replace_assistant_message_content(
                        outcome.output_artifacts,
                        &direct_answer,
                    );
                    outcome.events.push(AssistantRunReactEvent {
                        event_name: "assistant_run.spreadsheet_row_analysis_direct_answered"
                            .to_string(),
                        payload: json!({
                            "source": "spreadsheet_row_analysis_direct_answer",
                            "reason": "attendance_row_analysis_prompt",
                            "assistant_message_chars": direct_answer.chars().count(),
                        }),
                    });
                }
                if let Some(direct_answer) = assistant_run_resume_project_delivery_controlled_answer(
                    &outcome.evidence_state,
                    &request,
                ) {
                    outcome.output_artifacts = assistant_run_replace_assistant_message_content(
                        outcome.output_artifacts,
                        &direct_answer,
                    );
                    outcome.events.push(AssistantRunReactEvent {
                        event_name: "assistant_run.resume_project_delivery_direct_answered"
                            .to_string(),
                        payload: json!({
                            "source": "resume_project_delivery_rows",
                            "reason": "multi_resume_project_delivery_prompt",
                            "assistant_message_chars": direct_answer.chars().count(),
                        }),
                    });
                }
                (
                    outcome.runtime_manifest,
                    outcome.execution_trail_steps,
                    outcome.output_artifacts,
                    outcome.events,
                )
            }
            None => {
                let mut skip_quality_retry = false;
                let response = if let Some(direct_answer) =
                    assistant_run_answer_quality_spreadsheet_controlled_answer(
                        &evidence_state,
                        &request,
                    ) {
                    skip_quality_retry = true;
                    let response = assistant_run_direct_answer_response(direct_answer);
                    state
                        .storage
                        .assistant_runs()
                        .append_event(
                            state.tenant_id,
                            run.id,
                            &NewAssistantRunEvent {
                                event_name:
                                    "assistant_run.spreadsheet_row_analysis_direct_answered"
                                        .to_string(),
                                payload: json!({
                                    "source": "spreadsheet_row_analysis_direct_answer",
                                    "reason": "attendance_row_analysis_prompt",
                                    "runtime": render_runtime_manifest(&response.runtime),
                                }),
                                created_at: Utc::now(),
                            },
                        )
                        .await
                        .map_err(ApiError::from_storage)?;
                    response
                } else if let Some(direct_answer) = deterministic_scan_direct_answer.clone() {
                    skip_quality_retry = true;
                    let response = assistant_run_direct_answer_response(direct_answer);
                    state
                        .storage
                        .assistant_runs()
                        .append_event(
                            state.tenant_id,
                            run.id,
                            &NewAssistantRunEvent {
                                event_name: "assistant_run.dataset_entity_scan_direct_answered"
                                    .to_string(),
                                payload: json!({
                                    "source": "dataset_entity_scan_direct_answer",
                                    "reason": "deterministic_scan_before_react",
                                    "runtime": render_runtime_manifest(&response.runtime),
                                }),
                                created_at: Utc::now(),
                            },
                        )
                        .await
                        .map_err(ApiError::from_storage)?;
                    response
                } else if let Some(direct_answer) =
                    assistant_run_preferred_dataset_entity_scan_direct_answer(
                        &request,
                        &evidence_state,
                    )
                {
                    skip_quality_retry = true;
                    let response = assistant_run_direct_answer_response(direct_answer);
                    state
                        .storage
                        .assistant_runs()
                        .append_event(
                            state.tenant_id,
                            run.id,
                            &NewAssistantRunEvent {
                                event_name: "assistant_run.dataset_entity_scan_direct_answered"
                                    .to_string(),
                                payload: json!({
                                    "source": "dataset_entity_scan_direct_answer",
                                    "reason": "company_statistics_prompt",
                                    "runtime": render_runtime_manifest(&response.runtime),
                                }),
                                created_at: Utc::now(),
                            },
                        )
                        .await
                        .map_err(ApiError::from_storage)?;
                    response
                } else {
                    let provider_input = if chat_runtime.mode == "placeholder" {
                        assistant_run_placeholder_user_message(false, &evidence_state)
                    } else {
                        build_assistant_run_provider_input_with_evidence(
                            &request,
                            Some(&evidence_state),
                        )
                    };
                    match complete_assistant_run_provider_for_create(
                        MODEL_LANE_ASSISTANT_CHAT,
                        chat_runtime.mode.clone(),
                        chat_runtime.provider.clone(),
                        chat_runtime.model.clone(),
                        provider_input,
                        live_delta_sink.clone(),
                    )
                    .await
                    {
                        Ok(response) => response,
                        Err(error) => {
                            if let Some(compact_provider_input) =
                                assistant_run_compact_provider_retry_input(
                                    &request,
                                    &evidence_state,
                                )
                            {
                                state
                                .storage
                                .assistant_runs()
                                .append_event(
                                    state.tenant_id,
                                    run.id,
                                    &NewAssistantRunEvent {
                                        event_name:
                                            "assistant_run.provider_compact_retry_started"
                                                .to_string(),
                                        payload: json!({
                                            "reason": "provider_failed_with_structured_scan_available",
                                            "previous_error_code": error.payload.code,
                                            "previous_error_status": error.status.as_u16(),
                                        }),
                                        created_at: Utc::now(),
                                    },
                                )
                                .await
                                .map_err(ApiError::from_storage)?;
                                match complete_assistant_run_provider_for_create(
                                    MODEL_LANE_ASSISTANT_CHAT,
                                    chat_runtime.mode.clone(),
                                    chat_runtime.provider.clone(),
                                    chat_runtime.model.clone(),
                                    compact_provider_input,
                                    live_delta_sink.clone(),
                                )
                                .await
                                {
                                    Ok(response) => {
                                        state
                                        .storage
                                        .assistant_runs()
                                        .append_event(
                                            state.tenant_id,
                                            run.id,
                                            &NewAssistantRunEvent {
                                                event_name:
                                                    "assistant_run.provider_compact_retry_completed"
                                                        .to_string(),
                                                payload: json!({
                                                    "source": "dataset_entity_scan_compact_retry",
                                                    "runtime": render_runtime_manifest(&response.runtime),
                                                }),
                                                created_at: Utc::now(),
                                            },
                                        )
                                        .await
                                        .map_err(ApiError::from_storage)?;
                                        response
                                    }
                                    Err(retry_error) => {
                                        if let Some(direct_answer) =
                                            assistant_run_dataset_entity_scan_direct_answer(
                                                &request,
                                                &evidence_state,
                                            )
                                        {
                                            let response =
                                                assistant_run_direct_answer_response(direct_answer);
                                            state
                                            .storage
                                            .assistant_runs()
                                            .append_event(
                                                state.tenant_id,
                                                run.id,
                                                &NewAssistantRunEvent {
                                                    event_name:
                                                        "assistant_run.provider_compact_retry_direct_answered"
                                                            .to_string(),
                                                    payload: json!({
                                                        "source": "dataset_entity_scan_direct_answer",
                                                        "previous_error_code": retry_error.payload.code,
                                                        "previous_error_status": retry_error.status.as_u16(),
                                                        "runtime": render_runtime_manifest(&response.runtime),
                                                    }),
                                                    created_at: Utc::now(),
                                                },
                                            )
                                            .await
                                            .map_err(ApiError::from_storage)?;
                                            response
                                        } else {
                                            state
                                        .storage
                                        .assistant_runs()
                                        .append_event(
                                            state.tenant_id,
                                            run.id,
                                            &NewAssistantRunEvent {
                                                event_name:
                                                    "assistant_run.provider_compact_retry_failed"
                                                        .to_string(),
                                                payload: json!({
                                                    "error_code": retry_error.payload.code,
                                                    "error_status": retry_error.status.as_u16(),
                                                }),
                                                created_at: Utc::now(),
                                            },
                                        )
                                        .await
                                        .map_err(ApiError::from_storage)?;
                                            let stage = "provider";
                                            record_assistant_run_create_failure(
                                                &state,
                                                run.id,
                                                &execution_trail,
                                                &retry_error,
                                                stage,
                                            )
                                            .await;
                                            return Err(
                                                assistant_run_create_error_with_run_context(
                                                    retry_error,
                                                    run.id,
                                                    stage,
                                                ),
                                            );
                                        }
                                    }
                                }
                            } else {
                                let stage = "provider";
                                record_assistant_run_create_failure(
                                    &state,
                                    run.id,
                                    &execution_trail,
                                    &error,
                                    stage,
                                )
                                .await;
                                return Err(assistant_run_create_error_with_run_context(
                                    error, run.id, stage,
                                ));
                            }
                        }
                    }
                };
                let mut runtime_manifest = render_runtime_manifest(&response.runtime);
                let mut retry_trail_steps = Vec::new();
                let mut retry_events = Vec::new();
                let mut output_artifacts = vec![json!({
                    "type": "assistant_message",
                    "role": ChatMessageRole::Assistant.as_str(),
                    "content": assistant_run_sanitize_customer_facing_answer_text(&response.output_text),
                })];
                if !skip_quality_retry {
                    if let Some(outcome) = maybe_run_assistant_run_answer_quality_retry_for_create(
                        &state,
                        &request,
                        run.id,
                        &selected_scope,
                        &evidence_state,
                        &response,
                        local_thread_id.as_deref(),
                        &active_secret_binding_ids,
                        current_user_id,
                        &react_runtime,
                        &chat_runtime,
                    )
                    .await?
                    {
                        evidence_state = outcome.evidence_state;
                        runtime_manifest = outcome.runtime_manifest;
                        retry_trail_steps = outcome.execution_trail_steps;
                        output_artifacts = outcome.output_artifacts;
                        retry_events = outcome.events;
                    }
                }
                (
                    runtime_manifest,
                    retry_trail_steps,
                    output_artifacts,
                    retry_events,
                )
            }
        };

    if react_enabled_for_execution {
        execution_trail.push(json!({
            "status": "completed",
            "label": "Host-Controlled ReAct 运行",
            "runtime_mode": runtime_mode_for_trail,
            "provider": runtime_provider_for_trail,
            "model": runtime_model_for_trail,
            "at": now,
        }));
        execution_trail.append(&mut react_trail_steps);
    } else if deterministic_scan_direct_answer_available {
        execution_trail.push(json!({
            "status": "completed",
            "label": "结构化扫描直接回答",
            "runtime_mode": runtime_mode_for_trail,
            "provider": runtime_provider_for_trail,
            "model": runtime_model_for_trail,
            "at": now,
        }));
    } else {
        execution_trail.push(json!({
            "status": "completed",
            "label": "普通聊天运行时返回",
            "runtime_mode": runtime_mode_for_trail,
            "provider": runtime_provider_for_trail,
            "model": runtime_model_for_trail,
            "at": now,
        }));
        if !react_trail_steps.is_empty() {
            execution_trail.push(json!({
                "status": "completed",
                "label": "回答质量门禁扩供料",
                "runtime_mode": react_runtime.mode.as_str(),
                "provider": react_runtime.provider.as_str(),
                "model": react_runtime.model.as_str(),
                "at": Utc::now(),
            }));
            execution_trail.append(&mut react_trail_steps);
        }
    }
    if let Some(artifact) =
        assistant_run_resume_project_delivery_html_artifact(run.id, &request, &evidence_state, now)
    {
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.resume_project_delivery_html_artifact_created"
                        .to_string(),
                    payload: json!({
                        "source": "resume_project_delivery_rows",
                        "reason": "high_information_resume_project_delivery_answer",
                        "generation_route": ASSISTANT_RUN_HTML_GENERATION_ROUTE_RAPID_ARTIFACT,
                        "image2_required": false,
                        "static_page_pipeline": false,
                        "html_artifacts": [artifact.clone()],
                    }),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        output_artifacts.push(json!({
            "type": "html_artifact",
            "id": artifact.id,
            "title": artifact.title,
            "template_id": "resume_project_delivery_matrix",
        }));
    }
    state
        .storage
        .assistant_runs()
        .update_runtime_manifest(state.tenant_id, run.id, &runtime_manifest)
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .assistant_runs()
        .update_evidence_state(state.tenant_id, run.id, &evidence_state)
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .assistant_runs()
        .update_execution_trail(
            state.tenant_id,
            run.id,
            &Value::Array(execution_trail.clone()),
        )
        .await
        .map_err(ApiError::from_storage)?;
    output_artifacts = assistant_run_sanitize_customer_facing_output_artifacts(output_artifacts);
    let run = state
        .storage
        .assistant_runs()
        .attach_output_artifacts(
            state.tenant_id,
            run.id,
            &Value::Array(output_artifacts.clone()),
        )
        .await
        .map_err(ApiError::from_storage)?;

    if let Some(executor_selection) = assistant_run_executor_transport_selection_from_env() {
        let codex_runtime = assistant_run_codex_runtime_selection();
        let codex_model_gateway = assistant_run_codex_model_gateway_snapshot(&codex_runtime);
        let codex_package = build_assistant_run_codex_context_package(
            run.id,
            run.local_thread_id.as_deref(),
            &request.prompt,
            &request.messages,
            &run.startup_briefing,
            &selected_scope,
            &codex_scope_candidates,
            &evidence_state,
            request.current_artifact.as_ref(),
            &codex_model_gateway,
            executor_selection.effective_transport.clone(),
        );
        let codex_output = execute_codex_conversation_plan(&codex_package);
        let codex_shadow_comparison = assistant_run_codex_shadow_comparison(
            &codex_output,
            react_enabled,
            &runtime_manifest,
            &output_artifacts,
            &react_events,
            &selected_scope,
            request.current_artifact.as_ref(),
        );
        execution_trail.extend(assistant_run_codex_execution_trail_entries(
            &codex_output,
            now,
            Some(&codex_shadow_comparison),
            Some(&executor_selection.policy),
        ));
        state
            .storage
            .assistant_runs()
            .update_execution_trail(
                state.tenant_id,
                run.id,
                &Value::Array(execution_trail.clone()),
            )
            .await
            .map_err(ApiError::from_storage)?;
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.codex_executor_diagnostic".to_string(),
                    payload: assistant_run_codex_event_payload(
                        &codex_output,
                        Some(&codex_shadow_comparison),
                        Some(&executor_selection.policy),
                    ),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
    }
    let react_event_names = react_events
        .iter()
        .map(|event| event.event_name.clone())
        .collect::<Vec<_>>();
    for event in react_events {
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: event.event_name,
                    payload: event.payload,
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
    }
    if let Some(case_package) = assistant_run_answer_quality_low_quality_case_package(
        run.id,
        &request,
        &selected_scope,
        &evidence_state,
        &output_artifacts,
        &react_event_names,
    ) {
        let enqueue_case_package = case_package.clone();
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.answer_quality_autofix.case_collected".to_string(),
                    payload: case_package,
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        assistant_run_answer_quality_autofix_enqueue_if_enabled(
            &state,
            run.id,
            &enqueue_case_package,
        )
        .await?;
    }
    state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run.id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.completed".to_string(),
                payload: json!({
                    "service_lane": run.service_lane.clone(),
                    "runtime": runtime_manifest.clone(),
                }),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    let events = state
        .storage
        .assistant_runs()
        .list_events(state.tenant_id, run.id)
        .await
        .map_err(ApiError::from_storage)?;
    let diagnostics = assistant_run_detail_diagnostics(&run, &events);

    Ok((
        StatusCode::CREATED,
        Json(CreateAssistantRunResponse {
            assistant_run_id: run.id,
            assistant_message: AssistantRunMessageView {
                role: ChatMessageRole::Assistant,
                content: output_artifacts
                    .first()
                    .and_then(|artifact| artifact.get("content"))
                    .and_then(Value::as_str)
                    .unwrap_or_default()
                    .to_string(),
            },
            runtime: run.runtime_manifest,
            selected_scope,
            scope_candidates: value_array(scope_candidates),
            evidence_state,
            execution_trail,
            output_artifacts,
            required_confirmations: Vec::new(),
            diagnostics,
        }),
    ))
}

