fn external_channel_static_page_existing_artifact_reply_from_events(
    events: &[AssistantRunEvent],
    conversation_external_id: &str,
) -> Option<ExternalBotReplyView> {
    let event = events.iter().rev().find(|event| {
        event.event_name == "assistant_run.external_channel_static_page_stable_artifact_reused"
            || (event.event_name == "assistant_run.external_channel_static_page_pipeline_queued"
                && external_channel_static_page_accepted_template_baseline(Some(&event.payload)))
    })?;
    let mut payload = event.payload.clone();
    if let Some(public_url) = external_channel_static_page_baseline_public_url(&payload) {
        set_payload_value(&mut payload, "public_url", json!(public_url));
        set_payload_value(&mut payload, "generated_artifact_url", json!(public_url));
        set_payload_value(&mut payload, "artifact_links", json!([public_url]));
    }
    let payload = external_channel_static_page_payload_with_event_intent(&payload, events);
    Some(external_channel_static_page_stable_artifact_reused_reply(
        conversation_external_id,
        &payload,
    ))
}

fn external_channel_static_page_fixed_task_reply_from_events(
    events: &[AssistantRunEvent],
    conversation_external_id: &str,
) -> Option<ExternalBotReplyView> {
    let latest_fixed = events.iter().rev().find(|event| {
        event.event_name.starts_with("codex_host.fixed_task.")
            && external_channel_fixed_task_template_id(event).as_deref()
                == Some("static_page_image2_data_publish")
    })?;
    let latest_publish_terminal = events
        .iter()
        .rev()
        .find(|event| {
            matches!(
                event.event_name.as_str(),
                "assistant_run.external_channel_static_page_publish_completed"
                    | "assistant_run.external_channel_static_page_publish_failed"
            )
        })
        .map(|event| event.sequence_no)
        .unwrap_or(i32::MIN);
    if latest_publish_terminal > latest_fixed.sequence_no {
        return None;
    }
    let fixed_event =
        external_channel_static_page_fixed_task_event_with_status_context(events, latest_fixed);
    let latest_cancelled = events
        .iter()
        .rev()
        .find(|event| event.event_name == "codex_host_task.cancelled");
    if let Some(cancelled) =
        latest_cancelled.filter(|cancelled| cancelled.sequence_no > latest_fixed.sequence_no)
    {
        return Some(external_channel_fixed_task_processing_reply(
            conversation_external_id,
            "static_page_image2_data_publish",
            "cancelled",
            &fixed_event,
            Some(cancelled),
        ));
    }
    let latest_exec_failed = events
        .iter()
        .rev()
        .find(|event| event.event_name == "codex_host_task.exec_failed");
    if let Some(failed) =
        latest_exec_failed.filter(|failed| failed.sequence_no > latest_fixed.sequence_no)
    {
        if external_channel_static_page_existing_artifact_reply_from_events(
            events,
            conversation_external_id,
        )
        .is_some()
        {
            return None;
        }
        return Some(external_channel_fixed_task_processing_reply(
            conversation_external_id,
            "static_page_image2_data_publish",
            "failed",
            &fixed_event,
            Some(failed),
        ));
    }
    let latest_poll_retry = events
        .iter()
        .rev()
        .find(|event| event.event_name == "codex_host_task.poll_retry");
    if let Some(retry) =
        latest_poll_retry.filter(|retry| retry.sequence_no > latest_fixed.sequence_no)
    {
        let retry_state = match retry.payload.get("reason").and_then(Value::as_str) {
            Some("cloudflare_orchestrator_submitted" | "cloudflare_orchestrator_pending") => {
                "running"
            }
            _ => "retrying",
        };
        return Some(external_channel_fixed_task_processing_reply(
            conversation_external_id,
            "static_page_image2_data_publish",
            retry_state,
            &fixed_event,
            Some(retry),
        ));
    }
    let latest_heartbeat = events.iter().rev().find(|event| {
        matches!(
            event.event_name.as_str(),
            "codex_host_task.cloudflare_heartbeat" | "codex_host_task.exec_heartbeat"
        )
    });
    if let Some(heartbeat) =
        latest_heartbeat.filter(|heartbeat| heartbeat.sequence_no > latest_fixed.sequence_no)
    {
        return Some(external_channel_fixed_task_processing_reply(
            conversation_external_id,
            "static_page_image2_data_publish",
            "running",
            &fixed_event,
            Some(heartbeat),
        ));
    }
    Some(external_channel_fixed_task_terminal_or_queued_reply(
        conversation_external_id,
        &fixed_event,
        "static_page_image2_data_publish",
    ))
}

fn external_channel_data_ingestion_analysis_reply_from_events(
    events: &[AssistantRunEvent],
    conversation_external_id: &str,
) -> Option<ExternalBotReplyView> {
    if let Some(event) = events
        .iter()
        .rev()
        .find(|event| event.event_name == "assistant_run.data_ingestion_staging_sync_updated")
    {
        let workflow_status = event
            .payload
            .get("workflow_status")
            .and_then(Value::as_str)
            .unwrap_or("running");
        let task_status = match workflow_status {
            "succeeded" => "data_ingestion_staging_sync_completed",
            "failed" | "dead_lettered" | "cancelled" => "data_ingestion_staging_sync_failed",
            _ => "data_ingestion_staging_sync_running",
        };
        let text = match task_status {
            "data_ingestion_staging_sync_completed" => {
                "DataMax 已完成 staging 数据集同步，后续可在该数据集上继续问答和生成报表。"
            }
            "data_ingestion_staging_sync_failed" => {
                "DataMax staging 数据集同步未完成，已记录失败阶段和原因，需重试或人工处理。"
            }
            _ => "DataMax staging 数据集同步正在执行，当前阶段已更新。",
        };
        return Some(external_channel_task_status_reply_for_conversation(
            conversation_external_id,
            task_status,
            Some(text.to_string()),
            Some(json!({
                "type": "v3_data_ingestion_staging_sync",
                "status": task_status,
                "template_id": "data_ingestion_analysis",
                "plan_id": event.payload.get("plan_id").cloned().unwrap_or(Value::Null),
                "dataset_id": event.payload.get("dataset_id").cloned().unwrap_or(Value::Null),
                "dataset_key": event.payload.get("dataset_key").cloned().unwrap_or(Value::Null),
                "dataset_title": event.payload.get("dataset_title").cloned().unwrap_or(Value::Null),
                "source_id": event.payload.get("source_id").cloned().unwrap_or(Value::Null),
                "sync_run_id": event.payload.get("sync_run_id").cloned().unwrap_or(Value::Null),
                "sync_kind": event.payload.get("sync_kind").cloned().unwrap_or(Value::Null),
                "workflow_execution_id": event.payload.get("workflow_execution_id").cloned().unwrap_or(Value::Null),
                "workflow_status": event.payload.get("workflow_status").cloned().unwrap_or(Value::Null),
                "workflow_stage": event.payload.get("workflow_stage").cloned().unwrap_or(Value::Null),
                "failure_kind": event.payload.get("failure_kind").cloned().unwrap_or(Value::Null),
                "last_error": event.payload.get("last_error").cloned().unwrap_or(Value::Null),
                "production_write_allowed": false,
                "raw_table_dump_imported": false,
                "next_step": event.payload.get("next_step").cloned().unwrap_or(Value::Null),
            })),
            Vec::new(),
        ));
    }
    if let Some(event) = events
        .iter()
        .rev()
        .find(|event| event.event_name == "assistant_run.data_ingestion_staging_sync_started")
    {
        return Some(external_channel_task_status_reply_for_conversation(
            conversation_external_id,
            "data_ingestion_staging_sync_started",
            Some(
                "DataMax 已启动 staging 数据集同步任务，后续会继续进入数据集入库和索引流程。"
                    .to_string(),
            ),
            Some(json!({
                "type": "v3_data_ingestion_staging_sync",
                "status": "data_ingestion_staging_sync_started",
                "template_id": "data_ingestion_analysis",
                "plan_id": event.payload.get("plan_id").cloned().unwrap_or(Value::Null),
                "dataset_id": event.payload.get("dataset_id").cloned().unwrap_or(Value::Null),
                "dataset_key": event.payload.get("dataset_key").cloned().unwrap_or(Value::Null),
                "dataset_title": event.payload.get("dataset_title").cloned().unwrap_or(Value::Null),
                "source_id": event.payload.get("source_id").cloned().unwrap_or(Value::Null),
                "sync_run_id": event.payload.get("sync_run_id").cloned().unwrap_or(Value::Null),
                "sync_kind": event.payload.get("sync_kind").cloned().unwrap_or(Value::Null),
                "workflow_execution_id": event.payload.get("workflow_execution_id").cloned().unwrap_or(Value::Null),
                "enqueued_task_count": event.payload.get("enqueued_task_count").cloned().unwrap_or(Value::from(0)),
                "production_write_allowed": false,
                "raw_table_dump_imported": false,
                "next_step": event.payload.get("next_step").cloned().unwrap_or(Value::Null),
            })),
            Vec::new(),
        ));
    }
    if let Some(event) = events
        .iter()
        .rev()
        .find(|event| event.event_name == "assistant_run.data_ingestion_staging_plan_confirmed")
    {
        return Some(external_channel_task_status_reply_for_conversation(
            conversation_external_id,
            "data_ingestion_staging_dataset_ready",
            Some(
                "DataMax 已按人工确认创建或复用 staging 数据集，后续可继续导入数据或生成报表。"
                    .to_string(),
            ),
            Some(json!({
                "type": "v3_data_ingestion_staging_plan_execution",
                "status": "data_ingestion_staging_dataset_ready",
                "template_id": "data_ingestion_analysis",
                "plan_id": event.payload.get("plan_id").cloned().unwrap_or(Value::Null),
                "dataset_id": event.payload.get("dataset_id").cloned().unwrap_or(Value::Null),
                "dataset_key": event.payload.get("dataset_key").cloned().unwrap_or(Value::Null),
                "dataset_title": event.payload.get("dataset_title").cloned().unwrap_or(Value::Null),
                "created_dataset": event.payload.get("created_dataset").cloned().unwrap_or(Value::Bool(false)),
                "imported_row_count": event.payload.get("imported_row_count").cloned().unwrap_or(Value::from(0)),
                "production_write_allowed": false,
                "raw_table_dump_imported": false,
                "next_step": event.payload.get("next_step").cloned().unwrap_or(Value::Null),
            })),
            Vec::new(),
        ));
    }
    let event = events.iter().rev().find(|event| {
        matches!(
            event.event_name.as_str(),
            "assistant_run.data_ingestion_analysis_completed"
                | "assistant_run.data_ingestion_analysis_needs_human"
                | "assistant_run.data_ingestion_analysis_failed"
        )
    })?;
    let task_status = match event.event_name.as_str() {
        "assistant_run.data_ingestion_analysis_completed" => "data_ingestion_analysis_completed",
        "assistant_run.data_ingestion_analysis_needs_human" => {
            "data_ingestion_analysis_needs_human"
        }
        _ => "data_ingestion_analysis_failed",
    };
    let text = match event.event_name.as_str() {
        "assistant_run.data_ingestion_analysis_completed" => {
            "DataMax 已完成数据接入分析，已生成只读质量报告、字段映射和 staging 建议。"
        }
        "assistant_run.data_ingestion_analysis_needs_human" => {
            "DataMax 已完成数据接入分析，但继续入库或改 schema 前需要人工确认。"
        }
        _ => "DataMax 数据接入分析未完成，已记录失败原因，需重试或人工处理。",
    };
    let result_summary = event
        .payload
        .get("result_summary")
        .cloned()
        .unwrap_or(Value::Null);
    Some(external_channel_task_status_reply_for_conversation(
        conversation_external_id,
        task_status,
        Some(text.to_string()),
        Some(json!({
            "type": "v3_data_ingestion_analysis_result",
            "status": task_status,
            "template_id": "data_ingestion_analysis",
            "codex_host_workflow_execution_id": event
                .payload
                .get("codex_host_workflow_execution_id")
                .cloned()
                .unwrap_or(Value::Null),
            "result_summary": result_summary,
            "staging_plan": event
                .payload
                .get("staging_plan")
                .cloned()
                .unwrap_or(Value::Null),
            "staging_plan_available": event
                .payload
                .get("staging_plan_available")
                .cloned()
                .unwrap_or(Value::Bool(false)),
            "human_review_required": event
                .payload
                .get("human_review_required")
                .cloned()
                .unwrap_or(Value::Bool(task_status != "data_ingestion_analysis_completed")),
            "staging_spec_available": event
                .payload
                .get("staging_spec_available")
                .cloned()
                .unwrap_or(Value::Bool(false)),
        })),
        Vec::new(),
    ))
}

fn external_channel_fixed_task_reply_from_events(
    events: &[AssistantRunEvent],
    conversation_external_id: &str,
) -> Option<ExternalBotReplyView> {
    let latest_fixed = events
        .iter()
        .rev()
        .find(|event| event.event_name.starts_with("codex_host.fixed_task."));
    let latest_data_ingestion_queued = events
        .iter()
        .rev()
        .find(|event| event.event_name == "assistant_run.data_ingestion_analysis_queued");
    let latest_poll_retry = events
        .iter()
        .rev()
        .find(|event| event.event_name == "codex_host_task.poll_retry");
    let latest_heartbeat = events.iter().rev().find(|event| {
        matches!(
            event.event_name.as_str(),
            "codex_host_task.cloudflare_heartbeat" | "codex_host_task.exec_heartbeat"
        )
    });
    let latest_exec_failed = events
        .iter()
        .rev()
        .find(|event| event.event_name == "codex_host_task.exec_failed");
    let latest_cancelled = events
        .iter()
        .rev()
        .find(|event| event.event_name == "codex_host_task.cancelled");

    if let Some(fixed) = latest_fixed {
        let template_id = external_channel_fixed_task_template_id(fixed)?;
        if let Some(cancelled) =
            latest_cancelled.filter(|cancelled| cancelled.sequence_no > fixed.sequence_no)
        {
            return Some(external_channel_fixed_task_processing_reply(
                conversation_external_id,
                &template_id,
                "cancelled",
                fixed,
                Some(cancelled),
            ));
        }
        if let Some(failed) =
            latest_exec_failed.filter(|failed| failed.sequence_no > fixed.sequence_no)
        {
            return Some(external_channel_fixed_task_processing_reply(
                conversation_external_id,
                &template_id,
                "failed",
                fixed,
                Some(failed),
            ));
        }
        if let Some(retry) = latest_poll_retry.filter(|retry| retry.sequence_no > fixed.sequence_no)
        {
            return Some(external_channel_fixed_task_processing_reply(
                conversation_external_id,
                &template_id,
                "retrying",
                fixed,
                Some(retry),
            ));
        }
        if let Some(heartbeat) =
            latest_heartbeat.filter(|heartbeat| heartbeat.sequence_no > fixed.sequence_no)
        {
            return Some(external_channel_fixed_task_processing_reply(
                conversation_external_id,
                &template_id,
                "running",
                fixed,
                Some(heartbeat),
            ));
        }
        return Some(external_channel_fixed_task_terminal_or_queued_reply(
            conversation_external_id,
            fixed,
            &template_id,
        ));
    }

    latest_data_ingestion_queued.map(|event| {
        external_channel_task_status_reply_for_conversation(
            conversation_external_id,
            "data_ingestion_analysis_queued",
            Some("DataMax 已提交数据接入分析任务，正在生成只读分析和入库建议。".to_string()),
            Some(json!({
                "type": "v3_data_ingestion_analysis",
                "status": "data_ingestion_analysis_queued",
                "template_id": event
                    .payload
                    .get("template_id")
                    .cloned()
                    .unwrap_or_else(|| json!("data_ingestion_analysis")),
                "codex_host_workflow_execution_id": event
                    .payload
                    .get("codex_host_workflow_execution_id")
                    .cloned()
                    .unwrap_or(Value::Null),
                "poll_after_seconds": 15,
            })),
            Vec::new(),
        )
    })
}

fn external_channel_fixed_task_processing_reply(
    conversation_external_id: &str,
    template_id: &str,
    state: &str,
    fixed_event: &AssistantRunEvent,
    runtime_event: Option<&AssistantRunEvent>,
) -> ExternalBotReplyView {
    let prefix = external_channel_fixed_task_status_prefix(template_id);
    let task_status = format!("{prefix}_{state}");
    let text = match (template_id, state) {
        ("data_ingestion_analysis", "retrying") => {
            "DataMax 数据接入分析仍在执行，后台任务超时后已自动续轮询。"
        }
        ("data_ingestion_analysis", "cancelled") => {
            "DataMax 数据接入分析任务已取消，未写入生产库，也未继续修改数据集。"
        }
        ("data_ingestion_analysis", "failed") => {
            "DataMax 数据接入分析未完成，已记录失败原因，需重试或人工处理。"
        }
        ("data_ingestion_analysis", _) => "DataMax 数据接入分析正在执行，请稍后查询结果。",
        ("static_page_image2_data_publish", "retrying") => {
            "DataMax 静态页发布仍在执行，后台任务超时后已自动续轮询。"
        }
        ("static_page_image2_data_publish", "cancelled") => {
            "DataMax 静态页发布任务已取消，未生成新的最终发布链接。"
        }
        ("static_page_image2_data_publish", "failed") => {
            "DataMax 静态页发布未完成，需重试或人工处理。"
        }
        ("static_page_image2_data_publish", _) => "DataMax 已完成页面规划，正在生成最终静态页。",
        ("answer_quality_autofix", "cancelled") => {
            "DataMax 回答质量修复诊断任务已取消，未应用任何代码或配置变更。"
        }
        ("answer_quality_autofix", "retrying") => {
            "DataMax 回答质量修复诊断仍在执行，已自动续轮询。"
        }
        ("answer_quality_autofix", "failed") => "DataMax 回答质量修复诊断未完成。",
        ("answer_quality_autofix", _) => "DataMax 回答质量修复诊断正在执行。",
        (_, "cancelled") => "DataMax 后台任务已取消。",
        (_, "retrying") => "DataMax 后台任务仍在执行，已自动续轮询。",
        (_, "failed") => "DataMax 后台任务未完成，需重试或人工处理。",
        _ => "DataMax 后台任务正在执行。",
    };
    external_channel_task_status_reply_for_conversation(
        conversation_external_id,
        &task_status,
        Some(text.to_string()),
        Some(json!({
            "type": external_channel_fixed_task_card_type(template_id),
            "status": task_status,
            "template_id": template_id,
            "codex_host_workflow_execution_id": external_channel_fixed_task_workflow_execution_id(fixed_event),
            "status_url": fixed_event.payload.get("status_url").cloned().unwrap_or(Value::Null),
            "status_method": fixed_event.payload.get("status_method").cloned().unwrap_or_else(|| json!("GET")),
            "recipient_delivery": external_channel_recipient_delivery_from_payload(&fixed_event.payload),
            "permission_review_status": external_channel_permission_review_status_from_payload(&fixed_event.payload),
            "editable_after_publish": external_channel_editable_after_publish_from_payload(&fixed_event.payload),
            "runtime_event": runtime_event.map(|event| json!({
                "event_name": event.event_name.clone(),
                "status": event.payload.get("status").cloned().unwrap_or(Value::Null),
                "reason": event
                    .payload
                    .get("reason")
                    .and_then(Value::as_str)
                    .map(codex_host_fixed_task_safe_text)
                    .unwrap_or_default(),
                "retryable": event.payload.get("retryable").cloned().unwrap_or(Value::Null),
                "attempt": event.payload.get("attempt").cloned().unwrap_or(Value::Null),
                "max_attempts": event.payload.get("max_attempts").cloned().unwrap_or(Value::Null),
                "available_at": event.payload.get("available_at").cloned().unwrap_or(Value::Null),
                "elapsed_ms": event.payload.get("elapsed_ms").cloned().unwrap_or(Value::Null),
                "heartbeat_count": event.payload.get("heartbeat_count").cloned().unwrap_or(Value::Null),
            })).unwrap_or(Value::Null),
            "poll_after_seconds": match state {
                "retrying" => Value::from(30),
                "cancelled" | "failed" => Value::Null,
                _ => Value::from(15),
            },
        })),
        Vec::new(),
    )
}

fn external_channel_fixed_task_terminal_or_queued_reply(
    conversation_external_id: &str,
    event: &AssistantRunEvent,
    template_id: &str,
) -> ExternalBotReplyView {
    let event_status = event
        .payload
        .get("status")
        .and_then(Value::as_str)
        .unwrap_or("queued");
    let prefix = external_channel_fixed_task_status_prefix(template_id);
    let terminal_state = match event.event_name.as_str() {
        "codex_host.fixed_task.completed" => "completed",
        "codex_host.fixed_task.needs_human" => "needs_human",
        "codex_host.fixed_task.rejected" => "failed",
        _ => "queued",
    };
    let task_status = match (template_id, terminal_state) {
        ("static_page_image2_data_publish", "completed") => "static_page_published".to_string(),
        _ => format!("{prefix}_{terminal_state}"),
    };
    let artifact_url = event
        .payload
        .pointer("/output/artifact_public_url")
        .and_then(Value::as_str)
        .filter(|url| codex_host_fixed_task_public_artifact_url_allowed(url))
        .map(str::to_string);
    let text = match (template_id, terminal_state) {
        ("data_ingestion_analysis", "completed") => {
            "DataMax 已完成数据接入分析，已生成只读质量报告、字段映射和后续动作建议。"
        }
        ("data_ingestion_analysis", "needs_human") => {
            "DataMax 数据接入分析需要人工确认后继续，当前不会自动写库或修改 schema。"
        }
        ("data_ingestion_analysis", "failed") => {
            "DataMax 数据接入分析未完成，已记录失败原因，需重试或人工处理。"
        }
        ("data_ingestion_analysis", _) => "DataMax 已提交数据接入分析任务。",
        ("static_page_image2_data_publish", "completed") => "DataMax 静态页已生成并发布。",
        ("static_page_image2_data_publish", "needs_human") => {
            "DataMax 静态页发布需要人工确认或处理。"
        }
        ("static_page_image2_data_publish", "failed") => {
            "DataMax 静态页发布未完成，需重试或人工处理。"
        }
        ("static_page_image2_data_publish", _) => "DataMax 已提交静态页发布任务。",
        ("answer_quality_autofix", "completed") => "DataMax 已完成回答质量修复诊断。",
        ("answer_quality_autofix", "needs_human") => "DataMax 回答质量修复诊断需要人工审查后继续。",
        ("answer_quality_autofix", "failed") => "DataMax 回答质量修复诊断未完成。",
        ("answer_quality_autofix", _) => "DataMax 已提交回答质量修复诊断任务。",
        (_, "completed") => "DataMax 后台任务已完成。",
        (_, "needs_human") => "DataMax 后台任务需要人工处理。",
        (_, "failed") => "DataMax 后台任务未完成，需重试或人工处理。",
        _ => "DataMax 后台任务已提交。",
    };
    let card = json!({
        "type": external_channel_fixed_task_card_type(template_id),
        "status": task_status,
        "template_id": template_id,
        "output_status": event_status,
        "codex_host_workflow_execution_id": external_channel_fixed_task_workflow_execution_id(event),
        "status_url": event.payload.get("status_url").cloned().unwrap_or(Value::Null),
        "status_method": event.payload.get("status_method").cloned().unwrap_or_else(|| json!("GET")),
        "recipient_delivery": external_channel_recipient_delivery_from_payload(&event.payload),
        "permission_review_status": external_channel_permission_review_status_from_payload(&event.payload),
        "editable_after_publish": external_channel_editable_after_publish_from_payload(&event.payload),
        "artifact_public_url": artifact_url.clone().map(Value::String).unwrap_or(Value::Null),
        "output": event.payload.get("output").cloned().unwrap_or(Value::Null),
        "validation": event.payload.get("validation").cloned().unwrap_or(Value::Null),
        "poll_after_seconds": if terminal_state == "queued" { Value::from(15) } else { Value::Null },
    });
    external_channel_task_status_reply_for_conversation(
        conversation_external_id,
        &task_status,
        Some(text.to_string()),
        Some(card),
        artifact_url.into_iter().collect(),
    )
}

fn external_channel_static_page_latest_codex_heartbeat_after(
    events: &[AssistantRunEvent],
    sequence_no: i32,
) -> Option<&AssistantRunEvent> {
    events.iter().rev().find(|event| {
        event.sequence_no > sequence_no
            && matches!(
                event.event_name.as_str(),
                "codex_host_task.cloudflare_heartbeat" | "codex_host_task.exec_heartbeat"
            )
    })
}

fn external_channel_static_page_latest_named_event<'a>(
    events: &'a [AssistantRunEvent],
    event_name: &str,
) -> Option<&'a AssistantRunEvent> {
    events
        .iter()
        .rev()
        .find(|event| event.event_name == event_name)
}

