async fn enrich_external_channel_database_source_scope(
    state: &AppState,
    connection: &ExternalChannelConnectionSummary,
    message: &ExternalBotMessageView,
    prompt: &str,
    selected_scope: &mut Value,
) -> std::result::Result<(), ApiError> {
    let explicit_business_source_ids = message
        .business_datasource_ids
        .iter()
        .filter_map(|value| non_empty_trimmed_string(value))
        .collect::<BTreeSet<_>>();
    if explicit_business_source_ids.is_empty()
        && !external_channel_message_requests_static_page_artifact(message, prompt)
        && !assistant_run_database_schema_context_requested(prompt)
    {
        return Ok(());
    }

    let requested_source_ids = if explicit_business_source_ids.is_empty() {
        let mut allowed = external_channel_allowed_database_source_ids(&connection.config_redacted);
        if let Some(default_source_id) =
            external_channel_default_source_id_from_config(&connection.config_redacted)
        {
            allowed.insert(default_source_id);
        }
        allowed
    } else {
        for source_id in &explicit_business_source_ids {
            ensure_external_channel_database_source_allowed(connection, source_id)?;
        }
        explicit_business_source_ids
    };
    if requested_source_ids.is_empty() {
        return Ok(());
    }

    let mut database_source_ids = BTreeSet::new();
    let mut database_dataset_bindings = Vec::new();
    for source_id in requested_source_ids {
        let source = match load_enabled_database_source_connection(state, &source_id).await {
            Ok(source) => source,
            Err(_) => continue,
        };
        database_source_ids.insert(source.source_id.clone());
        let default_dataset_id = mysql_source_config_for_request(&source, &Value::Null)
            .ok()
            .and_then(|config| config.default_dataset_id)
            .and_then(|raw| Uuid::parse_str(raw.trim()).ok())
            .map(DatasetId);
        if let Some(dataset_id) = default_dataset_id {
            database_dataset_bindings.push((source.source_id.clone(), dataset_id));
        }
    }
    if database_source_ids.is_empty() {
        return Ok(());
    }

    set_payload_value(
        selected_scope,
        "database_source_ids",
        json!(database_source_ids.iter().cloned().collect::<Vec<_>>()),
    );
    if !database_dataset_bindings.is_empty() {
        append_database_source_default_datasets_to_scope(
            selected_scope,
            &database_dataset_bindings,
        );
    }
    set_payload_value(
        selected_scope,
        "database_source_scope",
        json!({
            "source": "external_channel_allowed_database_sources",
            "source_ids": database_source_ids.iter().cloned().collect::<Vec<_>>(),
            "requested_business_datasource_ids": message.business_datasource_ids,
            "default_dataset_bindings": database_dataset_bindings
                .iter()
                .map(|(source_id, dataset_id)| json!({
                    "source_id": source_id,
                    "dataset_id": dataset_id,
                }))
                .collect::<Vec<_>>(),
            "policy": if message.business_datasource_ids.is_empty() {
                "connection_allowed_database_sources_for_report_workflow"
            } else {
                "explicit_business_datasource_ids"
            },
        }),
    );
    Ok(())
}

fn append_database_source_default_datasets_to_scope(
    selected_scope: &mut Value,
    bindings: &[(String, DatasetId)],
) {
    let mut datasets = selected_scope
        .get("datasets")
        .and_then(Value::as_array)
        .cloned()
        .unwrap_or_default();
    for (source_id, dataset_id) in bindings {
        if datasets
            .iter()
            .filter_map(dataset_id_from_scope_item)
            .any(|existing| existing == *dataset_id)
        {
            continue;
        }
        datasets.push(json!({
            "type": "dataset",
            "id": dataset_id,
            "source": "database_source_default_dataset",
            "database_source_id": source_id,
        }));
    }
    set_payload_value(selected_scope, "datasets", Value::Array(datasets));
}

async fn find_static_page_xinbai_primary_template_baseline_by_public_url(
    state: &AppState,
    current_prompt: Option<&str>,
    selected_scope: &Value,
    source_refs: &Value,
    current_user_id: Option<UserId>,
    connection_id: Option<&str>,
    current_tokens: &BTreeSet<String>,
) -> std::result::Result<Option<(StaticPageDraft, StaticPageTemplateBaselineScore)>, ApiError> {
    if !static_page_template_context_prefers_xinbai_primary(
        current_prompt,
        selected_scope,
        source_refs,
    ) {
        return Ok(None);
    }
    let mut candidate_urls = vec![assistant_run_xinbai_published_report_url()];
    if candidate_urls
        .iter()
        .all(|url| url != XINBAI_PUBLISHED_REPORT_DEFAULT_PUBLIC_URL)
    {
        candidate_urls.push(XINBAI_PUBLISHED_REPORT_DEFAULT_PUBLIC_URL.to_string());
    }
    for public_url in candidate_urls {
        let Some(draft) = state
            .storage
            .static_page_drafts()
            .find_accepted_baseline_by_public_url(state.tenant_id, &public_url)
            .await
            .map_err(ApiError::from_storage)?
        else {
            continue;
        };
        if !static_page_draft_is_accepted_template_baseline(&draft)
            || static_page_draft_is_template_fallback_baseline(&draft)
            || static_page_template_draft_is_non_default_noise_baseline(&draft)
            || static_page_template_draft_is_local_generated_report_instance(&draft)
            || !static_page_template_draft_is_xinbai_primary_default_template(&draft)
            || static_page_published_public_url_from_draft(&draft).is_none()
        {
            continue;
        }
        let draft_connection_id = external_channel_static_page_source_ref_string(
            &draft.source_refs,
            "channel_connection_id",
        );
        let visible_by_owner = static_page_owner_is_visible(draft.owner_user_id, current_user_id);
        let visible_by_same_channel = connection_id
            .is_some_and(|connection_id| draft_connection_id.as_deref() == Some(connection_id));
        if !visible_by_owner && !visible_by_same_channel {
            continue;
        }
        if let Some(connection_id) = connection_id {
            if draft_connection_id
                .as_deref()
                .is_some_and(|value| value != connection_id)
            {
                continue;
            }
        }
        if !static_page_template_intent_compatible(current_prompt, &draft) {
            continue;
        }
        let baseline_tokens =
            static_page_template_match_tokens(&draft.selected_scope, &draft.source_refs);
        let mut candidate_score = static_page_template_baseline_score(
            current_prompt,
            selected_scope,
            source_refs,
            current_tokens,
            &draft,
            &baseline_tokens,
        );
        candidate_score.add(120, "pinned_xinbai_primary_public_url_lookup");
        return Ok(Some((draft, candidate_score)));
    }
    Ok(None)
}

async fn find_static_page_template_baseline_by_dataset_overlap(
    state: &AppState,
    current_prompt: Option<&str>,
    selected_scope: &Value,
    source_refs: &Value,
    current_user_id: Option<UserId>,
    connection_id: Option<&str>,
) -> std::result::Result<StaticPageTemplateOverlapSearchOutcome, ApiError> {
    let current_tokens = static_page_template_match_tokens(selected_scope, source_refs);
    let mut outcome = StaticPageTemplateOverlapSearchOutcome {
        draft: None,
        selected_score: None,
        selected_features: Vec::new(),
        current_token_count: current_tokens.len(),
        accepted_baseline_count: 0,
        visible_published_baseline_count: 0,
        scope_intersection_count: 0,
        template_intent_match_count: 0,
        template_intent_mismatch_count: 0,
        default_prompt_match_count: 0,
        default_prompt_mismatch_count: 0,
    };
    if current_tokens.is_empty() {
        return Ok(outcome);
    }
    let current_prefers_xinbai_primary = static_page_template_context_prefers_xinbai_primary(
        current_prompt,
        selected_scope,
        source_refs,
    );
    if current_prefers_xinbai_primary {
        if let Some((draft, score)) =
            find_static_page_xinbai_primary_template_baseline_by_public_url(
                state,
                current_prompt,
                selected_scope,
                source_refs,
                current_user_id,
                connection_id,
                &current_tokens,
            )
            .await?
        {
            outcome.accepted_baseline_count = 1;
            outcome.visible_published_baseline_count = 1;
            outcome.scope_intersection_count = 1;
            outcome.template_intent_match_count = 1;
            outcome.default_prompt_match_count = 1;
            outcome.selected_score = Some(score.score);
            outcome.selected_features = score.features;
            outcome.draft = Some(draft);
            return Ok(outcome);
        }
    }
    let baselines = state
        .storage
        .static_page_drafts()
        .list_accepted_baselines(state.tenant_id, 100)
        .await
        .map_err(ApiError::from_storage)?;

    let mut best_match: Option<(StaticPageDraft, StaticPageTemplateBaselineScore)> = None;
    let mut best_xinbai_primary_match: Option<(StaticPageDraft, StaticPageTemplateBaselineScore)> =
        None;
    for draft in baselines {
        if !static_page_draft_is_accepted_template_baseline(&draft) {
            continue;
        }
        outcome.accepted_baseline_count += 1;
        let draft_connection_id = external_channel_static_page_source_ref_string(
            &draft.source_refs,
            "channel_connection_id",
        );
        if let Some(connection_id) = connection_id {
            if draft_connection_id
                .as_deref()
                .is_some_and(|value| value != connection_id)
            {
                continue;
            }
        }
        let visible_by_owner = static_page_owner_is_visible(draft.owner_user_id, current_user_id);
        let visible_by_same_channel = connection_id
            .is_some_and(|connection_id| draft_connection_id.as_deref() == Some(connection_id));
        if !visible_by_owner && !visible_by_same_channel {
            continue;
        }
        if static_page_draft_is_template_fallback_baseline(&draft) {
            continue;
        }
        if static_page_template_draft_is_non_default_noise_baseline(&draft) {
            continue;
        }
        if static_page_template_draft_is_local_generated_report_instance(&draft) {
            continue;
        }
        if static_page_published_public_url_from_draft(&draft).is_none() {
            continue;
        }
        outcome.visible_published_baseline_count += 1;
        let baseline_tokens =
            static_page_template_match_tokens(&draft.selected_scope, &draft.source_refs);
        if !static_page_template_tokens_intersect(&current_tokens, &baseline_tokens) {
            continue;
        }
        outcome.scope_intersection_count += 1;
        if !static_page_template_intent_compatible(current_prompt, &draft) {
            outcome.template_intent_mismatch_count += 1;
            continue;
        }
        outcome.template_intent_match_count += 1;
        if static_page_default_prompt_tokens_match(
            selected_scope,
            source_refs,
            &draft.selected_scope,
            &draft.source_refs,
        ) {
            outcome.default_prompt_match_count += 1;
            let candidate_score = static_page_template_baseline_score(
                current_prompt,
                selected_scope,
                source_refs,
                &current_tokens,
                &draft,
                &baseline_tokens,
            );
            let draft_is_xinbai_primary =
                static_page_template_draft_is_xinbai_primary_default_template(&draft);
            if current_prefers_xinbai_primary && !draft_is_xinbai_primary {
                continue;
            }
            if draft_is_xinbai_primary {
                let should_replace = best_xinbai_primary_match
                    .as_ref()
                    .is_none_or(|(_, best_score)| candidate_score.score > best_score.score);
                if should_replace {
                    best_xinbai_primary_match = Some((draft, candidate_score));
                }
                continue;
            }
            let should_replace = best_match
                .as_ref()
                .is_none_or(|(_, best_score)| candidate_score.score > best_score.score);
            if should_replace {
                best_match = Some((draft, candidate_score));
            }
            continue;
        }
        outcome.default_prompt_mismatch_count += 1;
    }
    let selected_match = best_xinbai_primary_match.or(best_match);
    if let Some((draft, score)) = selected_match {
        outcome.selected_score = Some(score.score);
        outcome.selected_features = score.features;
        outcome.draft = Some(draft);
    }
    Ok(outcome)
}

async fn static_page_template_prewarm_pending_exists(
    state: &AppState,
    prewarm_key: &str,
) -> std::result::Result<bool, ApiError> {
    let exists = sqlx::query_scalar::<_, bool>(
        r#"
        select exists (
            select 1
            from workflow_executions e
            join workflow_tasks t on t.execution_id = e.id
            where e.tenant_id = $1
              and (
                coalesce(e.context->>'prewarm_key', '') = $2
                or coalesce(t.payload->>'prewarm_key', '') = $2
                or coalesce(t.payload #>> '{source_refs,prewarm,key}', '') = $2
              )
              and e.status in ('pending', 'running')
              and t.status in ('queued', 'claimed')
        )
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(prewarm_key)
    .fetch_one(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;
    Ok(exists)
}

async fn maybe_enqueue_external_channel_static_page_template_prewarm(
    state: &AppState,
    connection_id: &str,
    run: &AssistantRun,
    assistant_request: &CreateAssistantRunRequest,
    message: &ExternalBotMessageView,
    now: DateTime<Utc>,
) -> std::result::Result<(), ApiError> {
    if !platform_env_flag("STATIC_PAGE_TEMPLATE_PREWARM_ENABLED", false) {
        return Ok(());
    }
    if external_channel_message_requests_static_page_artifact(message, &assistant_request.prompt)
        || external_channel_message_requests_data_ingestion_analysis(&assistant_request.prompt)
    {
        return Ok(());
    }

    let selected_scope = assistant_request
        .selected_scope
        .as_ref()
        .unwrap_or(&run.selected_scope);
    let Some(candidate) =
        static_page_template_prewarm_candidate(connection_id, selected_scope, message)
    else {
        return Ok(());
    };

    if let Some(dataset_artifact_key) = candidate.dataset_artifact_key.as_deref() {
        if state
            .storage
            .static_page_drafts()
            .find_latest_accepted_baseline_by_artifact_key(state.tenant_id, dataset_artifact_key)
            .await
            .map_err(ApiError::from_storage)?
            .as_ref()
            .filter(|draft| static_page_draft_is_accepted_template_baseline(draft))
            .and_then(|draft| static_page_published_public_url_from_draft(draft))
            .is_some()
        {
            return Ok(());
        }
    }

    let overlap_outcome = find_static_page_template_baseline_by_dataset_overlap(
        state,
        message.text.as_deref(),
        selected_scope,
        &candidate.source_refs,
        None,
        Some(connection_id),
    )
    .await?;
    if overlap_outcome.draft.is_some() {
        return Ok(());
    }
    if static_page_template_prewarm_pending_exists(state, &candidate.prewarm_key).await? {
        return Ok(());
    }

    let available_at = static_page_template_prewarm_delay(now);
    let prewarm_prompt = static_page_template_prewarm_prompt(message);
    let draft_outcome = create_static_page_draft_for_assistant_run_id(
        state,
        run.id,
        None,
        CreateStaticPageDraftRequest {
            title: Some("DataMax 静态页模板预热".to_string()),
            prompt: Some(prewarm_prompt.clone()),
            template_reference_id: None,
            selected_scope: Some(selected_scope.clone()),
            visibility_snapshot: None,
            source_refs: candidate.source_refs.clone(),
            draft_payload: Value::Null,
        },
    )
    .await?;
    if static_page_draft_is_accepted_template_baseline(&draft_outcome.draft)
        && static_page_published_public_url_from_draft(&draft_outcome.draft).is_some()
    {
        return Ok(());
    }

    let task_payload_patch = static_page_template_prewarm_task_payload(
        connection_id,
        run,
        message,
        selected_scope,
        &candidate,
        now,
    );
    let image_prompt_payload =
        build_static_page_image_prompt_payload(&draft_outcome.draft, Some(&prewarm_prompt));
    let (_status, Json(image_response)) = create_static_page_image_job_for_draft_with_options(
        state,
        draft_outcome.draft.clone(),
        CreateStaticPageImageJobRequest {
            prompt: Some(prewarm_prompt),
            image_prompt_payload,
        },
        StaticPageImageJobCreateOptions {
            task_available_at: Some(available_at),
            task_payload_patch: Some(task_payload_patch),
            queue_message: Some("低负载时自动预热模板，客户不可见。".to_string()),
            operation_summary: Some("静态页模板预热任务已进入低优先级队列。".to_string()),
        },
    )
    .await?;
    state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run.id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.static_page_template_prewarm_queued".to_string(),
                payload: json!({
                    "type": "static_page_template_prewarm_candidate",
                    "prewarm_key": candidate.prewarm_key,
                    "draft_id": draft_outcome.draft.id,
                    "image_job_id": image_response.image_job.id,
                    "queue": "static_page",
                    "task_key": "generate_static_page_image",
                    "available_at": available_at,
                    "scope_token_count": candidate.scope_tokens.len(),
                    "dataset_artifact_key": candidate.dataset_artifact_key,
                    "low_load_policy": static_page_template_prewarm_low_load_policy(),
                    "customer_visible": false,
                }),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok(())
}

fn external_channel_static_page_template_stability_key(
    message: &ExternalBotMessageView,
    prompt: &str,
) -> String {
    let default_prompt = message.default_prompt.as_deref();
    if let Some(template_reference_id) =
        external_channel_static_page_template_reference_id(message, prompt)
    {
        if let Some(token) = static_page_stable_key_token(&template_reference_id) {
            return static_page_template_stability_key_with_default_prompt(
                format!("template:{token}"),
                default_prompt,
            );
        }
    }
    for skill in message
        .requested_skills
        .iter()
        .filter(|skill| external_requested_skill_mode(skill) != "disabled")
    {
        if !external_requested_skill_is_document_template(skill) {
            continue;
        }
        let source_id = external_document_template_skill_source_id(skill)
            .and_then(|value| static_page_stable_key_token(&value))
            .unwrap_or_else(|| "source-default".to_string());
        let document_external_id = external_document_template_skill_external_id(skill)
            .or_else(|| {
                external_document_template_skill_document_id(skill).map(|id| id.to_string())
            })
            .and_then(|value| static_page_stable_key_token(&value));
        let revision = external_document_template_skill_revision_external_id(skill)
            .and_then(|value| static_page_stable_key_token(&value))
            .unwrap_or_else(|| "latest".to_string());
        if let Some(document_external_id) = document_external_id {
            return static_page_template_stability_key_with_default_prompt(
                format!("document-template:{source_id}:{document_external_id}:{revision}"),
                default_prompt,
            );
        }
    }
    static_page_template_stability_key_with_default_prompt("template:default", default_prompt)
}

fn external_channel_message_requests_data_ingestion_analysis(prompt: &str) -> bool {
    let compact = prompt
        .chars()
        .filter(|ch| !ch.is_whitespace())
        .collect::<String>()
        .to_ascii_lowercase();
    external_channel_text_has_any(
        &compact,
        prompt,
        &[
            "数据接入",
            "入库",
            "建表",
            "字段映射",
            "数据源",
            "同步",
            "数据库分析",
            "导入",
            "清洗",
            "schema",
            "etl",
            "import",
            "mapping",
            "data ingestion",
            "data-ingestion",
            "staging plan",
            "staging_plan",
        ],
    )
}

fn collect_external_data_ingestion_database_source_ids(
    connection: &ExternalChannelConnectionSummary,
    selected_scope: &Value,
    evidence_state: &Value,
) -> Vec<String> {
    collect_external_static_page_database_source_ids(connection, selected_scope, evidence_state)
}

fn selected_string_ids_from_scope(scope: &Value, keys: &[&str]) -> Vec<String> {
    let mut ids = BTreeSet::new();
    for key in keys {
        if let Some(value) = scope
            .get(*key)
            .and_then(Value::as_str)
            .and_then(non_empty_trimmed_string)
        {
            ids.insert(value);
        }
        for item in scope
            .get(*key)
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
        {
            if let Some(value) = item
                .as_str()
                .and_then(non_empty_trimmed_string)
                .or_else(|| {
                    item.get("id")
                        .and_then(Value::as_str)
                        .and_then(non_empty_trimmed_string)
                })
                .or_else(|| {
                    item.get("file_id")
                        .and_then(Value::as_str)
                        .and_then(non_empty_trimmed_string)
                })
                .or_else(|| {
                    item.get("source_id")
                        .and_then(Value::as_str)
                        .and_then(non_empty_trimmed_string)
                })
                .or_else(|| {
                    item.get("table_id")
                        .and_then(Value::as_str)
                        .and_then(non_empty_trimmed_string)
                })
            {
                ids.insert(value);
            }
        }
    }
    ids.into_iter().collect()
}

fn external_channel_data_ingestion_dataset_scope(
    tenant_id: TenantId,
    connection: &ExternalChannelConnectionSummary,
    run: &AssistantRun,
) -> Value {
    json!({
        "tenant_id": tenant_id.to_string(),
        "dataset_ids": selected_dataset_ids_from_scope(&run.selected_scope)
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>(),
        "database_source_ids": collect_external_data_ingestion_database_source_ids(
            connection,
            &run.selected_scope,
            &run.evidence_state,
        ),
        "selected_document_ids": selected_document_ids_from_scope(&run.selected_scope)
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>(),
        "uploaded_file_ids": selected_string_ids_from_scope(
            &run.selected_scope,
            &["uploaded_file_ids", "uploadedFiles", "files", "file_ids"]
        ),
        "table_ids": selected_string_ids_from_scope(
            &run.selected_scope,
            &["table_ids", "tables", "selected_tables"]
        ),
        "scope_source": "v3_external_channel_selected_scope",
    })
}

fn external_channel_data_ingestion_scope_has_source(dataset_scope: &Value) -> bool {
    [
        "dataset_ids",
        "database_source_ids",
        "selected_document_ids",
        "uploaded_file_ids",
        "table_ids",
    ]
    .iter()
    .any(|key| {
        dataset_scope
            .get(key)
            .and_then(Value::as_array)
            .is_some_and(|values| {
                values.iter().any(|value| {
                    value
                        .as_str()
                        .map(str::trim)
                        .is_some_and(|value| !value.is_empty())
                })
            })
    })
}

