fn external_channel_static_page_image2_codex_execution(
    tenant_id: TenantId,
    workflow_catalog: &WorkflowCatalog,
    assistant_run_id: AssistantRunId,
    local_thread_id: Option<String>,
    fixed_task: CodexHostFixedTaskTemplateContextView,
) -> std::result::Result<(WorkflowExecution, WorkflowEventRecord), ApiError> {
    if !external_channel_static_page_fixed_task_preview_ready(&fixed_task) {
        return Err(ApiError::bad_request(
            "static_page_effect_image_not_ready",
            "static_page_image2_data_publish requires a preview-ready Image2 asset before queuing Codex Host"
                .to_string(),
        ));
    }
    let definition = workflow_catalog
        .find_definition(WorkflowKind::CodexHostTask)
        .ok_or_else(|| {
            ApiError::internal(
                "workflow_definition_missing",
                "codex_host_task workflow definition is not registered".to_string(),
            )
        })?;
    let now = Utc::now();
    let execution_id = WorkflowExecutionId::new();
    let runtime_state = definition.initial_state(execution_id, now);
    let capability = fixed_task.template_id.as_str().to_string();
    let request = CodexHostTaskRequestView {
        assistant_run_id,
        capability: capability.clone(),
        task: Some(
            "Run the fixed DataMax Image2-first static-page publish template and return only the fixed output schema."
                .to_string(),
        ),
        local_thread_id,
        fixed_task: Some(fixed_task),
        task_memory_policy: CodexHostTaskMemoryPolicyView::task_scoped(
            assistant_run_id,
            execution_id,
        ),
        safety: CodexHostTaskSafetyPolicyView::default(),
    };
    let mut context = match request.to_workflow_context() {
        Value::Object(map) => map,
        _ => Map::new(),
    };
    context.insert(
        "fixed_task_bundle".to_string(),
        codex_host_fixed_task_bundle_manifest(capability.as_str()),
    );
    context.insert(
        "retries_remaining".to_string(),
        Value::Number(runtime_state.retries_remaining.into()),
    );
    let execution = WorkflowExecution {
        id: execution_id,
        tenant_id,
        dataset_id: None,
        report_plan_id: None,
        kind: WorkflowKind::CodexHostTask,
        version: runtime_state.version,
        stage: runtime_state.stage,
        status: runtime_state.status,
        attempt: 0,
        context: Value::Object(context),
        created_at: now,
        updated_at: now,
    };
    let initial_event = codex_host_fixed_task_created_event(&execution, assistant_run_id);
    Ok((execution, initial_event))
}

#[allow(clippy::too_many_arguments)]
async fn create_static_page_template_baseline_preview_job(
    state: &AppState,
    draft: StaticPageDraft,
    prompt: &str,
    template_reference: Option<&Value>,
    relaxed_template_match: &Value,
    visual_contract_url: &str,
    now: DateTime<Utc>,
) -> std::result::Result<(StaticPageDraft, StaticPageImageJobView), ApiError> {
    let mut draft = refresh_static_page_draft_data_contract_for_action(
        state,
        draft,
        "submit_static_page_template_baseline_preview",
    )
    .await?;
    let mut image_prompt_payload = build_static_page_image_prompt_payload(&draft, Some(prompt));
    set_payload_value(&mut image_prompt_payload, "image2_skipped", json!(true));
    set_payload_value(
        &mut image_prompt_payload,
        "image2_skip_reason",
        json!("accepted_dataset_overlap_template_baseline"),
    );
    set_payload_value(
        &mut image_prompt_payload,
        "template_baseline_visual_contract_url",
        json!(visual_contract_url),
    );
    set_payload_value(
        &mut image_prompt_payload,
        "relaxed_template_match",
        relaxed_template_match.clone(),
    );
    if let Some(template_reference) = template_reference {
        set_payload_value(
            &mut image_prompt_payload,
            "template_reference",
            template_reference.clone(),
        );
    }
    let mut orchestrator = image_prompt_payload
        .get("orchestrator")
        .cloned()
        .unwrap_or_else(|| json!({}));
    ensure_json_object(&mut orchestrator);
    set_payload_value(&mut orchestrator, "image2Skipped", json!(true));
    set_payload_value(
        &mut orchestrator,
        "image2SkipReason",
        json!("accepted_dataset_overlap_template_baseline"),
    );
    set_payload_value(
        &mut orchestrator,
        "previewAssetProvenance",
        json!({
            "sourceAssetKind": "accepted_static_page_template_baseline",
            "sourceAssetRef": visual_contract_url,
            "sourceAssetRefRedacted": false,
            "sourceAssetHadQuery": false,
            "persisted": true,
            "persistedPreviewAssetKey": visual_contract_url,
            "storageStatus": "accepted_template_baseline",
        }),
    );
    set_payload_value(&mut image_prompt_payload, "orchestrator", orchestrator);

    let job = state
        .storage
        .static_page_image_jobs()
        .create(
            state.tenant_id,
            &NewStaticPageImageJob {
                draft_id: draft.id,
                assistant_run_id: draft.assistant_run_id,
                status: StaticPageImageJobStatus::PreviewReady,
                queue_position: None,
                image_prompt_payload,
                preview_asset_key: Some(visual_contract_url.to_string()),
                failure_reason: None,
                confirmed_at: Some(now),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;

    let operations = vec![json!({
        "type": "mark_preview_ready",
        "previewImage": {
            "imageJobId": job.id,
            "assetKey": visual_contract_url,
            "source": "accepted_static_page_template_baseline",
            "image2Skipped": true,
            "image2SkipReason": "accepted_dataset_overlap_template_baseline",
        },
    })];
    draft.draft_payload = apply_static_page_operations_to_payload(
        draft.draft_payload,
        &operations,
        Some("已命中已发布模板，复用模板视觉合同并继续制作静态页。"),
    );
    append_static_page_operations_metadata(
        &mut draft.draft_payload,
        &operations,
        Some(prompt),
        "已命中已发布模板，复用模板视觉合同并继续制作静态页。",
    );
    draft.status = StaticPageDraftStatus::Previewed;
    let draft = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;

    append_static_page_draft_run_event(
        state,
        &draft,
        "static_page_image_job.created",
        json!({
            "draft_id": draft.id,
            "image_job_id": job.id,
            "status": job.status.as_str(),
            "queue_position": job.queue_position,
            "workflow_execution_id": Value::Null,
            "workflow_task_id": Value::Null,
            "image2_skipped": true,
            "image2_skip_reason": "accepted_dataset_overlap_template_baseline",
            "preview_asset_key": visual_contract_url,
            "relaxed_template_match": relaxed_template_match,
        }),
    )
    .await?;
    append_static_page_draft_run_event(
        state,
        &draft,
        "static_page_image_job.preview_ready",
        json!({
            "draft_id": draft.id,
            "image_job_id": job.id,
            "status": "preview_ready",
            "preview_asset_key": visual_contract_url,
            "image2_skipped": true,
            "image2_skip_reason": "accepted_dataset_overlap_template_baseline",
            "template_reference": template_reference.cloned().unwrap_or(Value::Null),
            "relaxed_template_match": relaxed_template_match,
        }),
    )
    .await?;

    Ok((draft, to_static_page_image_job_view(job)))
}

