async fn create_static_page_render_for_draft(
    state: &AppState,
    mut draft: StaticPageDraft,
    request: CreateStaticPageRenderRequest,
) -> std::result::Result<(StatusCode, Json<CreateStaticPageRenderResponse>), ApiError> {
    draft = refresh_static_page_draft_data_contract_for_action(
        state,
        draft,
        static_page_render_submit_action(),
    )
    .await?;
    let image_job = if request.direct_html {
        None
    } else {
        let image_job =
            resolve_static_page_render_image_job(state, &draft, request.image_job_id).await?;
        ensure_static_page_preview_contract_current(&draft, image_job.as_ref())?;
        image_job
    };
    if static_page_draft_requires_final_render_data_quality_gate(&draft) {
        if let Some((reason, details)) =
            static_page_final_render_data_quality_gate_for_draft(&draft)
        {
            return Err(ApiError::bad_request_with_details(
                "static_page_final_render_data_quality_gate",
                reason,
                details,
            ));
        }
    }
    if request.background {
        let mut render_output = state
            .storage
            .static_page_render_outputs()
            .create(
                state.tenant_id,
                &new_queued_static_page_render_output(&draft, image_job.as_ref(), Utc::now()),
            )
            .await
            .map_err(ApiError::from_storage)?;
        let workflow_execution = build_initial_static_page_render_execution(
            state,
            &draft,
            &render_output,
            image_job.as_ref(),
        )?;
        let initial_event =
            build_initial_static_page_render_event(&workflow_execution, &draft, &render_output);
        state
            .storage
            .workflow_executions()
            .create_with_initial_event(&workflow_execution, &initial_event)
            .await
            .map_err(ApiError::from_storage)?;
        let started = apply_workflow_signal_with_dependencies(
            &state.storage,
            &state.workflow_catalog,
            &state.event_bus,
            state.tenant_id,
            workflow_execution.id,
            WorkflowSignal::Start,
        )
        .await?;
        let started_execution = state
            .storage
            .workflow_executions()
            .get_by_id(state.tenant_id, workflow_execution.id)
            .await
            .map_err(ApiError::from_storage)?
            .ok_or_else(|| {
                ApiError::internal(
                    "workflow_execution_missing_after_start",
                    format!(
                        "workflow execution {} was missing after start",
                        workflow_execution.id
                    ),
                )
            })?;
        let workflow_task_id = static_page_render_first_workflow_task_id(&started.enqueued_tasks);
        render_output = apply_static_page_render_workflow_start_to_output(
            &draft,
            render_output,
            image_job.as_ref(),
            &started_execution,
            workflow_task_id,
        );
        render_output = state
            .storage
            .static_page_render_outputs()
            .update(state.tenant_id, &render_output)
            .await
            .map_err(ApiError::from_storage)?;
        append_static_page_draft_run_event(
            state,
            &draft,
            static_page_render_queued_event_name(),
            static_page_render_queued_event_payload(
                &draft,
                &render_output,
                &workflow_execution,
                workflow_task_id,
            ),
        )
        .await?;

        return Ok((
            StatusCode::CREATED,
            Json(static_page_render_response(draft, render_output)),
        ));
    }

    let rendered = render_static_page(&build_static_page_render_request(
        &draft,
        image_job.as_ref(),
    ));
    let render_output = state
        .storage
        .static_page_render_outputs()
        .create(
            state.tenant_id,
            &new_rendered_static_page_render_output(
                &draft,
                image_job.as_ref(),
                rendered.html,
                rendered.asset_manifest,
                Utc::now(),
            ),
        )
        .await
        .map_err(ApiError::from_storage)?;
    draft = apply_static_page_final_render_to_draft(draft, &render_output, request.direct_html);
    let draft = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &draft,
        static_page_render_created_event_name(),
        static_page_render_created_event_payload(&draft, &render_output),
    )
    .await?;

    Ok((
        StatusCode::CREATED,
        Json(static_page_render_response(draft, render_output)),
    ))
}

async fn create_static_page_render_output_inline(
    state: &AppState,
    mut draft: StaticPageDraft,
    image_job: Option<StaticPageImageJob>,
    direct_html: bool,
) -> std::result::Result<(StaticPageDraft, StaticPageRenderOutputView), ApiError> {
    let rendered = render_static_page(&build_static_page_render_request(
        &draft,
        image_job.as_ref(),
    ));
    let render_output = state
        .storage
        .static_page_render_outputs()
        .create(
            state.tenant_id,
            &new_rendered_static_page_render_output(
                &draft,
                image_job.as_ref(),
                rendered.html,
                rendered.asset_manifest,
                Utc::now(),
            ),
        )
        .await
        .map_err(ApiError::from_storage)?;
    draft = apply_static_page_final_render_to_draft(draft, &render_output, direct_html);
    let draft = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &draft,
        static_page_render_created_event_name(),
        static_page_render_created_event_payload(&draft, &render_output),
    )
    .await?;
    let selected_scope = draft.selected_scope.clone();
    Ok((
        draft,
        to_static_page_render_output_view(render_output, Some(&selected_scope)),
    ))
}

async fn refresh_static_page_draft_data_contract_for_action(
    state: &AppState,
    mut draft: StaticPageDraft,
    action: &str,
) -> std::result::Result<StaticPageDraft, ApiError> {
    let previous_validation_summary =
        static_page_payload_data_snapshot_validation_summary(&draft.draft_payload);
    let mut refreshed_payload = draft.draft_payload.clone();
    refresh_static_page_payload_with_draft_context(&mut refreshed_payload, &draft);
    if refreshed_payload == draft.draft_payload {
        return Ok(draft);
    }

    let next_validation_summary =
        static_page_payload_data_snapshot_validation_summary(&refreshed_payload);
    draft.status = status_from_static_page_payload(&refreshed_payload).unwrap_or(draft.status);
    draft.draft_payload = refreshed_payload;
    let updated = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &updated,
        "static_page_draft.data_contract_auto_refreshed",
        json!({
            "draft_id": updated.id,
            "action": action,
            "previous_validation_summary": previous_validation_summary,
            "next_validation_summary": next_validation_summary,
        }),
    )
    .await?;
    Ok(updated)
}

async fn list_static_page_render_outputs(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(draft_id): Path<String>,
) -> std::result::Result<Json<Vec<StaticPageRenderOutputView>>, ApiError> {
    let draft_id = parse_static_page_draft_id(&draft_id)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let draft = load_visible_static_page_draft(&state, draft_id, current_user_id).await?;
    let outputs = state
        .storage
        .static_page_render_outputs()
        .list_by_draft(state.tenant_id, draft.id)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(Json(
        outputs
            .into_iter()
            .map(|output| to_static_page_render_output_view(output, Some(&draft.selected_scope)))
            .collect(),
    ))
}

async fn list_conversation_memory_items(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<ConversationMemoryQuery>,
) -> std::result::Result<Json<Vec<ConversationMemoryItemView>>, ApiError> {
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let local_thread_id = required_field("local_thread_id", query.local_thread_id)?;
    validate_required("local_thread_id", &local_thread_id)?;
    let items = state
        .storage
        .conversation_memory_items()
        .list_by_local_thread(
            state.tenant_id,
            local_thread_id.trim(),
            query.query.as_deref(),
            query.limit.unwrap_or(20),
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok(Json(
        items
            .into_iter()
            .filter(|item| owner_user_id_is_visible(item.user_id, current_user_id))
            .map(to_conversation_memory_item_view)
            .collect(),
    ))
}

async fn list_assistant_run_conversation_memory_candidates(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(run_id): Path<String>,
    Query(query): Query<ConversationMemoryQuery>,
) -> std::result::Result<Json<Vec<ConversationMemoryItemView>>, ApiError> {
    let run_id = parse_assistant_run_id(&run_id)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let run = load_visible_assistant_run_for_user(&state, run_id, current_user_id).await?;
    let local_thread_id = run.local_thread_id.ok_or_else(|| {
        ApiError::bad_request(
            "assistant_run_local_thread_missing",
            "assistant run has no local thread id for conversation memory lookup".to_string(),
        )
    })?;
    let items = state
        .storage
        .conversation_memory_items()
        .list_by_local_thread(
            state.tenant_id,
            local_thread_id.trim(),
            query.query.as_deref(),
            query.limit.unwrap_or(20),
        )
        .await
        .map_err(ApiError::from_storage)?;

    Ok(Json(
        items
            .into_iter()
            .filter(|item| owner_user_id_is_visible(item.user_id, current_user_id))
            .map(to_conversation_memory_item_view)
            .collect(),
    ))
}

#[cfg(test)]
fn build_assistant_run_provider_input(request: &CreateAssistantRunRequest) -> String {
    build_assistant_run_provider_input_with_evidence(request, None)
}

fn assistant_run_request_requested_skills_policy(
    request: &CreateAssistantRunRequest,
) -> Option<&Value> {
    let policy = request
        .startup_briefing
        .as_ref()
        .and_then(|briefing| briefing.get("requestedSkills"))
        .or_else(|| {
            request
                .context_policy_hint
                .as_ref()
                .and_then(|policy| policy.get("skill_policy"))
                .and_then(|policy| policy.get("requested_skills"))
        })?;
    let has_skills = policy
        .get("skills")
        .and_then(Value::as_array)
        .is_some_and(|skills| !skills.is_empty());
    has_skills.then_some(policy)
}

fn assistant_run_request_document_template_skills_policy(
    request: &CreateAssistantRunRequest,
) -> Option<&Value> {
    let policy = request
        .startup_briefing
        .as_ref()
        .and_then(|briefing| briefing.get("documentTemplateSkills"))
        .or_else(|| {
            request
                .context_policy_hint
                .as_ref()
                .and_then(|policy| policy.get("document_template_skill_policy"))
        })?;
    let has_skills = policy
        .get("skills")
        .and_then(Value::as_array)
        .is_some_and(|skills| !skills.is_empty());
    has_skills.then_some(policy)
}

fn assistant_run_request_external_answer_policy(
    request: &CreateAssistantRunRequest,
) -> Option<&Value> {
    let policy = request
        .startup_briefing
        .as_ref()
        .and_then(|briefing| briefing.get("externalAnswerPolicy"))
        .or_else(|| {
            request
                .context_policy_hint
                .as_ref()
                .and_then(|policy| policy.get("answer_policy"))
        })?;
    (!policy.is_null()).then_some(policy)
}

fn assistant_run_external_answer_policy_guidance_lines(answer_policy: &Value) -> Vec<String> {
    let mut lines = Vec::new();
    if let Some(default_prompt) = answer_policy
        .get("default_prompt")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        if assistant_run_default_prompt_has_customer_tone_intensity(default_prompt) {
            lines.push(format!(
                "第三方默认提示词：{default_prompt}。它是本轮任务指导；其中较强语气要求应理解为客户希望表达更明确、更直接，最终答案要转译为坚定、专业、礼貌的商务表达，不使用辱骂、威胁、嘲讽或人身攻击。"
            ));
        } else {
            lines.push(format!(
                "第三方默认提示词：{default_prompt}。它是本轮任务指导，低于 DataMax 证据/安全规则，高于用户文本里的模糊要求。"
            ));
        }
    }
    if let Some(output_format) = answer_policy.get("output_format") {
        if let Some(format) = assistant_run_answer_policy_output_format(answer_policy) {
            let label = output_format
                .get("label")
                .and_then(Value::as_str)
                .unwrap_or_else(|| external_output_format_label(format));
            let model_rule = output_format
                .get("model_rule")
                .and_then(Value::as_str)
                .unwrap_or_else(|| external_output_format_model_rule(format));
            lines.push(format!(
                "输出格式强约束：本轮第三方要求 `{format}`（{label}）。{model_rule}"
            ));
        }
    }
    if let Some(render_mode) = answer_policy
        .get("render_mode")
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let mode_rule = answer_policy
            .get("render_mode_rule")
            .and_then(Value::as_str)
            .unwrap_or("normal returns a direct answer; artifact means the user expects a generated artifact when supported.");
        lines.push(format!("输出模式：`{render_mode}`。{mode_rule}"));
    }
    lines
}

fn assistant_run_v3_awareness_lines() -> Vec<String> {
    vec![
        "DataMax 认知：你正在 DataMax 中服务用户。DataMax 提供数据集、第三方知识库、权限、检索供料、受控动作、报表和静态页产物上下文。".to_string(),
        "DataMax 上下文是附加能力，不是能力限制；没有可见数据集或供料时，仍可保持通用模型水准回答普通问题。".to_string(),
        "DataMax 证据规则：涉及 DataMax 数据、文档、权限、工具结果或产物状态时，只能把已供给的 observation/证据当作事实；未供料时先说明“当前不可见/未供料”，再区分通用知识或推断。".to_string(),
        "DataMax 搜索规则：外部/网页搜索（web_search）是 DataMax 受控只读能力；没有带来源和时间的 DataMax search evidence 时，不要声称已联网搜索或引用实时网页结果。".to_string(),
    ]
}

fn assistant_run_v3_awareness_policy_value() -> Value {
    json!({
        "identity": "你正在服务 DataMax。DataMax 是数据集、第三方知识库、权限、检索供料、受控动作、报表和静态页产物的统一工作台。",
        "additiveContextRule": "DataMax 上下文是附加能力，不是能力限制。即使当前没有可见数据集或供料，也可以保持通用模型水准回答普通问题。",
        "unavailableEvidenceRule": "涉及 DataMax 数据、文档、权限、工具结果或产物状态时，只有收到 DataMax observation/供料才能当作事实。未供料时先说明“当前不可见/未供料”，再区分通用判断。",
        "externalSearchPolicy": {
            "status": "v3_controlled_read_only",
            "modelRule": "外部/网页搜索是 DataMax 受控只读能力；未收到带来源和时间的 DataMax search evidence 前，不要声称已联网搜索或引用实时网页结果。"
        }
    })
}

fn build_assistant_run_provider_input_with_evidence(
    request: &CreateAssistantRunRequest,
    evidence_state: Option<&Value>,
) -> String {
    let selected_scope = request.selected_scope.as_ref();
    let plain_ordinary_chat = assistant_run_is_plain_ordinary_chat_scope(
        selected_scope,
        evidence_state,
        request.current_artifact.as_ref(),
    );
    let mut sections = if plain_ordinary_chat {
        vec![
            "你是通用模型助手，运行在 AI 数据智能助手中。".to_string(),
            "当前未选择数据集，也没有供料证据；请按普通模型问答直接回答用户问题，可以使用你的通用知识、推理和表达能力，不要因为缺少数据集而拒答、降级或强行讨论数据工作台。".to_string(),
            "只有当用户明确询问本系统、数据集、文档、报表、静态页、上传或采集能力时，才结合产品背景说明系统能力。".to_string(),
        ]
    } else {
        vec![
            "你是 AI 数据智能助手里的模型回答运行时。".to_string(),
            "宿主只负责识别意图、提供上下文和执行受控动作；最终正文由你自行组织，不要按宿主规则拼模板化回答。".to_string(),
            "系统能力背景：可普通聊天、检索供料、读取文档细节、读取音视频转写/场景等媒体细节、创建报表、规划/渲染/修改静态页、导出静态页 ZIP 交付包。涉及供料中的数据、指标、文档事实或产物状态时，不要编造；普通常识和开放问答仍可使用模型通用能力。".to_string(),
        ]
    };
    if assistant_run_scope_is_external_channel(selected_scope) {
        sections.push(
            "外部通道直答合同：本次输出会同步返回给第三方用户，必须直接回答用户问题；禁止把“已收到/处理中/稍后为您分析/系统将结合知识库与数据源/为您输出结论”当作最终答案。若文档未解析、不可见或供料不足，请直接说明当前可见状态和下一步，而不是承诺稍后输出。"
                .to_string(),
        );
        sections.push(
            "外部通道供料表达要求：如果已经收到文档、检索切片、事实快照或会话范围供料，优先把相关证据整理成可执行结论、步骤、表格或清单；不要把“当前可见”“暂未直接检索到”“资料不足”“建议补充资料”放在答案开头。若供料只是相关章节而非专项原文，必须区分“文档明文规定”和“按相关章节/通用规范整理的可参考流程”，不要把推导或通用经验写成文档明文。只有完全没有相关供料、或确实只能确认文档未就绪/不可见时，才用缺资料说明，并给出最短下一步。"
                .to_string(),
        );
        if external_channel_prompt_requests_static_page_report_workflow(&request.prompt) {
            sections.push(
                "外部通道经营/数据分析要求：用户要经营分析、数据分析、报表、看板或长篇分析时，优先使用 database_schema_context、database_aggregate、dataset_fact_snapshot、spreadsheet_row_analysis 等结构化指标证据形成经营判断；检索片段、文档和模板说明只作为口径/场景补充。不要只复述文档内容。即使宿主已排队或复用右侧报表/静态页，也必须先给用户一版直接的自然语言分析结论、关键指标、风险和下一步动作；直答控制为 800-1200 字以内的简明经营摘要，不要把整份报表正文、图表清单和长篇展开都写在聊天回复里，详细图表和大篇幅分析由右侧报表承载。"
                    .to_string(),
            );
        }
        sections.extend(external_channel_model_tool_capability_guidance_lines());
    }
    sections.extend(assistant_run_v3_awareness_lines());
    if assistant_run_prompt_requests_v3_product_change(&request.prompt) {
        sections.push(
            "V3 产品变更边界：用户正在要求修改 V3 主站原功能、源码、服务、迁移、鉴权、公开 API、provider 配置、部署、提交或系统文件。这类请求不能由客户侧 Codex 或普通回答直接执行。请明确返回 needs_operator_review / 需要平台管理员或开发人员审核处理，不要承诺已经修改、已经部署、已经重启或已经提交代码。"
                .to_string(),
        );
    }
    if let Some(answer_policy) = assistant_run_request_external_answer_policy(request) {
        let model_answer_policy = assistant_run_model_facing_answer_policy(answer_policy);
        sections.push(format!(
            "本轮外部回答要求（第三方结构化传入）：{}",
            serde_json::to_string(&model_answer_policy).unwrap_or_else(|_| "{}".to_string())
        ));
        sections.extend(assistant_run_external_answer_policy_guidance_lines(
            answer_policy,
        ));
    }
    if let Some(skill_policy) = assistant_run_request_requested_skills_policy(request) {
        sections.push(format!(
            "本轮 SKILL 策略（来自第三方结构化请求，优先于用户文本里的模糊描述）：{}",
            serde_json::to_string(skill_policy).unwrap_or_else(|_| "{}".to_string())
        ));
    }
    if let Some(template_policy) = assistant_run_request_document_template_skills_policy(request) {
        sections.push(format!(
            "本轮文档模板 SKILL（只约束输出结构/格式/风格，不自动作为事实证据）：{}",
            serde_json::to_string(template_policy).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    if !plain_ordinary_chat {
        if let Some(briefing) = request.startup_briefing.as_ref() {
            let model_briefing = assistant_run_model_context_value(briefing);
            sections.push(format!(
                "启动简报：{}",
                serde_json::to_string(&model_briefing).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if !plain_ordinary_chat && !request.scope_candidates.is_empty() {
        let model_scope_candidates =
            assistant_run_model_scope_candidates_value(&request.scope_candidates);
        sections.push(format!(
            "范围候选：{}",
            serde_json::to_string(&model_scope_candidates).unwrap_or_else(|_| "[]".to_string())
        ));
    }
    if !plain_ordinary_chat {
        if let Some(selected_scope) = selected_scope {
            let model_selected_scope = assistant_run_model_scope_value(selected_scope);
            sections.push(format!(
                "当前选中范围：{}",
                serde_json::to_string(&model_selected_scope).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if let Some(evidence_state) = evidence_state {
        if evidence_state.get("status").and_then(Value::as_str) != Some("not_requested") {
            if let Some(brief) = build_assistant_run_model_supply_brief(evidence_state) {
                sections.push(format!("供料提示（供你参考，不是回答模板）：\n{brief}"));
            }
            let model_evidence_state = assistant_run_model_evidence_state(evidence_state);
            sections.push(format!(
                "供料证据（可引用上下文）：{}",
                serde_json::to_string(&model_evidence_state).unwrap_or_else(|_| "{}".to_string())
            ));
        }
    }
    if let Some(current_artifact) = request.current_artifact.as_ref() {
        let current_artifact_brief = assistant_run_current_artifact_brief(current_artifact);
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(&current_artifact_brief).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    if let Some(option_followup_context) =
        assistant_run_short_option_followup_context(&request.prompt, &request.messages)
    {
        sections.push(format!(
            "短选项回复续接解释（必须优先理解）：\n{option_followup_context}"
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(12)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| {
            format!(
                "{}: {}",
                message.role.as_str(),
                truncate_assistant_context_text(
                    &message.content,
                    ASSISTANT_RUN_MODEL_HISTORY_TEXT_LIMIT
                )
            )
        })
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("最近对话：\n{}", history.join("\n")));
    }

    sections.push(format!("用户问题：{}", request.prompt.trim()));
    sections.join("\n\n")
}

fn assistant_run_scope_is_external_channel(scope: Option<&Value>) -> bool {
    let Some(scope) = scope else {
        return false;
    };
    scope
        .get("type")
        .and_then(Value::as_str)
        .is_some_and(|value| value == "external_channel")
        || scope
            .get("mode")
            .and_then(Value::as_str)
            .is_some_and(|value| value == "external_channel")
}

fn build_assistant_run_continue_provider_input(
    run: &AssistantRun,
    request: &ContinueAssistantRunRequest,
    continue_prompt: &str,
    selected_scope: &Value,
    evidence_state: &Value,
    max_steps: usize,
) -> String {
    let plain_ordinary_chat = assistant_run_is_plain_ordinary_chat_scope(
        Some(selected_scope),
        Some(evidence_state),
        request.current_artifact.as_ref(),
    );
    let model_evidence_state = assistant_run_model_evidence_state(evidence_state);
    let mut sections = if plain_ordinary_chat {
        vec![
            "你是通用模型助手，正在继续一轮普通对话。".to_string(),
            "当前没有数据集供料或产物上下文；请按用户继续指令直接作答，不要因为运行在数据智能助手中而限制通用问答能力。".to_string(),
            format!("原始问题：{}", run.user_prompt.trim()),
            format!("继续指令：{}", continue_prompt.trim()),
        ]
    } else {
        vec![
            "你是 AI 数据智能助手里的 AssistantRun 连续执行回答运行时。".to_string(),
            "宿主只负责供料和受控动作；最终正文由你自行组织。如果需要平台能力，只提出下一步动作需求；已有供料可作为上下文参考。".to_string(),
            format!("运行ID：{}", run.id),
            format!("原始问题：{}", run.user_prompt.trim()),
            format!("继续指令：{}", continue_prompt.trim()),
            format!("本次最多连续动作数：{}", max_steps),
            format!(
                "当前选中范围：{}",
                serde_json::to_string(&assistant_run_model_scope_value(selected_scope))
                    .unwrap_or_else(|_| "{}".to_string())
            ),
            format!(
                "供料状态：{}",
                serde_json::to_string(&model_evidence_state).unwrap_or_else(|_| "{}".to_string())
            ),
        ]
    };
    sections.extend(assistant_run_v3_awareness_lines());
    if let Some(answer_policy) = selected_scope
        .get("answer_policy")
        .or_else(|| selected_scope.get("answerPolicy"))
        .filter(|policy| !policy.is_null())
    {
        let model_answer_policy = assistant_run_model_facing_answer_policy(answer_policy);
        sections.push(format!(
            "本轮外部回答要求（第三方结构化传入）：{}",
            serde_json::to_string(&model_answer_policy).unwrap_or_else(|_| "{}".to_string())
        ));
        sections.extend(assistant_run_external_answer_policy_guidance_lines(
            answer_policy,
        ));
    }
    if let Some(brief) = build_assistant_run_model_supply_brief(evidence_state) {
        sections.push(format!("供料提示（供你参考，不是回答模板）：\n{brief}"));
    }

    if let Some(current_artifact) = request.current_artifact.as_ref() {
        let current_artifact_brief = assistant_run_current_artifact_brief(current_artifact);
        sections.push(format!(
            "当前打开产物：{}",
            serde_json::to_string(&current_artifact_brief).unwrap_or_else(|_| "{}".to_string())
        ));
    }

    if let Some(option_followup_context) =
        assistant_run_short_option_followup_context(continue_prompt, &request.messages)
    {
        sections.push(format!(
            "短选项回复续接解释（必须优先理解）：\n{option_followup_context}"
        ));
    }

    let history = request
        .messages
        .iter()
        .rev()
        .take(8)
        .collect::<Vec<_>>()
        .into_iter()
        .rev()
        .map(|message| {
            format!(
                "{}: {}",
                message.role.as_str(),
                truncate_assistant_context_text(
                    &message.content,
                    ASSISTANT_RUN_MODEL_HISTORY_TEXT_LIMIT
                )
            )
        })
        .collect::<Vec<_>>();
    if !history.is_empty() {
        sections.push(format!("继续前最近对话：\n{}", history.join("\n")));
    }

    sections.join("\n\n")
}

fn build_assistant_run_model_supply_brief(evidence_state: &Value) -> Option<String> {
    let status = evidence_state.get("status").and_then(Value::as_str)?;
    if status == "not_requested" {
        return None;
    }

    let supplied_count = assistant_run_evidence_supplied_count(evidence_state);
    let detail_target_count = assistant_run_detail_target_count(evidence_state);
    let fallback_count = evidence_state
        .get("fallback_supply_count")
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let supply_quality = evidence_state.get("supply_quality");
    let supply_quality_status = supply_quality
        .and_then(|quality| quality.get("status"))
        .and_then(Value::as_str)
        .unwrap_or("unknown");
    let citation_locator_count = supply_quality
        .and_then(|quality| quality.get("citationLocatorCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let media_context_count = supply_quality
        .and_then(|quality| quality.get("mediaContextCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let dataset_fact_snapshot_count = supply_quality
        .and_then(|quality| quality.get("datasetFactSnapshotCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let asset_profile_hint_count = supply_quality
        .and_then(|quality| quality.get("assetProfileHintCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let document_not_ready_count = supply_quality
        .and_then(|quality| quality.get("documentNotReadyCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let document_failed_count = supply_quality
        .and_then(|quality| quality.get("documentFailedCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let document_reparsing_count = supply_quality
        .and_then(|quality| quality.get("documentReparsingCount"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let mut lines = vec![
        format!(
            "状态：{status}；可引用供料 {supplied_count} 条；建议细读目标 {detail_target_count} 个；兜底切片 {fallback_count} 条。"
        ),
        format!(
            "供料质量：{supply_quality_status}；来源定位 {citation_locator_count} 个；库级事实快照 {dataset_fact_snapshot_count} 个；媒体上下文 {media_context_count} 个；资产画像提示 {asset_profile_hint_count} 个。"
        ),
        "供料只作为可引用上下文；最终正文由模型自行组织。涉及供料里的数据、指标、文档事实或产物状态时不要编造；普通常识、解释和建议可以使用模型通用知识，并区分供料事实与通用判断。detail_targets 只代表建议细读目标，不是引用依据。".to_string(),
    ];
    if document_not_ready_count > 0 {
        lines.push(format!(
            "文档解析状态：有 {document_not_ready_count} 份可见文档未完全就绪，其中失败 {document_failed_count} 份，重解析/重试中 {document_reparsing_count} 份；涉及这些文档时应说明解析状态，不要声称已经读到完整内容。"
        ));
    }
    if let Some(followup) = evidence_state
        .get("recovery_followup")
        .filter(|value| !value.is_null())
    {
        let question = followup
            .get("question")
            .and_then(Value::as_str)
            .unwrap_or("请补充文档名称、页码、关键词或统计口径，我会沿用本会话继续检索。");
        let status = followup
            .get("status")
            .and_then(Value::as_str)
            .unwrap_or("answer_with_current_evidence_then_followup_if_needed");
        lines.push(format!(
            "证据恢复追问：{status}；{question} 模型要求：不能只说“未直接检索到”；先用当前供料和通用知识给一轮可执行答复。若仍无法核验，使用上述追问，并说明下一轮会沿用本会话范围继续检索。"
        ));
    }

    if let Some(items) = evidence_state
        .get("supplied_items")
        .and_then(Value::as_array)
    {
        for (index, item) in items
            .iter()
            .filter_map(assistant_run_model_supply_item_brief)
            .take(ASSISTANT_RUN_MODEL_SUPPLY_BRIEF_ITEM_LIMIT)
            .enumerate()
        {
            lines.push(format!("供料{}：{item}", index + 1));
        }
    }

    if let Some(memory) = evidence_state
        .get("conversation_memory_items")
        .and_then(Value::as_array)
    {
        for (index, item) in memory
            .iter()
            .filter_map(assistant_run_model_memory_item_brief)
            .take(2)
            .enumerate()
        {
            lines.push(format!("历史{}：{item}", index + 1));
        }
    }

    if let Some(targets) = evidence_state
        .get("detail_targets")
        .and_then(Value::as_array)
    {
        let target_briefs = targets
            .iter()
            .filter_map(assistant_run_model_detail_target_brief)
            .take(ASSISTANT_RUN_DETAIL_TARGET_LIMIT)
            .collect::<Vec<_>>();
        if !target_briefs.is_empty() {
            lines.push(format!(
                "建议细读：{}。需要原文措辞、表格/OCR、音视频时间戳或字段定义时，先调用 read_document_detail。",
                target_briefs.join("；")
            ));
        }
    }

    Some(lines.join("\n"))
}

fn assistant_run_model_evidence_state(evidence_state: &Value) -> Value {
    let mut model_state = evidence_state.clone();
    if let Some(object) = model_state.as_object_mut() {
        if let Some((items, budget)) = object
            .get("supplied_items")
            .and_then(Value::as_array)
            .map(|items| assistant_run_model_budgeted_supply_items(items))
        {
            object.insert("supplied_items".to_string(), Value::Array(items));
            object.insert("model_context_budget".to_string(), budget);
        }
        if let Some(memory_items) = object
            .get_mut("conversation_memory_items")
            .and_then(Value::as_array_mut)
        {
            let compacted = memory_items
                .iter()
                .take(ASSISTANT_RUN_MODEL_CONTEXT_MEMORY_LIMIT)
                .map(assistant_run_model_conversation_memory_item)
                .collect::<Vec<_>>();
            *memory_items = compacted;
        }
        if let Some(detail_targets) = object
            .get_mut("detail_targets")
            .and_then(Value::as_array_mut)
        {
            detail_targets.truncate(ASSISTANT_RUN_DETAIL_TARGET_LIMIT);
        }
        if let Some(selected_scope) = object.get_mut("selected_scope") {
            *selected_scope = assistant_run_model_scope_value(selected_scope);
        }
    }
    assistant_run_model_context_value(&model_state)
}

fn assistant_run_model_compact_json_value(
    value: &Value,
    text_limit: usize,
    array_limit: usize,
) -> Value {
    match value {
        Value::String(text) => Value::String(truncate_assistant_supply_text(text, text_limit)),
        Value::Array(items) => Value::Array(
            items
                .iter()
                .take(array_limit)
                .map(|item| assistant_run_model_compact_json_value(item, text_limit, array_limit))
                .collect(),
        ),
        Value::Object(object) => {
            let mut compact = Map::new();
            for (key, child) in object {
                compact.insert(
                    key.clone(),
                    assistant_run_model_compact_json_value(child, text_limit, array_limit),
                );
            }
            Value::Object(compact)
        }
        _ => value.clone(),
    }
}

