async fn record_assistant_run_create_failure(
    state: &AppState,
    run_id: AssistantRunId,
    execution_trail: &[Value],
    error: &ApiError,
    stage: &str,
) {
    let now = Utc::now();
    let mut failed_trail = execution_trail.to_vec();
    failed_trail.push(json!({
        "status": "failed",
        "label": "AssistantRun 执行失败",
        "stage": stage,
        "error_code": error.payload.code,
        "http_status": error.status.as_u16(),
        "at": now,
    }));
    if let Err(update_error) = state
        .storage
        .assistant_runs()
        .update_execution_trail(state.tenant_id, run_id, &Value::Array(failed_trail))
        .await
    {
        tracing::warn!(
            error = ?update_error,
            run_id = %run_id,
            "failed to persist assistant run failure trail"
        );
    }
    if let Err(event_error) = state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run_id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.failed".to_string(),
                payload: json!({
                    "stage": stage,
                    "code": error.payload.code,
                    "message": error.payload.message,
                    "http_status": error.status.as_u16(),
                }),
                created_at: now,
            },
        )
        .await
    {
        tracing::warn!(
            error = ?event_error,
            run_id = %run_id,
            "failed to persist assistant run failure event"
        );
    }
}

fn assistant_run_create_error_with_run_context(
    mut error: ApiError,
    run_id: AssistantRunId,
    stage: &str,
) -> ApiError {
    let mut details = error.payload.details.take().unwrap_or_else(|| json!({}));
    set_payload_string(&mut details, "assistant_run_id", &run_id.to_string());
    set_payload_string(&mut details, "stage", stage);
    error.payload.details = Some(details);
    error
}

fn assistant_run_sanitize_customer_facing_output_artifacts(
    output_artifacts: Vec<Value>,
) -> Vec<Value> {
    output_artifacts
        .into_iter()
        .map(|mut artifact| {
            if artifact.get("type").and_then(Value::as_str) == Some("assistant_message") {
                if let Some(content) = artifact
                    .get("content")
                    .and_then(Value::as_str)
                    .map(ToOwned::to_owned)
                {
                    set_payload_string(
                        &mut artifact,
                        "content",
                        &assistant_run_sanitize_customer_facing_answer_text(&content),
                    );
                }
            }
            artifact
        })
        .collect()
}

fn assistant_run_sanitize_customer_facing_answer_text(output_text: &str) -> String {
    let mut sanitized = output_text.trim().to_string();
    for (raw, replacement) in [
        (
            "low_text_coverage_fallback_unavailable",
            "解析质量较低，正文未成功提取",
        ),
        ("low_text_coverage", "解析质量较低"),
        ("parse_degraded", "解析质量较低"),
        ("document_parse_status", "文档解析状态"),
        ("model_status", "解析状态"),
    ] {
        sanitized = sanitized.replace(raw, replacement);
    }
    if assistant_run_react_output_contains_internal_marker(&sanitized) {
        return "本轮回答包含内部检索指令，系统已拦截未直接展示。请稍后重试，我会基于当前可见资料直接给出结论。".to_string();
    }
    sanitized
}

fn build_assistant_run_react_natural_fallback_input(
    base_input: String,
    observations: &[Value],
    reason: &str,
) -> String {
    let mut sections = vec![
        base_input,
        "ReAct 自然回答兜底要求：上一轮工具规划没有产出可直接展示给用户的最终回答。请改为面向用户直接自然语言作答；不要输出 JSON、observation、execution_trail、react_trace、tool_trace、runtime_manifest 或 provider 原始载荷。".to_string(),
        "如果当前没有拿到 DataMax 可见证据，只在涉及 DataMax 数据/文档/权限/产物状态时说明“当前不可见/未供料”；普通问题继续用你的通用能力回答。".to_string(),
        format!("兜底原因：{reason}"),
    ];
    if !observations.is_empty() {
        let summaries = observations
            .iter()
            .map(assistant_run_react_observation_summary)
            .collect::<Vec<_>>();
        sections.push(format!(
            "已执行动作摘要（仅用于判断下一句回答，不要原样输出）：{}",
            serde_json::to_string(&summaries).unwrap_or_else(|_| "[]".to_string())
        ));
    }
    sections.join("\n\n")
}

fn build_assistant_run_react_compact_natural_fallback_input(
    user_prompt: &str,
    evidence_state: &Value,
    observations: &[Value],
    reason: &str,
) -> String {
    let evidence_items =
        assistant_run_compact_evidence_items_for_natural_fallback(evidence_state, 8);
    let observation_summaries = observations
        .iter()
        .map(assistant_run_react_observation_summary)
        .collect::<Vec<_>>();
    let supply_quality = evidence_state
        .get("supply_quality")
        .cloned()
        .unwrap_or(Value::Null);
    let answer_policy = assistant_run_evidence_state_external_answer_policy(evidence_state);
    let answer_policy_guidance = answer_policy
        .map(assistant_run_external_answer_policy_guidance_lines)
        .unwrap_or_default();
    let requires_json_output =
        answer_policy.and_then(assistant_run_answer_policy_output_format) == Some("json");
    let output_guard = if requires_json_output {
        "优先使用 DataMax 已供料证据；证据不完整时，先给基于已检索材料和通用专业常识的可执行建议，并清楚标注资料来源状态。不要输出 observation、execution_trail、react_trace、runtime_manifest 或内部路径；最终客户答案必须遵守本轮 JSON 输出格式要求。".to_string()
    } else {
        "优先使用 DataMax 已供料证据；证据不完整时，先给基于已检索材料和通用专业常识的可执行建议，并清楚标注“资料中未定位到专门条款/需要补充制度文件”。不要输出 JSON、observation、execution_trail、react_trace、runtime_manifest 或内部路径。".to_string()
    };
    let answer_shape_requirement = if requires_json_output {
        "输出要求：只输出合法 JSON，不要使用 Markdown 代码围栏；如果是养老/护理应急类问题，可用字段表达现场处置、上报记录、家属沟通、后续复盘/材料。"
    } else {
        "输出要求：用中文，给出简明流程；如果是养老/护理应急类问题，按“现场处置、上报记录、家属沟通、后续复盘/材料”组织。"
    };
    let recovery_followup = evidence_state
        .get("recovery_followup")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let mut sections = vec![
        "你是 DataMax 智能助手。上一轮工具规划没有产出可直接展示给用户的最终回答，现在必须直接给客户可展示答案或提出一个明确追问。".to_string(),
        output_guard,
        format!("用户问题：{}", user_prompt.trim()),
        format!("兜底原因：{reason}"),
        format!(
            "供料质量摘要：{}",
            serde_json::to_string(&supply_quality).unwrap_or_else(|_| "null".to_string())
        ),
        format!(
            "证据摘要：{}",
            serde_json::to_string(&evidence_items).unwrap_or_else(|_| "[]".to_string())
        ),
        format!(
            "可继续追问/恢复动作：{}",
            serde_json::to_string(&recovery_followup).unwrap_or_else(|_| "null".to_string())
        ),
        format!(
            "已执行动作摘要：{}",
            serde_json::to_string(&observation_summaries).unwrap_or_else(|_| "[]".to_string())
        ),
        answer_shape_requirement.to_string(),
    ];
    if !answer_policy_guidance.is_empty() {
        sections.push(format!(
            "外部输出要求：\n{}",
            answer_policy_guidance.join("\n")
        ));
    }
    sections.join("\n\n")
}

fn assistant_run_compact_evidence_items_for_natural_fallback(
    evidence_state: &Value,
    limit: usize,
) -> Vec<Value> {
    value_array(
        evidence_state
            .get("supplied_items")
            .cloned()
            .unwrap_or_else(|| json!([])),
    )
    .into_iter()
    .take(limit)
    .map(|item| {
        json!({
            "type": item.get("type").and_then(Value::as_str).unwrap_or("evidence"),
            "summary": item
                .get("summary")
                .and_then(Value::as_str)
                .map(|value| truncate_assistant_supply_text(value, 260))
                .unwrap_or_default(),
            "source_locator": item.get("source_locator").cloned().unwrap_or(Value::Null),
            "document_id": item.get("document_id").cloned().unwrap_or(Value::Null),
            "chunk_index": item.get("chunk_index").cloned().unwrap_or(Value::Null),
            "content_excerpt": item
                .get("content_excerpt")
                .or_else(|| item.get("content"))
                .and_then(Value::as_str)
                .map(|value| truncate_assistant_supply_text(value, 700))
                .unwrap_or_default(),
            "fallback_reason": item.get("fallback_reason").cloned().unwrap_or(Value::Null),
        })
    })
    .collect()
}

fn assistant_run_react_step_limit_followup_message(evidence_state: &Value) -> String {
    let supplied_count = assistant_run_evidence_supplied_count(evidence_state);
    if supplied_count > 0 {
        return format!(
            "我已检索到 {supplied_count} 条相关资料，但还没有定位到足够明确的专门流程条款。可以继续：请补充制度名称、页码或关键词；如果没有专门制度，我也可以先按已检索到的突发事件处置线索和通用养老机构应急规范，整理一版“现场处置、家属沟通、上报记录、后续复盘”的流程。"
        );
    }
    "当前没有检索到可见资料。请补充相关制度文件、文档范围或关键词，我会继续检索并整理可执行流程。"
        .to_string()
}

async fn complete_assistant_run_react_natural_answer_fallback(
    chat_runtime: &LlmRuntimeSelection,
    provider_input: String,
) -> Option<(String, Value)> {
    if chat_runtime.mode == "placeholder" {
        return None;
    }
    let response = complete_assistant_run_provider(
        MODEL_LANE_ASSISTANT_CHAT,
        chat_runtime.mode.clone(),
        chat_runtime.provider.clone(),
        chat_runtime.model.clone(),
        provider_input,
    )
    .await
    .ok()?;
    let answer = response.output_text.trim().to_string();
    if answer.is_empty() {
        return None;
    }
    Some((answer, render_runtime_manifest(&response.runtime)))
}

#[allow(clippy::too_many_arguments)]
async fn maybe_run_assistant_run_answer_quality_retry_for_artifacts(
    state: &AppState,
    request: &CreateAssistantRunRequest,
    active_assistant_run_id: AssistantRunId,
    selected_scope: &Value,
    initial_evidence_state: &Value,
    output_artifacts: &[Value],
    local_thread_id: Option<&str>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    react_runtime: &LlmRuntimeSelection,
    chat_runtime: &LlmRuntimeSelection,
) -> std::result::Result<Option<AssistantRunReactOutcome>, ApiError> {
    let Some(answer) = assistant_run_assistant_message_content_from_artifacts(output_artifacts)
    else {
        return Ok(None);
    };
    let response = assistant_run_answer_quality_synthetic_response(answer);
    maybe_run_assistant_run_answer_quality_retry_for_create(
        state,
        request,
        active_assistant_run_id,
        selected_scope,
        initial_evidence_state,
        &response,
        local_thread_id,
        active_secret_binding_ids,
        current_user_id,
        react_runtime,
        chat_runtime,
    )
    .await
}

#[allow(clippy::too_many_arguments)]
async fn maybe_run_assistant_run_answer_quality_retry_for_create(
    state: &AppState,
    request: &CreateAssistantRunRequest,
    active_assistant_run_id: AssistantRunId,
    selected_scope: &Value,
    initial_evidence_state: &Value,
    initial_response: &LlmResponse,
    local_thread_id: Option<&str>,
    active_secret_binding_ids: &[SecretBindingId],
    current_user_id: Option<UserId>,
    react_runtime: &LlmRuntimeSelection,
    chat_runtime: &LlmRuntimeSelection,
) -> std::result::Result<Option<AssistantRunReactOutcome>, ApiError> {
    if chat_runtime.mode == "placeholder" || react_runtime.mode == "placeholder" {
        return Ok(None);
    }
    let quality_budget =
        assistant_run_answer_quality_budget_for_evidence(request, initial_evidence_state);
    let budget = quality_budget.answer_retry_budget;
    if budget == 0 {
        return Ok(None);
    }

    let mut current_answer = initial_response.output_text.trim().to_string();
    let mut current_evidence_state = initial_evidence_state.clone();
    let mut last_outcome = None;
    let mut budget_event_emitted = false;

    for attempt_index in 1..=budget {
        let Some(reason) = assistant_run_answer_quality_retry_reason_with_judge(
            &current_answer,
            &current_evidence_state,
            request,
            chat_runtime,
        )
        .await
        else {
            break;
        };
        let retry_scope = assistant_run_answer_quality_retry_scope(
            selected_scope,
            &request.prompt,
            attempt_index,
        );
        let mut retry_request = assistant_run_answer_quality_retry_request(
            request,
            &retry_scope,
            attempt_index,
            budget,
            &quality_budget,
            reason,
            &current_answer,
        );
        let mut retry_evidence_state = build_assistant_run_evidence_state(
            state,
            &retry_scope,
            &request.prompt,
            local_thread_id,
            active_secret_binding_ids,
            current_user_id,
        )
        .await?;
        retry_evidence_state = assistant_run_answer_quality_retry_evidence_state(
            retry_evidence_state,
            attempt_index,
            &quality_budget,
            reason,
        );
        retry_request.selected_scope = Some(retry_scope.clone());

        let started_event = AssistantRunReactEvent {
            event_name: "assistant_run.answer_quality_gate.retry_started".to_string(),
            payload: json!({
                "attempt": attempt_index,
                "budget": budget,
                "reason": reason,
                "strategy": "react_expand_supply",
            }),
        };
        let outcome = match run_assistant_run_react_for_create(
            state,
            &retry_request,
            active_assistant_run_id,
            &retry_scope,
            retry_evidence_state,
            local_thread_id,
            active_secret_binding_ids,
            current_user_id,
            &react_runtime.mode,
            &react_runtime.provider,
            &react_runtime.model,
            chat_runtime,
        )
        .await
        {
            Ok(mut outcome) => {
                if !budget_event_emitted {
                    outcome.events.insert(0, AssistantRunReactEvent {
                        event_name: "assistant_run.answer_quality_gate.budget_selected".to_string(),
                        payload: json!({
                            "answer_retry_budget": quality_budget.answer_retry_budget,
                            "react_step_budget": quality_budget.react_step_budget,
                            "premium_action_budget": quality_budget.premium_action_budget,
                            "reason": quality_budget.reason,
                            "dissatisfaction": if assistant_run_request_expresses_strong_complaint(request) {
                                "strong_complaint"
                            } else if assistant_run_request_expresses_dissatisfaction(request) {
                                "dissatisfied"
                            } else {
                                "none"
                            },
                        }),
                    });
                    budget_event_emitted = true;
                }
                outcome.events.insert(0, started_event);
                outcome
            }
            Err(error) => {
                state
                    .storage
                    .assistant_runs()
                    .append_event(
                        state.tenant_id,
                        active_assistant_run_id,
                        &NewAssistantRunEvent {
                            event_name: "assistant_run.answer_quality_gate.retry_failed"
                                .to_string(),
                            payload: json!({
                                "attempt": attempt_index,
                                "budget": budget,
                                "reason": reason,
                                "error_code": error.payload.code.as_str(),
                                "error_status": error.status.as_u16(),
                            }),
                            created_at: Utc::now(),
                        },
                    )
                    .await
                    .map_err(ApiError::from_storage)?;
                return Ok(last_outcome);
            }
        };

        let next_answer =
            assistant_run_assistant_message_content_from_artifacts(&outcome.output_artifacts)
                .unwrap_or_default();
        let next_reason = assistant_run_answer_quality_retry_reason_with_judge(
            &next_answer,
            &outcome.evidence_state,
            request,
            chat_runtime,
        )
        .await;
        let mut outcome = outcome;
        let retry_exhausted = next_reason.is_some() && attempt_index >= budget;
        outcome.events.push(AssistantRunReactEvent {
            event_name: if retry_exhausted {
                "assistant_run.answer_quality_gate.retry_exhausted".to_string()
            } else {
                "assistant_run.answer_quality_gate.retry_completed".to_string()
            },
            payload: json!({
                "attempt": attempt_index,
                "budget": budget,
                "previous_reason": reason,
                "remaining_reason": next_reason,
                "accepted": next_reason.is_none(),
                "assistant_message_chars": next_answer.chars().count(),
            }),
        });
        let accepted_answer =
            if let Some(remaining_reason) = next_reason.filter(|_| retry_exhausted) {
                let controlled_answer = assistant_run_answer_quality_exhausted_controlled_answer(
                    &outcome.evidence_state,
                    request,
                    remaining_reason,
                );
                outcome.output_artifacts = assistant_run_replace_assistant_message_content(
                    outcome.output_artifacts,
                    &controlled_answer,
                );
                outcome.events.push(AssistantRunReactEvent {
                    event_name: "assistant_run.answer_quality_gate.exhausted_controlled_fallback"
                        .to_string(),
                    payload: json!({
                        "attempt": attempt_index,
                        "budget": budget,
                        "remaining_reason": remaining_reason,
                        "assistant_message_chars": controlled_answer.chars().count(),
                    }),
                });
                controlled_answer
            } else {
                next_answer
            };
        outcome.output_artifacts =
            assistant_run_sanitize_customer_facing_output_artifacts(outcome.output_artifacts);

        current_answer = accepted_answer;
        current_evidence_state = outcome.evidence_state.clone();
        let accepted = next_reason.is_none() || retry_exhausted;
        last_outcome = Some(outcome);
        if accepted {
            break;
        }
    }

    Ok(last_outcome)
}

fn assistant_run_replace_assistant_message_content(
    mut output_artifacts: Vec<Value>,
    content: &str,
) -> Vec<Value> {
    for artifact in output_artifacts.iter_mut() {
        if artifact.get("type").and_then(Value::as_str) == Some("assistant_message") {
            set_payload_string(artifact, "content", content);
            return output_artifacts;
        }
    }
    output_artifacts.push(json!({
        "type": "assistant_message",
        "role": ChatMessageRole::Assistant.as_str(),
        "content": content,
        "source": "answer_quality_gate_exhausted_controlled_fallback",
    }));
    output_artifacts
}

fn assistant_run_answer_quality_low_quality_case_package(
    assistant_run_id: AssistantRunId,
    request: &CreateAssistantRunRequest,
    selected_scope: &Value,
    evidence_state: &Value,
    output_artifacts: &[Value],
    event_names: &[String],
) -> Option<Value> {
    let answer = assistant_run_assistant_message_content_from_artifacts(output_artifacts)
        .unwrap_or_default();
    let mut signals = Vec::<String>::new();
    if assistant_run_request_expresses_strong_complaint(request) {
        signals.push("strong_user_complaint".to_string());
    } else if assistant_run_request_expresses_dissatisfaction(request) {
        signals.push("user_complaint".to_string());
    }
    if let Some(reason) =
        assistant_run_answer_quality_retry_reason(&answer, evidence_state, request)
    {
        signals.push(match reason {
            "internal_marker_answer" => "unsafe_internal_marker_answer".to_string(),
            "insufficient_or_uncertain_answer" => "weak_insufficient_evidence_answer".to_string(),
            other => format!("answer_quality_{other}"),
        });
    }
    if assistant_run_answer_contains_insufficient_evidence_marker(&answer)
        && assistant_run_answer_quality_has_deterministic_supply(evidence_state)
    {
        signals.push("deterministic_supply_ignored".to_string());
    }
    if assistant_run_answer_quality_report_link_expected(request)
        && !assistant_run_output_artifacts_include_report_link(output_artifacts)
    {
        signals.push("missing_report_artifact_link".to_string());
    }
    if event_names
        .iter()
        .any(|event| event.contains("answer_quality_gate.retry_exhausted"))
    {
        signals.push("retry_exhausted".to_string());
    }
    if event_names
        .iter()
        .any(|event| event.contains("answer_quality_gate.exhausted_controlled_fallback"))
    {
        signals.push("controlled_fallback_used".to_string());
    }
    let upgrade_parse_attempted = event_names
        .iter()
        .any(|event| event.contains("upgrade_parse_vlm"));
    if assistant_run_supply_quality_suggests_parse_recovery(evidence_state)
        && !upgrade_parse_attempted
    {
        signals.push("parse_quality_degraded_without_upgrade".to_string());
    }
    if assistant_run_answer_quality_repeated_fallback_or_timeout(event_names) {
        signals.push("repeated_fallback_or_timeout".to_string());
    }
    signals.sort();
    signals.dedup();
    if signals.is_empty() {
        return None;
    }
    let supply_quality = evidence_state
        .get("supply_quality")
        .cloned()
        .unwrap_or(Value::Null);
    Some(json!({
        "template_id": "answer_quality_autofix",
        "status": "collected",
        "assistant_run_id": assistant_run_id.to_string(),
        "low_quality_signals": signals,
        "user_question": truncate_assistant_supply_text(&request.prompt, 800),
        "customer_answer_excerpt": truncate_assistant_supply_text(&answer, 1000),
        "selected_scope_summary": assistant_run_answer_quality_case_selected_scope_summary(selected_scope),
        "evidence_summary": {
            "supply_quality": supply_quality,
            "recovery_followup": evidence_state
                .get("recovery_followup")
                .filter(|value| !value.is_null())
                .cloned()
                .unwrap_or(Value::Null),
            "answer_supply_sources": assistant_run_answer_quality_case_supply_sources(evidence_state),
            "retrieval_or_fact_snapshot_status": assistant_run_answer_quality_case_supply_status(evidence_state),
        },
        "trace_summary": {
            "events": event_names.iter().take(24).cloned().collect::<Vec<_>>(),
            "quality_gate_events": event_names.iter().filter(|event| event.contains("answer_quality_gate")).take(12).cloned().collect::<Vec<_>>(),
        },
        "blocking_gate_enabled": false,
    }))
}

fn assistant_run_answer_quality_has_deterministic_supply(evidence_state: &Value) -> bool {
    let supply_quality_has_deterministic_rows = evidence_state
        .get("supply_quality")
        .map(|supply_quality| {
            [
                "datasetFactSnapshotCount",
                "dataset_fact_snapshot_count",
                "spreadsheetRowAnalysisCount",
                "spreadsheet_row_analysis_count",
                "databaseAggregateCount",
                "database_aggregate_count",
            ]
            .iter()
            .any(|key| {
                supply_quality
                    .get(*key)
                    .and_then(Value::as_u64)
                    .unwrap_or(0)
                    > 0
            })
        })
        .unwrap_or(false);
    supply_quality_has_deterministic_rows
        || evidence_state
            .get("supplied_items")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .any(|item| {
                matches!(
                    item.get("type").and_then(Value::as_str),
                    Some(
                        "dataset_fact_snapshot" | "database_aggregate" | "spreadsheet_row_analysis"
                    )
                )
            })
}

fn assistant_run_answer_quality_report_link_expected(request: &CreateAssistantRunRequest) -> bool {
    assistant_run_xinbai_published_report_link_answer(&request.prompt).is_some()
        || external_channel_prompt_requests_static_page_report_workflow(&request.prompt)
}

fn assistant_run_output_artifacts_include_report_link(output_artifacts: &[Value]) -> bool {
    output_artifacts.iter().any(|artifact| {
        let artifact_kind = artifact
            .get("artifact_kind")
            .or_else(|| artifact.get("artifactKind"))
            .and_then(Value::as_str)
            .unwrap_or_default();
        let artifact_type = artifact
            .get("type")
            .and_then(Value::as_str)
            .unwrap_or_default();
        let has_static_page_type = matches!(
            artifact_type,
            "generated_artifact" | "external_channel_static_page_artifact" | "static_page_artifact"
        ) || artifact_kind == "static_page";
        let has_url = [
            "public_url",
            "publicUrl",
            "generated_artifact_url",
            "generatedArtifactUrl",
            "download_url",
            "downloadUrl",
            "html_download_url",
            "htmlDownloadUrl",
        ]
        .iter()
        .any(|key| {
            artifact
                .get(*key)
                .and_then(Value::as_str)
                .map(codex_host_fixed_task_public_artifact_url_allowed)
                .unwrap_or(false)
        }) || artifact
            .get("artifact_links")
            .or_else(|| artifact.get("artifactLinks"))
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .any(|value| {
                value
                    .as_str()
                    .map(codex_host_fixed_task_public_artifact_url_allowed)
                    .unwrap_or(false)
            });
        has_static_page_type && has_url
    })
}

fn assistant_run_answer_quality_repeated_fallback_or_timeout(event_names: &[String]) -> bool {
    event_names
        .iter()
        .filter(|event| {
            let lower = event.to_ascii_lowercase();
            lower.contains("fallback")
                || lower.contains("timeout")
                || lower.contains("timed_out")
                || lower.contains("provider_failed")
                || lower.contains("retry_exhausted")
        })
        .count()
        >= 2
}

fn assistant_run_answer_quality_autofix_fixed_task_from_case(
    case_package: &Value,
) -> Option<CodexHostFixedTaskTemplateContextView> {
    if case_package.get("template_id").and_then(Value::as_str) != Some("answer_quality_autofix") {
        return None;
    }
    let case_id = case_package
        .get("case_id")
        .and_then(Value::as_str)
        .map(str::to_string)
        .or_else(|| {
            case_package
                .get("assistant_run_id")
                .and_then(Value::as_str)
                .map(|run_id| format!("assistant-run-{run_id}"))
        });
    Some(CodexHostFixedTaskTemplateContextView {
        template_id: CodexHostFixedTaskTemplateIdView::AnswerQualityAutofix,
        version: 1,
        assistant_run_id: case_package
            .get("assistant_run_id")
            .and_then(Value::as_str)
            .map(str::to_string),
        draft_id: None,
        case_id,
        dataset_scope: Value::Null,
        requirements: Value::Null,
        image2: Value::Null,
        policies: Value::Null,
        low_quality_signals: value_array(
            case_package
                .get("low_quality_signals")
                .cloned()
                .unwrap_or(Value::Null),
        )
        .into_iter()
        .filter_map(|value| value.as_str().map(str::to_string))
        .collect(),
        user_question: case_package
            .get("user_question")
            .and_then(Value::as_str)
            .map(str::to_string),
        customer_answer: case_package
            .get("customer_answer_excerpt")
            .and_then(Value::as_str)
            .map(str::to_string),
        evidence_summary: case_package
            .get("evidence_summary")
            .cloned()
            .unwrap_or(Value::Null),
        trace_summary: case_package
            .get("trace_summary")
            .cloned()
            .unwrap_or(Value::Null),
        allowed_write_scope: Some(assistant_run_answer_quality_autofix_allowed_write_scope()),
        human_review_policy:
            CodexHostFixedTaskHumanReviewPolicyView::AutoForDiagnosisAndPatchProposal,
    })
}

fn assistant_run_answer_quality_autofix_allowed_write_scope() -> CodexHostFixedTaskWriteScopeView {
    CodexHostFixedTaskWriteScopeView {
        files: vec![
            "crates/platform-api/src/lib.rs".to_string(),
            "fixtures/document-quality/**".to_string(),
            "scripts/run-document-quality-smoke.ps1".to_string(),
            "scripts/run-v3-quality-gate-smoke.ps1".to_string(),
            "docs/validation/**".to_string(),
        ],
        symbols: vec![
            "assistant_run_answer_quality_*".to_string(),
            "assistant_run_react_*".to_string(),
            "assistant_run_supply_quality_*".to_string(),
        ],
    }
}

async fn maybe_enqueue_assistant_run_customer_codex_sidecar(
    state: &AppState,
    run: &AssistantRun,
    request: &CreateAssistantRunRequest,
    selected_scope: &Value,
    evidence_state: &Value,
    now: DateTime<Utc>,
) -> std::result::Result<Option<WorkflowExecutionId>, ApiError> {
    let prompt = request.prompt.trim();
    if prompt.is_empty() {
        return Ok(None);
    }
    if !assistant_run_prompt_requests_codex_forward(prompt) {
        return Ok(None);
    }
    if assistant_run_prompt_requests_v3_product_change(prompt) {
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.codex_sidecar_scope_blocked".to_string(),
                    payload: assistant_run_customer_codex_sidecar_scope_blocked_payload(
                        CODEX_CAPABILITY_V3_PRODUCT_CHANGE_REQUEST,
                        "v3_product_change_not_customer_writable",
                    ),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        return Ok(None);
    }
    let Some(capability) = assistant_run_customer_codex_sidecar_capability(request, selected_scope)
    else {
        return Ok(None);
    };
    if let Err(reason) = assistant_run_customer_codex_sidecar_preflight(capability) {
        state
            .storage
            .assistant_runs()
            .append_event(
                state.tenant_id,
                run.id,
                &NewAssistantRunEvent {
                    event_name: "assistant_run.codex_sidecar_preflight_rejected".to_string(),
                    payload: json!({
                        "capability": capability,
                        "reason": reason,
                        "non_blocking": true,
                    }),
                    created_at: now,
                },
            )
            .await
            .map_err(ApiError::from_storage)?;
        return Ok(None);
    }

    let (execution, initial_event) = assistant_run_customer_codex_sidecar_execution(
        state.tenant_id,
        &state.workflow_catalog,
        run.id,
        run.local_thread_id.clone(),
        capability,
        request,
        selected_scope,
        evidence_state,
    )?;
    let execution_id = execution.id;
    state
        .storage
        .workflow_executions()
        .create_with_initial_event(&execution, &initial_event)
        .await
        .map_err(ApiError::from_storage)?;
    state
        .storage
        .assistant_runs()
        .append_event(
            state.tenant_id,
            run.id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.codex_sidecar_queued".to_string(),
                payload: json!({
                    "capability": capability,
                    "workflow_execution_id": execution_id.to_string(),
                    "non_blocking": true,
                    "main_answer_path_preserved": true,
                }),
                created_at: now,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    apply_workflow_signal(state, execution_id, WorkflowSignal::Start).await?;
    Ok(Some(execution_id))
}

fn assistant_run_customer_codex_sidecar_scope_blocked_payload(
    capability: &str,
    reason: &str,
) -> Value {
    json!({
        "capability": capability,
        "route": capability,
        "status": "needs_operator_review",
        "reason": reason,
        "allowed_next_step": "operator can review this as a product change request",
        "non_blocking": true,
        "main_answer_path_preserved": true,
        "v3_product_repo_write_allowed": false,
        "customer_writable": false,
    })
}

fn assistant_run_customer_codex_sidecar_preflight(
    capability: &str,
) -> std::result::Result<(), &'static str> {
    if !platform_env_flag("CODEX_HOST_TASK_ENABLED", false) {
        return Err("codex_host_task_disabled");
    }
    if !env_csv_contains("CODEX_HOST_TASK_ALLOWLIST", capability) {
        return Err("codex_host_task_not_allowlisted");
    }
    if !env_csv_contains("CODEX_HOST_AGENT_PROFILE_ALLOWED_CAPABILITIES", capability) {
        return Err("codex_host_agent_capability_not_allowlisted");
    }
    Ok(())
}

fn assistant_run_customer_codex_sidecar_capability(
    request: &CreateAssistantRunRequest,
    selected_scope: &Value,
) -> Option<&'static str> {
    let prompt = request.prompt.trim();
    if prompt.is_empty()
        || !assistant_run_prompt_requests_codex_forward(prompt)
        || assistant_run_prompt_requests_v3_product_change(prompt)
    {
        return None;
    }
    if assistant_run_prompt_requests_generated_static_page_edit(
        prompt,
        request.current_artifact.as_ref(),
    ) {
        return Some(CODEX_CAPABILITY_GENERATED_STATIC_PAGE_EDIT);
    }
    if assistant_run_prompt_requests_customer_codex_report_artifact_package(
        prompt,
        request,
        selected_scope,
    ) {
        return Some(CODEX_CAPABILITY_CUSTOMER_ARTIFACT_REQUEST);
    }
    if assistant_run_prompt_requests_data_ingestion_or_integration_sidecar(prompt)
        && assistant_run_data_ingestion_sidecar_scope_has_source(selected_scope)
    {
        return Some(CODEX_CAPABILITY_DATA_INGESTION_ANALYSIS);
    }
    if assistant_run_prompt_requests_generated_static_page_publish(prompt, request, selected_scope)
    {
        return Some(CODEX_CAPABILITY_GENERATED_STATIC_PAGE_PUBLISH);
    }
    if assistant_run_prompt_requests_customer_artifact_workspace(prompt, request, selected_scope) {
        return Some(CODEX_CAPABILITY_CUSTOMER_ARTIFACT_REQUEST);
    }
    if assistant_run_prompt_requests_data_analysis_report_sidecar(prompt, request, selected_scope) {
        return Some(CODEX_CAPABILITY_CUSTOMER_ARTIFACT_REQUEST);
    }
    Some(CODEX_CAPABILITY_CUSTOMER_COMPLEX_REQUEST)
}

fn assistant_run_prompt_requests_codex_forward(prompt: &str) -> bool {
    let trimmed = prompt.trim_start();
    if trimmed.eq_ignore_ascii_case("cc") {
        return true;
    }
    let lower = trimmed.to_ascii_lowercase();
    lower.starts_with("cc ")
        || lower.starts_with("cc:")
        || lower.starts_with("cc：")
        || lower.starts_with("cc,")
        || lower.starts_with("cc，")
        || lower.starts_with("cc.")
        || lower.starts_with("cc。")
        || lower.starts_with("cc;")
        || lower.starts_with("cc；")
        || lower.starts_with("cc-")
        || lower.starts_with("cc\n")
        || lower.starts_with("cc\t")
}

fn assistant_run_prompt_without_codex_forward_prefix(prompt: &str) -> &str {
    let trimmed = prompt.trim_start();
    if !assistant_run_prompt_requests_codex_forward(trimmed) {
        return prompt;
    }
    if trimmed.eq_ignore_ascii_case("cc") {
        return "";
    }
    trimmed[2..].trim_start_matches(|ch: char| {
        ch.is_whitespace() || matches!(ch, ':' | '：' | ',' | '，' | '.' | '。' | ';' | '；' | '-')
    })
}

fn assistant_run_prompt_requests_v3_product_change(prompt: &str) -> bool {
    let compact = prompt
        .chars()
        .filter(|ch| !ch.is_whitespace())
        .collect::<String>();
    let lower = prompt.to_ascii_lowercase();
    let has_v3_signal =
        prompt_contains_any(
            prompt,
            &[
                "V3",
                "主站",
                "原功能",
                "产品功能",
                "登录",
                "鉴权",
                "接口",
                "部署",
                "发版",
            ],
        ) || ascii_prompt_contains_any(&lower, &["v3", "api", "auth", "deploy", "login"]);
    let has_change_signal =
        prompt_contains_any(
            prompt,
            &[
                "修改", "改造", "调整", "删除", "新增", "重构", "发版", "部署", "重启",
            ],
        ) || ascii_prompt_contains_any(&lower, &["modify", "change", "patch", "deploy", "restart"]);
    if !(has_v3_signal && has_change_signal) {
        return false;
    }
    if assistant_run_prompt_requests_data_ingestion_or_integration_sidecar(prompt) {
        return false;
    }
    if assistant_run_prompt_mentions_customer_codex_artifact_surface(&compact, &lower)
        && !assistant_run_prompt_mentions_v3_product_system_surface(&compact, &lower)
    {
        return false;
    }
    true
}

