fn assistant_run_database_mapping_for_prompt<'a>(
    config: &'a MySqlSourceConfig,
    prompt: &str,
) -> Option<&'a MySqlTableMapping> {
    let normalized = prompt.to_ascii_lowercase();
    config
        .tables
        .iter()
        .find(|mapping| normalized.contains(&mapping.table.to_ascii_lowercase()))
        .or_else(|| config.tables.first())
}

fn assistant_run_database_schema_mappings_for_prompt<'a>(
    config: &'a MySqlSourceConfig,
    prompt: &str,
) -> Vec<&'a MySqlTableMapping> {
    let normalized = prompt.to_ascii_lowercase();
    let mut mappings = config
        .tables
        .iter()
        .filter(|mapping| normalized.contains(&mapping.table.to_ascii_lowercase()))
        .take(ASSISTANT_RUN_DATABASE_SCHEMA_TABLE_LIMIT)
        .collect::<Vec<_>>();
    if mappings.is_empty() {
        mappings = config
            .tables
            .iter()
            .take(ASSISTANT_RUN_DATABASE_SCHEMA_TABLE_LIMIT)
            .collect();
    }
    mappings
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct AssistantRunDatabaseAggregatePlan {
    role: &'static str,
    intent: &'static str,
    dimensions: Vec<String>,
}

fn assistant_run_database_aggregate_dimension_plans(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Vec<AssistantRunDatabaseAggregatePlan> {
    let wants_report = assistant_run_database_prompt_wants_report(prompt);
    let wants_rank = wants_report
        || prompt_has_any(
            prompt,
            &[
                "区域", "位置", "楼层", "门", "梯", "点位", "areaname", "area", "top", "排名",
                "排行", "排序", "前", "最高", "最大", "哪些", "哪个", "店铺", "门店", "分店",
                "品牌",
            ],
        );
    let wants_trend = wants_report
        || prompt_has_any(
            prompt,
            &[
                "时间", "日期", "小时", "日", "趋势", "变化", "txdate", "date", "time", "by time",
            ],
        );
    let wants_comparison = wants_report
        || prompt_has_any(
            prompt,
            &[
                "对比", "分类", "类型", "类别", "维度", "areatype", "category", "type",
            ],
        );

    let mut plans = Vec::new();
    if wants_rank {
        if let Some(dimension) = assistant_run_database_prompt_entity_dimension(mapping, prompt)
            .or_else(|| assistant_run_database_entity_dimension(mapping))
        {
            push_assistant_run_database_aggregate_plan(
                &mut plans,
                "ranking",
                "entity_topn",
                vec![dimension],
            );
        }
    }
    if wants_trend {
        if let Some(dimension) = assistant_run_database_time_column(mapping) {
            push_assistant_run_database_aggregate_plan(
                &mut plans,
                "trend",
                "time_series",
                vec![dimension],
            );
        }
    }
    if wants_comparison {
        if let Some(dimension) = assistant_run_database_category_dimension(mapping) {
            push_assistant_run_database_aggregate_plan(
                &mut plans,
                "comparison",
                "category_comparison",
                vec![dimension],
            );
        }
    }
    if plans.is_empty() {
        push_assistant_run_database_aggregate_plan(
            &mut plans,
            "primary",
            "prompt_requested",
            assistant_run_database_aggregate_dimensions(mapping, prompt),
        );
    }
    plans.truncate(ASSISTANT_RUN_DATABASE_AGGREGATE_REQUEST_LIMIT);
    plans
}

fn assistant_run_database_prompt_wants_report(prompt: &str) -> bool {
    prompt_has_any(
        prompt,
        &[
            "报表",
            "报告",
            "看板",
            "仪表盘",
            "图文",
            "静态页",
            "html",
            "dashboard",
            "report",
            "visual",
        ],
    )
}

fn push_assistant_run_database_aggregate_plan(
    plans: &mut Vec<AssistantRunDatabaseAggregatePlan>,
    role: &'static str,
    intent: &'static str,
    dimensions: Vec<String>,
) {
    if dimensions.is_empty()
        || plans
            .iter()
            .any(|existing| existing.dimensions == dimensions)
    {
        return;
    }
    plans.push(AssistantRunDatabaseAggregatePlan {
        role,
        intent,
        dimensions,
    });
}

fn assistant_run_database_entity_dimension(mapping: &MySqlTableMapping) -> Option<String> {
    mapping
        .title_column
        .as_deref()
        .map(ToOwned::to_owned)
        .or_else(|| Some(mapping.id_column.clone()))
}

fn assistant_run_database_prompt_entity_dimension(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Option<String> {
    let columns = assistant_run_database_mapping_columns(mapping);
    let find_column = |patterns: &[&str]| {
        patterns.iter().find_map(|pattern| {
            columns
                .iter()
                .find(|column| column.to_ascii_lowercase().contains(pattern))
                .cloned()
        })
    };
    if prompt_has_any(
        prompt,
        &["店铺", "门店", "分店", "店名", "柜组", "专柜", "shop"],
    ) {
        return find_column(&[
            "shopdesc",
            "shop_name",
            "shopname",
            "storedesc",
            "store_name",
            "storename",
            "store_init",
        ]);
    }
    if prompt_has_any(prompt, &["品牌", "租户", "商户", "brand", "lease"]) {
        return find_column(&[
            "branddesc",
            "brand_name",
            "brandname",
            "leasename",
            "lease_name",
        ]);
    }
    if prompt_has_any(prompt, &["品类", "业态", "类目", "category"]) {
        return find_column(&["catgldesc", "catgmdesc", "catgsdesc", "category"]);
    }
    if prompt_has_any(prompt, &["大区", "区域", "小区", "片区", "region", "area"]) {
        return find_column(&[
            "dist_name",
            "areaname",
            "area_name",
            "region",
            "omdname",
            "parentname",
            "area",
        ]);
    }
    if prompt_has_any(prompt, &["合同", "contract"]) {
        return find_column(&["contract_no", "htbh"]);
    }
    None
}

fn assistant_run_database_category_dimension(mapping: &MySqlTableMapping) -> Option<String> {
    let columns = assistant_run_database_mapping_columns(mapping);
    columns
        .iter()
        .find(|column| column.eq_ignore_ascii_case("areatype"))
        .cloned()
        .or_else(|| {
            columns
                .iter()
                .find(|column| {
                    let lower = column.to_ascii_lowercase();
                    lower.contains("category")
                        || lower.contains("type")
                        || lower.contains("class")
                        || lower.contains("kind")
                        || lower.contains("status")
                        || lower.contains("level")
                })
                .cloned()
        })
}

fn assistant_run_database_aggregate_metrics(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Vec<String> {
    let mut metrics = Vec::new();
    if prompt_has_metric_terms(
        prompt,
        &[
            "取高",
            "高分成",
            "分成线",
            "缺口",
            "差多少",
            "还差",
            "需增",
            "机会",
            "接近",
            "就快",
        ],
    ) {
        push_database_metric_if_present(mapping, &mut metrics, "xuzengxiaoshou");
        push_database_metric_if_present(mapping, &mut metrics, "quekou");
    }
    if prompt_has_metric_terms(prompt, &["销售", "销售额", "成交", "sale", "sales", "sold"])
    {
        push_database_metric_if_present(mapping, &mut metrics, "amttotal");
        push_database_metric_if_present(mapping, &mut metrics, "amtsold");
        push_database_metric_if_present(mapping, &mut metrics, "sale_num");
        push_database_metric_if_present(mapping, &mut metrics, "salenum");
    }
    if prompt_has_metric_terms(prompt, &["租金", "提成", "固定", "rent", "fee"]) {
        push_database_metric_if_present(mapping, &mut metrics, "tichengzujin");
        push_database_metric_if_present(mapping, &mut metrics, "yuezujin");
        push_database_metric_if_present(mapping, &mut metrics, "htzj");
    }
    if prompt_has_metric_terms(prompt, &["down", "下行", "离开", "离场", "出场", "出口"])
    {
        push_database_metric_if_present(mapping, &mut metrics, "down");
    }
    if prompt_has_metric_terms(prompt, &["up", "上行", "进入", "进场", "入口"]) {
        push_database_metric_if_present(mapping, &mut metrics, "up");
    }
    if metrics.is_empty() && prompt_has_metric_terms(prompt, &["流量", "客流", "traffic"]) {
        push_database_metric_if_present(mapping, &mut metrics, "up");
        push_database_metric_if_present(mapping, &mut metrics, "down");
    }
    if metrics.is_empty() {
        for column in assistant_run_database_metric_columns(mapping) {
            push_unique_string(&mut metrics, &column);
            if metrics.len() >= ASSISTANT_RUN_DATABASE_AGGREGATE_METRIC_LIMIT {
                break;
            }
        }
    }
    metrics.truncate(ASSISTANT_RUN_DATABASE_AGGREGATE_METRIC_LIMIT);
    metrics
}

fn push_database_metric_if_present(
    mapping: &MySqlTableMapping,
    metrics: &mut Vec<String>,
    column: &str,
) {
    if metrics.iter().any(|metric| metric == column) {
        return;
    }
    if assistant_run_database_mapping_columns(mapping)
        .iter()
        .any(|candidate| candidate == column)
    {
        metrics.push(column.to_string());
    }
}

fn assistant_run_database_aggregate_dimensions(
    mapping: &MySqlTableMapping,
    prompt: &str,
) -> Vec<String> {
    let mut dimensions = Vec::new();
    let wants_time = prompt_has_any(
        prompt,
        &[
            "时间", "日期", "小时", "日", "趋势", "txdate", "date", "time", "by time",
        ],
    );
    let wants_entity = prompt_has_any(
        prompt,
        &[
            "区域", "位置", "楼层", "门", "梯", "点位", "areaname", "area", "top", "排名", "排行",
            "排序", "前",
        ],
    );
    if wants_entity {
        if let Some(dimension) = assistant_run_database_prompt_entity_dimension(mapping, prompt)
            .or_else(|| assistant_run_database_entity_dimension(mapping))
        {
            push_unique_string(&mut dimensions, &dimension);
        }
    }
    if wants_time {
        if let Some(time_column) = assistant_run_database_time_column(mapping) {
            push_unique_string(&mut dimensions, &time_column);
        }
    }
    if dimensions.is_empty() {
        if let Some(title_column) = mapping.title_column.as_deref() {
            push_unique_string(&mut dimensions, title_column);
        }
    }
    dimensions.truncate(3);
    dimensions
}

fn assistant_run_database_time_column(mapping: &MySqlTableMapping) -> Option<String> {
    let columns = assistant_run_database_mapping_columns(mapping);
    columns
        .iter()
        .find(|column| column.eq_ignore_ascii_case("txdate"))
        .cloned()
        .or_else(|| {
            columns
                .iter()
                .find(|column| {
                    let lower = column.to_ascii_lowercase();
                    lower.contains("date") || lower.contains("time")
                })
                .cloned()
        })
}

fn assistant_run_database_aggregation(prompt: &str, has_metric: bool) -> String {
    if !has_metric {
        return "count".to_string();
    }
    if prompt_has_any(prompt, &["平均", "avg", "average"]) {
        "avg".to_string()
    } else if prompt_has_any(prompt, &["最低", "最小", "min"]) {
        "min".to_string()
    } else if prompt_has_any(prompt, &["单点最大", "最大值", "max"]) {
        "max".to_string()
    } else {
        "sum".to_string()
    }
}

fn assistant_run_database_aggregate_order_direction(prompt: &str, metric: Option<&str>) -> String {
    if prompt_has_any(prompt, &["最低", "最小", "min", "升序"]) {
        return "asc".to_string();
    }
    let metric = metric.unwrap_or("").to_ascii_lowercase();
    let gap_metric = metric.contains("xuzeng")
        || metric.contains("quekou")
        || metric.contains("gap")
        || metric.contains("shortfall");
    if gap_metric
        && prompt_has_any(
            prompt,
            &[
                "取高机会",
                "机会最大",
                "最接近",
                "接近",
                "就快",
                "差多少",
                "还差",
                "高分成线",
            ],
        )
        && !prompt_has_any(prompt, &["缺口最大", "最大缺口", "差距最大"])
    {
        return "asc".to_string();
    }
    "desc".to_string()
}

fn assistant_run_database_aggregate_latest_time_column(
    mapping: &MySqlTableMapping,
    prompt: &str,
    metric: Option<&str>,
    aggregate_plan: &AssistantRunDatabaseAggregatePlan,
) -> Option<String> {
    if aggregate_plan.intent == "time_series" {
        return None;
    }
    let time_column = assistant_run_database_time_column(mapping)?;
    if aggregate_plan
        .dimensions
        .iter()
        .any(|dimension| dimension == &time_column)
    {
        return None;
    }
    if prompt_has_any(
        prompt,
        &[
            "趋势",
            "变化",
            "按日",
            "按天",
            "按时间",
            "历史",
            "区间",
            "同比",
            "环比",
            "trend",
        ],
    ) {
        return None;
    }
    let metric = metric.unwrap_or("").to_ascii_lowercase();
    let current_metric = metric.contains("yuezujin")
        || metric.contains("zujin")
        || metric.contains("rent")
        || metric.contains("amttotal")
        || metric.contains("ticheng")
        || metric.contains("xuzeng")
        || metric.contains("quekou")
        || metric.contains("dayamt")
        || metric.contains("salenum")
        || metric.contains("sale");
    let current_prompt = prompt_has_any(
        prompt,
        &[
            "当前",
            "现在",
            "目前",
            "本月",
            "最新",
            "经营健康度",
            "总览",
            "月租金",
            "租金",
            "取高",
            "高分成",
            "缺口",
            "销售额",
            "还差",
            "最接近",
        ],
    );
    if current_metric || current_prompt {
        return Some(time_column);
    }
    None
}

fn assistant_run_database_mapping_columns(mapping: &MySqlTableMapping) -> Vec<String> {
    let mut columns = Vec::new();
    push_unique_string(&mut columns, &mapping.id_column);
    for column in &mapping.id_columns {
        push_unique_string(&mut columns, column);
    }
    if let Some(column) = mapping.title_column.as_deref() {
        push_unique_string(&mut columns, column);
    }
    for column in &mapping.content_columns {
        push_unique_string(&mut columns, column);
    }
    if let Some(column) = mapping.updated_at_column.as_deref() {
        push_unique_string(&mut columns, column);
    }
    if let Some(column) = mapping.version_column.as_deref() {
        push_unique_string(&mut columns, column);
    }
    for column in &mapping.metadata_columns {
        push_unique_string(&mut columns, column);
    }
    columns
}

fn assistant_run_database_aggregate_scan_limit() -> u32 {
    std::env::var("ASSISTANT_RUN_DATABASE_AGGREGATE_SCAN_LIMIT")
        .ok()
        .and_then(|value| value.parse::<u32>().ok())
        .unwrap_or(ASSISTANT_RUN_DATABASE_AGGREGATE_SCAN_LIMIT_DEFAULT)
        .clamp(1, ASSISTANT_RUN_DATABASE_AGGREGATE_SCAN_LIMIT_MAX)
}

async fn build_assistant_run_document_parse_status_supply(
    state: &AppState,
    dataset: &Dataset,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<Vec<Value>, ApiError> {
    let candidate_documents = list_documents_for_dataset_scope(state, dataset.id)
        .await?
        .into_iter()
        .filter(|document| owner_user_id_is_visible(document.owner_user_id, current_user_id))
        .filter(|document| {
            selected_document_ids.is_empty() || selected_document_ids.contains(&document.id)
        })
        .collect::<Vec<_>>();

    if candidate_documents.is_empty() {
        return Ok(Vec::new());
    }

    let mut documents = Vec::new();
    let mut limited_by_document_limit = false;
    for document in candidate_documents {
        if documents.len() >= ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_DOCUMENT_LIMIT {
            limited_by_document_limit = true;
            break;
        }
        if !document_is_visible_for_external_acl(
            state,
            external_acl_filter,
            &document,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?
        {
            continue;
        }
        documents.push(document);
    }

    if documents.is_empty() {
        return Ok(Vec::new());
    }

    let document_ids = documents
        .iter()
        .map(|document| document.id)
        .collect::<Vec<_>>();
    let workflow_by_document =
        load_latest_upload_ingest_workflow_snapshots(state, dataset.id, &document_ids).await?;

    let mut scanned_document_count = 0usize;
    let mut status_counts = BTreeMap::<String, usize>::new();
    let mut attention_documents = Vec::new();
    let mut active_parse_count = 0usize;
    let mut failed_document_count = 0usize;
    let mut reparsing_document_count = 0usize;
    let mut degraded_parse_count = 0usize;

    for document in documents {
        scanned_document_count += 1;

        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        let parse_status = assistant_scope_document_parse_status(&document, &chunks);
        let inferred_parse_quality_summary =
            assistant_run_inferred_low_text_parse_quality_summary(&document, &chunks);
        let parse_quality_summary = assistant_run_document_parse_quality_summary(&document)
            .or_else(|| inferred_parse_quality_summary.clone());
        let parse_quality_status =
            assistant_run_document_parse_quality_status(&document).or_else(|| {
                parse_quality_summary
                    .as_ref()
                    .and_then(|summary| value_at_any_key(summary, &["status"]))
                    .and_then(Value::as_str)
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .map(ToOwned::to_owned)
            });
        let workflow = workflow_by_document.get(&document.id);
        let model_status = assistant_run_document_parse_model_status(
            &document,
            &parse_status,
            chunks.len(),
            parse_quality_status.as_deref(),
            workflow,
        );
        *status_counts.entry(model_status.clone()).or_insert(0) += 1;

        if assistant_run_document_parse_status_is_active(&model_status) {
            active_parse_count += 1;
        }
        if model_status == "failed" {
            failed_document_count += 1;
        }
        if model_status == "reparsing" || model_status == "reparse_queued" {
            reparsing_document_count += 1;
        }
        if model_status == "parse_degraded" {
            degraded_parse_count += 1;
        }

        if assistant_run_document_parse_status_needs_attention(&model_status) {
            let mut item = json!({
                "document_id": document.id,
                "title": document.title.clone(),
                "content_type": document.content_type.clone(),
                "lifecycle": document.lifecycle.as_str(),
                "parse_status": parse_status,
                "model_status": model_status,
                "chunk_count": chunks.len(),
                "updated_at": document.updated_at,
                "ingest": assistant_run_document_ingest_summary(&document),
            });
            if let Some(parse_quality_status) = parse_quality_status {
                set_payload_string(&mut item, "parse_quality_status", &parse_quality_status);
            }
            if let Some(parse_quality_summary) = parse_quality_summary {
                set_payload_value(&mut item, "parse_quality_summary", parse_quality_summary);
            }
            if let Some(workflow) = workflow {
                set_payload_value(&mut item, "workflow", workflow.clone());
            }
            if let Some(external_ref) = assistant_run_document_external_ref(&document) {
                set_payload_value(&mut item, "external_document", external_ref);
            }
            attention_documents.push(item);
        }
    }

    if scanned_document_count == 0
        || (active_parse_count == 0 && failed_document_count == 0 && degraded_parse_count == 0)
    {
        return Ok(Vec::new());
    }

    let status_summary = assistant_scope_count_summary(&status_counts);
    let summary = format!(
        "文档解析状态：已扫描可见文档 {scanned_document_count} 份，状态分布 {status_summary}。未完成/失败/重解析中的文档仅代表资料暂不可完整引用；模型应据此说明解析状态，避免把未解析内容当作事实。"
    );

    Ok(vec![json!({
        "type": "document_parse_status",
        "source": "visible_document_ingest_state",
        "dataset_id": dataset.id,
        "summary": summary,
        "score": 1.0,
        "lexical_score": 1.0,
        "recall_score": 1.0,
        "scanned_document_count": scanned_document_count,
        "status_summary": status_summary,
        "status_counts": status_counts,
        "active_parse_count": active_parse_count,
        "failed_document_count": failed_document_count,
        "reparsing_document_count": reparsing_document_count,
        "degraded_parse_count": degraded_parse_count,
        "not_ready_document_count": active_parse_count + failed_document_count + degraded_parse_count,
        "attention_documents": attention_documents
            .into_iter()
            .take(ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_ATTENTION_LIMIT)
            .collect::<Vec<_>>(),
        "model_guidance": [
            "When a relevant document is parsing, queued, indexing, failed, reparsing, or parse_degraded, say the document content is not fully ready instead of guessing.",
            "Translate internal status codes such as parse_degraded or low_text_coverage into plain Chinese; do not show raw status identifiers to the user.",
            "If reparsing or reparse_queued is present, explain that a retry is already underway or queued.",
            "If parse_quality_summary.vlm_rescue is present, mention whether MiniMax VLM rescue was selected or whether the local parse was kept.",
            "Use ready retrieval evidence and fallback chunks for facts; use this item for document availability/status only."
        ],
        "limits": {
            "maxDocuments": ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_DOCUMENT_LIMIT,
            "maxAttentionDocuments": ASSISTANT_RUN_DOCUMENT_PARSE_STATUS_ATTENTION_LIMIT,
            "limitedByDocumentLimit": limited_by_document_limit,
        },
    })])
}

pub(crate) async fn load_latest_upload_ingest_workflow_snapshots(
    state: &AppState,
    dataset_id: DatasetId,
    document_ids: &[DocumentId],
) -> std::result::Result<HashMap<DocumentId, Value>, ApiError> {
    if document_ids.is_empty() {
        return Ok(HashMap::new());
    }
    let document_id_strings = document_ids
        .iter()
        .map(ToString::to_string)
        .collect::<Vec<_>>();
    let rows = sqlx::query(
        r#"
        select distinct on (e.context ->> 'document_id')
               e.context ->> 'document_id' as document_id,
               e.id as execution_id,
               e.status,
               e.stage,
               e.attempt,
               e.context,
               e.created_at,
               e.updated_at,
               (
                   select jsonb_build_object(
                       'task_id', t.id,
                       'queue', t.queue,
                       'task_key', t.task_key,
                       'status', t.status,
                       'attempt', t.attempt,
                       'max_attempts', t.max_attempts,
                       'available_at', t.available_at,
                       'claimed_at', t.claimed_at,
                       'finished_at', t.finished_at,
                       'error', t.error
                   )
                   from workflow_tasks t
                   where t.execution_id = e.id
                   order by t.updated_at desc, t.created_at desc
                   limit 1
               ) as latest_task
        from workflow_executions e
        where e.tenant_id = $1
          and e.dataset_id = $2
          and e.kind = $3
          and e.context ? 'document_id'
          and e.context ->> 'document_id' = any($4)
        order by e.context ->> 'document_id', e.updated_at desc, e.created_at desc
        "#,
    )
    .bind(state.tenant_id.0)
    .bind(dataset_id.0)
    .bind(WorkflowKind::UploadIngest.as_str())
    .bind(&document_id_strings)
    .fetch_all(state.storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    let mut snapshots = HashMap::new();
    for row in rows {
        let Some(document_id) = row
            .get::<Option<String>, _>("document_id")
            .and_then(|raw| Uuid::parse_str(raw.trim()).ok().map(DocumentId))
        else {
            continue;
        };
        let context = row.get::<Value, _>("context");
        let latest_task = row
            .try_get::<Option<Value>, _>("latest_task")
            .ok()
            .flatten();
        snapshots.insert(
            document_id,
            json!({
                "execution_id": WorkflowExecutionId(row.get("execution_id")),
                "status": row.get::<String, _>("status"),
                "stage": row.get::<String, _>("stage"),
                "attempt": row.get::<i32, _>("attempt"),
                "retries_remaining": context.get("retries_remaining").cloned().unwrap_or(Value::Null),
                "retry_reason": context.get("retry_reason").cloned().unwrap_or(Value::Null),
                "last_error": context.get("last_error").cloned().unwrap_or(Value::Null),
                "latest_task": latest_task,
                "created_at": row.get::<DateTime<Utc>, _>("created_at"),
                "updated_at": row.get::<DateTime<Utc>, _>("updated_at"),
            }),
        );
    }
    Ok(snapshots)
}

fn assistant_run_document_parse_model_status(
    document: &Document,
    parse_status: &str,
    chunk_count: usize,
    parse_quality_status: Option<&str>,
    workflow: Option<&Value>,
) -> String {
    let workflow_status = workflow
        .and_then(|value| value.get("status"))
        .and_then(Value::as_str)
        .unwrap_or("");
    let workflow_stage = workflow
        .and_then(|value| value.get("stage"))
        .and_then(Value::as_str)
        .unwrap_or("");
    let workflow_active = matches!(workflow_status, "pending" | "running");

    if workflow_active && document.lifecycle == DocumentLifecycle::Failed {
        return if workflow_status == "pending" {
            "reparse_queued".to_string()
        } else {
            "reparsing".to_string()
        };
    }
    if workflow_active && workflow_stage == "index_retrieval_artifacts" {
        return "indexing".to_string();
    }
    if workflow_active {
        return if workflow_status == "pending" {
            "queued".to_string()
        } else {
            "parsing".to_string()
        };
    }
    if document.lifecycle == DocumentLifecycle::Failed || parse_status == "failed" {
        return "failed".to_string();
    }
    if matches!(parse_status, "parse_degraded" | "placeholder")
        || parse_quality_status
            .map(|status| status.contains("low_text_coverage"))
            .unwrap_or(false)
    {
        return "parse_degraded".to_string();
    }
    if document.lifecycle == DocumentLifecycle::Received {
        return "received".to_string();
    }
    if document.lifecycle == DocumentLifecycle::Indexed {
        return "ready".to_string();
    }
    if document.lifecycle == DocumentLifecycle::Extracted && chunk_count > 0 {
        return "extracted_pending_index".to_string();
    }
    document.lifecycle.as_str().to_string()
}

fn assistant_run_document_parse_status_is_active(status: &str) -> bool {
    matches!(
        status,
        "queued" | "parsing" | "indexing" | "reparsing" | "reparse_queued"
    )
}

fn assistant_run_document_parse_status_needs_attention(status: &str) -> bool {
    !matches!(status, "ready" | "extracted_pending_index" | "archived")
}

fn assistant_run_document_parse_quality_status(document: &Document) -> Option<String> {
    assistant_run_document_parse_quality_metadata(document)
        .and_then(|parse_quality| value_at_any_key(parse_quality, &["status"]))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
}

fn assistant_run_document_parse_quality_metadata(document: &Document) -> Option<&Value> {
    let ingest = document
        .metadata
        .get("ingest")
        .filter(|value| value.is_object())?;
    value_at_any_key(ingest, &["parse_metadata", "parseMetadata"])
        .and_then(|parse_metadata| {
            value_at_any_key(parse_metadata, &["parse_quality", "parseQuality"])
        })
        .filter(|value| value.is_object())
}

fn assistant_run_document_parse_quality_summary(document: &Document) -> Option<Value> {
    let ingest = document
        .metadata
        .get("ingest")
        .filter(|value| value.is_object())?;
    let parse_quality = assistant_run_document_parse_quality_metadata(document)?;
    let mut summary = Map::new();

    copy_json_fields(
        ingest,
        &mut summary,
        &[
            "parse_method",
            "parse_status",
            "parse_quality_status",
            "cloud_structured_provider",
        ],
    );
    copy_json_fields(
        parse_quality,
        &mut summary,
        &[
            "kind",
            "status",
            "text_chars",
            "min_usable_text_chars",
            "fallback_status",
            "recommended_fallback",
        ],
    );
    if let Some(fallback_from) = value_at_any_key(parse_quality, &["fallback_from", "fallbackFrom"])
        .and_then(compact_parse_quality_candidate_report)
    {
        summary.insert("fallback_from".to_string(), fallback_from);
    }
    if let Some(candidate_selection) =
        assistant_run_parse_quality_candidate_selection_summary(parse_quality)
    {
        summary.insert("candidate_selection".to_string(), candidate_selection);
    }
    if let Some(vlm_rescue) = assistant_run_parse_quality_vlm_rescue_summary(parse_quality) {
        summary.insert("vlm_rescue".to_string(), vlm_rescue);
    }
    if let Some(auto_reparse) = value_at_any_key(ingest, &["auto_reparse", "autoReparse"])
        .and_then(assistant_run_auto_reparse_summary)
    {
        summary.insert("auto_reparse".to_string(), auto_reparse);
    }

    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn assistant_run_inferred_low_text_parse_quality_summary(
    document: &Document,
    chunks: &[DocumentChunk],
) -> Option<Value> {
    if !assistant_run_document_is_pdf_like(document) || chunks.is_empty() {
        return None;
    }
    let text_chars = chunks
        .iter()
        .map(|chunk| assistant_run_low_text_parse_signal_chars(&chunk.content))
        .sum::<usize>();
    if text_chars >= ASSISTANT_RUN_INFERRED_LOW_TEXT_PARSE_MIN_CHARS {
        return None;
    }
    Some(json!({
        "kind": "pdf_text_extraction",
        "status": "low_text_coverage",
        "text_chars": text_chars,
        "min_usable_text_chars": ASSISTANT_RUN_INFERRED_LOW_TEXT_PARSE_MIN_CHARS,
        "inferred_from": "stored_document_chunks",
        "fallback_status": "recommended",
        "recommended_fallback": "ocr_reparse"
    }))
}

fn assistant_run_document_is_pdf_like(document: &Document) -> bool {
    document
        .content_type
        .eq_ignore_ascii_case("application/pdf")
        || document.title.to_ascii_lowercase().ends_with(".pdf")
        || document.object_key.to_ascii_lowercase().ends_with(".pdf")
}

fn assistant_run_low_text_parse_signal_chars(text: &str) -> usize {
    text.chars()
        .filter(|ch| {
            !ch.is_whitespace()
                && !ch.is_ascii_punctuation()
                && !matches!(
                    *ch,
                    '。' | '，'
                        | '、'
                        | '；'
                        | '：'
                        | '！'
                        | '？'
                        | '（'
                        | '）'
                        | '【'
                        | '】'
                        | '《'
                        | '》'
                        | '“'
                        | '”'
                        | '‘'
                        | '’'
                        | '-'
                        | '—'
                        | '_'
                        | '|'
                )
        })
        .count()
}

fn assistant_run_parse_quality_candidate_selection_summary(parse_quality: &Value) -> Option<Value> {
    let candidate_selection = value_at_any_key(
        parse_quality,
        &["candidate_selection", "candidateSelection"],
    )?;
    let mut summary = Map::new();
    copy_json_fields(
        candidate_selection,
        &mut summary,
        &["policy", "selected_method"],
    );
    if let Some(selected) = value_at_any_key(candidate_selection, &["selected"])
        .and_then(compact_parse_quality_candidate_report)
    {
        summary.insert("selected".to_string(), selected);
    }
    if let Some(candidate_count) = value_at_any_key(candidate_selection, &["candidates"])
        .and_then(Value::as_array)
        .map(Vec::len)
    {
        summary.insert("candidate_count".to_string(), json!(candidate_count));
    }
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn assistant_run_parse_quality_vlm_rescue_summary(parse_quality: &Value) -> Option<Value> {
    let vlm_rescue = value_at_any_key(parse_quality, &["vlm_rescue", "vlmRescue"])?;
    let mut summary = Map::new();
    copy_json_fields(vlm_rescue, &mut summary, &["policy", "selected"]);
    for key in ["existing", "vlm"] {
        if let Some(report) =
            value_at_any_key(vlm_rescue, &[key]).and_then(compact_parse_quality_candidate_report)
        {
            summary.insert(key.to_string(), report);
        }
    }
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn assistant_run_auto_reparse_summary(auto_reparse: &Value) -> Option<Value> {
    let mut summary = Map::new();
    copy_json_fields(
        auto_reparse,
        &mut summary,
        &[
            "status",
            "reason",
            "attempt_count",
            "max_attempts",
            "updated_at",
        ],
    );
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn compact_parse_quality_candidate_report(value: &Value) -> Option<Value> {
    let mut summary = Map::new();
    copy_json_fields(
        value,
        &mut summary,
        &[
            "method",
            "text_chars",
            "structure_block_count",
            "heading_count",
            "table_signal_count",
            "quality_score",
        ],
    );
    if summary.is_empty() {
        None
    } else {
        Some(Value::Object(summary))
    }
}

fn assistant_run_document_ingest_summary(document: &Document) -> Value {
    let Some(ingest) = document
        .metadata
        .get("ingest")
        .filter(|value| value.is_object())
    else {
        return Value::Null;
    };
    let mut summary = Map::new();
    for key in [
        "processor",
        "parse_method",
        "cloud_structured_provider",
        "chunk_count",
        "extracted_chars",
        "failed_at",
        "last_error",
    ] {
        if let Some(value) = ingest.get(key).cloned() {
            summary.insert(key.to_string(), value);
        }
    }
    if let Some(parse_quality_status) = assistant_run_document_parse_quality_status(document) {
        summary.insert(
            "parse_quality_status".to_string(),
            json!(parse_quality_status),
        );
    }
    if let Some(parse_quality_summary) = assistant_run_document_parse_quality_summary(document) {
        summary.insert("parse_quality_summary".to_string(), parse_quality_summary);
    }
    Value::Object(summary)
}

fn assistant_run_document_external_ref(document: &Document) -> Option<Value> {
    let external_source = document
        .metadata
        .get("external_source")
        .or_else(|| document.metadata.get("externalSource"))?
        .as_object()?;
    let source_id = external_source
        .get("source_id")
        .or_else(|| external_source.get("sourceId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let document_external_id = external_source
        .get("document_external_id")
        .or_else(|| external_source.get("documentExternalId"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    Some(json!({
        "source_id": source_id,
        "document_external_id": document_external_id,
        "revision_external_id": external_source
            .get("revision_external_id")
            .or_else(|| external_source.get("revisionExternalId"))
            .and_then(Value::as_str),
    }))
}

async fn build_assistant_run_dataset_entity_scan_supply(
    state: &AppState,
    dataset: &Dataset,
    current_user_id: Option<UserId>,
    external_acl_filter: Option<&ExternalAclFilterContext>,
    selected_document_ids: &[DocumentId],
    allow_selected_documents_without_acl_snapshot: bool,
) -> std::result::Result<Vec<Value>, ApiError> {
    let documents = list_documents_for_dataset_scope(state, dataset.id)
        .await?
        .into_iter()
        .filter(|document| {
            document_is_visible_for_assistant_evidence_owner_scope(
                document,
                current_user_id,
                selected_document_ids,
                allow_selected_documents_without_acl_snapshot,
            )
        })
        .filter(|document| {
            selected_document_ids.is_empty() || selected_document_ids.contains(&document.id)
        })
        .collect::<Vec<_>>();

    let mut scanned_document_count = 0usize;
    let mut limited_by_document_limit = false;
    let mut entities_by_key: BTreeMap<(String, String), BTreeSet<String>> = BTreeMap::new();
    let mut candidate_terms_by_name: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut years_by_year: BTreeMap<i32, BTreeSet<String>> = BTreeMap::new();
    let mut sections_by_title: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut paragraphs_by_excerpt: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut tables_by_signal: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut document_hits = Vec::new();
    let mut resume_profile_rows = Vec::new();
    let mut resume_project_delivery_rows = Vec::new();

    for document in documents {
        if scanned_document_count >= ASSISTANT_RUN_DATASET_ENTITY_SCAN_DOCUMENT_LIMIT {
            limited_by_document_limit = true;
            break;
        }
        if !document_is_visible_for_external_acl(
            state,
            external_acl_filter,
            &document,
            selected_document_ids,
            allow_selected_documents_without_acl_snapshot,
        )
        .await?
        {
            continue;
        }
        scanned_document_count += 1;

        let chunks = state
            .storage
            .document_chunks()
            .list_by_document(state.tenant_id, document.id)
            .await
            .map_err(ApiError::from_storage)?;
        let scan_text = dataset_entity_scan_text(&document, &chunks);
        let structured_entity_candidates =
            extract_document_entity_candidates_from_chunk_metadata(&chunks, 64);
        let has_structured_organizations = structured_entity_candidates
            .iter()
            .any(|candidate| candidate.entity_type == "organization");
        let text_scan = if has_structured_organizations {
            dataset_entity_scan_structured_text(&document, &chunks)
                .unwrap_or_else(|| scan_text.clone())
        } else {
            scan_text.clone()
        };
        let entity_candidates = merge_document_entity_candidates(
            structured_entity_candidates,
            extract_document_entity_candidates_from_text(&text_scan, 64),
            64,
        );
        let company_names = entity_candidates
            .iter()
            .filter(|candidate| candidate.entity_type == "organization")
            .map(|candidate| candidate.name.clone())
            .collect::<Vec<_>>();
        let candidate_terms = extract_document_candidate_terms_for_scan(&chunks, &scan_text, 32);
        let document_years = extract_resume_years(&scan_text, 32);
        let section_titles = extract_document_section_titles_for_scan(&chunks, &scan_text, 32);
        let paragraph_samples = extract_document_paragraphs_for_scan(&chunks, 16);
        let table_signals = extract_document_table_signals_for_scan(&chunks, &scan_text, 16);
        let resume_profile =
            extract_resume_document_profile(&document, &text_scan, &entity_candidates);
        let document_project_delivery_rows = extract_resume_project_delivery_rows(
            &document,
            &chunks,
            &resume_profile,
            &entity_candidates,
            ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_ROW_LIMIT
                .saturating_sub(resume_project_delivery_rows.len()),
        );
        if entity_candidates.is_empty()
            && candidate_terms.is_empty()
            && document_years.is_empty()
            && section_titles.is_empty()
            && paragraph_samples.is_empty()
            && table_signals.is_empty()
            && document_project_delivery_rows.is_empty()
            && resume_profile.is_empty()
        {
            continue;
        }

        for candidate in &entity_candidates {
            entities_by_key
                .entry((candidate.entity_type.to_string(), candidate.name.clone()))
                .or_default()
                .insert(document.id.to_string());
        }
        for term in &candidate_terms {
            candidate_terms_by_name
                .entry(term.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for year in &document_years {
            years_by_year
                .entry(*year)
                .or_default()
                .insert(document.id.to_string());
        }
        for title in &section_titles {
            sections_by_title
                .entry(title.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for paragraph in &paragraph_samples {
            paragraphs_by_excerpt
                .entry(paragraph.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for table_signal in &table_signals {
            tables_by_signal
                .entry(table_signal.clone())
                .or_default()
                .insert(document.id.to_string());
        }
        for delivery_row in &document_project_delivery_rows {
            if !delivery_row.project_name_is_placeholder() {
                entities_by_key
                    .entry(("project".to_string(), delivery_row.project_name.clone()))
                    .or_default()
                    .insert(document.id.to_string());
            }
        }
        if !resume_profile.is_empty()
            && resume_profile_rows.len() < ASSISTANT_RUN_RESUME_PROFILE_ROW_LIMIT
        {
            resume_profile_rows.push(resume_profile.to_value());
        }
        if !document_project_delivery_rows.is_empty()
            && resume_project_delivery_rows.len() < ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_ROW_LIMIT
        {
            resume_project_delivery_rows.extend(
                document_project_delivery_rows
                    .into_iter()
                    .take(
                        ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_ROW_LIMIT
                            .saturating_sub(resume_project_delivery_rows.len()),
                    )
                    .map(|row| row.to_value()),
            );
        }
        document_hits.push(json!({
            "document_id": document.id,
            "company_names": company_names,
            "entities": entity_candidates
                .iter()
                .take(24)
                .map(|candidate| json!({
                    "type": candidate.entity_type,
                    "name": candidate.name.clone(),
                }))
                .collect::<Vec<_>>(),
            "candidate_terms": candidate_terms,
            "years": document_years,
            "section_titles": section_titles,
            "paragraph_samples": paragraph_samples,
            "table_signals": table_signals,
        }));
    }

    if scanned_document_count == 0 {
        return Ok(Vec::new());
    }

    let entity_count = entities_by_key.len();
    let organization_count = entities_by_key
        .keys()
        .filter(|(entity_type, _)| entity_type == "organization")
        .count();
    let candidate_term_count = candidate_terms_by_name.len();
    let year_count = years_by_year.len();
    let section_count = sections_by_title.len();
    let paragraph_count = paragraphs_by_excerpt.len();
    let table_signal_count = tables_by_signal.len();
    let mut organization_rows = entities_by_key
        .iter()
        .filter(|((entity_type, _), _)| entity_type == "organization")
        .map(|((_, name), document_ids)| (name.clone(), document_ids.clone()))
        .collect::<Vec<_>>();
    organization_rows.sort_by(
        |(left_name, left_documents), (right_name, right_documents)| {
            right_documents
                .len()
                .cmp(&left_documents.len())
                .then_with(|| left_name.cmp(right_name))
        },
    );
    let company_rows = organization_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(name, document_ids)| {
            json!({
                "name": name,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect::<Vec<_>>();
    let company_names = organization_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(name, _)| name.clone())
        .collect::<Vec<_>>();
    let skill_rows = entity_rows_for_type(&entities_by_key, "skill");
    let project_rows = entity_rows_for_type(&entities_by_key, "project");
    let position_rows = entity_rows_for_type(&entities_by_key, "position");
    let location_rows = entity_rows_for_type(&entities_by_key, "location");
    let person_rows = entity_rows_for_type(&entities_by_key, "person");
    let school_rows = entity_rows_for_type(&entities_by_key, "school");
    let degree_rows = entity_rows_for_type(&entities_by_key, "degree");
    let certificate_rows = entity_rows_for_type(&entities_by_key, "certificate");
    let keyword_rows = candidate_term_rows_for_scan(&candidate_terms_by_name);
    let year_rows = year_rows_for_scan(&years_by_year);
    let section_rows = structure_rows_for_scan(&sections_by_title);
    let paragraph_rows = structure_rows_for_scan(&paragraphs_by_excerpt);
    let table_rows = structure_rows_for_scan(&tables_by_signal);
    let entity_rows_by_type = json!({
        "organization": company_rows.clone(),
        "skill": skill_rows.clone(),
        "project": project_rows.clone(),
        "position": position_rows.clone(),
        "location": location_rows.clone(),
        "person": person_rows.clone(),
        "school": school_rows.clone(),
        "degree": degree_rows.clone(),
        "certificate": certificate_rows.clone(),
        "keyword": keyword_rows.clone(),
        "year": year_rows.clone(),
        "section": section_rows.clone(),
        "paragraph": paragraph_rows.clone(),
        "table": table_rows.clone(),
    });
    let company_summary = organization_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .map(|(name, document_ids)| {
            if document_ids.len() > 1 {
                format!("{name}({}份)", document_ids.len())
            } else {
                name.clone()
            }
        })
        .collect::<Vec<_>>()
        .join("、");
    let entity_views = entities_by_key
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .map(|((entity_type, name), document_ids)| {
            json!({
                "type": entity_type,
                "name": name,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect::<Vec<_>>();
    let candidate_term_views = keyword_rows
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .cloned()
        .collect::<Vec<_>>();
    let entity_summary = entities_by_key
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT)
        .map(|((entity_type, name), document_ids)| {
            let label = document_entity_type_label(entity_type);
            if document_ids.len() > 1 {
                format!("{label}:{name}({}份)", document_ids.len())
            } else {
                format!("{label}:{name}")
            }
        })
        .collect::<Vec<_>>()
        .join("、");
    let summary = if entity_summary.is_empty() {
        format!(
            "资料库实体扫描：已扫描可见文档 {scanned_document_count} 份，未识别到明确实体，候选名词 {candidate_term_count} 个。"
        )
    } else {
        let company_part = if company_summary.is_empty() {
            entity_summary
        } else {
            company_summary
        };
        format!(
            "资料库实体扫描：已扫描可见文档 {scanned_document_count} 份，识别实体 {entity_count} 个，其中公司/组织 {organization_count} 个，候选名词 {candidate_term_count} 个。公司/组织统计以 company_rows 和 company_count 为准：{company_part}。"
        )
    };

    let mut item = Map::new();
    item.insert("type".to_string(), json!("dataset_entity_scan"));
    item.insert("source".to_string(), json!("visible_document_scan"));
    item.insert("dataset_id".to_string(), json!(dataset.id));
    item.insert("entity_type".to_string(), json!("document_entity_scan"));
    item.insert(
        "legacy_entity_type".to_string(),
        json!("company_or_organization"),
    );
    item.insert(
        "entity_types".to_string(),
        json!([
            "organization",
            "person",
            "position",
            "skill",
            "location",
            "project",
            "school",
            "degree",
            "certificate",
            "keyword",
            "year",
            "section",
            "paragraph",
            "table"
        ]),
    );
    item.insert("summary".to_string(), json!(summary));
    item.insert("score".to_string(), json!(1.0));
    item.insert("lexical_score".to_string(), json!(1.0));
    item.insert("recall_score".to_string(), json!(1.0));
    item.insert(
        "scanned_document_count".to_string(),
        json!(scanned_document_count),
    );
    item.insert("entity_count".to_string(), json!(entity_count));
    item.insert("organization_count".to_string(), json!(organization_count));
    item.insert("company_count".to_string(), json!(organization_count));
    item.insert("company_rows".to_string(), Value::Array(company_rows));
    item.insert("skill_rows".to_string(), Value::Array(skill_rows));
    item.insert("project_rows".to_string(), Value::Array(project_rows));
    item.insert("position_rows".to_string(), Value::Array(position_rows));
    item.insert("location_rows".to_string(), Value::Array(location_rows));
    item.insert("person_rows".to_string(), Value::Array(person_rows));
    item.insert("school_rows".to_string(), Value::Array(school_rows));
    item.insert("degree_rows".to_string(), Value::Array(degree_rows));
    item.insert(
        "certificate_rows".to_string(),
        Value::Array(certificate_rows),
    );
    item.insert("entity_rows_by_type".to_string(), entity_rows_by_type);
    item.insert(
        "resume_profile_rows".to_string(),
        Value::Array(resume_profile_rows),
    );
    item.insert(
        "resume_project_delivery_rows".to_string(),
        Value::Array(resume_project_delivery_rows),
    );
    item.insert(
        "candidate_term_count".to_string(),
        json!(candidate_term_count),
    );
    item.insert("year_count".to_string(), json!(year_count));
    item.insert("section_count".to_string(), json!(section_count));
    item.insert("paragraph_count".to_string(), json!(paragraph_count));
    item.insert("table_signal_count".to_string(), json!(table_signal_count));
    item.insert("keyword_rows".to_string(), Value::Array(keyword_rows));
    item.insert("year_rows".to_string(), Value::Array(year_rows));
    item.insert("section_rows".to_string(), Value::Array(section_rows));
    item.insert("paragraph_rows".to_string(), Value::Array(paragraph_rows));
    item.insert("table_rows".to_string(), Value::Array(table_rows));
    item.insert("company_names".to_string(), json!(company_names));
    item.insert("entities".to_string(), Value::Array(entity_views));
    item.insert(
        "candidate_terms".to_string(),
        Value::Array(candidate_term_views),
    );
    item.insert(
        "document_hits".to_string(),
        Value::Array(document_hits.into_iter().take(24).collect::<Vec<_>>()),
    );
    item.insert(
        "answer_guidance".to_string(),
        json!({
            "company_count_authoritative": organization_count,
            "scanned_document_count_authoritative": scanned_document_count,
            "company_rows_authoritative": true,
            "entity_rows_by_type_authoritative": true,
            "keyword_rows_authoritative": true,
            "year_rows_authoritative": true,
            "section_rows_authoritative": true,
            "paragraph_rows_authoritative": true,
            "table_rows_authoritative": true,
            "resume_profile_rows_authoritative": true,
            "resume_project_delivery_rows_authoritative": true,
            "ignore_candidate_terms_for_company_count": true,
            "do_not_sum_company_row_document_counts_as_total_documents": true,
            "candidate_terms_are_only_noun_hints": true,
        }),
    );
    item.insert(
        "limits".to_string(),
        json!({
            "maxDocuments": ASSISTANT_RUN_DATASET_ENTITY_SCAN_DOCUMENT_LIMIT,
            "maxChunksPerDocument": ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT,
            "maxEntities": ASSISTANT_RUN_DATASET_ENTITY_SCAN_ENTITY_LIMIT,
            "maxCompanyRows": ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT,
            "limitedByDocumentLimit": limited_by_document_limit,
        }),
    );

    Ok(vec![Value::Object(item)])
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct DocumentEntityCandidate {
    entity_type: &'static str,
    name: String,
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
struct ResumeDocumentProfile {
    document_id: String,
    document_title: String,
    candidate_name: Option<String>,
    gender: Option<String>,
    age: Option<u64>,
    birth_year: Option<i32>,
    earliest_year: Option<i32>,
    latest_year: Option<i32>,
    year_count: usize,
    company_count: usize,
    skill_count: usize,
    project_count: usize,
    position_count: usize,
    location_count: usize,
    certificate_count: usize,
    company_names: Vec<String>,
    skill_names: Vec<String>,
    project_names: Vec<String>,
    position_names: Vec<String>,
    location_names: Vec<String>,
    school_names: Vec<String>,
    degree_names: Vec<String>,
    certificate_names: Vec<String>,
}

impl ResumeDocumentProfile {
    fn is_empty(&self) -> bool {
        self.candidate_name.is_none()
            && self.gender.is_none()
            && self.age.is_none()
            && self.birth_year.is_none()
            && self.earliest_year.is_none()
            && self.latest_year.is_none()
            && self.company_count == 0
            && self.skill_count == 0
            && self.project_count == 0
            && self.position_count == 0
            && self.location_count == 0
            && self.certificate_count == 0
            && self.school_names.is_empty()
            && self.degree_names.is_empty()
    }

    fn to_value(&self) -> Value {
        json!({
            "document_id": self.document_id,
            "document_title": self.document_title,
            "candidate_name": self.candidate_name,
            "gender": self.gender,
            "age": self.age,
            "birth_year": self.birth_year,
            "earliest_year": self.earliest_year,
            "latest_year": self.latest_year,
            "year_count": self.year_count,
            "company_count": self.company_count,
            "skill_count": self.skill_count,
            "project_count": self.project_count,
            "position_count": self.position_count,
            "location_count": self.location_count,
            "certificate_count": self.certificate_count,
            "company_names": &self.company_names,
            "skill_names": &self.skill_names,
            "project_names": &self.project_names,
            "position_names": &self.position_names,
            "location_names": &self.location_names,
            "school_names": &self.school_names,
            "degree_names": &self.degree_names,
            "certificate_names": &self.certificate_names,
        })
    }
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ResumeProjectDeliveryRow {
    document_id: String,
    document_title: String,
    candidate_name: String,
    project_name: String,
    delivery_summary: String,
    tech_stack: Vec<String>,
    source_locator: String,
    chunk_index: i32,
    confidence: String,
}

impl ResumeProjectDeliveryRow {
    fn project_name_is_placeholder(&self) -> bool {
        self.project_name == "未识别项目名称"
    }

    fn to_value(self) -> Value {
        json!({
            "document_id": self.document_id,
            "document_title": self.document_title,
            "candidate_name": self.candidate_name,
            "project_name": self.project_name,
            "delivery_summary": self.delivery_summary,
            "tech_stack": self.tech_stack,
            "source_locator": self.source_locator,
            "chunk_index": self.chunk_index,
            "confidence": self.confidence,
        })
    }
}

fn entity_rows_for_type(
    entities_by_key: &BTreeMap<(String, String), BTreeSet<String>>,
    entity_type: &str,
) -> Vec<Value> {
    let mut rows = entities_by_key
        .iter()
        .filter(|((candidate_type, _), _)| candidate_type == entity_type)
        .map(|((_, name), document_ids)| (name.clone(), document_ids.clone()))
        .collect::<Vec<_>>();
    rows.sort_by(
        |(left_name, left_documents), (right_name, right_documents)| {
            right_documents
                .len()
                .cmp(&left_documents.len())
                .then_with(|| left_name.cmp(right_name))
        },
    );
    rows.iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(name, document_ids)| {
            json!({
                "name": name,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect()
}

fn candidate_term_rows_for_scan(
    candidate_terms_by_name: &BTreeMap<String, BTreeSet<String>>,
) -> Vec<Value> {
    let mut rows = candidate_terms_by_name
        .iter()
        .map(|(name, document_ids)| (name.clone(), document_ids.clone()))
        .collect::<Vec<_>>();
    rows.sort_by(
        |(left_name, left_documents), (right_name, right_documents)| {
            right_documents
                .len()
                .cmp(&left_documents.len())
                .then_with(|| {
                    document_candidate_term_score(right_name)
                        .cmp(&document_candidate_term_score(left_name))
                })
                .then_with(|| left_name.cmp(right_name))
        },
    );
    rows.iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(name, document_ids)| {
            json!({
                "name": name,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect()
}

fn year_rows_for_scan(years_by_year: &BTreeMap<i32, BTreeSet<String>>) -> Vec<Value> {
    years_by_year
        .iter()
        .rev()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(year, document_ids)| {
            json!({
                "name": year.to_string(),
                "year": year,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect()
}

fn structure_rows_for_scan(rows_by_name: &BTreeMap<String, BTreeSet<String>>) -> Vec<Value> {
    let mut rows = rows_by_name
        .iter()
        .map(|(name, document_ids)| (name.clone(), document_ids.clone()))
        .collect::<Vec<_>>();
    rows.sort_by(
        |(left_name, left_documents), (right_name, right_documents)| {
            right_documents
                .len()
                .cmp(&left_documents.len())
                .then_with(|| left_name.cmp(right_name))
        },
    );
    rows.iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_ROW_LIMIT)
        .map(|(name, document_ids)| {
            json!({
                "name": name,
                "document_count": document_ids.len(),
                "document_ids": document_ids.iter().take(5).cloned().collect::<Vec<_>>(),
            })
        })
        .collect()
}

fn extract_document_section_titles_for_scan(
    chunks: &[DocumentChunk],
    scan_text: &str,
    limit: usize,
) -> Vec<String> {
    let mut titles = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        for title in document_chunk_section_title_hints(chunk) {
            push_document_structure_signal(&mut titles, title, limit);
        }
    }
    for title in infer_section_title_hints_from_text(scan_text, limit) {
        push_document_structure_signal(&mut titles, title, limit);
    }
    titles
}

fn extract_document_paragraphs_for_scan(chunks: &[DocumentChunk], limit: usize) -> Vec<String> {
    let mut paragraphs = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        if let Some(value) = chunk
            .metadata
            .get("parse_metadata")
            .and_then(|value| value.get("document_structure"))
        {
            for paragraph in document_structure_paragraph_samples(value, limit) {
                push_document_paragraph_sample(&mut paragraphs, paragraph, limit);
            }
        }
        for paragraph in infer_paragraph_samples_from_text(&chunk.content, limit) {
            push_document_paragraph_sample(&mut paragraphs, paragraph, limit);
        }
        if paragraphs.len() >= limit {
            break;
        }
    }
    paragraphs
}

fn extract_document_table_signals_for_scan(
    chunks: &[DocumentChunk],
    scan_text: &str,
    limit: usize,
) -> Vec<String> {
    let mut signals = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        for signal in document_chunk_table_signals(chunk, limit) {
            push_document_structure_signal(&mut signals, signal, limit);
        }
        if signals.len() >= limit {
            return signals;
        }
    }
    for signal in infer_table_signals_from_text(scan_text, limit) {
        push_document_structure_signal(&mut signals, signal, limit);
    }
    signals
}

fn document_chunk_table_signals(chunk: &DocumentChunk, limit: usize) -> Vec<String> {
    let mut signals = Vec::new();
    for key in [
        "table_signals",
        "tableSignals",
        "table_like_signals",
        "tableLikeSignals",
    ] {
        if let Some(value) = chunk.metadata.get(key) {
            collect_string_list(value, &mut signals);
        }
    }
    if let Some(value) = chunk
        .metadata
        .get("parse_metadata")
        .and_then(|value| value.get("table_like_signals"))
    {
        collect_string_list(value, &mut signals);
    }
    if let Some(value) = chunk
        .metadata
        .get("parse_metadata")
        .and_then(|value| value.get("document_structure"))
    {
        for signal in document_structure_table_signals(value, limit) {
            push_document_structure_signal(&mut signals, signal, limit);
        }
    }
    visit_document_vlm_payloads(&chunk.metadata, |payload| {
        if let Some(value) = payload
            .get("tableLikeSignals")
            .or_else(|| payload.get("table_like_signals"))
        {
            collect_string_list(value, &mut signals);
        }
        if payload
            .get("chartOrTableDetected")
            .or_else(|| payload.get("chart_or_table_detected"))
            .and_then(Value::as_bool)
            .unwrap_or(false)
        {
            if let Some(summary) = payload
                .get("visualSummary")
                .or_else(|| payload.get("summary"))
                .and_then(Value::as_str)
            {
                push_document_structure_signal(&mut signals, summary, limit);
            }
        }
    });
    signals.truncate(limit);
    signals
}

fn document_structure_paragraph_samples(structure: &Value, limit: usize) -> Vec<String> {
    let mut paragraphs = Vec::new();
    let Some(blocks) = structure.get("blocks").and_then(Value::as_array) else {
        return paragraphs;
    };
    for block in blocks {
        if document_structure_block_is_title(block)
            || document_structure_block_is_term_source(block)
        {
            continue;
        }
        let block_type = document_structure_block_type(block);
        if !block_type.is_empty()
            && ![
                "text",
                "paragraph",
                "plain_text",
                "body",
                "content",
                "list",
                "list_item",
            ]
            .iter()
            .any(|value| block_type.contains(value))
        {
            continue;
        }
        let Some(text) = document_structure_block_text(block) else {
            continue;
        };
        push_document_paragraph_sample(&mut paragraphs, text, limit);
        if paragraphs.len() >= limit {
            break;
        }
    }
    paragraphs
}

fn document_structure_table_signals(structure: &Value, limit: usize) -> Vec<String> {
    let mut signals = Vec::new();
    let Some(blocks) = structure.get("blocks").and_then(Value::as_array) else {
        return signals;
    };
    for block in blocks {
        let block_type = document_structure_block_type(block);
        if !["table", "cell", "table_title"]
            .iter()
            .any(|value| block_type.contains(value))
        {
            continue;
        }
        let Some(text) = document_structure_block_text(block) else {
            continue;
        };
        push_document_structure_signal(&mut signals, text, limit);
        if signals.len() >= limit {
            break;
        }
    }
    signals
}

fn infer_paragraph_samples_from_text(text: &str, limit: usize) -> Vec<String> {
    let mut paragraphs = Vec::new();
    for raw in text.split("\n\n") {
        let normalized = raw
            .lines()
            .map(str::trim)
            .filter(|line| !line.is_empty())
            .collect::<Vec<_>>()
            .join(" ");
        if normalized.is_empty() {
            continue;
        }
        if normalize_section_title_hint(&normalized).is_some()
            || looks_like_table_signal_line(&normalized)
        {
            continue;
        }
        push_document_paragraph_sample(&mut paragraphs, normalized, limit);
        if paragraphs.len() >= limit {
            break;
        }
    }
    paragraphs
}

fn infer_table_signals_from_text(text: &str, limit: usize) -> Vec<String> {
    let mut signals = Vec::new();
    for line in text.lines().map(str::trim).filter(|line| !line.is_empty()) {
        if !looks_like_table_signal_line(line) {
            continue;
        }
        push_document_structure_signal(&mut signals, line, limit);
        if signals.len() >= limit {
            break;
        }
    }
    signals
}

fn looks_like_table_signal_line(line: &str) -> bool {
    let pipe_count = line.matches('|').count();
    pipe_count >= 2
        || line.matches('\t').count() >= 2
        || (line.contains("｜") && line.matches('｜').count() >= 2)
}

fn push_document_structure_signal(output: &mut Vec<String>, value: impl AsRef<str>, limit: usize) {
    if output.len() >= limit {
        return;
    }
    let normalized_value = normalize_document_entity_value(value.as_ref());
    let normalized = normalized_value
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ");
    let char_count = normalized.chars().count();
    if !(2..=120).contains(&char_count)
        || is_document_entity_noise(&normalized)
        || output.iter().any(|existing| existing == &normalized)
    {
        return;
    }
    output.push(normalized);
}

fn push_document_paragraph_sample(output: &mut Vec<String>, value: impl AsRef<str>, limit: usize) {
    if output.len() >= limit {
        return;
    }
    let normalized = value
        .as_ref()
        .trim()
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .chars()
        .take(180)
        .collect::<String>();
    let char_count = normalized.chars().count();
    if !(12..=180).contains(&char_count)
        || is_document_entity_noise(&normalized)
        || output.iter().any(|existing| existing == &normalized)
    {
        return;
    }
    output.push(normalized);
}

fn extract_resume_document_profile(
    document: &Document,
    scan_text: &str,
    entity_candidates: &[DocumentEntityCandidate],
) -> ResumeDocumentProfile {
    let years = extract_resume_timeline_years(scan_text, 32);
    let company_names = resume_profile_entity_names(entity_candidates, "organization", 16);
    let skill_names = resume_profile_entity_names(entity_candidates, "skill", 24);
    let mut project_names = resume_profile_entity_names(entity_candidates, "project", 16);
    for name in extract_project_like_terms(scan_text, 16) {
        push_document_candidate_term(&mut project_names, name, 16);
    }
    let position_names = resume_profile_entity_names(entity_candidates, "position", 12);
    let location_names = resume_profile_entity_names(entity_candidates, "location", 12);
    let school_names = resume_profile_entity_names(entity_candidates, "school", 12);
    let degree_names = resume_profile_entity_names(entity_candidates, "degree", 8);
    let certificate_names = resume_profile_entity_names(entity_candidates, "certificate", 12);
    let mut profile = ResumeDocumentProfile {
        document_id: document.id.to_string(),
        document_title: resume_profile_display_title(document),
        candidate_name: extract_resume_candidate_name(scan_text)
            .or_else(|| extract_resume_candidate_name_from_title(&document.title))
            .or_else(|| extract_resume_candidate_name_from_marked_text(scan_text))
            .or_else(|| extract_resume_candidate_name_from_object_key(&document.object_key))
            .or_else(|| {
                entity_candidates
                    .iter()
                    .find(|candidate| candidate.entity_type == "person")
                    .map(|candidate| candidate.name.clone())
            }),
        gender: extract_resume_gender(scan_text),
        age: extract_resume_age(scan_text),
        birth_year: extract_resume_birth_year(scan_text),
        earliest_year: years.iter().min().copied(),
        latest_year: years.iter().max().copied(),
        year_count: years.len(),
        company_count: company_names.len(),
        skill_count: skill_names.len(),
        project_count: project_names.len(),
        position_count: position_names.len(),
        location_count: location_names.len(),
        certificate_count: certificate_names.len(),
        company_names,
        skill_names,
        project_names,
        position_names,
        location_names,
        school_names,
        degree_names,
        certificate_names,
    };
    if profile.age.is_none() {
        if let Some(birth_year) = profile.birth_year {
            let current_year = Utc::now().year();
            if (1950..=current_year).contains(&birth_year) {
                let age = current_year - birth_year;
                if (16..=80).contains(&age) {
                    profile.age = Some(age as u64);
                }
            }
        }
    }
    if !resume_profile_has_document_signal(document, scan_text, &profile) {
        return ResumeDocumentProfile::default();
    }
    profile
}

fn extract_resume_project_delivery_rows(
    document: &Document,
    chunks: &[DocumentChunk],
    profile: &ResumeDocumentProfile,
    entity_candidates: &[DocumentEntityCandidate],
    limit: usize,
) -> Vec<ResumeProjectDeliveryRow> {
    if limit == 0 {
        return Vec::new();
    }
    let candidate_name = profile
        .candidate_name
        .clone()
        .or_else(|| extract_resume_candidate_name_from_title(&document.title))
        .or_else(|| extract_resume_candidate_name_from_object_key(&document.object_key))
        .or_else(|| {
            entity_candidates
                .iter()
                .find(|candidate| candidate.entity_type == "person")
                .map(|candidate| candidate.name.clone())
        })
        .unwrap_or_else(|| "未知候选人".to_string());
    let document_title = resume_profile_display_title(document);
    let mut rows = Vec::new();
    let mut seen = BTreeSet::new();

    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_CHUNK_LIMIT)
    {
        let lines = resume_project_delivery_lines(&chunk.content);
        if lines.is_empty() || !resume_project_delivery_chunk_has_signal(&lines) {
            continue;
        }
        for (line_index, line) in lines.iter().enumerate() {
            let Some(project_name) = resume_project_delivery_project_name_from_line(line) else {
                continue;
            };
            if project_heading_is_noise(&project_name) {
                continue;
            }
            let block_lines = resume_project_delivery_block_lines(&lines, line_index);
            let delivery_summary =
                resume_project_delivery_summary_from_block(&block_lines, &project_name);
            if delivery_summary.is_empty() {
                continue;
            }
            let key = format!(
                "{}:{}:{}",
                document.id,
                normalize_document_entity_value(&candidate_name),
                normalize_document_entity_value(&project_name)
            );
            if !seen.insert(key) {
                continue;
            }
            let block_text = block_lines.join("\n");
            rows.push(ResumeProjectDeliveryRow {
                document_id: document.id.to_string(),
                document_title: document_title.clone(),
                candidate_name: candidate_name.clone(),
                project_name,
                delivery_summary,
                tech_stack: resume_project_delivery_tech_stack(&block_text, 8),
                source_locator: format!("document://{}/chunks/{}", document.id, chunk.chunk_index),
                chunk_index: chunk.chunk_index,
                confidence: "medium".to_string(),
            });
            if rows.len() >= limit {
                return rows;
            }
        }
    }

    if rows.is_empty() && resume_project_delivery_profile_has_project_names(profile) {
        for project_name in profile.project_names.iter().take(limit) {
            rows.push(ResumeProjectDeliveryRow {
                document_id: document.id.to_string(),
                document_title: document_title.clone(),
                candidate_name: candidate_name.clone(),
                project_name: project_name.clone(),
                delivery_summary: "识别到项目名称，但当前轻量扫描未抽到明确交付职责句。"
                    .to_string(),
                tech_stack: profile.skill_names.iter().take(8).cloned().collect(),
                source_locator: format!("document://{}/profile", document.id),
                chunk_index: -1,
                confidence: "low".to_string(),
            });
        }
    }

    rows
}

fn resume_project_delivery_profile_has_project_names(profile: &ResumeDocumentProfile) -> bool {
    !profile.project_names.is_empty()
}

fn resume_project_delivery_lines(text: &str) -> Vec<String> {
    text.lines()
        .map(normalize_document_entity_value)
        .filter(|line| !line.is_empty())
        .collect()
}

fn resume_project_delivery_chunk_has_signal(lines: &[String]) -> bool {
    lines.iter().any(|line| {
        prompt_contains_any(
            line,
            &[
                "项目经验",
                "项目经历",
                "项目名称",
                "项目职责",
                "项目描述",
                "项目成果",
                "交付",
                "上线",
                "落地",
            ],
        ) || resume_project_delivery_project_name_from_line(line).is_some()
    })
}

fn resume_project_delivery_block_lines(lines: &[String], start_index: usize) -> Vec<String> {
    let mut block_lines = Vec::new();
    for line in lines.iter().skip(start_index) {
        if block_lines.len() >= ASSISTANT_RUN_RESUME_PROJECT_DELIVERY_BLOCK_LINE_LIMIT {
            break;
        }
        if !block_lines.is_empty() && resume_project_delivery_project_name_from_line(line).is_some()
        {
            break;
        }
        if !block_lines.is_empty()
            && normalize_section_title_hint(line).is_some()
            && !prompt_contains_any(line, &["职责", "成果", "描述", "技术", "交付"])
        {
            break;
        }
        block_lines.push(line.clone());
    }
    block_lines
}

fn resume_project_delivery_summary_from_block(lines: &[String], project_name: &str) -> String {
    let mut summaries = Vec::new();
    for line in lines {
        if resume_project_delivery_line_is_project_heading(line, project_name) {
            continue;
        }
        if !resume_project_delivery_line_has_summary_signal(line) {
            continue;
        }
        let summary = resume_project_delivery_clean_summary_line(line);
        if summary.is_empty() || summaries.iter().any(|existing| existing == &summary) {
            continue;
        }
        summaries.push(summary);
        if summaries.len() >= 3 {
            break;
        }
    }
    if summaries.is_empty() {
        for line in lines.iter().skip(1) {
            let summary = resume_project_delivery_clean_summary_line(line);
            if summary.chars().count() >= 8 {
                summaries.push(summary);
                break;
            }
        }
    }
    summaries.join("；")
}

fn resume_project_delivery_line_is_project_heading(line: &str, project_name: &str) -> bool {
    resume_project_delivery_project_name_from_line(line)
        .as_deref()
        .is_some_and(|name| name == project_name)
}

fn resume_project_delivery_line_has_summary_signal(line: &str) -> bool {
    prompt_contains_any(
        line,
        &[
            "负责", "职责", "参与", "主导", "带领", "设计", "开发", "实现", "完成", "交付", "上线",
            "落地", "搭建", "架构", "优化", "对接", "部署", "维护", "推进", "成果", "模块", "需求",
        ],
    )
}

fn resume_project_delivery_clean_summary_line(line: &str) -> String {
    let mut summary = normalize_document_entity_value(line);
    for label in [
        "项目职责",
        "项目描述",
        "项目成果",
        "职责描述",
        "责任描述",
        "主要职责",
        "工作职责",
        "工作内容",
        "项目内容",
        "项目介绍",
        "技术栈",
    ] {
        if let Some(value) = labeled_entity_value(&summary, label) {
            summary = normalize_document_entity_value(&value);
            break;
        }
    }
    summary.chars().take(140).collect()
}

fn resume_project_delivery_tech_stack(text: &str, limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for skill in [
        "Java",
        "Spring Boot",
        "SpringCloud",
        "Spring Cloud",
        "Python",
        "Go",
        "Rust",
        "JavaScript",
        "TypeScript",
        "React",
        "Vue",
        "Node.js",
        "MySQL",
        "PostgreSQL",
        "Redis",
        "MongoDB",
        "Kafka",
        "RabbitMQ",
        "Docker",
        "Kubernetes",
        "微服务",
        "物联网",
        "IoT",
        "AI",
        "大数据",
        "数据治理",
        "系统架构",
    ] {
        if text.contains(skill) {
            push_document_candidate_term(&mut values, skill, limit);
        }
        if values.len() >= limit {
            break;
        }
    }
    values
}

fn resume_profile_entity_names(
    entity_candidates: &[DocumentEntityCandidate],
    entity_type: &str,
    limit: usize,
) -> Vec<String> {
    let mut names = Vec::new();
    for candidate in entity_candidates {
        if candidate.entity_type == entity_type {
            push_document_candidate_term(&mut names, &candidate.name, limit);
        }
        if names.len() >= limit {
            break;
        }
    }
    names
}

fn resume_profile_has_document_signal(
    document: &Document,
    scan_text: &str,
    profile: &ResumeDocumentProfile,
) -> bool {
    profile.age.is_some()
        || profile.gender.is_some()
        || profile.birth_year.is_some()
        || resume_profile_text_has_signal(&document.title)
        || resume_profile_text_has_signal(&document.object_key)
        || resume_profile_text_has_signal(scan_text)
        || (profile.candidate_name.is_some()
            && resume_profile_title_has_candidate_file_shape(&document.title))
}

fn resume_profile_text_has_signal(text: &str) -> bool {
    let lower_text = text.to_ascii_lowercase();
    [
        "简历",
        "履历",
        "候选人",
        "求职",
        "应聘",
        "招聘",
        "人才",
        "面试",
        "工作经验",
        "工作经历",
        "项目经验",
        "教育经历",
        "专业技能",
        "自我评价",
    ]
    .iter()
    .any(|hint| text.contains(hint))
        || ["resume", "cv", "candidate", "recruit"]
            .iter()
            .any(|hint| lower_text.contains(hint))
}

fn resume_profile_title_has_candidate_file_shape(title: &str) -> bool {
    let lower_title = title.to_ascii_lowercase();
    let has_document_extension = [".pdf", ".doc", ".docx", ".wps", ".rtf"]
        .iter()
        .any(|suffix| lower_title.ends_with(suffix));
    has_document_extension && extract_resume_candidate_name_from_title(title).is_some()
}

fn extract_resume_candidate_name(text: &str) -> Option<String> {
    extract_labeled_entity_values(text, &["姓名", "候选人"], 4)
        .into_iter()
        .find(|value| looks_like_person_name(value))
}

fn extract_resume_candidate_name_from_title(text: &str) -> Option<String> {
    extract_resume_candidate_name_from_heading_text(text, true)
        .or_else(|| extract_resume_candidate_name_from_object_key(text))
}

fn extract_resume_candidate_name_from_marked_text(text: &str) -> Option<String> {
    extract_resume_candidate_name_from_heading_text(text, false)
}

fn extract_resume_candidate_name_from_object_key(object_key: &str) -> Option<String> {
    let file_label = resume_profile_object_key_label(object_key)?;
    for segment in file_label.split(['-', '_', ' ', '　']) {
        let raw_segment = normalize_document_entity_value(
            segment
                .split(['(', '（', '[', '【'])
                .next()
                .unwrap_or(segment),
        );
        let normalized = normalize_resume_file_person_segment(&raw_segment);
        if looks_like_person_name(&normalized) {
            return Some(normalized);
        }
        if looks_like_resume_ascii_person_name(&raw_segment) {
            return Some(raw_segment);
        }
        if let Some(name) = extract_resume_candidate_name_from_heading_text(&normalized, false) {
            return Some(name);
        }
        if let Some(prefix) = raw_segment
            .split_once("简历")
            .map(|(prefix, _)| normalize_resume_file_person_segment(prefix))
            .filter(|value| looks_like_person_name(value))
        {
            return Some(prefix);
        }
        if let Some(prefix) = raw_segment
            .split_once("简历")
            .map(|(prefix, _)| normalize_document_entity_value(prefix))
            .filter(|value| looks_like_resume_ascii_person_name(value))
        {
            return Some(prefix);
        }
    }
    extract_resume_candidate_name_from_heading_text(&file_label, false)
}

fn normalize_resume_file_person_segment(value: &str) -> String {
    let trimmed = value.trim().trim_start_matches(|ch: char| {
        ch.is_ascii_alphanumeric() || matches!(ch, '.' | '_' | '-' | ' ' | '　')
    });
    normalize_document_entity_value(trimmed)
}

fn looks_like_resume_ascii_person_name(value: &str) -> bool {
    let normalized = value.trim();
    let lower = normalized.to_ascii_lowercase();
    let char_count = normalized.chars().count();
    let alpha_count = normalized
        .chars()
        .filter(|ch| ch.is_ascii_alphabetic())
        .count();
    (2..=32).contains(&char_count)
        && alpha_count >= 2
        && normalized
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || matches!(ch, '.' | '-' | '_' | ' '))
        && ![
            "boss", "cv", "iot", "java", "resume", "title", "profile", "document", "python",
            "golang", "backend", "frontend", "product", "manager",
        ]
        .contains(&lower.as_str())
}

fn resume_profile_display_title(document: &Document) -> String {
    let title = normalize_document_entity_value(&document.title);
    if !title.is_empty() && !resume_profile_generic_version_label(&title) {
        return title;
    }
    resume_profile_object_key_label(&document.object_key)
        .filter(|value| !resume_profile_generic_version_label(value))
        .unwrap_or(title)
}

fn resume_profile_generic_version_label(value: &str) -> bool {
    let normalized = value.trim().to_ascii_lowercase();
    if normalized.is_empty() {
        return true;
    }
    if normalized == "v" || normalized == "version" || normalized == "版本" {
        return true;
    }
    normalized
        .strip_prefix('v')
        .filter(|suffix| !suffix.is_empty())
        .is_some_and(|suffix| suffix.chars().all(|ch| ch.is_ascii_digit()))
}

fn resume_profile_object_key_label(object_key: &str) -> Option<String> {
    let file_name = object_key
        .rsplit(['/', '\\'])
        .next()
        .map(str::trim)
        .filter(|value| !value.is_empty())?;
    let stem = file_name
        .rsplit_once('.')
        .map(|(prefix, _)| prefix)
        .unwrap_or(file_name);
    let parts = stem.splitn(4, '-').collect::<Vec<_>>();
    let label = if parts.len() == 4
        && parts[0].chars().all(|ch| ch.is_ascii_digit())
        && parts[1].chars().all(|ch| ch.is_ascii_hexdigit())
        && parts[2].chars().all(|ch| ch.is_ascii_digit())
    {
        parts[3]
    } else {
        stem
    };
    let normalized = normalize_document_entity_value(label);
    (!normalized.is_empty()).then_some(normalized)
}

fn extract_resume_candidate_name_from_heading_text(
    text: &str,
    allow_standalone_name_line: bool,
) -> Option<String> {
    for line in text.lines().take(16) {
        let normalized = normalize_document_entity_value(line);
        if allow_standalone_name_line && looks_like_person_name(&normalized) {
            return Some(normalized);
        }
        let compact = normalized
            .chars()
            .filter(|ch| !ch.is_whitespace())
            .collect::<String>();
        for marker in [
            "个人简历",
            "个人履历",
            "简历",
            "履历",
            "Personalresume",
            "Resume",
            "CV",
        ] {
            if let Some(index) = compact.find(marker) {
                let prefix = compact[..index].trim_matches(|ch: char| {
                    ch.is_whitespace()
                        || matches!(ch, ':' | '：' | '-' | '_' | '|' | '｜' | '/' | '\\')
                });
                if looks_like_person_name(prefix) {
                    return Some(prefix.to_string());
                }
            }
        }
    }
    None
}

fn extract_resume_gender(text: &str) -> Option<String> {
    for value in extract_labeled_resume_values(text, &["性别"], 4) {
        if let Some(gender) = normalize_resume_gender(&value) {
            return Some(gender.to_string());
        }
    }
    for line in text.lines().take(24) {
        for segment in line.split(|ch: char| {
            matches!(ch, '\t' | '|' | '｜' | '/' | '／' | '，' | ',' | '；' | ';')
        }) {
            let normalized = normalize_document_entity_value(segment);
            if let Some(gender) = normalize_resume_gender(&normalized) {
                return Some(gender.to_string());
            }
        }
    }
    None
}

fn normalize_resume_gender(value: &str) -> Option<&'static str> {
    let normalized = value.trim();
    if normalized.contains("男女") || normalized.contains("不限") {
        return None;
    }
    if normalized.starts_with('男') || normalized == "M" || normalized.eq_ignore_ascii_case("male")
    {
        Some("男")
    } else if normalized.starts_with('女')
        || normalized == "F"
        || normalized.eq_ignore_ascii_case("female")
    {
        Some("女")
    } else {
        None
    }
}

fn extract_resume_age(text: &str) -> Option<u64> {
    for value in extract_labeled_resume_values(text, &["年龄"], 4) {
        if let Some(age) = first_bounded_number(&value, 16, 80) {
            return Some(age);
        }
    }
    None
}

fn extract_resume_birth_year(text: &str) -> Option<i32> {
    for value in extract_labeled_resume_values(text, &["出生年月", "出生日期", "出生年", "生日"], 4)
    {
        if let Some(year) = extract_years_from_text(&value, 1).into_iter().next() {
            if (1950..=Utc::now().year()).contains(&year) {
                return Some(year);
            }
        }
    }
    for line in text.lines().take(32) {
        if !line.contains("出生") {
            continue;
        }
        if let Some(year) = extract_years_from_text(line, 1).into_iter().next() {
            if (1950..=Utc::now().year()).contains(&year) {
                return Some(year);
            }
        }
    }
    None
}

fn extract_labeled_resume_values(text: &str, labels: &[&str], limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for line in text.lines() {
        for segment in line.split(|ch: char| matches!(ch, '\t' | '|' | '；' | ';')) {
            let normalized = segment.trim();
            if normalized.is_empty() {
                continue;
            }
            for label in labels {
                if let Some(value) = labeled_entity_value(normalized, label) {
                    for item in split_entity_value_list(&value) {
                        let item = normalize_document_entity_value(&item);
                        if !item.is_empty() && !values.iter().any(|existing| existing == &item) {
                            values.push(item);
                        }
                        if values.len() >= limit {
                            return values;
                        }
                    }
                }
            }
        }
    }
    values
}

fn extract_resume_timeline_years(text: &str, limit: usize) -> Vec<i32> {
    let birth_year = extract_resume_birth_year(text);
    let timeline_text = text
        .lines()
        .filter(|line| {
            !["出生", "生日", "年龄", "身份证"]
                .iter()
                .any(|label| line.contains(label))
        })
        .collect::<Vec<_>>()
        .join("\n");
    let years = extract_resume_years(&timeline_text, limit)
        .into_iter()
        .filter(|year| *year >= 1990 && Some(*year) != birth_year)
        .collect::<Vec<_>>();
    if years.is_empty() {
        extract_resume_years(text, limit)
            .into_iter()
            .filter(|year| *year >= 1990 && Some(*year) != birth_year)
            .collect()
    } else {
        years
    }
}

fn extract_resume_years(text: &str, limit: usize) -> Vec<i32> {
    let mut years = extract_years_from_text(text, limit);
    years.sort_unstable();
    years.dedup();
    years
}

fn extract_years_from_text(text: &str, limit: usize) -> Vec<i32> {
    let current_year = Utc::now().year();
    let mut years = Vec::new();
    let chars = text.chars().collect::<Vec<_>>();
    for index in 0..chars.len().saturating_sub(3) {
        if !chars[index..index + 4].iter().all(|ch| ch.is_ascii_digit()) {
            continue;
        }
        let raw = chars[index..index + 4].iter().collect::<String>();
        let Ok(year) = raw.parse::<i32>() else {
            continue;
        };
        if (1950..=current_year + 1).contains(&year) && !years.contains(&year) {
            years.push(year);
            if years.len() >= limit {
                break;
            }
        }
    }
    years
}

fn first_bounded_number(text: &str, min: u64, max: u64) -> Option<u64> {
    let mut digits = String::new();
    for ch in text.chars() {
        if ch.is_ascii_digit() {
            digits.push(ch);
            continue;
        }
        if let Some(value) = parse_bounded_number(&digits, min, max) {
            return Some(value);
        }
        digits.clear();
    }
    parse_bounded_number(&digits, min, max)
}

fn parse_bounded_number(digits: &str, min: u64, max: u64) -> Option<u64> {
    if digits.is_empty() {
        return None;
    }
    let value = digits.parse::<u64>().ok()?;
    (min..=max).contains(&value).then_some(value)
}

fn dataset_entity_scan_text(document: &Document, chunks: &[DocumentChunk]) -> String {
    let mut parts = vec![document.title.trim().to_string()];
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        parts.push(chunk.content.trim().to_string());
        parts.extend(document_chunk_section_title_hints(chunk));
        parts.extend(document_chunk_noun_terms(chunk));
    }
    parts
        .into_iter()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
        .collect::<Vec<_>>()
        .join("\n")
}

fn dataset_entity_scan_structured_text(
    document: &Document,
    chunks: &[DocumentChunk],
) -> Option<String> {
    let mut parts = Vec::new();
    let mut seen = BTreeSet::new();
    push_unique_scan_text_part(&mut parts, &mut seen, &document.title);
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        if chunk.content.contains("Visual summary:")
            || chunk.content.contains("Visual transcription:")
            || chunk.content.contains("Visual evidence:")
        {
            push_unique_scan_text_part(&mut parts, &mut seen, &chunk.content);
        }
        collect_document_metadata_scan_text(&chunk.metadata, &mut parts, &mut seen);
    }
    if parts.is_empty() {
        None
    } else {
        Some(parts.join("\n"))
    }
}

fn push_unique_scan_text_part(parts: &mut Vec<String>, seen: &mut BTreeSet<String>, value: &str) {
    let normalized = value.trim();
    if normalized.is_empty() {
        return;
    }
    let normalized = truncate_assistant_supply_text(normalized, 1600);
    if seen.insert(normalized.clone()) {
        parts.push(normalized);
    }
}

fn collect_document_metadata_scan_text(
    metadata: &BTreeMap<String, Value>,
    parts: &mut Vec<String>,
    seen: &mut BTreeSet<String>,
) {
    visit_document_vlm_payloads(metadata, |payload| {
        for field in ["summary", "visualSummary", "transcribedText"] {
            if let Some(value) = payload.get(field).and_then(Value::as_str) {
                push_unique_scan_text_part(parts, seen, value);
            }
        }
        if let Some(entities) = payload.get("entities").and_then(Value::as_array) {
            for entity in entities {
                if let Some(text) = entity.get("text").and_then(Value::as_str) {
                    push_unique_scan_text_part(parts, seen, text);
                }
            }
        }
        if let Some(fields) = payload.get("fieldCandidates").and_then(Value::as_array) {
            for field in fields {
                let key = field.get("key").and_then(Value::as_str).unwrap_or("");
                let value = field.get("value").and_then(Value::as_str).unwrap_or("");
                if !key.trim().is_empty() && !value.trim().is_empty() {
                    push_unique_scan_text_part(parts, seen, &format!("{key}: {value}"));
                }
            }
        }
        if let Some(blocks) = payload.get("evidenceBlocks").and_then(Value::as_array) {
            for block in blocks {
                let title = block.get("title").and_then(Value::as_str).unwrap_or("");
                let text = block.get("text").and_then(Value::as_str).unwrap_or("");
                if !title.trim().is_empty() || !text.trim().is_empty() {
                    push_unique_scan_text_part(parts, seen, &format!("{title}: {text}"));
                }
            }
        }
    });
}

fn extract_document_entity_candidates_from_text(
    text: &str,
    limit: usize,
) -> Vec<DocumentEntityCandidate> {
    let mut candidates = Vec::new();
    let mut seen = BTreeSet::new();
    for name in extract_company_names_from_text(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "organization", name, limit);
    }
    for name in extract_labeled_entity_values(text, &["姓名", "候选人", "联系人"], limit) {
        if looks_like_person_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "person", name, limit);
        }
    }
    for name in extract_labeled_entity_values(
        text,
        &["应聘岗位", "目标岗位", "岗位", "职位", "职务", "角色"],
        limit,
    ) {
        if looks_like_position_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "position", name, limit);
        }
    }
    for name in
        extract_labeled_entity_values(text, &["技能", "核心技能", "专业技能", "技术栈"], limit)
    {
        if looks_like_skill_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "skill", name, limit);
        }
    }
    for name in extract_known_skill_names(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "skill", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &[
            "工作地点",
            "项目地点",
            "所在地",
            "所在城市",
            "城市",
            "地点",
            "籍贯",
        ],
        limit,
    ) {
        if looks_like_location_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "location", name, limit);
        }
    }
    for name in extract_known_location_names(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "location", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &[
            "毕业院校",
            "毕业学校",
            "就读院校",
            "学校",
            "院校",
            "大学",
            "学院",
        ],
        limit,
    ) {
        if looks_like_school_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "school", name, limit);
        }
    }
    for name in extract_school_like_terms(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "school", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &["最高学历", "学历", "学位", "教育程度", "教育背景"],
        limit,
    ) {
        if let Some(degree) = normalize_degree_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "degree", degree, limit);
        }
    }
    for name in extract_known_degree_names(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "degree", name, limit);
    }
    for name in extract_labeled_entity_values(
        text,
        &["证书", "资格证书", "认证", "资质", "职业资格"],
        limit,
    ) {
        if looks_like_certificate_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "certificate", name, limit);
        }
    }
    for name in extract_certificate_like_terms(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "certificate", name, limit);
    }
    for name in
        extract_labeled_entity_values(text, &["项目名称", "项目/产品名称", "产品名称"], limit)
    {
        if looks_like_project_name(&name) {
            push_document_entity_candidate(&mut candidates, &mut seen, "project", name, limit);
        }
    }
    for name in extract_project_like_terms(text, limit) {
        push_document_entity_candidate(&mut candidates, &mut seen, "project", name, limit);
    }
    candidates.truncate(limit);
    candidates
}

fn extract_document_entity_candidates_from_chunk_metadata(
    chunks: &[DocumentChunk],
    limit: usize,
) -> Vec<DocumentEntityCandidate> {
    let mut candidates = Vec::new();
    let mut seen = BTreeSet::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        visit_document_vlm_payloads(&chunk.metadata, |payload| {
            collect_document_vlm_entity_candidates(payload, &mut candidates, &mut seen, limit);
        });
        if candidates.len() >= limit {
            break;
        }
    }
    candidates
}

fn visit_document_vlm_payloads<F>(metadata: &BTreeMap<String, Value>, mut visitor: F)
where
    F: FnMut(&Value),
{
    for value in metadata.values() {
        visit_document_vlm_payloads_value(value, &mut visitor);
    }
}

fn visit_document_vlm_payloads_value<F>(value: &Value, visitor: &mut F)
where
    F: FnMut(&Value),
{
    if let Some(object) = value.as_object() {
        if let Some(payload) = object
            .get("vlm")
            .and_then(|vlm| vlm.get("payload"))
            .filter(|payload| payload.is_object())
        {
            visitor(payload);
        }
        for child in object.values() {
            visit_document_vlm_payloads_value(child, visitor);
        }
    } else if let Some(array) = value.as_array() {
        for child in array {
            visit_document_vlm_payloads_value(child, visitor);
        }
    }
}

fn collect_document_vlm_entity_candidates(
    payload: &Value,
    candidates: &mut Vec<DocumentEntityCandidate>,
    seen: &mut BTreeSet<String>,
    limit: usize,
) {
    if let Some(entities) = payload.get("entities").and_then(Value::as_array) {
        for entity in entities {
            if candidates.len() >= limit {
                return;
            }
            let Some(entity_type) = entity
                .get("type")
                .and_then(Value::as_str)
                .and_then(document_metadata_entity_type)
            else {
                continue;
            };
            let Some(text) = entity.get("text").and_then(Value::as_str) else {
                continue;
            };
            push_document_metadata_entity_candidate(candidates, seen, entity_type, text, limit);
        }
    }

    if let Some(fields) = payload.get("fieldCandidates").and_then(Value::as_array) {
        for field in fields {
            if candidates.len() >= limit {
                return;
            }
            let Some(entity_type) = field
                .get("key")
                .and_then(Value::as_str)
                .and_then(document_field_candidate_entity_type)
            else {
                continue;
            };
            let Some(value) = field.get("value").and_then(Value::as_str) else {
                continue;
            };
            push_document_metadata_entity_candidate(candidates, seen, entity_type, value, limit);
        }
    }

    if let Some(blocks) = payload.get("evidenceBlocks").and_then(Value::as_array) {
        let mut block_text = String::new();
        for block in blocks {
            if let Some(title) = block.get("title").and_then(Value::as_str) {
                block_text.push_str(title);
                block_text.push('\n');
            }
            if let Some(text) = block.get("text").and_then(Value::as_str) {
                block_text.push_str(text);
                block_text.push('\n');
            }
        }
        for name in extract_company_names_from_text(&block_text, limit) {
            push_document_metadata_entity_candidate(candidates, seen, "organization", &name, limit);
        }
    }
}

fn merge_document_entity_candidates(
    primary: Vec<DocumentEntityCandidate>,
    secondary: Vec<DocumentEntityCandidate>,
    limit: usize,
) -> Vec<DocumentEntityCandidate> {
    let mut merged = Vec::new();
    let mut seen = BTreeSet::new();
    for candidate in primary.into_iter().chain(secondary) {
        push_document_entity_candidate(
            &mut merged,
            &mut seen,
            candidate.entity_type,
            candidate.name,
            limit,
        );
        if merged.len() >= limit {
            break;
        }
    }
    merged
}

fn push_document_entity_candidate(
    output: &mut Vec<DocumentEntityCandidate>,
    seen: &mut BTreeSet<String>,
    entity_type: &'static str,
    name: String,
    limit: usize,
) {
    if output.len() >= limit {
        return;
    }
    let normalized = normalize_document_entity_value(&name);
    if normalized.is_empty() {
        return;
    }
    let normalized = match entity_type {
        "project" => {
            let Some(project_name) = normalize_project_entity_name(&normalized) else {
                return;
            };
            project_name
        }
        "degree" => {
            let Some(degree_name) = normalize_degree_name(&normalized) else {
                return;
            };
            degree_name
        }
        _ => normalized,
    };
    let key = format!("{entity_type}:{normalized}");
    if seen.insert(key) {
        output.push(DocumentEntityCandidate {
            entity_type,
            name: normalized,
        });
    }
}

fn push_document_metadata_entity_candidate(
    output: &mut Vec<DocumentEntityCandidate>,
    seen: &mut BTreeSet<String>,
    entity_type: &'static str,
    value: &str,
    limit: usize,
) {
    let normalized = normalize_document_entity_value(value);
    let accepted = match entity_type {
        "organization" => looks_like_metadata_organization_name(&normalized),
        "person" => looks_like_person_name(&normalized),
        "position" => looks_like_position_name(&normalized),
        "skill" => looks_like_skill_name(&normalized),
        "location" => looks_like_location_name(&normalized),
        "school" => looks_like_school_name(&normalized),
        "degree" => normalize_degree_name(&normalized).is_some(),
        "certificate" => looks_like_certificate_name(&normalized),
        "project" => {
            looks_like_project_name(&normalized)
                && looks_like_project_heading_candidate(&normalized)
                && !project_heading_is_noise(&normalized)
        }
        _ => false,
    };
    if accepted {
        push_document_entity_candidate(output, seen, entity_type, normalized, limit);
    }
}

fn document_metadata_entity_type(raw: &str) -> Option<&'static str> {
    let normalized = raw.trim();
    let lower = normalized.to_ascii_lowercase();
    if lower.contains("organization")
        || lower.contains("company")
        || normalized.contains("公司")
        || normalized.contains("组织")
        || normalized.contains("单位")
    {
        Some("organization")
    } else if lower.contains("person") || normalized.contains("人名") || normalized == "姓名" {
        Some("person")
    } else if lower.contains("job")
        || lower.contains("title")
        || normalized.contains("职位")
        || normalized.contains("岗位")
        || normalized.contains("职务")
    {
        Some("position")
    } else if lower.contains("skill")
        || normalized.contains("技能")
        || normalized.contains("技术栈")
    {
        Some("skill")
    } else if lower.contains("location")
        || lower.contains("city")
        || normalized.contains("地点")
        || normalized.contains("城市")
    {
        Some("location")
    } else if lower.contains("school")
        || lower.contains("university")
        || lower.contains("college")
        || normalized.contains("学校")
        || normalized.contains("院校")
        || normalized.contains("大学")
        || normalized.contains("学院")
    {
        Some("school")
    } else if lower.contains("degree")
        || lower.contains("education")
        || normalized.contains("学历")
        || normalized.contains("学位")
    {
        Some("degree")
    } else if lower.contains("certificate")
        || lower.contains("certification")
        || lower.contains("credential")
        || normalized.contains("证书")
        || normalized.contains("认证")
        || normalized.contains("资质")
    {
        Some("certificate")
    } else if lower.contains("project")
        || lower.contains("product")
        || normalized.contains("项目")
        || normalized.contains("产品")
    {
        Some("project")
    } else {
        None
    }
}

fn document_field_candidate_entity_type(raw_key: &str) -> Option<&'static str> {
    let key = raw_key.trim();
    let lower = key.to_ascii_lowercase();
    if lower.contains("employer")
        || lower.contains("company")
        || lower.contains("work_unit")
        || key.contains("公司")
        || key.contains("雇主")
        || key.contains("工作单位")
        || key.contains("任职单位")
    {
        Some("organization")
    } else if lower.contains("name") || key == "姓名" || key.contains("候选人") {
        Some("person")
    } else if lower.contains("position")
        || lower.contains("job_title")
        || key.contains("职位")
        || key.contains("岗位")
    {
        Some("position")
    } else if lower.contains("skill") || key.contains("技能") || key.contains("技术栈") {
        Some("skill")
    } else if lower.contains("city")
        || lower.contains("location")
        || key.contains("城市")
        || key.contains("地点")
    {
        Some("location")
    } else if lower.contains("school")
        || lower.contains("university")
        || lower.contains("college")
        || key.contains("学校")
        || key.contains("院校")
        || key.contains("毕业院校")
    {
        Some("school")
    } else if lower.contains("degree")
        || lower.contains("education")
        || key.contains("学历")
        || key.contains("学位")
    {
        Some("degree")
    } else if lower.contains("certificate")
        || lower.contains("certification")
        || lower.contains("credential")
        || key.contains("证书")
        || key.contains("认证")
        || key.contains("资质")
    {
        Some("certificate")
    } else if lower.contains("project") || key.contains("项目") {
        Some("project")
    } else {
        None
    }
}

fn extract_document_candidate_terms_for_scan(
    chunks: &[DocumentChunk],
    scan_text: &str,
    limit: usize,
) -> Vec<String> {
    let mut terms = Vec::new();
    for chunk in chunks
        .iter()
        .take(ASSISTANT_RUN_DATASET_ENTITY_SCAN_CHUNK_LIMIT)
    {
        for hint in document_chunk_section_title_hints(chunk) {
            push_document_candidate_term(&mut terms, hint, limit);
        }
        for term in document_chunk_noun_terms(chunk) {
            push_document_candidate_term(&mut terms, term, limit);
        }
    }
    for term in extract_document_candidate_terms_from_text(scan_text, limit) {
        push_document_candidate_term(&mut terms, term, limit);
    }
    terms
}

fn extract_document_candidate_terms_from_text(text: &str, limit: usize) -> Vec<String> {
    let mut terms = BTreeSet::new();
    for token in lexical_query_tokens(text) {
        if document_candidate_term_has_signal(&token) {
            let normalized = normalize_document_entity_value(&token);
            if !normalized.is_empty() {
                terms.insert(normalized);
            }
        }
    }
    let mut terms = terms.into_iter().collect::<Vec<_>>();
    terms.sort_by(|left, right| {
        document_candidate_term_score(right)
            .cmp(&document_candidate_term_score(left))
            .then_with(|| right.chars().count().cmp(&left.chars().count()))
            .then_with(|| left.cmp(right))
    });
    terms.truncate(limit);
    terms
}

fn push_document_candidate_term(output: &mut Vec<String>, value: impl AsRef<str>, limit: usize) {
    if output.len() >= limit {
        return;
    }
    let normalized = normalize_document_entity_value(value.as_ref());
    let char_count = normalized.chars().count();
    if char_count < 2
        || char_count > 32
        || output.iter().any(|existing| existing == &normalized)
        || is_document_entity_noise(&normalized)
    {
        return;
    }
    output.push(normalized);
}

fn extract_labeled_entity_values(text: &str, labels: &[&str], limit: usize) -> Vec<String> {
    let mut values = Vec::new();
    for line in text.lines() {
        for segment in line.split(|ch: char| matches!(ch, '\t' | '|' | '；' | ';')) {
            let normalized = segment.trim();
            if normalized.is_empty() {
                continue;
            }
            for label in labels {
                if let Some(value) = labeled_entity_value(normalized, label) {
                    for item in split_entity_value_list(&value) {
                        push_document_candidate_term(&mut values, item, limit);
                    }
                }
            }
            if values.len() >= limit {
                return values;
            }
        }
    }
    values
}

fn labeled_entity_value(segment: &str, label: &str) -> Option<String> {
    let normalized = segment.trim();
    let label_position = normalized.find(label)?;
    if label_position > 4 {
        return None;
    }
    let mut rest = normalized[label_position + label.len()..].trim();
    rest = rest.trim_start_matches(|ch: char| {
        ch.is_whitespace() || matches!(ch, ':' | '：' | '-' | '—' | '–' | '=')
    });
    if rest.is_empty() {
        return None;
    }
    Some(rest.chars().take(120).collect())
}

fn split_entity_value_list(value: &str) -> Vec<String> {
    value
        .split(|ch: char| {
            matches!(
                ch,
                ',' | '，' | '、' | '/' | '／' | ';' | '；' | '|' | '\t' | '\n' | '\r'
            )
        })
        .map(normalize_document_entity_value)
        .filter(|value| !value.is_empty())
        .collect()
}

fn normalize_document_entity_value(value: &str) -> String {
    value
        .trim()
        .trim_matches(|ch: char| {
            ch.is_whitespace()
                || matches!(
                    ch,
                    ':' | '：'
                        | '-'
                        | '—'
                        | '–'
                        | '_'
                        | '，'
                        | ','
                        | '。'
                        | '；'
                        | ';'
                        | '、'
                        | '（'
                        | '('
                        | '）'
                        | ')'
                        | '【'
                        | '['
                        | '】'
                        | ']'
                        | '"'
                        | '\''
                )
        })
        .chars()
        .take(80)
        .collect::<String>()
}

fn looks_like_metadata_organization_name(value: &str) -> bool {
    let char_count = value.chars().count();
    if char_count < 2
        || char_count > 40
        || value.contains('@')
        || value.chars().all(|ch| ch.is_ascii_digit())
        || company_name_has_unbalanced_brackets(value)
        || is_document_entity_noise(value)
        || company_candidate_has_ocr_noise(value)
    {
        return false;
    }
    if is_valid_company_name(value) {
        return true;
    }
    let has_name_signal = value.chars().any(is_cjk_query_token_char)
        || value.chars().any(|ch| ch.is_ascii_alphabetic());
    has_name_signal
        && ![
            "公司",
            "集团",
            "网络有限公司",
            "顾问有限公司",
            "科技有限公司",
            "信息有限公司",
        ]
        .contains(&value)
}

fn looks_like_person_name(value: &str) -> bool {
    let char_count = value.chars().count();
    char_count >= 2
        && char_count <= 4
        && value.chars().all(is_cjk_query_token_char)
        && !is_document_entity_noise(value)
        && !is_resume_person_name_noise(value)
        && !looks_like_position_name(value)
        && ![
            "姓名",
            "候选人",
            "联系人",
            "公司",
            "项目",
            "岗位",
            "职位",
            "城市",
            "技能",
        ]
        .contains(&value)
}

