fn assistant_run_static_page_structure_signals_brief(current_artifact: &Value) -> Option<Value> {
    const HINT_LIMIT: usize = 12;
    const FIELD_LIMIT: usize = 4;
    const MODULE_LIMIT: usize = 8;

    let snapshot = current_artifact
        .get("dataSnapshot")
        .or_else(|| current_artifact.get("data_snapshot"))?;
    let mut section_title_hints = Vec::<String>::new();

    let field_candidates = snapshot
        .get("fieldCandidates")
        .or_else(|| snapshot.get("field_candidates"))
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter(|candidate| {
                    assistant_run_static_page_field_path(candidate).as_deref()
                        == Some("retrieval.section_title_hints")
                })
                .take(FIELD_LIMIT)
                .map(|candidate| {
                    let hints =
                        assistant_run_static_page_section_title_hints(candidate, HINT_LIMIT);
                    for hint in &hints {
                        push_string_hint(&mut section_title_hints, hint);
                    }
                    let mut brief = Map::new();
                    for (source_key, target_key) in [
                        ("sourceId", "sourceId"),
                        ("source_id", "sourceId"),
                        ("fieldPath", "fieldPath"),
                        ("field_path", "fieldPath"),
                        ("label", "label"),
                        ("kind", "kind"),
                        ("confidence", "confidence"),
                    ] {
                        assistant_run_insert_safe_scalar_field(
                            &mut brief, candidate, source_key, target_key,
                        );
                    }
                    brief.insert("sectionTitleHints".to_string(), json!(hints));
                    Value::Object(brief)
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    let bound_modules = snapshot
        .get("moduleBindings")
        .or_else(|| snapshot.get("module_bindings"))
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|module| {
                    let binding = module
                        .get("binding")
                        .or_else(|| module.get("dataBinding"))
                        .or_else(|| module.get("data_binding"))
                        .unwrap_or(&Value::Null);
                    let binding_quality = module
                        .get("bindingQuality")
                        .or_else(|| module.get("binding_quality"))
                        .unwrap_or(&Value::Null);
                    let matched_candidate = binding_quality
                        .get("matchedFieldCandidate")
                        .or_else(|| binding_quality.get("matched_field_candidate"))
                        .unwrap_or(&Value::Null);
                    let field_path = assistant_run_static_page_field_path(binding)
                        .or_else(|| assistant_run_static_page_field_path(binding_quality))
                        .or_else(|| assistant_run_static_page_field_path(matched_candidate));
                    if field_path.as_deref() != Some("retrieval.section_title_hints") {
                        return None;
                    }
                    let hints =
                        assistant_run_static_page_section_title_hints(matched_candidate, HINT_LIMIT);
                    for hint in &hints {
                        push_string_hint(&mut section_title_hints, hint);
                    }
                    Some(json!({
                        "moduleId": static_page_artifact_string(module, &["moduleId", "module_id"]).unwrap_or_default(),
                        "title": static_page_artifact_string(module, &["title"]).unwrap_or_default(),
                        "fieldPath": field_path,
                        "bindingQualityStatus": static_page_artifact_string(module, &["bindingQualityStatus", "binding_quality_status"])
                            .or_else(|| static_page_artifact_string(binding_quality, &["status"]))
                            .unwrap_or_default(),
                        "sectionTitleHints": hints,
                    }))
                })
                .take(MODULE_LIMIT)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    if section_title_hints.is_empty() && field_candidates.is_empty() && bound_modules.is_empty() {
        return None;
    }
    section_title_hints.truncate(HINT_LIMIT);

    Some(json!({
        "status": if section_title_hints.is_empty() { "none" } else { "available" },
        "policy": "source_structure_only_no_body_no_sample_rows",
        "sectionTitleHints": section_title_hints,
        "fieldCandidates": field_candidates,
        "boundModules": bound_modules,
    }))
}

fn assistant_run_static_page_field_path(value: &Value) -> Option<String> {
    static_page_artifact_string(value, &["fieldPath", "field_path", "field"])
}

pub(crate) fn assistant_run_static_page_section_title_hints(
    value: &Value,
    limit: usize,
) -> Vec<String> {
    let mut hints = Vec::new();
    for key in [
        "sectionTitleHints",
        "section_title_hints",
        "sectionTitles",
        "section_titles",
        "headingHints",
        "heading_hints",
    ] {
        if let Some(value) = value.get(key) {
            collect_string_list(value, &mut hints);
        }
    }
    hints.truncate(limit);
    hints
}

fn assistant_run_static_page_binding_quality_brief(current_artifact: &Value) -> Option<Value> {
    let bindings = current_artifact
        .get("dataSnapshot")
        .or_else(|| current_artifact.get("data_snapshot"))
        .and_then(|snapshot| {
            snapshot
                .get("moduleBindings")
                .or_else(|| snapshot.get("module_bindings"))
        })
        .and_then(Value::as_array)?;

    let modules = bindings
        .iter()
        .take(24)
        .map(assistant_run_static_page_binding_quality_module_brief)
        .collect::<Vec<_>>();
    if modules.is_empty() {
        return None;
    }
    let attention_modules = modules
        .iter()
        .filter(|module| {
            module
                .get("bindingQualityStatus")
                .and_then(Value::as_str)
                .is_some_and(|status| status != "confirmed")
                || module
                    .get("chartDataFit")
                    .and_then(Value::as_str)
                    .is_some_and(|fit| matches!(fit, "needs_sample_rows" | "missing_binding"))
        })
        .count();

    Some(json!({
        "moduleCount": modules.len(),
        "attentionModules": attention_modules,
        "policy": "quality_only_no_sample_rows",
        "modules": modules,
    }))
}

pub(crate) fn assistant_run_static_page_binding_quality_module_brief(binding: &Value) -> Value {
    let data_binding = binding
        .get("binding")
        .or_else(|| binding.get("dataBinding"))
        .or_else(|| binding.get("data_binding"))
        .unwrap_or(&Value::Null);
    let binding_quality = binding
        .get("bindingQuality")
        .or_else(|| binding.get("binding_quality"))
        .unwrap_or(&Value::Null);
    json!({
        "moduleId": static_page_artifact_string(binding, &["moduleId", "module_id"]).unwrap_or_default(),
        "title": static_page_artifact_string(binding, &["title"]).unwrap_or_default(),
        "visualizationType": static_page_artifact_string(binding, &["visualizationType", "visualization_type"]).unwrap_or_default(),
        "chartRuntime": static_page_artifact_string(binding, &["chartRuntime", "chart_runtime"]).unwrap_or_default(),
        "dataQuality": static_page_artifact_string(binding, &["dataQuality", "data_quality"]).unwrap_or_default(),
        "bindingQualityStatus": static_page_artifact_string(binding, &["bindingQualityStatus", "binding_quality_status"])
            .or_else(|| static_page_artifact_string(binding_quality, &["status"]))
            .unwrap_or_default(),
        "chartDataFit": static_page_artifact_string(binding, &["chartDataFit", "chart_data_fit"])
            .or_else(|| static_page_artifact_string(binding_quality, &["chartDataFit", "chart_data_fit"]))
            .unwrap_or_default(),
        "reason": static_page_artifact_string(binding_quality, &["reason"]).unwrap_or_default(),
        "recommendedAction": static_page_artifact_string(binding, &["recommendedAction", "recommended_action"])
            .or_else(|| static_page_artifact_string(binding_quality, &["recommendedAction", "recommended_action"]))
            .unwrap_or_default(),
        "sampleRows": binding_quality
            .get("sampleRows")
            .or_else(|| binding_quality.get("sample_rows"))
            .and_then(Value::as_u64)
            .or_else(|| {
                binding
                    .get("sampleData")
                    .or_else(|| binding.get("sample_data"))
                    .and_then(Value::as_array)
                    .map(|items| items.len() as u64)
            })
            .unwrap_or(0),
        "sourceId": static_page_artifact_string(data_binding, &["sourceId", "source_id"])
            .or_else(|| static_page_artifact_string(binding_quality, &["sourceId", "source_id"]))
            .unwrap_or_default(),
        "fieldPath": static_page_artifact_string(data_binding, &["fieldPath", "field_path", "field"])
            .or_else(|| static_page_artifact_string(binding_quality, &["fieldPath", "field_path", "field"]))
            .unwrap_or_default(),
    })
}

fn assistant_run_static_page_module_briefs(current_artifact: &Value) -> Vec<Value> {
    let Some(modules) = current_artifact.get("modules").and_then(Value::as_array) else {
        return Vec::new();
    };

    modules
        .iter()
        .take(24)
        .enumerate()
        .filter_map(|(index, module)| {
            let mut brief = Map::new();
            brief.insert("index".to_string(), json!(index));
            for key in [
                "id",
                "title",
                "name",
                "type",
                "visualizationType",
                "visualization_type",
                "chartType",
                "chart_type",
                "chartRuntime",
                "chart_runtime",
            ] {
                assistant_run_insert_safe_scalar_field(&mut brief, module, key, key);
            }

            if let Some(visualization) = module.get("visualization") {
                let mut visualization_brief = Map::new();
                assistant_run_insert_safe_scalar_field(
                    &mut visualization_brief,
                    visualization,
                    "type",
                    "type",
                );
                assistant_run_insert_safe_scalar_field(
                    &mut visualization_brief,
                    visualization,
                    "chartRuntime",
                    "chartRuntime",
                );
                assistant_run_insert_safe_scalar_field(
                    &mut visualization_brief,
                    visualization,
                    "chart_runtime",
                    "chart_runtime",
                );
                if !visualization_brief.is_empty() {
                    brief.insert(
                        "visualization".to_string(),
                        Value::Object(visualization_brief),
                    );
                }
            }

            if let Some(data_binding) = module
                .get("dataBinding")
                .or_else(|| module.get("data_binding"))
            {
                let mut data_binding_brief = Map::new();
                for key in [
                    "type",
                    "label",
                    "sourceId",
                    "source_id",
                    "fieldPath",
                    "field_path",
                    "datasetId",
                    "dataset_id",
                ] {
                    assistant_run_insert_safe_scalar_field(
                        &mut data_binding_brief,
                        data_binding,
                        key,
                        key,
                    );
                }
                if !data_binding_brief.is_empty() {
                    brief.insert("dataBinding".to_string(), Value::Object(data_binding_brief));
                }
            }

            if let Some(layout) = module.get("layout").and_then(Value::as_object) {
                let mut layout_brief = Map::new();
                for key in ["x", "y", "w", "h", "minW", "minH", "maxW", "maxH"] {
                    if let Some(value) =
                        layout.get(key).and_then(assistant_run_safe_artifact_scalar)
                    {
                        layout_brief.insert(key.to_string(), value);
                    }
                }
                if !layout_brief.is_empty() {
                    brief.insert("layout".to_string(), Value::Object(layout_brief));
                }
            }

            (brief.len() > 1).then_some(Value::Object(brief))
        })
        .collect()
}

pub(crate) fn assistant_run_insert_safe_scalar_field(
    target: &mut Map<String, Value>,
    source: &Value,
    source_key: &str,
    target_key: &str,
) {
    if let Some(value) = source
        .get(source_key)
        .and_then(assistant_run_safe_artifact_scalar)
    {
        target.insert(target_key.to_string(), value);
    }
}

fn assistant_run_insert_safe_scalar_array_field(
    target: &mut Map<String, Value>,
    source: &Value,
    source_key: &str,
    target_key: &str,
    limit: usize,
) {
    if let Some(items) = source.get(source_key).and_then(Value::as_array) {
        let safe_items = items
            .iter()
            .take(limit)
            .filter_map(assistant_run_safe_artifact_scalar)
            .collect::<Vec<_>>();
        target.insert(target_key.to_string(), Value::Array(safe_items));
    }
}

pub(crate) fn assistant_run_safe_artifact_scalar(value: &Value) -> Option<Value> {
    match value {
        Value::Bool(_) | Value::Number(_) => Some(value.clone()),
        Value::String(text) => Some(json!(truncate_scope_candidate_text(text.trim()))),
        _ => None,
    }
}

fn truncate_scope_candidate_text(value: &str) -> String {
    value.chars().take(80).collect()
}

fn dedupe_assistant_run_scope_candidate_values(candidates: Vec<Value>) -> Vec<Value> {
    let mut seen = HashSet::new();
    candidates
        .into_iter()
        .filter(|candidate| {
            let candidate_type = candidate.get("type").and_then(Value::as_str).unwrap_or("");
            let id = candidate.get("id").and_then(Value::as_str).unwrap_or("");
            if candidate_type.is_empty() || id.is_empty() {
                return true;
            }
            seen.insert(format!("{candidate_type}:{id}"))
        })
        .collect()
}

async fn conversation_memory_source_has_visible_items(
    state: &AppState,
    local_thread_id: &str,
    current_user_id: Option<UserId>,
) -> std::result::Result<bool, ApiError> {
    let local_thread_id = local_thread_id.trim();
    if local_thread_id.is_empty() {
        return Ok(false);
    }
    Ok(state
        .storage
        .conversation_memory_items()
        .list_by_local_thread(state.tenant_id, local_thread_id, None, 1)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .any(|item| {
            owner_user_id_is_visible(item.user_id, current_user_id)
                && assistant_run_memory_item_is_supply_eligible(&item)
        }))
}

async fn load_selected_conversation_memory_items(
    state: &AppState,
    selected_scope: &Value,
    current_local_thread_id: Option<&str>,
    current_user_id: Option<UserId>,
) -> std::result::Result<Vec<Value>, ApiError> {
    let mut supplied_items = Vec::new();
    for local_thread_id in
        selected_scope_conversation_memory_local_thread_ids(selected_scope, current_local_thread_id)
    {
        let items = state
            .storage
            .conversation_memory_items()
            .list_by_local_thread(
                state.tenant_id,
                &local_thread_id,
                None,
                assistant_run_conversation_memory_limit(),
            )
            .await
            .map_err(ApiError::from_storage)?;

        for item in items {
            if !owner_user_id_is_visible(item.user_id, current_user_id)
                || !assistant_run_memory_item_is_supply_eligible(&item)
                || !conversation_memory_item_allowed_for_selected_scope(
                    state,
                    selected_scope,
                    &item,
                )
                .await?
            {
                continue;
            }
            supplied_items.push(conversation_memory_item_supply_value(item));
        }
    }
    Ok(supplied_items)
}

async fn conversation_memory_item_allowed_for_selected_scope(
    state: &AppState,
    selected_scope: &Value,
    item: &ConversationMemoryItem,
) -> std::result::Result<bool, ApiError> {
    if item.item_kind != "external_user_context_turn"
        || item.metadata.get("source").and_then(Value::as_str) != Some("external_channel")
    {
        return Ok(true);
    }
    let Some(current_conversation_external_id) =
        selected_scope_external_user_context_conversation_id(selected_scope)
    else {
        return Ok(true);
    };
    let Some(item_conversation_external_id) =
        conversation_memory_item_external_conversation_id(item)
    else {
        return Ok(true);
    };
    if item_conversation_external_id == current_conversation_external_id {
        return Ok(true);
    }
    if item
        .metadata
        .get("conversation_bound_scope")
        .and_then(Value::as_bool)
        .unwrap_or(false)
        || item
            .metadata
            .get("source_scope_kind")
            .and_then(Value::as_str)
            == Some("conversation_authorized_scope")
    {
        return Ok(false);
    }

    for run_id in conversation_memory_item_source_assistant_run_ids(item) {
        if let Some(run) = state
            .storage
            .assistant_runs()
            .get_by_id(state.tenant_id, run_id)
            .await
            .map_err(ApiError::from_storage)?
        {
            if external_user_context_memory_scope_is_conversation_bound(&run.selected_scope) {
                return Ok(false);
            }
        }
    }

    Ok(true)
}

fn selected_scope_external_user_context_conversation_id(selected_scope: &Value) -> Option<&str> {
    selected_scope
        .get("user_context_scope")
        .and_then(|scope| scope.get("conversation_external_id"))
        .and_then(Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
}

