#[derive(Debug, Deserialize)]
struct WorkflowExecutionListQuery {
    kind: Option<String>,
    status: Option<String>,
    limit: Option<usize>,
}

#[derive(Debug, Deserialize)]
struct WorkflowTaskQueueStatsQuery {
    kind: Option<String>,
    status: Option<String>,
    limit: Option<usize>,
}

async fn list_workflow_executions(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<WorkflowExecutionListQuery>,
) -> std::result::Result<Json<Vec<WorkflowExecutionView>>, ApiError> {
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let kind_filter = query
        .kind
        .as_deref()
        .map(parse_workflow_kind_query)
        .transpose()?;
    let status_filter = query
        .status
        .as_deref()
        .map(parse_workflow_status_query)
        .transpose()?;
    let limit = workflow_execution_list_limit(query.limit);
    let executions = state
        .storage
        .workflow_executions()
        .list_by_tenant(state.tenant_id)
        .await
        .map_err(ApiError::from_storage)?;

    let mut visible = Vec::with_capacity(executions.len());
    for execution in executions {
        if !workflow_execution_matches_filters(
            &execution,
            kind_filter.as_ref(),
            status_filter.as_ref(),
        ) {
            continue;
        }
        match ensure_workflow_execution_visible_for_user(
            &state,
            &execution,
            &active_secret_binding_ids,
            current_user_id,
        )
        .await
        {
            Ok(()) => visible.push(to_workflow_execution_view(execution)),
            Err(error) if error.status == StatusCode::NOT_FOUND => {}
            Err(error) => return Err(error),
        }
    }
    visible.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    if let Some(limit) = limit {
        visible.truncate(limit);
    }

    Ok(Json(visible))
}

async fn get_workflow_task_queue_stats(
    State(state): State<AppState>,
    headers: HeaderMap,
    Query(query): Query<WorkflowTaskQueueStatsQuery>,
) -> std::result::Result<Json<contracts::WorkflowTaskQueueStatsView>, ApiError> {
    require_workflow_queue_stats_access(&state, &headers).await?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    let kind_filter = query
        .kind
        .as_deref()
        .map(parse_workflow_kind_query)
        .transpose()?;
    let status_filter = query
        .status
        .as_deref()
        .map(parse_workflow_status_query)
        .transpose()?;
    let limit = workflow_task_queue_stats_limit(query.limit);
    let executions = state
        .storage
        .workflow_executions()
        .list_by_tenant(state.tenant_id)
        .await
        .map_err(ApiError::from_storage)?;

    let mut visible = Vec::with_capacity(executions.len().min(limit));
    for execution in executions {
        if !workflow_execution_matches_filters(
            &execution,
            kind_filter.as_ref(),
            status_filter.as_ref(),
        ) {
            continue;
        }
        match ensure_workflow_execution_visible_for_user(
            &state,
            &execution,
            &active_secret_binding_ids,
            current_user_id,
        )
        .await
        {
            Ok(()) => visible.push(execution),
            Err(error) if error.status == StatusCode::NOT_FOUND => {}
            Err(error) => return Err(error),
        }
    }
    visible.sort_by(|left, right| right.updated_at.cmp(&left.updated_at));
    visible.truncate(limit);

    let mut tasks = Vec::new();
    for execution in &visible {
        let execution_tasks = state
            .storage
            .workflow_tasks()
            .list_by_execution(execution.id)
            .await
            .map_err(ApiError::from_storage)?;
        tasks.extend(execution_tasks.into_iter().map(to_workflow_task_view));
    }

    Ok(Json(summarize_workflow_task_queue_stats(
        Utc::now(),
        visible.len(),
        &tasks,
    )))
}

async fn require_workflow_queue_stats_access(
    state: &AppState,
    headers: &HeaderMap,
) -> std::result::Result<(), ApiError> {
    if external_observability_access_allowed(headers) {
        return Ok(());
    }
    let Some((user, _session)) = current_auth_session(state, headers).await? else {
        return Err(ApiError::unauthorized(
            "external_observability_access_required",
            "workflow queue stats require an observability access key or operator session"
                .to_string(),
        ));
    };
    ensure_model_gateway_operator(&user)
}

