async fn start_workflow_execution(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(execution_id): Path<String>,
) -> std::result::Result<Json<AdvanceWorkflowExecutionResponse>, ApiError> {
    let execution_id = parse_execution_id(&execution_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_workflow_execution_for_user(
        &state,
        execution_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    let response = apply_workflow_signal(&state, execution_id, WorkflowSignal::Start).await?;
    sync_static_page_render_output_for_workflow(&state, execution_id).await?;

    Ok(Json(response))
}

async fn retry_workflow_execution_route(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(execution_id): Path<String>,
    Json(request): Json<RetryWorkflowExecutionRequest>,
) -> std::result::Result<Json<RetryWorkflowExecutionResponse>, ApiError> {
    let execution_id = parse_execution_id(&execution_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_workflow_execution_for_user(
        &state,
        execution_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    let response = retry_workflow_execution_with_state(&state, execution_id, request).await?;

    Ok(Json(response))
}

async fn send_workflow_signal(
    State(state): State<AppState>,
    headers: HeaderMap,
    Path(execution_id): Path<String>,
    Json(request): Json<WorkflowSignalRequest>,
) -> std::result::Result<Json<AdvanceWorkflowExecutionResponse>, ApiError> {
    let execution_id = parse_execution_id(&execution_id)?;
    let active_secret_binding_ids = active_secret_binding_ids_from_headers(&headers)?;
    let current_user_id = current_auth_user_id(&state, &headers).await?;
    load_visible_workflow_execution_for_user(
        &state,
        execution_id,
        &active_secret_binding_ids,
        current_user_id,
    )
    .await?;
    let signal = build_workflow_signal(request)?;
    let response = apply_workflow_signal(&state, execution_id, signal).await?;
    sync_static_page_render_output_for_workflow(&state, execution_id).await?;

    Ok(Json(response))
}

async fn retry_workflow_execution_with_state(
    state: &AppState,
    execution_id: WorkflowExecutionId,
    request: RetryWorkflowExecutionRequest,
) -> std::result::Result<RetryWorkflowExecutionResponse, ApiError> {
    validate_required("reason", &request.reason)?;

    let retry_transition = apply_workflow_signal(
        state,
        execution_id,
        WorkflowSignal::RetryRequested {
            reason: request.reason.trim().to_string(),
        },
    )
    .await?;
    let restart_transition = if retry_transition.execution.status == WorkflowStatus::Pending {
        Some(apply_workflow_signal(state, execution_id, WorkflowSignal::Start).await?)
    } else {
        None
    };
    sync_static_page_render_output_for_workflow(state, execution_id).await?;

    Ok(RetryWorkflowExecutionResponse {
        retry_transition,
        restart_transition,
    })
}

async fn sync_static_page_render_output_for_workflow(
    state: &AppState,
    execution_id: WorkflowExecutionId,
) -> std::result::Result<(), ApiError> {
    let Some(execution) = state
        .storage
        .workflow_executions()
        .get_by_id(state.tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(());
    };
    if execution.kind != WorkflowKind::StaticPageRender {
        return Ok(());
    }
    let Some(output_id) = execution
        .context
        .get("static_page_render_output_id")
        .and_then(Value::as_str)
        .and_then(|raw| Uuid::parse_str(raw).ok())
        .map(domain_model::StaticPageRenderOutputId)
    else {
        return Ok(());
    };
    let Some(mut output) = state
        .storage
        .static_page_render_outputs()
        .get_by_id(state.tenant_id, output_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(());
    };
    let next_status =
        static_page_render_output_status_for_workflow(&execution.status, &output.status);
    if output.status == StaticPageRenderOutputStatus::Rendered
        && !matches!(next_status, StaticPageRenderOutputStatus::Cancelled)
    {
        return Ok(());
    }
    output.status = next_status;
    output.asset_manifest =
        merge_static_page_render_output_workflow_manifest(&output.asset_manifest, &execution);
    state
        .storage
        .static_page_render_outputs()
        .update(state.tenant_id, &output)
        .await
        .map_err(ApiError::from_storage)?;
    Ok(())
}

pub(crate) async fn apply_workflow_signal(
    state: &AppState,
    execution_id: WorkflowExecutionId,
    signal: WorkflowSignal,
) -> std::result::Result<AdvanceWorkflowExecutionResponse, ApiError> {
    apply_workflow_signal_with_dependencies(
        &state.storage,
        &state.workflow_catalog,
        &state.event_bus,
        state.tenant_id,
        execution_id,
        signal,
    )
    .await
}

pub async fn apply_workflow_signal_with_dependencies(
    storage: &PgStorage,
    workflow_catalog: &WorkflowCatalog,
    event_bus: &EventBus,
    tenant_id: TenantId,
    execution_id: WorkflowExecutionId,
    signal: WorkflowSignal,
) -> std::result::Result<AdvanceWorkflowExecutionResponse, ApiError> {
    let execution = storage
        .workflow_executions()
        .get_by_id(tenant_id, execution_id)
        .await
        .map_err(ApiError::from_storage)?
        .ok_or_else(|| {
            ApiError::not_found(
                "workflow_execution_not_found",
                format!("workflow execution {} was not found", execution_id),
            )
        })?;

    let definition = workflow_catalog
        .find_definition(execution.kind.clone())
        .ok_or_else(|| {
            ApiError::internal(
                "workflow_definition_missing",
                format!(
                    "workflow definition {} is not registered",
                    execution.kind.as_str()
                ),
            )
        })?;
    let now = Utc::now();
    let runtime_state = workflow_runtime_state_from_execution(&execution)?;
    let transition = definition
        .transition(&runtime_state, signal, now)
        .map_err(ApiError::from_transition)?;
    let workflow_engine::WorkflowTransition {
        next_state,
        persisted_event,
        enqueued_tasks,
    } = transition;
    let next_execution = workflow_execution_from_transition(&execution, next_state)?;
    let pending_tasks: Vec<NewWorkflowTask> = enqueued_tasks
        .into_iter()
        .map(|task| NewWorkflowTask {
            queue: task.queue,
            task_key: task.task_key,
            payload: task.payload,
            available_at: persisted_event.occurred_at,
            max_attempts: 3,
        })
        .collect();
    let (persisted_event, persisted_tasks) = storage
        .workflow_executions()
        .advance_with_tasks(
            &next_execution,
            &persisted_event.name,
            &persisted_event.detail,
            persisted_event.occurred_at,
            &pending_tasks,
        )
        .await
        .map_err(ApiError::from_storage)?;
    update_external_sync_run_workflow_status(
        storage,
        tenant_id,
        &next_execution,
        persisted_event.created_at,
    )
    .await?;
    publish_workflow_transition_events(
        event_bus,
        &next_execution,
        &persisted_event,
        &persisted_tasks,
    )
    .await;
    if let Some(event) = codex_host_fixed_task_transition_audit_event(
        &next_execution,
        &persisted_event,
        persisted_tasks.len(),
    ) {
        let followup_event = event.clone();
        record_codex_host_fixed_task_audit_event(storage, tenant_id, event).await?;
        maybe_record_external_static_page_publish_completed(
            storage,
            tenant_id,
            &next_execution,
            &followup_event,
        )
        .await?;
        maybe_record_external_static_page_publish_failed(
            storage,
            tenant_id,
            &next_execution,
            &followup_event,
        )
        .await?;
        maybe_record_external_data_ingestion_analysis_result(
            storage,
            tenant_id,
            &next_execution,
            &followup_event,
        )
        .await?;
    }
    if let Err(error) = maybe_enqueue_external_static_page_publish_after_image_ready(
        storage,
        workflow_catalog,
        event_bus,
        tenant_id,
        &next_execution,
    )
    .await
    {
        tracing::warn!(
            error = ?error,
            execution_id = %next_execution.id,
            "external static-page auto-publish enqueue after Image2 preview failed"
        );
    }

    Ok(AdvanceWorkflowExecutionResponse {
        execution: to_workflow_execution_view(next_execution),
        persisted_event: to_workflow_event_view(persisted_event),
        enqueued_tasks: persisted_tasks
            .into_iter()
            .map(to_workflow_task_view)
            .collect(),
    })
}

async fn update_external_sync_run_workflow_status(
    storage: &PgStorage,
    tenant_id: TenantId,
    execution: &WorkflowExecution,
    occurred_at: DateTime<Utc>,
) -> std::result::Result<(), ApiError> {
    if execution.kind != WorkflowKind::ExternalSourceSync {
        return Ok(());
    }
    let Some(sync_run_id) = execution
        .context
        .get("external_sync_run_id")
        .and_then(Value::as_str)
        .and_then(|raw| Uuid::parse_str(raw).ok())
    else {
        return Ok(());
    };
    let failure_kind = match execution.status {
        WorkflowStatus::Failed => Some(
            execution
                .context
                .get("failed_task_key")
                .and_then(Value::as_str)
                .unwrap_or("workflow_failed")
                .to_string(),
        ),
        WorkflowStatus::Cancelled => Some("cancelled".to_string()),
        WorkflowStatus::DeadLettered => Some("dead_lettered".to_string()),
        WorkflowStatus::Pending | WorkflowStatus::Running | WorkflowStatus::Succeeded => None,
    };

    sqlx::query(
        r#"
        update external_sync_runs
        set status = $3,
            checkpoint = checkpoint || $4,
            failure_kind = $5,
            updated_at = $6
        where tenant_id = $1 and id = $2
        "#,
    )
    .bind(tenant_id.0)
    .bind(sync_run_id)
    .bind(execution.status.as_str())
    .bind(json!({
        "workflow_execution_id": execution.id,
        "workflow_stage": execution.stage,
        "workflow_status": execution.status.as_str(),
    }))
    .bind(&failure_kind)
    .bind(occurred_at)
    .execute(storage.pool())
    .await
    .map_err(|error| ApiError::from_storage(anyhow::Error::new(error)))?;

    maybe_record_data_ingestion_staging_sync_workflow_event(
        storage,
        tenant_id,
        execution,
        sync_run_id,
        failure_kind.as_deref(),
        occurred_at,
    )
    .await?;

    Ok(())
}

async fn maybe_record_data_ingestion_staging_sync_workflow_event(
    storage: &PgStorage,
    tenant_id: TenantId,
    execution: &WorkflowExecution,
    sync_run_id: Uuid,
    failure_kind: Option<&str>,
    occurred_at: DateTime<Utc>,
) -> std::result::Result<(), ApiError> {
    let staging = execution
        .context
        .pointer("/connector_context/data_ingestion_staging")
        .or_else(|| {
            execution
                .context
                .pointer("/connectorContext/dataIngestionStaging")
        })
        .unwrap_or(&Value::Null);
    let Some(assistant_run_id) = staging
        .get("assistant_run_id")
        .or_else(|| staging.get("assistantRunId"))
        .and_then(Value::as_str)
        .and_then(|raw| Uuid::parse_str(raw).ok())
        .map(AssistantRunId)
    else {
        return Ok(());
    };
    let Some(plan_id) = staging
        .get("plan_id")
        .or_else(|| staging.get("planId"))
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(ToOwned::to_owned)
    else {
        return Ok(());
    };
    let workflow_execution_id = execution.id.to_string();
    let already_recorded = storage
        .assistant_runs()
        .list_events(tenant_id, assistant_run_id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .any(|event| {
            event.event_name == "assistant_run.data_ingestion_staging_sync_updated"
                && event.payload.get("plan_id").and_then(Value::as_str) == Some(plan_id.as_str())
                && event
                    .payload
                    .get("workflow_execution_id")
                    .and_then(Value::as_str)
                    == Some(workflow_execution_id.as_str())
                && event.payload.get("workflow_stage").and_then(Value::as_str)
                    == Some(execution.stage.as_str())
                && event.payload.get("workflow_status").and_then(Value::as_str)
                    == Some(execution.status.as_str())
        });
    if already_recorded {
        return Ok(());
    }
    let last_error = execution
        .context
        .get("last_error")
        .and_then(Value::as_str)
        .map(codex_host_fixed_task_safe_text);
    let next_step = match execution.status {
        WorkflowStatus::Succeeded => "query_or_report_from_staging_dataset",
        WorkflowStatus::Failed | WorkflowStatus::Cancelled | WorkflowStatus::DeadLettered => {
            "retry_or_operator_review"
        }
        WorkflowStatus::Pending | WorkflowStatus::Running => "wait_for_external_source_sync_worker",
    };
    storage
        .assistant_runs()
        .append_event(
            tenant_id,
            assistant_run_id,
            &NewAssistantRunEvent {
                event_name: "assistant_run.data_ingestion_staging_sync_updated".to_string(),
                payload: json!({
                    "plan_id": plan_id,
                    "assistant_run_id": assistant_run_id.to_string(),
                    "dataset_id": staging.get("dataset_id").or_else(|| staging.get("datasetId")).cloned().unwrap_or(Value::Null),
                    "dataset_key": staging.get("dataset_key").or_else(|| staging.get("datasetKey")).cloned().unwrap_or(Value::Null),
                    "dataset_title": staging.get("dataset_title").or_else(|| staging.get("datasetTitle")).cloned().unwrap_or(Value::Null),
                    "source_id": staging.get("source_id").or_else(|| staging.get("sourceId")).cloned().unwrap_or(Value::Null),
                    "sync_run_id": sync_run_id.to_string(),
                    "sync_kind": execution.context.get("sync_kind").cloned().unwrap_or(Value::Null),
                    "workflow_execution_id": workflow_execution_id,
                    "workflow_stage": execution.stage.as_str(),
                    "workflow_status": execution.status.as_str(),
                    "failure_kind": failure_kind,
                    "last_error": last_error,
                    "production_write_allowed": false,
                    "schema_mutation_allowed": false,
                    "raw_table_dump_imported": false,
                    "next_step": next_step,
                }),
                created_at: occurred_at,
            },
        )
        .await
        .map_err(ApiError::from_storage)?;
    Ok(())
}

fn build_initial_report_plan_execution(
    state: &AppState,
    plan: &ReportPlan,
    service_handoff: Option<&contracts::ManifestServiceHandoffView>,
) -> std::result::Result<WorkflowExecution, ApiError> {
    let initial = workflow_initial_runtime_parts(
        &state.workflow_catalog,
        WorkflowKind::ReportPlan,
        Utc::now(),
    )?;
    let mut context = workflow_initial_context_with_retries(&initial.runtime_state);
    insert_report_default_context(&mut context, build_static_page_report_time_range_contract());
    if let Some(service_handoff) = service_handoff {
        context.insert("service_handoff".to_string(), json!(service_handoff));
    }

    Ok(workflow_initial_execution_from_parts(
        initial,
        state.tenant_id,
        Some(plan.dataset_id),
        Some(plan.id),
        context,
    ))
}

fn build_initial_external_source_sync_execution(
    state: &AppState,
    source: &ExternalSourceConnectionSummary,
    sync_run_id: Uuid,
    sync_kind: &str,
    dataset_id: Option<DatasetId>,
    owner_user_id: Option<UserId>,
    checkpoint: &Value,
    connector_context: &Value,
) -> std::result::Result<WorkflowExecution, ApiError> {
    let initial = workflow_initial_runtime_parts(
        &state.workflow_catalog,
        WorkflowKind::ExternalSourceSync,
        Utc::now(),
    )?;
    let mut context = workflow_initial_context_with_retries(&initial.runtime_state);
    context.insert(
        "source_id".to_string(),
        Value::String(source.source_id.clone()),
    );
    context.insert(
        "external_sync_run_id".to_string(),
        Value::String(sync_run_id.to_string()),
    );
    context.insert(
        "sync_kind".to_string(),
        Value::String(sync_kind.to_string()),
    );
    context.insert(
        "connector_kind".to_string(),
        Value::String(source.connector_kind.clone()),
    );
    context.insert(
        "display_name".to_string(),
        Value::String(source.display_name.clone()),
    );
    context.insert(
        "sync_mode".to_string(),
        Value::String(source.sync_mode.clone()),
    );
    context.insert(
        "permission_mode".to_string(),
        Value::String(source.permission_mode.clone()),
    );
    context.insert(
        "health_status".to_string(),
        Value::String(source.health_status.clone()),
    );
    context.insert("checkpoint".to_string(), checkpoint.clone());
    context.insert("connector_context".to_string(), connector_context.clone());
    if let Some(dataset_id) = dataset_id {
        context.insert(
            "dataset_id".to_string(),
            Value::String(dataset_id.to_string()),
        );
    }
    if let Some(owner_user_id) = owner_user_id {
        context.insert(
            "owner_user_id".to_string(),
            Value::String(owner_user_id.to_string()),
        );
    }

    Ok(workflow_initial_execution_from_parts(
        initial,
        state.tenant_id,
        dataset_id,
        None,
        context,
    ))
}

