pub(crate) fn to_document_summary(document: Document) -> DocumentSummary {
    let dataset_ids = vec![document.dataset_id];
    to_document_summary_with_dataset_ids(document, dataset_ids)
}

fn to_document_summary_with_dataset_ids(
    document: Document,
    dataset_ids: Vec<DatasetId>,
) -> DocumentSummary {
    let parse_status = document_metadata_parse_status(&document)
        .unwrap_or_else(|| document.lifecycle.as_str().to_string());
    let parse_quality_status = assistant_run_document_parse_quality_status(&document);
    let dataset_ids = normalize_document_dataset_ids(document.dataset_id, dataset_ids);
    DocumentSummary {
        id: document.id,
        dataset_id: document.dataset_id,
        dataset_ids: dataset_ids.clone(),
        dataset_ids_camel: dataset_ids,
        title: document.title,
        object_key: document.object_key,
        content_type: document.content_type,
        lifecycle: contracts::DocumentLifecycleView::from_domain(document.lifecycle),
        parse_status: parse_status.clone(),
        parse_status_camel: parse_status,
        parse_quality_status: parse_quality_status.clone(),
        parse_quality_status_camel: parse_quality_status,
        secret_binding_ids: document.secret_binding_ids,
        created_at: document.created_at,
        updated_at: document.updated_at,
    }
}

pub(crate) async fn to_document_summaries_with_dataset_ids(
    state: &AppState,
    documents: Vec<Document>,
    visible_dataset_ids: Option<&HashSet<DatasetId>>,
) -> std::result::Result<Vec<DocumentSummary>, ApiError> {
    let document_ids: Vec<DocumentId> = documents.iter().map(|document| document.id).collect();
    let membership_pairs = state
        .storage
        .dataset_document_memberships()
        .list_dataset_ids_by_documents(state.tenant_id, &document_ids)
        .await
        .map_err(ApiError::from_storage)?;
    let mut memberships_by_document: HashMap<DocumentId, Vec<DatasetId>> = HashMap::new();
    for (document_id, dataset_id) in membership_pairs {
        if visible_dataset_ids.is_none_or(|visible| visible.contains(&dataset_id)) {
            memberships_by_document
                .entry(document_id)
                .or_default()
                .push(dataset_id);
        }
    }
    Ok(documents
        .into_iter()
        .map(|document| {
            let dataset_ids = memberships_by_document
                .remove(&document.id)
                .unwrap_or_default();
            to_document_summary_with_dataset_ids(document, dataset_ids)
        })
        .collect())
}

pub(crate) async fn hydrate_document_summary_dataset_ids(
    state: &AppState,
    summary: DocumentSummary,
    visible_dataset_ids: Option<&HashSet<DatasetId>>,
) -> std::result::Result<DocumentSummary, ApiError> {
    let membership_dataset_ids = state
        .storage
        .dataset_document_memberships()
        .list_dataset_ids_by_document(state.tenant_id, summary.id)
        .await
        .map_err(ApiError::from_storage)?;
    let mut dataset_ids = Vec::new();
    for dataset_id in membership_dataset_ids {
        if visible_dataset_ids.is_none_or(|visible| visible.contains(&dataset_id)) {
            dataset_ids.push(dataset_id);
        }
    }
    let dataset_ids = normalize_document_dataset_ids(summary.dataset_id, dataset_ids);
    Ok(DocumentSummary {
        dataset_ids: dataset_ids.clone(),
        dataset_ids_camel: dataset_ids,
        ..summary
    })
}

pub(crate) fn to_document_detail_view(
    document: Document,
    chunks: Vec<DocumentChunk>,
    retrieval_evidences: Vec<RetrievalEvidence>,
    workflow: Option<Value>,
) -> DocumentDetailView {
    let parse_state = build_document_parse_status_view(
        &document,
        &chunks,
        retrieval_evidences.len(),
        workflow.as_ref(),
    );
    let mut view = DocumentDetailView {
        document: to_document_summary(document),
        chunks: chunks.into_iter().map(to_document_chunk_view).collect(),
        retrieval_evidences: retrieval_evidences
            .into_iter()
            .map(to_retrieval_evidence_view)
            .collect(),
        parse_state,
        model_facing: None,
    };
    view.model_facing = Some(derive_document_detail_model_facing_summary(&view));
    view
}

fn build_document_parse_status_view(
    document: &Document,
    chunks: &[DocumentChunk],
    retrieval_evidence_count: usize,
    workflow: Option<&Value>,
) -> contracts::DocumentParseStatusView {
    let parse_status = assistant_scope_document_parse_status(document, chunks);
    let parse_quality_summary = assistant_run_document_parse_quality_summary(document)
        .or_else(|| assistant_run_inferred_low_text_parse_quality_summary(document, chunks));
    let parse_quality_status =
        assistant_run_document_parse_quality_status(document).or_else(|| {
            parse_quality_summary
                .as_ref()
                .and_then(|summary| value_at_any_key(summary, &["status"]))
                .and_then(Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(ToOwned::to_owned)
        });
    let model_status = assistant_run_document_parse_model_status(
        document,
        &parse_status,
        chunks.len(),
        parse_quality_status.as_deref(),
        workflow,
    );
    contracts::DocumentParseStatusView {
        parse_status: parse_status.clone(),
        parse_status_camel: parse_status,
        parse_quality_status: parse_quality_status.clone(),
        parse_quality_status_camel: parse_quality_status,
        parse_quality_summary: parse_quality_summary.clone(),
        parse_quality_summary_camel: parse_quality_summary,
        model_status: model_status.clone(),
        model_status_camel: model_status,
        lifecycle: contracts::DocumentLifecycleView::from_domain(document.lifecycle.clone()),
        chunk_count: chunks.len(),
        retrieval_evidence_count,
        workflow: workflow.cloned(),
        ingest: document.metadata.get("ingest").cloned(),
    }
}

fn to_document_media_detail_view(
    document: Document,
    chunks: Vec<DocumentChunk>,
) -> DocumentMediaDetailView {
    let document = to_document_summary(document);
    let raw_media_metadata = extract_media_metadata_from_chunks(&chunks).unwrap_or_else(|| {
        json!({
            "kind": infer_media_kind_from_content_type(&document.content_type),
            "parse_status": "unknown",
            "transcript_segments": [],
            "scenes": [],
            "keyframe_ocr_snippets": [],
            "provider_evidence": []
        })
    });

    let mut view = DocumentMediaDetailView {
        media_kind: raw_media_metadata
            .get("kind")
            .and_then(Value::as_str)
            .filter(|value| !value.trim().is_empty())
            .unwrap_or_else(|| infer_media_kind_from_content_type(&document.content_type))
            .to_string(),
        parse_status: raw_media_metadata
            .get("parse_status")
            .and_then(Value::as_str)
            .unwrap_or("unknown")
            .to_string(),
        transcript_segments: collect_media_transcript_segments(&raw_media_metadata),
        scenes: collect_media_scenes(&raw_media_metadata),
        keyframe_ocr_snippets: collect_media_ocr_snippets(&raw_media_metadata),
        provider_evidence: collect_media_provider_evidence(&raw_media_metadata),
        raw_media_metadata,
        document,
        model_facing: None,
    };
    view.model_facing = Some(derive_document_media_detail_model_facing_summary(&view));
    view
}

pub(crate) fn to_compare_documents_view(
    documents: Vec<DocumentDetailView>,
) -> CompareDocumentsView {
    let mut view = CompareDocumentsView {
        documents,
        model_facing: None,
    };
    view.model_facing = Some(derive_compare_documents_model_facing_summary(&view));
    view
}

fn extract_media_metadata_from_chunks(chunks: &[DocumentChunk]) -> Option<Value> {
    chunks.iter().find_map(|chunk| {
        let metadata = Value::Object(Map::from_iter(chunk.metadata.clone()));
        metadata
            .pointer("/parse_metadata/media")
            .or_else(|| metadata.get("media"))
            .cloned()
    })
}

fn collect_media_transcript_segments(
    raw_media_metadata: &Value,
) -> Vec<contracts::MediaTranscriptSegmentView> {
    raw_media_metadata
        .get("transcript_segments")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    let text = item
                        .get("text")
                        .and_then(Value::as_str)
                        .map(str::trim)
                        .filter(|text| !text.is_empty())?
                        .to_string();
                    Some(contracts::MediaTranscriptSegmentView {
                        start_seconds: media_numeric_field(item, &["start_seconds", "start"]),
                        end_seconds: media_numeric_field(item, &["end_seconds", "end"]),
                        text,
                        source: media_string_field(item, &["source"])
                            .unwrap_or_else(|| "unknown".to_string()),
                        language: media_string_field(item, &["language"]),
                        confidence: media_numeric_field(item, &["confidence", "score"]),
                    })
                })
                .collect()
        })
        .unwrap_or_default()
}

fn collect_media_scenes(raw_media_metadata: &Value) -> Vec<contracts::MediaSceneView> {
    raw_media_metadata
        .get("scenes")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    let summary = media_string_field(item, &["summary", "label"])
                        .unwrap_or_else(|| "Scene".to_string());
                    Some(contracts::MediaSceneView {
                        start_seconds: media_numeric_field(item, &["start_seconds", "start"]),
                        end_seconds: media_numeric_field(item, &["end_seconds", "end"]),
                        representative_seconds: media_numeric_field(
                            item,
                            &["representative_seconds", "timestamp_seconds", "timestamp"],
                        ),
                        summary,
                        source: media_string_field(item, &["source"])
                            .unwrap_or_else(|| "unknown".to_string()),
                    })
                })
                .collect()
        })
        .unwrap_or_default()
}

fn collect_media_ocr_snippets(raw_media_metadata: &Value) -> Vec<contracts::MediaOcrSnippetView> {
    raw_media_metadata
        .get("keyframe_ocr_snippets")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    let text = media_string_field(item, &["text", "content"])?;
                    Some(contracts::MediaOcrSnippetView {
                        timestamp_seconds: media_numeric_field(
                            item,
                            &["timestamp_seconds", "timestamp", "time"],
                        ),
                        text,
                        source: media_string_field(item, &["source"])
                            .unwrap_or_else(|| "unknown".to_string()),
                    })
                })
                .collect()
        })
        .unwrap_or_default()
}

fn collect_media_provider_evidence(
    raw_media_metadata: &Value,
) -> Vec<contracts::MediaProviderEvidenceView> {
    if let Some(items) = raw_media_metadata
        .get("provider_evidence")
        .and_then(Value::as_array)
    {
        return items
            .iter()
            .filter_map(media_provider_evidence_from_value)
            .collect();
    }

    raw_media_metadata
        .get("provider_capabilities")
        .and_then(Value::as_object)
        .map(|object| {
            [
                "audio_transcript",
                "native_video_understanding",
                "keyframe_image_vlm",
            ]
            .into_iter()
            .filter_map(|key| object.get(key))
            .filter_map(media_provider_evidence_from_value)
            .collect()
        })
        .unwrap_or_default()
}

fn media_provider_evidence_from_value(
    value: &Value,
) -> Option<contracts::MediaProviderEvidenceView> {
    Some(contracts::MediaProviderEvidenceView {
        provider: media_string_field(value, &["provider"]).unwrap_or_else(|| "unknown".to_string()),
        capability: media_string_field(value, &["capability"])?,
        status: media_string_field(value, &["status"]).unwrap_or_else(|| "unknown".to_string()),
        supported: value
            .get("supported")
            .and_then(Value::as_bool)
            .unwrap_or(false),
        detail: media_string_field(value, &["detail"]).unwrap_or_default(),
        endpoint: media_string_field(value, &["endpoint"]),
        model: media_string_field(value, &["model"]).unwrap_or_default(),
    })
}

struct RankedRetrievalEvidence<'a> {
    evidence: &'a RetrievalEvidence,
    score: f64,
    lexical_score: f64,
    recall_score: f64,
    rank_hint: usize,
}

struct RankedDocumentChunk {
    document: Document,
    chunk: DocumentChunk,
    search_text: String,
    score: f64,
    lexical_score: f64,
}

fn rank_retrieval_evidences_for_prompt<'a>(
    evidences: &'a [RetrievalEvidence],
    prompt: &str,
    limit: usize,
) -> Vec<RankedRetrievalEvidence<'a>> {
    if evidences.is_empty() || limit == 0 {
        return Vec::new();
    }

    let query_variants = assistant_run_rank_query_variants(prompt);
    let mut ranked = evidences
        .iter()
        .map(|evidence| {
            let search_text = retrieval_evidence_search_text(evidence);
            let mut lexical_score = query_variants
                .iter()
                .map(|query| {
                    lexical_query_score(evidence, &query.weights, query.norm)
                        .max(lexical_text_score(&search_text, &query.weights, query.norm))
                        + lexical_domain_hint_score(&search_text, &query.text)
                })
                .fold(0.0, f64::max);
            lexical_score +=
                lexical_retrieval_original_query_signal_score(evidence, &search_text, prompt);
            let score = if lexical_score > 0.0 {
                lexical_score
            } else {
                evidence.recall_score
            };
            RankedRetrievalEvidence {
                evidence,
                score,
                lexical_score,
                recall_score: evidence.recall_score,
                rank_hint: rank_hint_from_evidence_manifest(evidence).unwrap_or(usize::MAX),
            }
        })
        .collect::<Vec<_>>();
    ranked.sort_by(|left, right| {
        right
            .lexical_score
            .partial_cmp(&left.lexical_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| {
                right
                    .score
                    .partial_cmp(&left.score)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .then_with(|| {
                right
                    .recall_score
                    .partial_cmp(&left.recall_score)
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
            .then_with(|| left.rank_hint.cmp(&right.rank_hint))
            .then_with(|| right.evidence.created_at.cmp(&left.evidence.created_at))
            .then_with(|| left.evidence.chunk_index.cmp(&right.evidence.chunk_index))
    });
    ranked.into_iter().take(limit).collect()
}

fn rank_document_chunks_for_prompt(
    sources: Vec<(Document, DocumentChunk)>,
    prompt: &str,
    limit: usize,
) -> Vec<RankedDocumentChunk> {
    if sources.is_empty() || limit == 0 {
        return Vec::new();
    }

    let query_variants = assistant_run_rank_query_variants_for_chunks(prompt, &sources);
    let mut ranked = sources
        .into_iter()
        .map(|(document, chunk)| {
            let search_text = document_chunk_search_text(&document, &chunk);
            let mut lexical_score = query_variants
                .iter()
                .map(|query| {
                    lexical_text_score(&search_text, &query.weights, query.norm)
                        + lexical_domain_hint_score(&search_text, &query.text)
                })
                .fold(0.0, f64::max);
            lexical_score += lexical_original_query_signal_overlap_score(&search_text, prompt);
            if document_chunk_looks_like_toc_or_index(&chunk) {
                lexical_score *= 0.35;
            }
            RankedDocumentChunk {
                document,
                chunk,
                search_text,
                score: lexical_score,
                lexical_score,
            }
        })
        .collect::<Vec<_>>();

    ranked.sort_by(|left, right| {
        right
            .lexical_score
            .partial_cmp(&left.lexical_score)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| right.chunk.updated_at.cmp(&left.chunk.updated_at))
            .then_with(|| left.chunk.chunk_index.cmp(&right.chunk.chunk_index))
            .then_with(|| left.document.title.cmp(&right.document.title))
    });
    ranked.into_iter().take(limit).collect()
}

fn assistant_run_rank_query_variants_for_chunks(
    prompt: &str,
    sources: &[(Document, DocumentChunk)],
) -> Vec<AssistantRunRankQuery> {
    let mut variants = assistant_run_rank_query_variants(prompt);
    let mut seen = variants
        .iter()
        .map(|variant| variant.text.clone())
        .collect::<BTreeSet<_>>();
    for text in assistant_run_section_title_hop_query_texts(prompt, sources, 4) {
        let text = normalize_assistant_reduced_query_text(&text);
        if text.is_empty() || !seen.insert(text.clone()) {
            continue;
        }
        let weights = lexical_query_term_weights(&text);
        let norm = vector_norm(&weights);
        if norm > 0.0 {
            variants.push(AssistantRunRankQuery {
                text,
                weights,
                norm,
            });
        }
    }
    variants
}

fn assistant_run_section_title_hop_query_texts(
    prompt: &str,
    sources: &[(Document, DocumentChunk)],
    limit: usize,
) -> Vec<String> {
    if limit == 0
        || (!prompt_requests_procedure_or_action(prompt)
            && !prompt_contains_elder_fall_signal(prompt)
            && !prompt_contains_elder_death_signal(prompt))
    {
        return Vec::new();
    }
    let expanded_prompt = assistant_run_expanded_supply_prompt(prompt);
    let original_query_weights = lexical_query_term_weights(prompt);
    let original_query_norm = vector_norm(&original_query_weights);
    let query_weights = lexical_query_term_weights(&expanded_prompt);
    let query_norm = vector_norm(&query_weights);
    if query_weights.is_empty() || query_norm <= 0.0 {
        return Vec::new();
    }

    let mut scored_titles = Vec::<(String, f64, bool)>::new();
    for (_document, chunk) in sources {
        let title_hints = document_chunk_section_title_hints(chunk);
        if title_hints.is_empty() {
            continue;
        }
        let toc_like = document_chunk_looks_like_toc_or_index(chunk);
        for title in title_hints {
            let original_overlap_score =
                lexical_text_score(&title, &original_query_weights, original_query_norm);
            let domain_score = lexical_domain_hint_score(&title, &expanded_prompt);
            if original_overlap_score <= 0.0 && domain_score <= 0.0 {
                continue;
            }
            let score = lexical_text_score(&title, &query_weights, query_norm)
                + domain_score
                + original_overlap_score;
            if score > 0.0 {
                scored_titles.push((title, score, toc_like));
            }
        }
    }
    scored_titles.sort_by(|left, right| {
        right
            .1
            .partial_cmp(&left.1)
            .unwrap_or(std::cmp::Ordering::Equal)
            .then_with(|| left.2.cmp(&right.2))
            .then_with(|| left.0.cmp(&right.0))
    });

    let mut seen = BTreeSet::new();
    scored_titles
        .into_iter()
        .filter_map(|(title, _score, _toc_like)| {
            if seen.insert(title.clone()) {
                Some(format!("{title} {expanded_prompt}"))
            } else {
                None
            }
        })
        .take(limit)
        .collect()
}

fn lexical_original_query_signal_overlap_score(content: &str, prompt: &str) -> f64 {
    let lower_content = content.to_ascii_lowercase();
    let mut seen = BTreeSet::new();
    let mut cjk_score: f64 = 0.0;
    let mut ascii_score: f64 = 0.0;
    for term in lexical_query_term_weights(prompt).keys() {
        if !seen.insert(term.clone()) || !assistant_run_reduced_query_term_is_signal(term) {
            continue;
        }
        let char_count = term.chars().count();
        if term.chars().all(|value| is_cjk_query_token_char(value)) {
            if char_count >= 2 && content.contains(term) {
                cjk_score += (0.018 * char_count.min(6) as f64).min(0.08);
            }
        } else if lower_content.contains(&term.to_ascii_lowercase()) {
            ascii_score += 0.018;
        }
    }
    cjk_score.min(0.24) + ascii_score.min(0.06)
}

fn lexical_retrieval_original_query_signal_score(
    evidence: &RetrievalEvidence,
    content: &str,
    prompt: &str,
) -> f64 {
    let score = lexical_original_query_signal_overlap_score(content, prompt)
        + lexical_ascii_field_signal_score(content, prompt)
        + lexical_numeric_cjk_literal_signal_score(content, prompt)
        + lexical_spreadsheet_overview_signal_score(evidence, content, prompt);
    score.clamp(-0.16, 0.82)
}

fn lexical_ascii_field_signal_score(content: &str, prompt: &str) -> f64 {
    let lower_content = content.to_ascii_lowercase();
    let mut seen = BTreeSet::new();
    let mut score: f64 = 0.0;
    let mut matched_field_terms = 0usize;
    for term in lexical_query_term_weights(prompt).keys() {
        if !seen.insert(term.clone())
            || term.chars().count() < 4
            || !term.chars().any(|value| value.is_ascii_alphanumeric())
            || !lower_content.contains(&term.to_ascii_lowercase())
        {
            continue;
        }
        let char_count = term.chars().count();
        score += if char_count >= 8 { 0.12 } else { 0.08 };
        matched_field_terms += 1;
    }
    if matched_field_terms >= 2 {
        score += 0.20;
    }
    if matched_field_terms >= 2 && prompt.contains("销售缺口") && lower_content.contains("quekou")
    {
        score += 0.08;
    }
    score.min(0.56)
}

fn lexical_numeric_cjk_literal_signal_score(content: &str, prompt: &str) -> f64 {
    let prompt_literals = lexical_numeric_cjk_literals(prompt);
    if prompt_literals.is_empty() {
        return 0.0;
    }

    let mut score: f64 = 0.0;
    let prompt_months = prompt_literals
        .iter()
        .filter(|literal| literal.ends_with('月'))
        .cloned()
        .collect::<BTreeSet<_>>();
    let content_literals = lexical_numeric_cjk_literals(content)
        .into_iter()
        .collect::<BTreeSet<_>>();

    for literal in &prompt_literals {
        if content.contains(literal) {
            score += if literal.ends_with('月') { 0.18 } else { 0.08 };
        }
    }

    if !prompt_months.is_empty()
        && !prompt_months
            .iter()
            .any(|literal| content_literals.contains(literal))
        && content_literals
            .iter()
            .any(|literal| literal.ends_with('月'))
    {
        score -= 0.12;
    }

    score.clamp(-0.12, 0.32)
}

fn lexical_numeric_cjk_literals(content: &str) -> Vec<String> {
    let mut literals = Vec::new();
    let mut digits = String::new();
    for value in content.chars() {
        if value.is_ascii_digit() {
            digits.push(value);
            continue;
        }
        if !digits.is_empty() && matches!(value, '年' | '月' | '日' | '天') {
            literals.push(format!("{digits}{value}"));
        }
        digits.clear();
    }
    literals
}

fn lexical_spreadsheet_overview_signal_score(
    evidence: &RetrievalEvidence,
    content: &str,
    prompt: &str,
) -> f64 {
    if !prompt_requests_spreadsheet_overview(prompt) {
        return 0.0;
    }
    let lowered_content = content.to_ascii_lowercase();
    let overview_locator = evidence.chunk_index == 0
        || lowered_content.contains("chunk 0")
        || content.contains("Sheet 1");
    let overview_content = content.contains("报表名")
        || content.contains("数据来源")
        || content.contains("计算方法")
        || content.contains("口径")
        || content.contains("表说明")
        || content.contains("字段说明")
        || content.contains("Sheet 1");
    let mut score: f64 = if overview_locator && overview_content {
        0.18
    } else if overview_content {
        0.08
    } else {
        0.0
    };
    if prompt.contains("计算方法") && content.contains("计算方法") {
        score += 0.44;
    }
    if prompt.contains("数据来源") && content.contains("数据来源") {
        score += 0.24;
    }
    if (prompt.contains("哪张表") || prompt.contains("哪个表") || prompt.contains("报表名"))
        && content.contains("报表名")
    {
        score += 0.12;
    }
    score.min(0.78)
}

fn prompt_requests_spreadsheet_overview(prompt: &str) -> bool {
    [
        "计算方法",
        "怎么算",
        "算法",
        "口径",
        "数据来源",
        "表说明",
        "报表名",
        "哪张表",
        "哪个表",
        "数据在哪里",
        "字段说明",
    ]
    .iter()
    .any(|signal| prompt.contains(signal))
        || prompt_requests_spreadsheet_contents(prompt)
}

fn prompt_requests_spreadsheet_contents(prompt: &str) -> bool {
    prompt.contains("内容")
        && (prompt.contains('表')
            || prompt.contains("报表")
            || prompt.to_ascii_lowercase().contains("sheet"))
}

fn select_retrieval_evidence_ids_for_prompt(
    evidences: &[RetrievalEvidence],
    prompt: &str,
    limit: usize,
) -> Vec<RetrievalEvidenceId> {
    rank_retrieval_evidences_for_prompt(evidences, prompt, limit)
        .into_iter()
        .map(|ranked| ranked.evidence.id)
        .collect()
}

fn search_retrieval_hits(
    evidences: &[RetrievalEvidence],
    prompt: &str,
    limit: usize,
) -> Vec<RetrievalSearchHitView> {
    rank_retrieval_evidences_for_prompt(evidences, prompt, limit)
        .into_iter()
        .map(|ranked| RetrievalSearchHitView {
            retrieval_evidence_id: ranked.evidence.id,
            document_id: ranked.evidence.document_id,
            score: ranked.score,
            summary: ranked.evidence.summary.clone(),
            source_locator: ranked.evidence.source_locator.clone(),
        })
        .collect()
}

