async fn load_html_artifact_from_record_for_run(
    state: &AppState,
    run_id: AssistantRunId,
    artifact_id: &str,
) -> std::result::Result<Option<HtmlArtifactManifestView>, ApiError> {
    let Some(record) = state
        .storage
        .html_artifacts()
        .get_by_id(state.tenant_id, artifact_id)
        .await
        .map_err(ApiError::from_storage)?
    else {
        return Ok(None);
    };
    if record.assistant_run_id != Some(run_id) {
        return Ok(None);
    }
    let manifest =
        serde_json::from_value::<HtmlArtifactManifestView>(record.manifest).map_err(|error| {
            ApiError::internal(
                "html_artifact_manifest_invalid",
                format!("stored HTML artifact manifest is invalid: {error}"),
            )
        })?;
    Ok(Some(manifest))
}

async fn load_visible_html_artifact_for_submit(
    state: &AppState,
    current_user_id: Option<UserId>,
    artifact_id: &str,
    request: &SubmitHtmlArtifactEventRequest,
) -> std::result::Result<(AssistantRun, HtmlArtifactManifestView), ApiError> {
    if let Some(raw_run_id) = request
        .assistant_run_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let run_id = parse_assistant_run_id(raw_run_id)?;
        let run = load_visible_assistant_run_for_user(state, run_id, current_user_id).await?;
        if let Some(artifact) =
            load_html_artifact_from_record_for_run(state, run.id, artifact_id).await?
        {
            return Ok((run, artifact));
        }
        let artifact = load_html_artifact_from_run_events(state, run.id, artifact_id).await?;
        persist_html_artifacts_for_run(state, &run, std::slice::from_ref(&artifact)).await?;
        return Ok((run, artifact));
    }

    if let Some(local_thread_id) = request
        .local_thread_id
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
    {
        let runs = state
            .storage
            .assistant_runs()
            .list_by_local_thread(
                state.tenant_id,
                local_thread_id,
                HTML_ARTIFACT_LIST_MAX_LIMIT,
            )
            .await
            .map_err(ApiError::from_storage)?;
        for run in runs
            .into_iter()
            .filter(|run| owner_user_id_is_visible(run.user_id, current_user_id))
        {
            if let Some(artifact) =
                load_html_artifact_from_record_for_run(state, run.id, artifact_id).await?
            {
                return Ok((run, artifact));
            }
            match load_html_artifact_from_run_events(state, run.id, artifact_id).await {
                Ok(artifact) => {
                    persist_html_artifacts_for_run(state, &run, std::slice::from_ref(&artifact))
                        .await?;
                    return Ok((run, artifact));
                }
                Err(error) if error.payload.code == "html_artifact_not_found" => continue,
                Err(error) => return Err(error),
            }
        }
    }

    Err(ApiError::not_found(
        "html_artifact_not_found",
        format!("html artifact {artifact_id} was not found"),
    ))
}

async fn load_html_artifact_from_run_events(
    state: &AppState,
    run_id: AssistantRunId,
    artifact_id: &str,
) -> std::result::Result<HtmlArtifactManifestView, ApiError> {
    load_html_artifacts_from_run_events(state, run_id, HTML_ARTIFACT_LIST_MAX_LIMIT as usize)
        .await?
        .into_iter()
        .find(|artifact| artifact.id == artifact_id)
        .ok_or_else(|| {
            ApiError::not_found(
                "html_artifact_not_found",
                format!("html artifact {artifact_id} was not found"),
            )
        })
}

async fn apply_html_artifact_event_to_product(
    state: &AppState,
    current_user_id: Option<UserId>,
    run: &AssistantRun,
    artifact: &HtmlArtifactManifestView,
    request: &SubmitHtmlArtifactEventRequest,
) -> std::result::Result<Option<Value>, ApiError> {
    if request.event_type.trim() != "html_artifact.patch" {
        return apply_html_artifact_action_intent_to_product(
            state,
            current_user_id,
            run,
            artifact,
            request,
        )
        .await;
    }
    if !matches!(
        artifact.source_type,
        contracts::HtmlArtifactSourceTypeView::StaticPage
    ) || !matches!(
        artifact.template_id,
        contracts::HtmlArtifactTemplateIdView::StaticPagePlanningHandoff
    ) {
        return Ok(None);
    }
    if artifact.owner_scope.scope_type != "static_page_draft" {
        return Ok(None);
    }

    let draft_id = parse_static_page_draft_id(&artifact.owner_scope.id)?;
    let mut draft = load_visible_static_page_draft(state, draft_id, current_user_id).await?;
    if draft.assistant_run_id != run.id {
        return Err(ApiError::bad_request(
            "html_artifact_owner_mismatch",
            "HTML artifact owner scope does not match the assistant run".to_string(),
        ));
    }

    let operations =
        static_page_operations_from_html_artifact_patch(&draft.draft_payload, &request.payload)?;
    if operations.is_empty() {
        return Err(ApiError::bad_request(
            "html_artifact_patch_noop",
            "HTML artifact patch did not contain supported static page changes".to_string(),
        ));
    }

    let summary = format!("已从 HTML 产物应用 {} 个静态页修改。", operations.len());
    let mut draft_payload = apply_static_page_operations_to_payload(
        draft.draft_payload.clone(),
        &operations,
        Some(&summary),
    );
    finalize_static_page_operations_payload(
        &mut draft_payload,
        &operations,
        Some("html_artifact.patch"),
        &summary,
    );
    draft.status = status_from_static_page_payload(&draft_payload)
        .or_else(|| status_from_static_page_operations(&operations))
        .unwrap_or(StaticPageDraftStatus::Planned);
    draft.draft_payload = draft_payload;

    let updated = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &updated,
        "static_page_draft.html_artifact_patch_applied",
        json!({
            "draft_id": updated.id,
            "artifact_id": artifact.id,
            "operation_count": operations.len(),
            "summary": summary,
        }),
    )
    .await?;

    Ok(Some(json!({
        "status": "applied",
        "target_type": "static_page_draft",
        "draft_id": updated.id,
        "operation_count": operations.len(),
        "summary": summary,
    })))
}

async fn apply_html_artifact_action_intent_to_product(
    state: &AppState,
    current_user_id: Option<UserId>,
    run: &AssistantRun,
    artifact: &HtmlArtifactManifestView,
    request: &SubmitHtmlArtifactEventRequest,
) -> std::result::Result<Option<Value>, ApiError> {
    if request.event_type.trim() != "html_artifact.action_intent" {
        return Ok(None);
    }
    if !matches!(
        artifact.source_type,
        contracts::HtmlArtifactSourceTypeView::StaticPage
    ) || !matches!(
        artifact.template_id,
        contracts::HtmlArtifactTemplateIdView::StaticPagePlanningHandoff
    ) {
        return Ok(None);
    }
    if artifact.owner_scope.scope_type != "static_page_draft" {
        return Ok(None);
    }

    let prompt = html_artifact_action_intent_prompt(&request.payload)?;
    let draft_id = parse_static_page_draft_id(&artifact.owner_scope.id)?;
    let mut draft = load_visible_static_page_draft(state, draft_id, current_user_id).await?;
    if draft.assistant_run_id != run.id {
        return Err(ApiError::bad_request(
            "html_artifact_owner_mismatch",
            "HTML artifact owner scope does not match the assistant run".to_string(),
        ));
    }

    let intent = interpret_static_page_draft_intent_for_api(
        state,
        &draft,
        &prompt,
        &draft.draft_payload,
        Vec::new(),
    )
    .await?;
    if intent.operations.is_empty() {
        return Err(ApiError::bad_request(
            "html_artifact_action_intent_noop",
            "HTML artifact action intent did not produce static page changes".to_string(),
        ));
    }

    let mut draft_payload = apply_static_page_operations_to_payload(
        draft.draft_payload.clone(),
        &intent.operations,
        Some(&intent.summary),
    );
    finalize_static_page_operations_payload(
        &mut draft_payload,
        &intent.operations,
        Some(&prompt),
        &intent.summary,
    );
    draft.status = status_from_static_page_payload(&draft_payload)
        .or_else(|| status_from_static_page_operations(&intent.operations))
        .unwrap_or(StaticPageDraftStatus::Planned);
    draft.draft_payload = draft_payload;

    let updated = state
        .storage
        .static_page_drafts()
        .update(state.tenant_id, &draft)
        .await
        .map_err(ApiError::from_storage)?;
    append_static_page_draft_run_event(
        state,
        &updated,
        "static_page_draft.html_artifact_intent_applied",
        json!({
            "draft_id": updated.id,
            "artifact_id": artifact.id,
            "prompt": prompt,
            "operation_count": intent.operations.len(),
            "summary": intent.summary,
            "runtime": intent.runtime,
        }),
    )
    .await?;

    Ok(Some(json!({
        "status": "applied",
        "target_type": "static_page_draft",
        "draft_id": updated.id,
        "operation_count": intent.operations.len(),
        "summary": intent.summary,
        "runtime": intent.runtime,
    })))
}

pub(crate) async fn hydrate_dataset_output_view(
    state: &AppState,
    output: DatasetOutput,
) -> std::result::Result<DatasetOutputView, ApiError> {
    let llm_invocations = list_llm_invocation_views_for_dataset_output(state, output.id).await?;
    let tool_executions = list_tool_execution_views_for_dataset_output(state, output.id).await?;
    let memory_directory = match output.memory_directory_id {
        Some(directory_id) => match state
            .storage
            .memory_directories()
            .get_by_id(state.tenant_id, directory_id)
            .await
            .map_err(ApiError::from_storage)?
        {
            Some(directory) => {
                visible_memory_directory_for_user(state, directory, output.owner_user_id)
                    .await?
                    .map(to_memory_directory_view)
            }
            None => None,
        },
        None => None,
    };
    let retrieval_evidences = state
        .storage
        .retrieval_evidences()
        .list_by_ids(state.tenant_id, &output.retrieval_evidence_ids)
        .await
        .map_err(ApiError::from_storage)?;
    let retrieval_evidences = filter_retrieval_evidences_for_visible_documents(
        state,
        output.dataset_id,
        retrieval_evidences,
        output.owner_user_id,
    )
    .await?
    .into_iter()
    .map(to_retrieval_evidence_view)
    .collect();

    let mut view = to_dataset_output_view(
        output,
        memory_directory,
        retrieval_evidences,
        llm_invocations,
        tool_executions,
    );
    view.model_facing = Some(derive_dataset_output_model_facing_summary(&view));

    Ok(view)
}

pub(crate) async fn hydrate_chat_session_view(
    state: &AppState,
    session: ChatSession,
) -> std::result::Result<ChatSessionView, ApiError> {
    let latest_assistant_message = state
        .storage
        .chat_messages()
        .list_by_session(state.tenant_id, session.id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .rev()
        .find(|message| message.role == ChatMessageRole::Assistant);
    let latest_assistant_message = match latest_assistant_message {
        Some(message) => Some(hydrate_chat_message_view(state, message).await?),
        None => None,
    };

    hydrate_chat_session_view_with_latest_assistant_message(
        state,
        session,
        latest_assistant_message,
    )
    .await
}

async fn hydrate_chat_session_view_with_latest_assistant_message(
    state: &AppState,
    session: ChatSession,
    latest_assistant_message: Option<ChatMessageView>,
) -> std::result::Result<ChatSessionView, ApiError> {
    let latest_memory_directory = match session.latest_memory_directory_id {
        Some(directory_id) => match state
            .storage
            .memory_directories()
            .get_by_id(state.tenant_id, directory_id)
            .await
            .map_err(ApiError::from_storage)?
        {
            Some(directory) => visible_memory_directory_for_user(state, directory, session.user_id)
                .await?
                .map(to_memory_directory_view),
            None => None,
        },
        None => None,
    };
    let latest_dataset_output = match session.latest_dataset_output_id {
        Some(output_id) => {
            let output = state
                .storage
                .dataset_outputs()
                .get_by_id(state.tenant_id, output_id)
                .await
                .map_err(ApiError::from_storage)?;
            match output {
                Some(output) if owner_user_id_is_visible(output.owner_user_id, session.user_id) => {
                    Some(hydrate_dataset_output_view(state, output).await?)
                }
                Some(_) => None,
                None => None,
            }
        }
        None => None,
    };

    let mut view = to_chat_session_view(
        session,
        latest_memory_directory,
        latest_dataset_output,
        latest_assistant_message,
    );
    view.model_facing = Some(derive_chat_session_model_facing_summary(&view));

    Ok(view)
}

async fn load_chat_message_views_for_session(
    state: &AppState,
    session_id: ChatSessionId,
) -> std::result::Result<Vec<ChatMessageView>, ApiError> {
    let messages = state
        .storage
        .chat_messages()
        .list_by_session(state.tenant_id, session_id)
        .await
        .map_err(ApiError::from_storage)?;
    let mut views = Vec::with_capacity(messages.len());
    for message in messages {
        views.push(hydrate_chat_message_view(state, message).await?);
    }
    Ok(views)
}

