async fn hydrate_published_report_detail_view(
    state: &AppState,
    report: PublishedReport,
) -> std::result::Result<PublishedReportDetailView, ApiError> {
    let versions = state
        .storage
        .published_report_versions()
        .list_by_report(state.tenant_id, report.id)
        .await
        .map_err(ApiError::from_storage)?
        .into_iter()
        .map(to_published_report_version_view)
        .collect::<Vec<_>>();
    let current_version = report.current_version_id.and_then(|current_version_id| {
        versions
            .iter()
            .find(|version| version.id == current_version_id)
            .cloned()
    });

    Ok(PublishedReportDetailView {
        report: to_published_report_view(report),
        current_version,
        versions,
    })
}

fn build_published_report_slug(plan: &ReportPlan) -> String {
    let base = slugify_report_title(&plan.title);
    let suffix = plan
        .id
        .to_string()
        .chars()
        .filter(|value| *value != '-')
        .take(8)
        .collect::<String>();
    format!("{base}-{suffix}")
}

fn slugify_report_title(title: &str) -> String {
    let mut slug = String::new();
    let mut last_was_separator = false;

    for character in title.chars() {
        if character.is_ascii_alphanumeric() {
            slug.push(character.to_ascii_lowercase());
            last_was_separator = false;
            continue;
        }
        if slug.is_empty() || last_was_separator {
            continue;
        }
        slug.push('-');
        last_was_separator = true;
    }

    while slug.ends_with('-') {
        slug.pop();
    }

    if slug.is_empty() {
        "report".to_string()
    } else {
        slug
    }
}

fn build_published_report_version_manifest(
    render_output: &ReportRenderOutput,
    publish_note: Option<&str>,
    published_at: DateTime<Utc>,
) -> Value {
    let publish_metadata = json!({
        "published_at": published_at,
        "source_render_output_id": render_output.id,
        "source_execution_id": render_output.execution_id,
        "publish_note": publish_note,
    });

    match render_output.asset_manifest.clone() {
        Value::Object(mut manifest) => {
            manifest.insert("publish_metadata".to_string(), publish_metadata);
            Value::Object(manifest)
        }
        other => json!({
            "render_asset_manifest": other,
            "publish_metadata": publish_metadata,
        }),
    }
}

fn assistant_run_detail_diagnostics(run: &AssistantRun, events: &[AssistantRunEvent]) -> Value {
    let provider_usage_events = assistant_run_provider_usage_events(run, events);
    json!({
        "codex_executor": assistant_run_codex_detail_diagnostics(events),
        "provider_usage": {
            "summary": assistant_run_provider_usage_summary(&provider_usage_events),
            "recent_events": assistant_run_recent_provider_usage_events(provider_usage_events, 8),
        },
    })
}

fn assistant_run_codex_detail_diagnostics(events: &[AssistantRunEvent]) -> Value {
    let codex_events = events
        .iter()
        .filter(|event| event.event_name == "assistant_run.codex_executor_diagnostic")
        .collect::<Vec<_>>();
    let codex_event_count = codex_events.len();
    let latest = codex_events.last().copied();
    let host_validation_results = assistant_run_codex_host_validation_results(events, 8);
    let host_validation_summary =
        assistant_run_codex_host_validation_summary(&host_validation_results);
    let shadow_gate = assistant_run_codex_shadow_gate_summary(&codex_events);
    let model_gateway_gate = assistant_run_codex_model_gateway_gate_summary(latest);
    let promotion_gate = assistant_run_codex_promotion_gate_summary_with_model_gateway(
        &shadow_gate,
        &host_validation_summary,
        &model_gateway_gate,
    );
    let latest_summary = latest
        .map(|event| {
            let payload = &event.payload;
            let context_budget = payload.get("context_budget").map(|budget| {
                json!({
                    "estimated_prompt_chars": budget.get("estimated_prompt_chars").cloned().unwrap_or(Value::Null),
                    "max_prompt_chars": budget.get("max_prompt_chars").cloned().unwrap_or(Value::Null),
                    "budget_pressure": budget.get("budget_pressure").cloned().unwrap_or(Value::Null),
                    "item_count": budget
                        .get("items")
                        .and_then(Value::as_array)
                        .map(|items| items.len())
                        .unwrap_or(0),
                })
            });
            let shadow = payload.get("shadow_comparison");
            let shadow_summary = shadow.map(|shadow| {
                json!({
                    "status": shadow
                        .pointer("/comparison/status")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "actionable": shadow
                        .pointer("/comparison/actionable")
                        .cloned()
                        .unwrap_or(Value::Bool(false)),
                    "codex_has_suggestion": shadow
                        .pointer("/comparison/codex_has_suggestion")
                        .cloned()
                        .unwrap_or(Value::Bool(false)),
                    "codex_mutation_allowed": shadow
                        .get("codex_mutation_allowed")
                        .cloned()
                        .unwrap_or(Value::Bool(false)),
                    "static_page_flow_preserved": shadow
                        .get("static_page_flow_preserved")
                        .cloned()
                        .unwrap_or(Value::Bool(true)),
                    "direct_action_types": shadow
                        .pointer("/direct/action_types")
                        .cloned()
                        .unwrap_or_else(|| json!([])),
                    "codex_suggested_action_type": shadow
                        .pointer("/codex/suggested_action_type")
                        .cloned()
                        .unwrap_or(Value::Null),
                    "next_gate": shadow
                        .pointer("/comparison/next_gate")
                        .cloned()
                        .unwrap_or(Value::Null),
                })
            });

            json!({
                "event_id": event.id.to_string(),
                "sequence_no": event.sequence_no,
                "transport": payload.get("transport").cloned().unwrap_or(Value::Null),
                "transport_policy": assistant_run_codex_transport_policy_summary(
                    payload.get("transport_policy"),
                ),
                "status": payload.get("status").cloned().unwrap_or(Value::Null),
                "codex_invoked": payload
                    .get("codex_invoked")
                    .cloned()
                    .unwrap_or(Value::Bool(false)),
                "fallback_to_direct": payload
                    .get("fallback_to_direct")
                    .cloned()
                    .unwrap_or(Value::Bool(true)),
                "planned_action_types": payload
                    .get("planned_action_types")
                    .cloned()
                    .unwrap_or_else(|| json!([])),
                "suggested_action": assistant_run_codex_suggested_action_summary(
                    payload.get("suggested_action"),
                    shadow,
                ),
                "model_gateway": assistant_run_codex_model_gateway_diagnostics_summary(
                    payload.get("model_gateway"),
                ),
                "provider_shim_observability": assistant_run_codex_provider_shim_observability_summary(
                    payload
                        .get("provider_shim_observability")
                        .or_else(|| payload.get("provider_shim"))
                        .or_else(|| payload.pointer("/model_gateway/provider_shim_observability"))
                        .or_else(|| payload.pointer("/model_gateway/provider_shim")),
                ),
                "output_schema": payload
                    .get("output_schema")
                    .cloned()
                    .unwrap_or(Value::Null),
                "host_invocation": payload
                    .get("host_invocation")
                    .map(|host_invocation| {
                        assistant_run_codex_host_invocation_summary(Some(host_invocation))
                    })
                    .unwrap_or(Value::Null),
                "context_budget": context_budget.unwrap_or(Value::Null),
                "supply_quality": assistant_run_codex_supply_quality_diagnostics_summary(
                    payload
                        .get("supply_quality")
                        .or_else(|| payload.pointer("/execution_trail/0/supply_quality")),
                ),
                "shadow_comparison": shadow_summary.unwrap_or(Value::Null),
            })
        })
        .unwrap_or(Value::Null);

    json!({
        "event_count": codex_event_count,
        "latest": latest_summary,
        "recent_shadow_events": assistant_run_codex_recent_shadow_events(&codex_events, 8),
        "shadow_gate": shadow_gate,
        "model_gateway_gate": model_gateway_gate,
        "host_validation_summary": host_validation_summary,
        "host_validation_results": host_validation_results,
        "fixed_tasks": assistant_run_codex_fixed_task_event_summary(events),
        "promotion_gate": promotion_gate,
        "mutation_allowed": false,
        "queue_allowed": false,
        "authority": "direct_until_shadow_gate_passes",
    })
}

#[derive(Debug)]
pub struct ApiError {
    status: StatusCode,
    payload: ApiErrorResponse,
}

impl ApiError {
    fn bad_request(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::BAD_REQUEST,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: None,
            },
        }
    }

    fn bad_request_with_details(code: &str, message: String, details: Value) -> Self {
        Self {
            status: StatusCode::BAD_REQUEST,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: Some(details),
            },
        }
    }

    fn not_found(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::NOT_FOUND,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: None,
            },
        }
    }

    fn unauthorized(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::UNAUTHORIZED,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: None,
            },
        }
    }

    fn forbidden(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::FORBIDDEN,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: None,
            },
        }
    }

    fn too_many_requests(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::TOO_MANY_REQUESTS,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: None,
            },
        }
    }

    fn service_unavailable(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::SERVICE_UNAVAILABLE,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: None,
            },
        }
    }

    fn internal(code: &str, message: String) -> Self {
        Self {
            status: StatusCode::INTERNAL_SERVER_ERROR,
            payload: ApiErrorResponse {
                code: code.to_string(),
                message,
                details: None,
            },
        }
    }

    fn from_storage(error: anyhow::Error) -> Self {
        if let Some(sqlx::Error::Database(db_error)) = error.downcast_ref::<sqlx::Error>() {
            match db_error.code().as_deref() {
                Some("23505") => {
                    return Self {
                        status: StatusCode::CONFLICT,
                        payload: ApiErrorResponse {
                            code: "conflict".to_string(),
                            message: db_error.message().to_string(),
                            details: None,
                        },
                    };
                }
                Some("23503") => {
                    return Self::bad_request(
                        "foreign_key_violation",
                        db_error.message().to_string(),
                    );
                }
                _ => {}
            }
        }

        tracing::error!(error = ?error, "platform-api storage operation failed");
        Self::internal("storage_error", error.to_string())
    }

    fn from_transition(error: workflow_engine::WorkflowTransitionError) -> Self {
        match error {
            workflow_engine::WorkflowTransitionError::UnsupportedSignal => Self::bad_request(
                "unsupported_signal",
                "the requested workflow signal is not supported".to_string(),
            ),
            workflow_engine::WorkflowTransitionError::InvalidTransition(message) => {
                Self::bad_request("invalid_transition", message)
            }
        }
    }
}

impl IntoResponse for ApiError {
    fn into_response(self) -> Response {
        (self.status, Json(self.payload)).into_response()
    }
}

impl std::fmt::Display for ApiError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}: {}", self.payload.code, self.payload.message)
    }
}

impl std::error::Error for ApiError {}

