    async fn create_test_external_assistant_run(
        state: &AppState,
        assistant_request: &CreateAssistantRunRequest,
        evidence_state: Value,
        now: DateTime<Utc>,
    ) -> AssistantRun {
        state
            .storage
            .assistant_runs()
            .create(
                state.tenant_id,
                &NewAssistantRun {
                    user_id: None,
                    local_thread_id: assistant_request.local_thread_id.clone(),
                    user_prompt: assistant_request.prompt.clone(),
                    startup_briefing: assistant_request
                        .startup_briefing
                        .clone()
                        .unwrap_or_else(|| json!({})),
                    selected_scope: assistant_request
                        .selected_scope
                        .clone()
                        .unwrap_or_else(|| json!({})),
                    scope_candidates: json!(assistant_request.scope_candidates.clone()),
                    context_policy: assistant_request
                        .context_policy_hint
                        .clone()
                        .unwrap_or_else(|| json!({})),
                    evidence_state,
                    service_lane: "external_channel".to_string(),
                    execution_trail: json!([]),
                    output_artifacts: json!([]),
                    runtime_manifest: json!({}),
                    created_at: now,
                },
            )
            .await
            .expect("assistant run should be created")
    }

    fn wecom_test_encoding_aes_key() -> String {
        use base64::{engine::general_purpose, Engine as _};

        let key: Vec<u8> = (1u8..=32).collect();
        general_purpose::STANDARD
            .encode(key)
            .trim_end_matches('=')
            .to_string()
    }

    fn encrypt_feishu_test_payload(payload: &Value, encrypt_key: &str) -> String {
        use aes::Aes256;
        use base64::{engine::general_purpose, Engine as _};
        use cbc::cipher::{block_padding::NoPadding, BlockModeEncrypt, KeyIvInit};
        use sha2::{Digest, Sha256};

        let key = Sha256::digest(encrypt_key.as_bytes());
        let iv = [0x24u8; 16];
        let mut plaintext = payload.to_string().into_bytes();
        let padding = 16 - (plaintext.len() % 16);
        let padding = if padding == 0 { 16 } else { padding };
        plaintext.extend(std::iter::repeat_n(padding as u8, padding));
        let plaintext_len = plaintext.len();
        let encrypted = cbc::Encryptor::<Aes256>::new_from_slices(&key, &iv)
            .expect("test AES encryptor should initialize")
            .encrypt_padded::<NoPadding>(&mut plaintext, plaintext_len)
            .expect("test plaintext is block aligned");
        let mut envelope = iv.to_vec();
        envelope.extend_from_slice(encrypted);
        general_purpose::STANDARD.encode(envelope)
    }

    fn encrypt_wecom_test_xml(xml: &str, receive_id: &str, encoding_aes_key: &str) -> String {
        use aes::Aes256;
        use base64::{engine::general_purpose, Engine as _};
        use cbc::cipher::{block_padding::NoPadding, BlockModeEncrypt, KeyIvInit};

        let key = general_purpose::STANDARD
            .decode(format!("{encoding_aes_key}="))
            .expect("test EncodingAESKey should decode");
        let mut plaintext = vec![0x42; 16];
        plaintext.extend_from_slice(&(xml.len() as u32).to_be_bytes());
        plaintext.extend_from_slice(xml.as_bytes());
        plaintext.extend_from_slice(receive_id.as_bytes());
        let padding = 32 - (plaintext.len() % 32);
        let padding = if padding == 0 { 32 } else { padding };
        plaintext.extend(std::iter::repeat_n(padding as u8, padding));
        let plaintext_len = plaintext.len();
        let encrypted = cbc::Encryptor::<Aes256>::new_from_slices(&key, &key[..16])
            .expect("test AES encryptor should initialize")
            .encrypt_padded::<NoPadding>(&mut plaintext, plaintext_len)
            .expect("test plaintext is block aligned");
        general_purpose::STANDARD.encode(encrypted)
    }

