    #[test]
    fn static_page_template_match_tokens_allow_dataset_overlap() {
        let baseline_scope = json!({
            "dataset_external_ids": ["dataset-a", "dataset-b"],
            "database_source_id": "db-main"
        });
        let request_scope = json!({
            "requested_dataset_external_ids": ["dataset-b", "dataset-c"]
        });
        let unrelated_scope = json!({
            "dataset_external_ids": ["dataset-x"],
            "database_source_id": "db-other"
        });

        let baseline_tokens = static_page_template_match_tokens(&baseline_scope, &json!({}));
        let request_tokens = static_page_template_match_tokens(&request_scope, &json!({}));
        let unrelated_tokens = static_page_template_match_tokens(&unrelated_scope, &json!({}));

        assert!(static_page_template_tokens_intersect(
            &baseline_tokens,
            &request_tokens
        ));
        assert!(!static_page_template_tokens_intersect(
            &baseline_tokens,
            &unrelated_tokens
        ));
    }

    #[test]
    fn static_page_template_match_allows_compatible_business_default_prompt_for_overlap() {
        let selected_scope = json!({
            "requested_dataset_external_ids": ["dataset-b"]
        });
        let baseline_scope = json!({
            "dataset_external_ids": ["dataset-a", "dataset-b"]
        });
        let request_source_refs = json!({
            "answer_policy": {
                "default_prompt": "请面向业务用户，按经营月报口径输出。"
            }
        });
        let same_prompt_baseline_refs = json!({
            "answer_policy": {
                "default_prompt": " 请面向业务用户，按经营月报口径输出。 "
            }
        });
        let compatible_prompt_baseline_refs = json!({
            "answer_policy": {
                "default_prompt": "请面向业务用户，优先基于本轮文档和数据源回答。"
            }
        });
        let different_prompt_baseline_refs = json!({
            "answer_policy": {
                "default_prompt": "请面向业务用户，按招聘简历对比口径输出。"
            }
        });

        let request_tokens = static_page_template_match_tokens(&selected_scope, &json!({}));
        let baseline_tokens = static_page_template_match_tokens(&baseline_scope, &json!({}));

        assert!(static_page_template_tokens_intersect(
            &request_tokens,
            &baseline_tokens
        ));
        assert!(static_page_default_prompt_tokens_match(
            &selected_scope,
            &request_source_refs,
            &baseline_scope,
            &same_prompt_baseline_refs,
        ));
        assert!(static_page_default_prompt_tokens_match(
            &selected_scope,
            &json!({
                "answer_policy": {
                    "default_prompt": "请面向业务用户，优先基于本轮文档回答。"
                }
            }),
            &baseline_scope,
            &compatible_prompt_baseline_refs,
        ));
        assert!(!static_page_default_prompt_tokens_match(
            &selected_scope,
            &request_source_refs,
            &baseline_scope,
            &different_prompt_baseline_refs,
        ));
        assert!(!static_page_default_prompt_tokens_match(
            &selected_scope,
            &request_source_refs,
            &baseline_scope,
            &json!({}),
        ));
    }

    #[test]
    fn static_page_template_overlap_summary_reports_default_prompt_mismatch() {
        let selected_scope = json!({
            "requested_dataset_external_ids": ["dataset-b"]
        });
        let source_refs = json!({
            "answer_policy": {
                "default_prompt": "请面向业务用户，按经营月报口径输出。"
            }
        });
        let outcome = StaticPageTemplateOverlapSearchOutcome {
            draft: None,
            selected_score: None,
            selected_features: Vec::new(),
            current_token_count: 1,
            accepted_baseline_count: 2,
            visible_published_baseline_count: 2,
            scope_intersection_count: 2,
            template_intent_match_count: 2,
            template_intent_mismatch_count: 0,
            default_prompt_match_count: 0,
            default_prompt_mismatch_count: 2,
        };

        let summary = outcome.summary(&selected_scope, &source_refs);

        assert_eq!(summary["status"], json!("not_matched"));
        assert_eq!(summary["reason"], json!("default_prompt_mismatch"));
        assert_eq!(
            summary["default_prompt_match_policy"],
            json!("same_or_compatible_business_default_prompt")
        );
        assert_eq!(summary["candidate_default_prompt_present"], json!(true));
        assert_eq!(summary["default_prompt_mismatch_count"], json!(2));
    }

