    #[tokio::test]
    async fn external_channel_database_scope_adds_allowed_source_default_dataset_for_report() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping external database scope enrichment test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;
        let tenant = storage
            .ensure_tenant(
                &format!("external-db-scope-test-{}", Uuid::new_v4()),
                "External DB Scope Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        let dataset = state
            .storage
            .datasets()
            .create(
                state.tenant_id,
                NewDataset {
                    key: format!("external-db-scope-dataset-{}", Uuid::new_v4()),
                    title: "新百经营分析数据库".to_string(),
                    description: None,
                    owner_user_id: None,
                },
            )
            .await
            .expect("dataset should be created");
        let _mysql_url = TestEnvVarRestore::set(
            "THIRD_PARTY_HY_SQL_DATABASE_URL",
            "mysql://readonly:redacted@127.0.0.1:3306/hy_sql",
        );
        sqlx::query(
            r#"
            insert into external_source_connections (
                id,
                tenant_id,
                connector_kind,
                source_key,
                display_name,
                base_url_redacted,
                config_redacted,
                sync_mode,
                permission_mode,
                status,
                health_status
            )
            values ($1, $2, 'mysql', $1, 'HY SQL', 'mysql://127.0.0.1/[redacted]', $3, 'manual', 'dataset_acl', 'enabled', 'healthy')
            "#,
        )
        .bind("hy-sql-report")
        .bind(state.tenant_id.0)
        .bind(json!({
            "database_source": {
                "connection_env": "THIRD_PARTY_HY_SQL_DATABASE_URL",
                "database": "hy_sql",
                "default_dataset_id": dataset.id.to_string(),
                "tables": [traffic_area_mapping_for_test()]
            }
        }))
        .execute(state.storage.pool())
        .await
        .expect("database source connection should be inserted");

        let connection = ExternalChannelConnectionSummary {
            platform: ExternalChannelPlatformView::GenericChat,
            status: "enabled".to_string(),
            config_redacted: json!({
                "default_source_id": "third-party-source-main",
                "allowed_database_source_ids": ["hy-sql-report"]
            }),
        };
        let mut message = sample_external_bot_message();
        message.render_mode = Some("normal".to_string());
        message.output_format = Some("rich_text".to_string());
        let mut selected_scope = json!({"type": "external_channel"});

        enrich_external_channel_database_source_scope(
            &state,
            &connection,
            &message,
            "生成一张经营分析可视化报表页，给可访问链接",
            &mut selected_scope,
        )
        .await
        .expect("database scope should enrich");

        assert_eq!(
            selected_scope["database_source_ids"],
            json!(["hy-sql-report"])
        );
        assert_eq!(selected_scope["datasets"][0]["id"], json!(dataset.id));
        assert_eq!(
            selected_scope["database_source_scope"]["default_dataset_bindings"][0]["source_id"],
            json!("hy-sql-report")
        );

        let mut large_analysis_scope = json!({"type": "external_channel"});
        enrich_external_channel_database_source_scope(
            &state,
            &connection,
            &message,
            "帮我对门店销售数据做一次全面数据分析，输出详细结论和图表",
            &mut large_analysis_scope,
        )
        .await
        .expect("large data analysis should enrich database scope");

        assert_eq!(
            large_analysis_scope["database_source_ids"],
            json!(["hy-sql-report"])
        );
        assert_eq!(large_analysis_scope["datasets"][0]["id"], json!(dataset.id));

        let mut business_work_analysis_scope = json!({"type": "external_channel"});
        enrich_external_channel_database_source_scope(
            &state,
            &connection,
            &message,
            "做一下新百的经营工作分析",
            &mut business_work_analysis_scope,
        )
        .await
        .expect("business work analysis should enrich database scope");

        assert_eq!(
            business_work_analysis_scope["database_source_ids"],
            json!(["hy-sql-report"])
        );
        assert_eq!(
            business_work_analysis_scope["datasets"][0]["id"],
            json!(dataset.id)
        );
    }

    #[test]
    fn external_channel_static_page_report_scope_uses_database_default_dataset_not_chat_scope() {
        let chat_dataset_id = DatasetId::new();
        let report_dataset_id = DatasetId::new();
        let document_id = DocumentId::new();
        let selected_scope = json!({
            "type": "external_channel",
            "dataset_external_ids": ["qa-temporary-group"],
            "requested_dataset_external_ids": ["qa-temporary-group"],
            "datasets": [{"type": "dataset", "id": chat_dataset_id}],
            "documents": [{"type": "document", "id": document_id, "document_external_id": "qa-doc-1"}],
            "database_source_ids": ["hy-sql-report"],
            "database_source_scope": {
                "source": "external_channel_allowed_database_sources",
                "source_ids": ["hy-sql-report"],
                "requested_business_datasource_ids": [],
                "default_dataset_bindings": [{
                    "source_id": "hy-sql-report",
                    "dataset_id": report_dataset_id,
                }],
                "policy": "connection_allowed_database_sources_for_report_workflow",
            },
        });

        let report_scope = external_channel_static_page_report_scope(&selected_scope);

        assert_eq!(report_scope["mode"], json!("report_fixed_dataset"));
        assert_eq!(
            report_scope["database_report_scope_policy"],
            json!("fixed_dataset_independent_of_chat_selection")
        );
        assert_eq!(
            selected_dataset_ids_from_scope(&report_scope),
            vec![report_dataset_id]
        );
        assert!(report_scope.get("dataset_external_ids").is_none());
        assert!(report_scope.get("requested_dataset_external_ids").is_none());
        assert!(report_scope.get("documents").is_none());

        let key = static_page_dataset_artifact_key(
            &report_scope,
            &json!({"database_source_ids": ["hy-sql-report"]}),
            "template:data-report",
            Some("generic-chat-main"),
        )
        .expect("report scope should produce a stable artifact key");
        assert!(key.contains(&format!("dataset_id:{report_dataset_id}")));
        assert!(!key.contains(&format!("dataset_id:{chat_dataset_id}")));
        assert!(!key.contains("qa-temporary-group"));
        assert!(!key.contains("qa-doc-1"));

        let connection = ExternalChannelConnectionSummary {
            platform: ExternalChannelPlatformView::GenericChat,
            status: "enabled".to_string(),
            config_redacted: json!({
                "default_source_id": "third-party-document-source",
                "allowed_database_source_ids": ["hy-sql-report"]
            }),
        };
        assert_eq!(
            collect_external_static_page_database_source_ids(
                &connection,
                &report_scope,
                &json!({"status": "empty"})
            ),
            vec!["hy-sql-report".to_string()]
        );
    }

