    #[test]
    fn external_image_structured_extract_retry_detects_missing_visible_rows() {
        let incomplete = json!({
            "visible_row_count": 3,
            "records": [
                {
                    "row_index": 1,
                    "order_no": "A1778730534",
                    "pay_amount_raw": "$700",
                    "status_label": "成功"
                }
            ]
        });
        assert!(external_image_structured_extract_payload_needs_retry(
            &incomplete
        ));

        let complete = json!({
            "visible_row_count": 2,
            "records": [
                {
                    "row_index": 1,
                    "order_no": "A1778730534",
                    "pay_amount_raw": "$700",
                    "status_label": "成功"
                },
                {
                    "row_index": 2,
                    "order_no": "A1778729946",
                    "pay_amount_raw": "$700",
                    "status_label": "处理中"
                }
            ]
        });
        assert!(!external_image_structured_extract_payload_needs_retry(
            &complete
        ));
    }

