    #[test]
    fn assistant_run_codex_external_channel_scope_exposes_external_action_contracts() {
        let selected_scope = json!({
            "type": "external_channel",
            "channel_connection_id": "channel-third-party-1",
            "platform": "third_party",
            "message_external_id": "msg-1"
        });

        let actions = assistant_run_codex_action_contracts(&selected_scope);

        assert!(actions.iter().any(|action| {
            action.action_type == "external_artifact.status" && !action.mutates_state
        }));
        assert!(actions.iter().any(|action| {
            action.action_type == "external_artifact.publish" && action.mutates_state
        }));
        let revoke = actions
            .iter()
            .find(|action| action.action_type == "external_artifact.revoke")
            .expect("revoke action should be available for external channel");
        let business = actions
            .iter()
            .find(|action| action.action_type == "external_business_action.invoke")
            .expect("business action should be available for external channel");

        assert_eq!(
            revoke.input_schema["properties"]["requires_confirmation"]["const"],
            json!(true)
        );
        assert_eq!(
            revoke.input_schema["properties"]["risk_level"]["enum"],
            json!([
                "read_only",
                "low_risk_write",
                "high_risk_write",
                "cross_system"
            ])
        );
        assert_eq!(
            business.input_schema["required"],
            json!([
                "connection_id",
                "target_system",
                "business_action_type",
                "risk_level",
                "requires_confirmation",
                "arguments_redacted"
            ])
        );
    }

    #[test]
    fn assistant_run_codex_package_trims_oversized_tool_outputs_but_preserves_refs() {
        let long_stdout = format!("stdout-start-{}-stdout-end", "x".repeat(40_000));
        let evidence_state = json!({
            "status": "supplied",
            "supplied_items": [{
                "type": "retrieval_evidence",
                "summary": "关键证据不能被工具输出预算裁掉",
                "retrieval_evidence_id": "evidence-keep"
            }],
            "tool_outputs": [{
                "tool_call_id": "tool-1",
                "evidence_ref": "evidence-keep",
                "timestamp_ms": 12345,
                "stdout": long_stdout,
                "error_code": "E_TIMEOUT"
            }]
        });

        let package = build_assistant_run_codex_context_package(
            AssistantRunId::new(),
            None,
            "检查工具输出预算",
            &[],
            &json!({}),
            &json!({"intent": "ordinary_chat"}),
            &[],
            &evidence_state,
            None,
            &json!({"lane": "codex_conversation"}),
            AssistantRunExecutorTransportView::CodexPlanOnly,
        );

        let tool_output = &package.evidence_state["tool_outputs"][0];
        let stdout = tool_output["stdout"]
            .as_str()
            .expect("trimmed stdout should remain a string");
        let serialized = package.evidence_state.to_string();

        assert!(stdout.contains("stdout-start"));
        assert!(stdout.contains("stdout-end"));
        assert!(stdout.contains("[codex-trimmed"));
        assert!(!stdout.contains(&"x".repeat(35_000)));
        assert_eq!(tool_output["evidence_ref"], json!("evidence-keep"));
        assert_eq!(tool_output["timestamp_ms"], json!(12345));
        assert_eq!(tool_output["error_code"], json!("E_TIMEOUT"));
        assert_eq!(tool_output["codex_trimmed_fields"], json!(["stdout"]));
        assert_eq!(
            package.evidence_state["codex_tool_output_budget"]["trimmed_output_count"],
            json!(1)
        );
        assert_eq!(package.context_budget.trimmed_item_count, 1);
        assert!(serialized.contains("关键证据不能被工具输出预算裁掉"));
        assert!(package.tool_output_policy.preserve_evidence_refs);
    }

    #[test]
    fn assistant_run_codex_diagnostic_payload_preserves_direct_fallback() {
        let package = build_assistant_run_codex_context_package(
            AssistantRunId::new(),
            Some("browser-thread-1"),
            "生成一个企业经营看板",
            &[],
            &json!({}),
            &json!({"mode": "ordinary_chat"}),
            &[],
            &json!({"status": "not_requested", "supplied_items": []}),
            None,
            &json!({"lane": "codex_conversation"}),
            AssistantRunExecutorTransportView::CodexDryRun,
        );

        let output = execute_codex_conversation_plan(&package);
        let shadow = assistant_run_codex_shadow_comparison(
            &output,
            false,
            &json!({
                "mode": "provider",
                "provider": "placeholder",
                "model": "assistant-chat-placeholder"
            }),
            &[json!({
                "type": "assistant_message",
                "content": "direct answer remains authoritative"
            })],
            &[],
            &json!({"mode": "ordinary_chat"}),
            None,
        );
        let unsafe_transport_policy = json!({
            "requested_transport": "codex_exec_schema",
            "effective_transport": "codex_plan_only",
            "real_transport_requested": true,
            "real_transport_feature_gate_enabled": false,
            "downgraded": true,
            "downgrade_reason": "real_transport_feature_gate_disabled",
            "direct_execution_authoritative": true,
            "codex_mutation_allowed": false,
            "queue_allowed": false,
            "manual_feature_gate_required_for_real_transport": true,
            "host_validation_required_for_real_transport": true,
            "next_step": "keep_codex_in_shadow_plan_only_until_promotion_gate_review",
            "debug_token": "sk-policy-payload-should-not-leak",
            "env_key": "ASSISTANT_RUN_CODEX_REAL_TRANSPORT_FEATURE_GATE"
        });
        let payload = assistant_run_codex_event_payload(
            &output,
            Some(&shadow),
            Some(&unsafe_transport_policy),
        );
        let trail = assistant_run_codex_execution_trail_entries(
            &output,
            Utc::now(),
            Some(&shadow),
            Some(&unsafe_transport_policy),
        );
        let payload_serialized = payload.to_string();
        let trail_serialized = serde_json::to_string(&trail).expect("trail serializes");

        assert_eq!(payload["transport"], json!("codex_dry_run"));
        assert_eq!(
            payload["transport_policy"]["requested_transport"],
            json!("codex_exec_schema")
        );
        assert_eq!(
            payload["transport_policy"]["effective_transport"],
            json!("codex_plan_only")
        );
        assert_eq!(payload["transport_policy"]["downgraded"], json!(true));
        assert_eq!(payload["transport_policy"]["debug_token"], Value::Null);
        assert_eq!(payload["transport_policy"]["env_key"], Value::Null);
        assert_eq!(payload["status"], json!("shadow_dry_run"));
        assert_eq!(payload["codex_invoked"], json!(false));
        assert_eq!(payload["fallback_to_direct"], json!(true));
        assert_eq!(payload["suggested_action"], Value::Null);
        assert_eq!(
            payload["output_schema"]["title"],
            json!("V3CodexPlanOnlyActionSuggestion")
        );
        assert_eq!(payload["host_invocation"], Value::Null);
        assert_eq!(
            payload["model_gateway"]["lane"],
            json!("codex_conversation")
        );
        assert_eq!(
            payload["shadow_comparison"]["authoritative_executor"],
            json!("direct")
        );
        assert_eq!(
            payload["shadow_comparison"]["codex_mutation_allowed"],
            json!(false)
        );
        assert_eq!(
            payload["shadow_comparison"]["comparison"]["actionable"],
            json!(false)
        );
        assert_eq!(
            payload["shadow_comparison"]["comparison"]["status"],
            json!("no_codex_suggestion")
        );
        assert_eq!(trail[0]["label"], json!("Codex 执行器诊断"));
        assert_eq!(
            trail[0]["transport_policy"]["requested_transport"],
            json!("codex_exec_schema")
        );
        assert_eq!(trail[0]["transport_policy"]["debug_token"], Value::Null);
        assert_eq!(trail[0]["fallback_to_direct"], json!(true));
        assert_eq!(
            trail[0]["shadow_comparison"]["direct_state_authoritative"],
            json!(true)
        );
        assert!(!payload_serialized.contains("sk-policy-payload-should-not-leak"));
        assert!(!payload_serialized.contains("ASSISTANT_RUN_CODEX_REAL_TRANSPORT_FEATURE_GATE"));
        assert!(!trail_serialized.contains("sk-policy-payload-should-not-leak"));
        assert!(!trail_serialized.contains("ASSISTANT_RUN_CODEX_REAL_TRANSPORT_FEATURE_GATE"));

        let mut suggested_output = output.clone();
        suggested_output.suggested_action = Some(json!({
            "action_type": "create_static_page_draft",
            "reason": "shadow-only static page planning candidate",
            "arguments": {
                "prompt": "codex suggested action payload raw prompt should not leak",
                "provider_key": "sk-suggested-action-should-not-leak"
            }
        }));
        suggested_output.execution_trail = vec![json!({
            "kind": "codex_executor.plan_only",
            "suggested_action": suggested_output.suggested_action.clone(),
            "host_invocation": {
                "kind": "not_applicable"
            }
        })];
        let matched_shadow = assistant_run_codex_shadow_comparison(
            &suggested_output,
            true,
            &json!({
                "mode": "provider",
                "provider": "placeholder",
                "model": "assistant-react-json-placeholder"
            }),
            &[json!({
                "type": "static_page_draft",
                "backendDraftId": "draft-1"
            })],
            &[],
            &json!({"intent": "static_page"}),
            None,
        );
        assert_eq!(
            matched_shadow["direct"]["action_types"],
            json!(["create_static_page_draft"])
        );
        assert_eq!(matched_shadow["comparison"]["status"], json!("matched"));
        assert_eq!(
            matched_shadow["comparison"]["next_gate"],
            json!("enable Codex mutation only after repeated matched shadow runs")
        );
        let matched_payload =
            assistant_run_codex_event_payload(&suggested_output, Some(&matched_shadow), None);
        let matched_trail = assistant_run_codex_execution_trail_entries(
            &suggested_output,
            Utc::now(),
            Some(&matched_shadow),
            None,
        );
        let matched_payload_serialized = matched_payload.to_string();
        let matched_trail_serialized =
            serde_json::to_string(&matched_trail).expect("matched trail serializes");
        assert_eq!(
            matched_payload["suggested_action"]["action_type"],
            json!("create_static_page_draft")
        );
        assert_eq!(
            matched_payload["suggested_action"]["has_arguments"],
            json!(true)
        );
        assert_eq!(
            matched_payload["suggested_action"]["arguments"],
            Value::Null
        );
        assert_eq!(
            matched_payload["execution_trail"][0]["suggested_action"]["has_arguments"],
            json!(true)
        );
        assert_eq!(
            matched_payload["execution_trail"][0]["suggested_action"]["arguments"],
            Value::Null
        );
        assert_eq!(
            matched_trail[0]["suggested_action"]["has_arguments"],
            json!(true)
        );
        assert!(!matched_payload_serialized.contains("codex suggested action payload raw prompt"));
        assert!(!matched_payload_serialized.contains("sk-suggested-action-should-not-leak"));
        assert!(!matched_trail_serialized.contains("codex suggested action payload raw prompt"));
        assert!(!matched_trail_serialized.contains("sk-suggested-action-should-not-leak"));
        assert_eq!(
            matched_payload["shadow_comparison"]["codex"]["model_gateway"]["lane"],
            json!("codex_conversation")
        );
        assert_eq!(
            matched_payload["output_schema"]["properties"]["suggested_action"]["properties"]
                ["action_type"]["enum"]
                .as_array()
                .expect("output schema action enum should exist")
                .iter()
                .any(|value| value.as_str() == Some("create_static_page_draft")),
            true
        );

        suggested_output.suggested_action = Some(json!({
            "action_type": "render_static_page"
        }));
        let diverged_shadow = assistant_run_codex_shadow_comparison(
            &suggested_output,
            true,
            &json!({"mode": "provider"}),
            &[json!({"type": "static_page_draft"})],
            &[],
            &json!({"intent": "static_page"}),
            None,
        );
        assert_eq!(diverged_shadow["comparison"]["status"], json!("diverged"));
        assert_eq!(diverged_shadow["codex_mutation_allowed"], json!(false));

        suggested_output.suggested_action = Some(json!({
            "action_type": "unsafe_os_command"
        }));
        let invalid_shadow = assistant_run_codex_shadow_comparison(
            &suggested_output,
            true,
            &json!({"mode": "provider"}),
            &[json!({"type": "static_page_draft"})],
            &[],
            &json!({"intent": "static_page"}),
            None,
        );
        assert_eq!(
            invalid_shadow["comparison"]["status"],
            json!("invalid_suggestion")
        );
        assert_eq!(
            invalid_shadow["codex"]["suggested_action_allowed"],
            json!(false)
        );
        assert_eq!(invalid_shadow["comparison"]["actionable"], json!(false));
    }

