    #[test]
    fn external_channel_static_page_publish_completed_event_becomes_artifact_link_reply() {
        let payload = json!({
            "conversation_external_id": "chat-static-page",
            "draft_id": StaticPageDraftId::new().to_string(),
            "image_job_id": StaticPageImageJobId::new().to_string(),
            "codex_host_workflow_execution_id": WorkflowExecutionId::new().to_string(),
            "public_url": "https://v3.elepcloud.com/generated-artifacts/database-static-pages/final/index.html",
            "data_url": "https://v3.elepcloud.com/generated-artifacts/database-static-pages/final/data.json",
            "data_snapshot_url": "https://v3.elepcloud.com/generated-artifacts/database-static-pages/final/data-snapshot.json",
            "dynamic_page_contract": {
                "version": 1,
                "data_file": "data.json",
                "source_snapshot_file": "data-snapshot.json"
            },
            "validation_summary": {
                "latest_snapshot": "2026-05-10",
                "source_row_count": 862,
                "detail_row_count": 40,
                "unit_policy": "validate_raw_value_then_choose_wan_or_yi"
            },
            "template_adaptation": {
                "userIntent": "我想看看五月份最新的取高机会",
                "focus": [
                    {"label": "销售/租金/取高口径"},
                    {"label": "门店/区域维度"}
                ]
            },
            "source_refs": {
                "selected_scope": {"must": "not leak"},
                "template_reference_id": "generated-static-page:template-002",
                "template_reference": {
                    "templateId": "generated-static-page:template-002",
                    "label": "新百经营分析默认模板"
                },
                "relaxed_template_match": {
                    "policy": "dataset_overlap",
                    "baseline_draft_id": "template-002"
                },
                "artifact_stability": {
                    "style_reuse_policy": "reuse_style_unless_explicit_redesign",
                    "data_refresh_policy": "refresh_data_files_from_dataset_sources",
                    "default_template_scope": "dataset_combination"
                }
            }
        });

        let focused_url = static_page_public_url_with_focus_label(
            "https://v3.elepcloud.com/generated-artifacts/database-static-pages/final/index.html",
            "取高机会",
        );
        let reply =
            external_channel_static_page_publish_completed_reply_from_event_payload(&payload)
                .expect("reply");

        assert_eq!(reply.reply_type, ExternalBotReplyTypeView::ArtifactLink);
        assert_eq!(
            reply.target_conversation_external_id,
            "chat-static-page".to_string()
        );
        assert_eq!(reply.task_status.as_deref(), Some("static_page_published"));
        assert_eq!(reply.artifact_links, vec![focused_url.clone()]);
        let text = reply.text.as_deref().unwrap_or_default();
        assert!(text.contains(&format!("页面链接：[点击查看报表]({focused_url})")));
        assert!(!text.contains("页面地址:"));
        assert_eq!(text.matches(&focused_url).count(), 1);
        assert!(text.contains("系统识别到本轮关注焦点：取高机会"));
        assert!(text.contains("报表会优先呈现：销售/租金/取高口径、门店/区域维度"));
        let card = reply.card.as_ref().expect("completed reply has card");
        assert_eq!(card["title"], json!(XINBAI_PUBLISHED_REPORT_TITLE));
        assert_eq!(card["report_title"], json!(XINBAI_PUBLISHED_REPORT_TITLE));
        assert_eq!(card["public_url"], json!(focused_url));
        assert_eq!(card["generated_artifact_url"], json!(focused_url));
        assert_eq!(card["download_url"], json!(focused_url));
        assert_eq!(card["html_download_url"], json!(focused_url));
        assert_eq!(card["artifact_links"], json!([focused_url]));
        assert_eq!(card["data_url"], json!(payload["data_url"]));
        assert_eq!(
            card["table_data_url"],
            json!("https://v3.elepcloud.com/generated-artifacts/database-static-pages/final/table-data.csv")
        );
        assert_eq!(
            card["ppt_download_url"],
            json!("https://v3.elepcloud.com/generated-artifacts/database-static-pages/final/report.ppt")
        );
        assert_eq!(
            card["markdown_download_url"],
            json!("https://v3.elepcloud.com/generated-artifacts/database-static-pages/final/report.md")
        );
        assert_eq!(card["download_exports"][0]["label"], json!("表格数据"));
        assert_eq!(
            card["data_snapshot_url"],
            json!(payload["data_snapshot_url"])
        );
        assert_eq!(
            card["dynamic_page_contract"]["data_file"],
            json!("data.json")
        );
        assert_eq!(
            card["template_reference_id"],
            json!("generated-static-page:template-002")
        );
        assert_eq!(card["template_match_policy"], json!("dataset_overlap"));
        assert_eq!(
            card["style_reuse_policy"],
            json!("reuse_style_unless_explicit_redesign")
        );
        assert_eq!(
            card["data_refresh_policy"],
            json!("refresh_data_files_from_dataset_sources")
        );
        let serialized = serde_json::to_string(&reply).expect("reply serializes");
        assert!(!serialized.contains("selected_scope"));
    }

    #[test]
    fn external_channel_static_page_stable_reuse_reply_surfaces_template_fields() {
        let public_url =
            "https://v3.elepcloud.com/generated-artifacts/database-static-pages/reused/index.html?focus=%E9%A3%8E%E9%99%A9%E5%BA%97%E9%93%BA";
        let payload = json!({
            "status": "static_page_stable_artifact_reused",
            "public_url": public_url,
            "draft_id": StaticPageDraftId::new().to_string(),
            "dataset_artifact_key": "dataset-combination:xinbai:template",
            "template_reference_id": "generated-static-page:template-003",
            "template_reference": {
                "templateId": "generated-static-page:template-003",
                "label": "新百经营分析默认模板"
            },
            "template_match_policy": "exact_dataset_artifact_key",
            "style_reuse_policy": "reuse_style_unless_explicit_redesign",
            "data_refresh_policy": "refresh_data_files_from_dataset_sources",
            "default_template_scope": "dataset_combination",
            "template_adaptation": {
                "focus": [
                    {"label": "低销售风险店铺"},
                    {"label": "销售预警分层"}
                ]
            }
        });

        let reply =
            external_channel_static_page_stable_artifact_reused_reply("chat-static-page", &payload);

        assert_eq!(reply.reply_type, ExternalBotReplyTypeView::ArtifactLink);
        assert_eq!(reply.task_status.as_deref(), Some("static_page_published"));
        assert_eq!(reply.artifact_links, vec![public_url.to_string()]);
        let text = reply.text.as_deref().unwrap_or_default();
        assert!(text.contains("已依据客户需求生成可访问的报表页面"));
        assert!(text.contains("页面链接：[点击查看报表](https://v3.elepcloud.com/generated-artifacts/database-static-pages/reused/index.html?focus=%E9%A3%8E%E9%99%A9%E5%BA%97%E9%93%BA)"));
        assert_eq!(text.matches(public_url).count(), 1);
        assert!(text.contains("系统识别到本轮关注焦点：风险店铺"));
        assert!(text.contains("报表会优先呈现：低销售风险店铺、销售预警分层"));
        assert!(!text.contains("页面地址:"));
        assert!(!text.contains("复用"));
        let card = reply.card.as_ref().expect("reuse card");
        assert_eq!(card["status"], json!("static_page_published"));
        assert_eq!(card["title"], json!(XINBAI_PUBLISHED_REPORT_TITLE));
        assert_eq!(card["report_title"], json!(XINBAI_PUBLISHED_REPORT_TITLE));
        assert_eq!(card["public_url"], json!(public_url));
        assert_eq!(card["generated_artifact_url"], json!(public_url));
        assert_eq!(card["download_url"], json!(public_url));
        assert_eq!(card["html_download_url"], json!(public_url));
        assert_eq!(card["artifact_links"], json!([public_url]));
        assert_eq!(
            card["text_download_url"],
            json!("https://v3.elepcloud.com/generated-artifacts/database-static-pages/reused/report.md")
        );
        assert_eq!(
            card["download_exports"][2]["label"],
            json!("文本下载（MD）")
        );
        assert_eq!(
            card["template_reference_id"],
            json!("generated-static-page:template-003")
        );
        assert_eq!(
            card["template_match_policy"],
            json!("exact_dataset_artifact_key")
        );
        assert_eq!(card["default_template_scope"], json!("dataset_combination"));
    }

