    #[test]
    fn assistant_run_codex_shadow_gate_tracks_stability_and_blocks_invalid() {
        let tenant_id = TenantId::new();
        let run_id = AssistantRunId::new();
        let now = Utc::now();
        let matched_event = |sequence_no| AssistantRunEvent {
            id: AssistantRunEventId::new(),
            tenant_id,
            run_id,
            sequence_no,
            event_name: "assistant_run.codex_executor_diagnostic".to_string(),
            payload: json!({
                "suggested_action": {
                    "action_type": "create_static_page_draft",
                    "mutation_allowed": false
                },
                "shadow_comparison": {
                    "codex_mutation_allowed": false,
                    "comparison": {
                        "status": "matched",
                        "codex_has_suggestion": true
                    }
                }
            }),
            created_at: now,
        };
        let stable_events = vec![matched_event(1), matched_event(2), matched_event(3)];
        let stable_refs = stable_events.iter().collect::<Vec<_>>();
        let stable_gate = assistant_run_codex_shadow_gate_summary(&stable_refs);

        assert_eq!(stable_gate["status"], json!("eligible_for_host_validation"));
        assert_eq!(stable_gate["matched_count"], json!(3));
        assert_eq!(stable_gate["matched_streak_count"], json!(3));
        assert_eq!(stable_gate["last_blocking_event"], Value::Null);
        assert_eq!(stable_gate["host_validation_allowed"], json!(true));
        assert_eq!(
            stable_gate["host_validation"]["ready_for_jump_host_validation"],
            json!(true)
        );
        assert_eq!(
            stable_gate["host_validation"]["local_execution_allowed"],
            json!(false)
        );
        assert_eq!(
            stable_gate["host_validation"]["required_host_kinds"],
            json!(["windows_jump", "mac_host"])
        );
        assert_eq!(
            stable_gate["host_validation"]["requires_task_workspace_root"],
            json!(true)
        );
        let validated_host_summary = assistant_run_codex_host_validation_summary(&[json!({
            "mode": "codex_exec",
            "status": "completed",
            "host_kind": "windows_jump",
            "host_kind_allowed": true,
            "host_validation_completed": true,
            "codex_invoked": true,
            "profile": {"kind": "codex-native", "model": "codex-host"},
            "command_plan": {"workspace_configured": true, "prompt_redacted": true},
            "process": {"exit_code": 0},
            "task_memory_isolated": true,
            "task_memory_space_configured": true,
            "html_artifact_count": 1,
        })]);
        let promotion_gate = assistant_run_codex_promotion_gate_summary_with_model_gateway(
            &stable_gate,
            &validated_host_summary,
            &json!({"status": "ready", "ready_for_promotion_review": true}),
        );
        assert_eq!(
            promotion_gate["status"],
            json!("eligible_for_feature_gate_review")
        );
        assert_eq!(
            promotion_gate["eligible_for_feature_gate_review"],
            json!(true)
        );
        assert_eq!(
            promotion_gate["readiness_checks"]["shadow_gate"]["ready"],
            json!(true)
        );
        assert_eq!(
            promotion_gate["readiness_checks"]["host_validation"]["ready"],
            json!(true)
        );
        assert_eq!(
            promotion_gate["readiness_checks"]["model_gateway"]["ready"],
            json!(true)
        );
        assert_eq!(promotion_gate["readiness_checks"]["all_ready"], json!(true));
        assert_eq!(promotion_gate["codex_mutation_allowed"], json!(false));
        assert_eq!(promotion_gate["queue_allowed"], json!(false));
        assert_eq!(
            promotion_gate["requires_manual_feature_gate_change"],
            json!(true)
        );
        let blocked_model_gateway_promotion_gate =
            assistant_run_codex_promotion_gate_summary_with_model_gateway(
                &stable_gate,
                &validated_host_summary,
                &json!({
                    "status": "auth_not_configured",
                    "ready_for_promotion_review": false
                }),
            );
        assert_eq!(
            blocked_model_gateway_promotion_gate["status"],
            json!("blocked_by_model_gateway")
        );
        assert_eq!(
            blocked_model_gateway_promotion_gate["blocked_by"],
            json!("auth_not_configured")
        );
        assert_eq!(
            blocked_model_gateway_promotion_gate["eligible_for_feature_gate_review"],
            json!(false)
        );
        assert_eq!(
            blocked_model_gateway_promotion_gate["readiness_checks"]["model_gateway"]["ready"],
            json!(false)
        );
        assert_eq!(
            blocked_model_gateway_promotion_gate["readiness_checks"]["model_gateway"]["status"],
            json!("auth_not_configured")
        );
        assert_eq!(
            blocked_model_gateway_promotion_gate["readiness_checks"]["all_ready"],
            json!(false)
        );
        assert_eq!(
            blocked_model_gateway_promotion_gate["next_step"],
            json!("fix_codex_model_gateway_profile_before_promotion")
        );
        let failed_host_summary = assistant_run_codex_host_validation_summary(&[json!({
            "mode": "codex_exec",
            "status": "failed",
            "host_kind": "windows_jump",
            "host_kind_allowed": true,
            "host_validation_completed": false,
            "codex_invoked": true,
            "profile": {"kind": "codex-compatible-shim", "model": "MiniMax-M2.7"},
            "command_plan": {"workspace_configured": true, "prompt_redacted": true},
            "process": {"exit_code": 1},
            "task_memory_isolated": true,
            "task_memory_space_configured": true,
            "html_artifact_count": 1,
        })]);
        let failed_host_promotion_gate =
            assistant_run_codex_promotion_gate_summary_with_model_gateway(
                &stable_gate,
                &failed_host_summary,
                &json!({"status": "ready", "ready_for_promotion_review": true}),
            );
        assert_eq!(
            failed_host_promotion_gate["status"],
            json!("blocked_by_host_validation")
        );
        assert_eq!(failed_host_promotion_gate["blocked_by"], json!("failed"));
        assert_eq!(
            failed_host_promotion_gate["eligible_for_feature_gate_review"],
            json!(false)
        );
        assert_eq!(
            failed_host_promotion_gate["readiness_checks"]["host_validation"]["ready"],
            json!(false)
        );
        assert_eq!(
            failed_host_promotion_gate["readiness_checks"]["host_validation"]["status"],
            json!("failed")
        );
        assert_eq!(
            failed_host_promotion_gate["codex_mutation_allowed"],
            json!(false)
        );
        assert_eq!(failed_host_promotion_gate["queue_allowed"], json!(false));
        assert_eq!(stable_gate["codex_mutation_allowed"], json!(false));
        assert_eq!(
            stable_gate["next_gate"],
            json!("jump_host_or_mac_host_validation")
        );

        let mut blocked_events = stable_events;
        blocked_events.push(AssistantRunEvent {
            id: AssistantRunEventId::new(),
            tenant_id,
            run_id,
            sequence_no: 4,
            event_name: "assistant_run.codex_executor_diagnostic".to_string(),
            payload: json!({
                "provider_secret": "sk-should-not-leak",
                "suggested_action": {
                    "action_type": "unsafe_os_command",
                    "mutation_allowed": true,
                    "arguments": {
                        "prompt": "raw prompt should not leak"
                    }
                },
                "shadow_comparison": {
                    "codex_mutation_allowed": false,
                    "codex": {
                        "suggested_action_type": "unsafe_os_command",
                        "suggested_action_allowed": false
                    },
                    "comparison": {
                        "status": "invalid_suggestion",
                        "codex_has_suggestion": true,
                        "actionable": false
                    }
                }
            }),
            created_at: now,
        });
        let blocked_refs = blocked_events.iter().collect::<Vec<_>>();
        let blocked_gate = assistant_run_codex_shadow_gate_summary(&blocked_refs);

        assert_eq!(blocked_gate["status"], json!("blocked"));
        assert_eq!(blocked_gate["invalid_count"], json!(1));
        assert_eq!(blocked_gate["unsafe_mutation_signal_count"], json!(1));
        assert_eq!(blocked_gate["matched_streak_count"], json!(0));
        assert_eq!(blocked_gate["last_blocking_event"]["sequence_no"], json!(4));
        assert_eq!(
            blocked_gate["last_blocking_event"]["comparison_status"],
            json!("invalid_suggestion")
        );
        assert_eq!(
            blocked_gate["last_blocking_event"]["codex_suggested_action_type"],
            json!("unsafe_os_command")
        );
        assert_eq!(blocked_gate["host_validation_allowed"], json!(false));
        assert_eq!(
            blocked_gate["host_validation"]["ready_for_jump_host_validation"],
            json!(false)
        );
        assert_eq!(
            blocked_gate["host_validation"]["blocked_by"],
            json!("invalid_suggestion")
        );
        assert_eq!(
            blocked_gate["host_validation"]["next_step"],
            json!("continue_shadow_comparison_until_stable")
        );
        let blocked_promotion_gate = assistant_run_codex_promotion_gate_summary_with_model_gateway(
            &blocked_gate,
            &validated_host_summary,
            &json!({"status": "ready", "ready_for_promotion_review": true}),
        );
        assert_eq!(
            blocked_promotion_gate["status"],
            json!("blocked_by_shadow_gate")
        );
        assert_eq!(blocked_promotion_gate["blocked_by"], json!("blocked"));
        assert_eq!(blocked_gate["queue_allowed"], json!(false));

        let recent = assistant_run_codex_recent_shadow_events(&blocked_refs, 3);
        assert_eq!(recent.len(), 3);
        assert_eq!(recent[0]["sequence_no"], json!(4));
        assert_eq!(recent[0]["comparison_status"], json!("invalid_suggestion"));
        assert_eq!(
            recent[0]["codex_suggested_action_type"],
            json!("unsafe_os_command")
        );
        assert_eq!(recent[0]["codex_suggested_action_allowed"], json!(false));
        assert_eq!(recent[0]["mutation_allowed"], json!(true));
        assert_eq!(recent[0]["codex_mutation_allowed"], json!(false));
        let recent_serialized = serde_json::to_string(&recent).expect("recent events serialize");
        assert!(!recent_serialized.contains("sk-should-not-leak"));
        assert!(!recent_serialized.contains("raw prompt should not leak"));
    }

    #[test]
    fn assistant_run_codex_host_validation_summary_tracks_failed_and_non_exec_states() {
        let empty = assistant_run_codex_host_validation_summary(&[]);
        assert_eq!(empty["status"], json!("not_run"));
        assert_eq!(empty["result_count"], json!(0));
        assert_eq!(
            empty["next_step"],
            json!("run_jump_host_smoke_with_codex_host_agent_when_shadow_gate_ready")
        );

        let non_exec_results = vec![json!({
            "mode": "plan_only",
            "status": "completed",
            "host_validation_completed": false,
            "codex_invoked": false,
            "capability": "inspect_project",
            "profile": {"kind": "codex-compatible-shim", "model": "MiniMax-M2.7"},
            "command_plan": {"workspace_configured": true, "prompt_redacted": true},
            "process": {"exit_code": Value::Null},
            "html_artifact_count": 1,
        })];
        let non_exec = assistant_run_codex_host_validation_summary(&non_exec_results);
        assert_eq!(non_exec["status"], json!("observed_non_exec"));
        assert_eq!(non_exec["completed_count"], json!(0));
        assert_eq!(non_exec["failed_count"], json!(0));
        assert_eq!(non_exec["latest"]["codex_invoked"], json!(false));
        assert_eq!(non_exec["codex_mutation_allowed"], json!(false));

        let invalid_host_results = vec![json!({
            "mode": "codex_exec",
            "status": "completed",
            "host_kind": "developer_workstation",
            "host_kind_allowed": false,
            "host_validation_completed": false,
            "codex_invoked": true,
            "capability": "inspect_project",
            "profile": {"kind": "codex-native", "model": "codex-host"},
            "command_plan": {"workspace_configured": true, "prompt_redacted": true},
            "process": {"exit_code": 0},
            "task_memory_isolated": true,
            "task_memory_space_configured": true,
            "html_artifact_count": 1,
        })];
        let invalid_host = assistant_run_codex_host_validation_summary(&invalid_host_results);
        let invalid_promotion_gate = assistant_run_codex_promotion_gate_summary_with_model_gateway(
            &json!({"host_validation_allowed": true, "status": "eligible_for_host_validation"}),
            &invalid_host,
            &json!({"status": "ready", "ready_for_promotion_review": true}),
        );

        assert_eq!(invalid_host["status"], json!("invalid_host"));
        assert_eq!(invalid_host["completed_count"], json!(0));
        assert_eq!(invalid_host["failed_count"], json!(1));
        assert_eq!(invalid_host["invalid_host_count"], json!(1));
        assert_eq!(
            invalid_host["latest"]["host_kind"],
            json!("developer_workstation")
        );
        assert_eq!(invalid_host["latest"]["host_kind_allowed"], json!(false));
        assert_eq!(
            invalid_host["next_step"],
            json!("rerun_codex_host_smoke_on_windows_jump_or_mac_host")
        );
        assert_eq!(
            invalid_promotion_gate["status"],
            json!("blocked_by_host_validation")
        );
        assert_eq!(invalid_promotion_gate["blocked_by"], json!("invalid_host"));
        assert_eq!(
            invalid_promotion_gate["eligible_for_feature_gate_review"],
            json!(false)
        );

        let guard_failed_results = vec![json!({
            "mode": "codex_exec",
            "status": "completed",
            "host_kind": "windows_jump",
            "host_kind_allowed": true,
            "host_validation_completed": true,
            "codex_invoked": true,
            "capability": "inspect_project",
            "profile": {"kind": "codex-compatible-shim", "model": "MiniMax-M2.7"},
            "command_plan": {
                "workspace_configured": false,
                "prompt_redacted": true
            },
            "process": {"exit_code": 0},
            "task_memory_isolated": true,
            "task_memory_space_configured": true,
            "html_artifact_count": 1,
        })];
        let guard_failed = assistant_run_codex_host_validation_summary(&guard_failed_results);

        assert_eq!(guard_failed["status"], json!("failed"));
        assert_eq!(guard_failed["completed_count"], json!(0));
        assert_eq!(guard_failed["failed_count"], json!(1));
        assert_eq!(guard_failed["invalid_host_count"], json!(0));
        assert_eq!(guard_failed["guard_failed_count"], json!(1));
        assert_eq!(
            guard_failed["latest"]["validation_requirements_met"],
            json!(false)
        );
        assert_eq!(guard_failed["latest"]["workspace_configured"], json!(false));
        assert_eq!(
            guard_failed["next_step"],
            json!("inspect_redacted_codex_host_report_and_retry_on_jump_host")
        );

        let failed_results = vec![
            json!({
                "mode": "codex_exec",
                "status": "failed",
                "host_kind": "windows_jump",
                "host_kind_allowed": true,
                "host_validation_completed": false,
                "codex_invoked": true,
                "capability": "inspect_project",
                "profile": {
                    "kind": "codex-compatible-shim",
                    "model": "MiniMax-M2.7",
                    "env_key": "MINIMAX_API_KEY"
                },
                "command_plan": {"workspace_configured": true, "prompt_redacted": true},
                "process": {"exit_code": 1, "stderr_excerpt": "sk-should-not-leak"},
                "task_memory_isolated": true,
                "task_memory_space_configured": true,
                "html_artifact_count": 1,
            }),
            json!({
                "mode": "codex_exec",
                "status": "completed",
                "host_kind": "windows_jump",
                "host_kind_allowed": true,
                "host_validation_completed": true,
                "codex_invoked": true,
                "capability": "inspect_project",
                "profile": {"kind": "codex-compatible-shim", "model": "MiniMax-M2.7"},
                "command_plan": {"workspace_configured": true, "prompt_redacted": true},
                "process": {"exit_code": 0},
                "task_memory_isolated": true,
                "task_memory_space_configured": true,
                "html_artifact_count": 1,
            }),
        ];
        let failed = assistant_run_codex_host_validation_summary(&failed_results);
        let serialized = failed.to_string();

        assert_eq!(failed["status"], json!("failed"));
        assert_eq!(failed["completed_count"], json!(1));
        assert_eq!(failed["failed_count"], json!(1));
        assert_eq!(failed["latest"]["exit_code"], json!(1));
        assert_eq!(
            failed["latest"]["profile_kind"],
            json!("codex-compatible-shim")
        );
        assert_eq!(
            failed["next_step"],
            json!("inspect_redacted_codex_host_report_and_retry_on_jump_host")
        );
        assert_eq!(failed["direct_execution_authoritative"], json!(true));
        assert_eq!(failed["local_execution_allowed"], json!(false));
        assert_eq!(failed["queue_allowed"], json!(false));
        assert!(!serialized.contains("MINIMAX_API_KEY"));
        assert!(!serialized.contains("sk-should-not-leak"));
    }

    #[test]
    fn html_artifacts_are_collected_from_nested_assistant_run_events() {
        let tenant_id = TenantId::new();
        let run_id = AssistantRunId::new();
        let run_id_string = run_id.to_string();
        let now = Utc::now();
        let mut older = HtmlArtifactManifestView::codex_execution_report(
            &run_id_string,
            "Codex dry run",
            "dry_run completed",
            json!({"mode": "dry_run", "status": "completed"}),
        );
        older.id = "html-artifact-old".to_string();
        older.created_at = now - Duration::seconds(10);
        let mut newer = HtmlArtifactManifestView::codex_execution_report(
            &run_id_string,
            "Codex plan",
            "plan_only planned",
            json!({"mode": "plan_only", "status": "planned"}),
        );
        newer.id = "html-artifact-new".to_string();
        newer.created_at = now;

        let events = vec![
            AssistantRunEvent {
                id: AssistantRunEventId::new(),
                tenant_id,
                run_id,
                sequence_no: 1,
                event_name: "codex_host.output".to_string(),
                payload: json!({
                    "html_artifacts": [
                        serde_json::to_value(&older).expect("older manifest serializes"),
                        {"kind": "not_html_artifact"}
                    ]
                }),
                created_at: now - Duration::seconds(10),
            },
            AssistantRunEvent {
                id: AssistantRunEventId::new(),
                tenant_id,
                run_id,
                sequence_no: 2,
                event_name: "workflow.task.completed".to_string(),
                payload: json!({
                    "output": {
                        "html_artifacts": [
                            serde_json::to_value(&newer).expect("newer manifest serializes")
                        ]
                    }
                }),
                created_at: now,
            },
        ];

        let mut artifacts = Vec::new();
        collect_html_artifacts_from_events(&events, &mut artifacts, 10);
        sort_and_dedupe_html_artifacts(&mut artifacts);

        assert_eq!(artifacts.len(), 2);
        assert_eq!(artifacts[0].id, "html-artifact-new");
        assert_eq!(artifacts[1].id, "html-artifact-old");
        assert_eq!(artifacts[0].payload["mode"], json!("plan_only"));
    }

    #[test]
    fn external_template_html_extracts_fenced_html_and_rejects_unsafe_content() {
        let html = extract_external_template_html_from_model_output(
            "说明如下：\n```html\n<section><h1>人员说明报告</h1></section>\n```",
        )
        .expect("fenced HTML should be extracted");
        assert!(html.contains("人员说明报告"));
        validate_external_template_html_artifact_content(&html)
            .expect("simple HTML should be accepted");

        let unsafe_error = validate_external_template_html_artifact_content(
            "<section onclick=\"alert(1)\"></section>",
        )
        .expect_err("event handlers should be rejected");
        assert_eq!(
            unsafe_error.payload.code,
            "external_template_html_artifact_unsafe"
        );
        assert!(extract_external_template_html_from_model_output("普通文字").is_none());
    }

    #[test]
    fn html_artifact_video_download_files_stay_inside_generated_workspace() {
        let root =
            std::env::temp_dir().join(format!("aidp-v3-html-artifact-download-{}", Uuid::new_v4()));
        let artifacts_dir = root.join("generated_artifacts");
        fs::create_dir_all(&artifacts_dir).expect("test artifacts dir should be created");
        let final_manifest_path = artifacts_dir.join("final_deliverables_manifest.json");
        let pptx_path = artifacts_dir.join("video_slides_screenshot_based.pptx");
        let slide_notes_path = artifacts_dir.join("slide_notes.md");
        let subtitle_map_path = artifacts_dir.join("subtitle_page_map.json");
        fs::write(&final_manifest_path, "{}").expect("test manifest should be written");
        fs::write(&pptx_path, "pptx").expect("test pptx should be written");
        fs::write(&slide_notes_path, "# notes").expect("test notes should be written");
        fs::write(&subtitle_map_path, "{}").expect("test subtitle map should be written");
        let artifact = HtmlArtifactManifestView {
            kind: "html_artifact".to_string(),
            version: 1,
            id: "html-artifact-video".to_string(),
            title: "视频提取摘要".to_string(),
            source_type: contracts::HtmlArtifactSourceTypeView::VideoExtraction,
            template_id: contracts::HtmlArtifactTemplateIdView::VideoExtractionSummary,
            owner_scope: contracts::HtmlArtifactOwnerScopeView {
                scope_type: "assistant_run".to_string(),
                id: AssistantRunId::new().to_string(),
            },
            data_refs: Vec::new(),
            provenance: contracts::HtmlArtifactProvenanceView {
                producer: "media-worker".to_string(),
                reason: "video_extraction_workflow_completed".to_string(),
                source_run_id: Some(AssistantRunId::new().to_string()),
            },
            interaction_mode: HtmlArtifactInteractionModeView::ReadOnly,
            created_at: Utc::now(),
            payload: json!({
                "generated_artifacts": {
                    "session_dir": root.display().to_string(),
                    "artifacts_dir": artifacts_dir.display().to_string(),
                    "files": [{
                        "artifact_kind": "final_deliverables_manifest",
                        "format": "application/json",
                        "path": final_manifest_path.display().to_string()
                    }, {
                        "artifact_kind": "pptx",
                        "format": "application/vnd.openxmlformats-officedocument.presentationml.presentation",
                        "path": pptx_path.display().to_string()
                    }, {
                        "artifact_kind": "slide_notes",
                        "format": "text/markdown",
                        "path": slide_notes_path.display().to_string()
                    }, {
                        "artifact_kind": "subtitle_page_map",
                        "format": "application/json",
                        "path": subtitle_map_path.display().to_string()
                    }]
                }
            }),
        };

        let expected = [
            (0, "final_deliverables_manifest.json", "application/json"),
            (
                1,
                "video_slides_screenshot_based.pptx",
                "application/vnd.openxmlformats-officedocument.presentationml.presentation",
            ),
            (2, "slide_notes.md", "text/markdown"),
            (3, "subtitle_page_map.json", "application/json"),
        ];
        for (index, file_name, content_type) in expected {
            let download = html_artifact_downloadable_file(&artifact, index)
                .expect("file inside generated workspace should be downloadable");

            assert!(download.path.ends_with(file_name));
            assert_eq!(download.file_name, file_name);
            assert_eq!(download.content_type, content_type);
        }
    }

    #[test]
    fn html_artifact_video_download_rejects_paths_outside_workspace() {
        let root = std::env::temp_dir().join(format!(
            "aidp-v3-html-artifact-download-root-{}",
            Uuid::new_v4()
        ));
        let artifacts_dir = root.join("generated_artifacts");
        fs::create_dir_all(&artifacts_dir).expect("test artifacts dir should be created");
        let outside_dir = std::env::temp_dir().join(format!(
            "aidp-v3-html-artifact-download-outside-{}",
            Uuid::new_v4()
        ));
        fs::create_dir_all(&outside_dir).expect("test outside dir should be created");
        let outside_file = outside_dir.join("leak.txt");
        fs::write(&outside_file, "nope").expect("test outside file should be written");
        let artifact = HtmlArtifactManifestView {
            kind: "html_artifact".to_string(),
            version: 1,
            id: "html-artifact-video".to_string(),
            title: "视频提取摘要".to_string(),
            source_type: contracts::HtmlArtifactSourceTypeView::VideoExtraction,
            template_id: contracts::HtmlArtifactTemplateIdView::VideoExtractionSummary,
            owner_scope: contracts::HtmlArtifactOwnerScopeView {
                scope_type: "assistant_run".to_string(),
                id: AssistantRunId::new().to_string(),
            },
            data_refs: Vec::new(),
            provenance: contracts::HtmlArtifactProvenanceView {
                producer: "media-worker".to_string(),
                reason: "video_extraction_workflow_completed".to_string(),
                source_run_id: Some(AssistantRunId::new().to_string()),
            },
            interaction_mode: HtmlArtifactInteractionModeView::ReadOnly,
            created_at: Utc::now(),
            payload: json!({
                "generated_artifacts": {
                    "session_dir": root.display().to_string(),
                    "artifacts_dir": artifacts_dir.display().to_string(),
                    "files": [{
                        "artifact_kind": "transcript_text",
                        "format": "text/plain",
                        "path": outside_file.display().to_string()
                    }]
                }
            }),
        };

        let error = html_artifact_downloadable_file(&artifact, 0)
            .expect_err("file outside generated workspace must be denied");

        assert_eq!(error.payload.code, "html_artifact_file_path_denied");
    }

