    #[test]
    fn static_page_preview_gate_allows_bound_chart_bindings_for_design_preview() {
        let now = Utc::now();
        let draft = StaticPageDraft {
            id: StaticPageDraftId::new(),
            tenant_id: TenantId::new(),
            owner_user_id: None,
            assistant_run_id: AssistantRunId::new(),
            title: "经营分析静态页".to_string(),
            status: StaticPageDraftStatus::Planned,
            selected_scope: json!({
                "mode": "user_selected",
                "datasets": [DatasetId::new().to_string()],
            }),
            visibility_snapshot: json!({"policy": "test"}),
            source_refs: Value::Null,
            draft_payload: json!({
                "version": 1,
                "status": "planning",
                "modules": [{
                    "id": "trend",
                    "title": "订单趋势",
                    "dataBinding": {
                        "sourceId": "dataset",
                        "fieldPath": "dataset.metrics_summary",
                        "label": "订单金额"
                    },
                    "visualization": {
                        "type": "line-chart",
                        "chartOptions": {
                            "dataKey": "dataset.metrics_summary"
                        }
                    }
                }]
            }),
            created_at: now,
            updated_at: now,
        };

        assert!(
            static_page_preview_data_quality_gate_for_draft(&draft).is_none(),
            "bound chart modules may enter design preview before sample rows are repaired"
        );

        assert!(
            static_page_final_render_data_quality_gate_for_draft(&draft).is_none(),
            "bound chart modules should proceed to final render; renderer carries data-quality warnings"
        );
    }

