    #[tokio::test]
    async fn assistant_run_falls_back_to_visible_document_chunks_without_retrieval_evidence() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "placeholder");
        std::env::remove_var("ASSISTANT_RUN_EVIDENCE_LIMIT");
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping assistant run chunk fallback test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("assistant-chunk-fallback-test-{}", Uuid::new_v4()),
                "Assistant Chunk Fallback Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        let dataset = state
            .storage
            .datasets()
            .create(
                state.tenant_id,
                NewDataset {
                    key: format!("orders-chunk-fallback-{}", Uuid::new_v4()),
                    title: "订单风险".to_string(),
                    description: Some("订单取消和延期风险资料。".to_string()),
                    owner_user_id: None,
                },
            )
            .await
            .expect("dataset should be created");
        let document = state
            .storage
            .documents()
            .create(
                state.tenant_id,
                NewDocument {
                    dataset_id: dataset.id,
                    title: "Order Risk Raw Notes".to_string(),
                    object_key: "documents/order-risk-raw.md".to_string(),
                    content_type: "text/markdown".to_string(),
                    secret_binding_ids: Vec::new(),
                    owner_user_id: None,
                    metadata: json!({}),
                },
            )
            .await
            .expect("document should be created");
        let now = Utc::now();
        let chunks = state
            .storage
            .document_chunks()
            .replace_for_document(
                state.tenant_id,
                document.id,
                &[
                    storage::NewDocumentChunk {
                        dataset_id: dataset.id,
                        document_id: document.id,
                        chunk_index: 0,
                        content: "Customer newsletter engagement improved last month."
                            .to_string(),
                        token_count: 8,
                        metadata: json!({"section": "newsletter"}),
                        created_at: now,
                    },
                    storage::NewDocumentChunk {
                        dataset_id: dataset.id,
                        document_id: document.id,
                        chunk_index: 1,
                        content:
                            "Order cancellation risk rises when delayed fulfillment exceeds two days."
                                .to_string(),
                        token_count: 12,
                        metadata: json!({"section": "risk"}),
                        created_at: now,
                    },
                ],
            )
            .await
            .expect("document chunks should be created");

        let (status, Json(response)) = create_assistant_run(
            State(state.clone()),
            HeaderMap::new(),
            Json(CreateAssistantRunRequest {
                prompt: "基于订单做一页静态页，重点看 order cancellation risk".to_string(),
                local_thread_id: Some("assistant-chunk-fallback-thread".to_string()),
                startup_briefing: Some(json!({"visibleDatasetCount": 1})),
                selected_scope: Some(json!({
                    "mode": "user_selected",
                    "datasets": [dataset.id],
                })),
                scope_candidates: Vec::new(),
                context_policy_hint: None,
                current_artifact: None,
                messages: Vec::new(),
            }),
        )
        .await
        .expect("assistant run should be created");

        assert_eq!(status, StatusCode::CREATED);
        assert_eq!(response.evidence_state["status"], json!("supplied"));
        assert_eq!(response.evidence_state["fallback_supply_count"], json!(2));
        assert_eq!(
            response.evidence_state["supply_quality"]["status"],
            json!("grounded")
        );
        assert_eq!(
            response.evidence_state["supply_quality"]["fallbackChunkCount"],
            json!(2)
        );
        assert!(response.evidence_state["supply_quality"]["notes"]
            .as_array()
            .expect("supply quality notes should be present")
            .iter()
            .any(|note| note.as_str() == Some("fallback_visible_document_chunks_used")));
        let first_item = &response.evidence_state["supplied_items"][0];
        assert_eq!(first_item["source"], json!("document_chunk_fallback"));
        assert_eq!(
            first_item["fallback_reason"],
            json!("retrieval_evidence_unavailable")
        );
        assert_eq!(first_item["document_chunk_id"], json!(chunks[1].id));
        assert!(first_item.get("retrieval_evidence_id").is_none());
        assert!(first_item["content_excerpt"]
            .as_str()
            .unwrap_or_default()
            .contains("Order cancellation risk"));
        assert_eq!(
            response.evidence_state["detail_targets"][0]["document_chunk_id"],
            json!(chunks[1].id)
        );
        assert!(response
            .assistant_message
            .content
            .contains("已有可见供料时，正式模型回答会优先参考供料"));
        assert!(!response.assistant_message.content.contains("供料状态:"));
        assert!(!response.assistant_message.content.contains("Prompt:"));
    }

    #[tokio::test]
    async fn assistant_run_supplies_document_parse_status_for_failed_and_reparsing_documents() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "placeholder");
        std::env::remove_var("ASSISTANT_RUN_EVIDENCE_LIMIT");
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping assistant run document parse status test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("assistant-parse-status-test-{}", Uuid::new_v4()),
                "Assistant Parse Status Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        let dataset = state
            .storage
            .datasets()
            .create(
                state.tenant_id,
                NewDataset {
                    key: format!("parse-status-{}", Uuid::new_v4()),
                    title: "Parse status dataset".to_string(),
                    description: Some("Documents with async parse states.".to_string()),
                    owner_user_id: None,
                },
            )
            .await
            .expect("dataset should be created");

        let failed_document = state
            .storage
            .documents()
            .create(
                state.tenant_id,
                NewDocument {
                    dataset_id: dataset.id,
                    title: "Customer one-character PDF".to_string(),
                    object_key: "documents/one-character.pdf".to_string(),
                    content_type: "application/pdf".to_string(),
                    secret_binding_ids: Vec::new(),
                    owner_user_id: None,
                    metadata: json!({
                        "external_source": {
                            "source_id": "third-party-source",
                            "document_external_id": "customer-pdf-1"
                        }
                    }),
                },
            )
            .await
            .expect("failed document should be created");
        let failed_document = state
            .storage
            .documents()
            .update_state(
                state.tenant_id,
                failed_document.id,
                DocumentLifecycle::Failed,
                None,
                &json!({
                    "parse_status": "failed",
                    "ingest": {
                        "last_error": "only one text character extracted",
                        "failed_at": Utc::now()
                    }
                }),
                Utc::now(),
            )
            .await
            .expect("failed document should be marked failed");

        let reparsing_document = state
            .storage
            .documents()
            .create(
                state.tenant_id,
                NewDocument {
                    dataset_id: dataset.id,
                    title: "Retrying resume PDF".to_string(),
                    object_key: "documents/retrying-resume.pdf".to_string(),
                    content_type: "application/pdf".to_string(),
                    secret_binding_ids: Vec::new(),
                    owner_user_id: None,
                    metadata: json!({
                        "external_source": {
                            "source_id": "third-party-source",
                            "document_external_id": "resume-pdf-2"
                        }
                    }),
                },
            )
            .await
            .expect("reparsing document should be created");
        let reparsing_document = state
            .storage
            .documents()
            .update_state(
                state.tenant_id,
                reparsing_document.id,
                DocumentLifecycle::Failed,
                None,
                &json!({
                    "parse_status": "failed",
                    "ingest": {
                        "last_error": "ocr timeout before retry",
                        "failed_at": Utc::now()
                    }
                }),
                Utc::now(),
            )
            .await
            .expect("reparsing document should be marked failed first");
        let execution = build_initial_upload_ingest_execution(&state, &reparsing_document)
            .expect("upload ingest execution should build");
        let initial_event = build_initial_upload_ingest_event(&execution, &reparsing_document);
        state
            .storage
            .workflow_executions()
            .create_with_initial_event(&execution, &initial_event)
            .await
            .expect("workflow execution should be created");
        let started = apply_workflow_signal(&state, execution.id, WorkflowSignal::Start)
            .await
            .expect("reparse workflow should start");
        assert_eq!(started.execution.status, WorkflowStatus::Running);

        let degraded_document = state
            .storage
            .documents()
            .create(
                state.tenant_id,
                NewDocument {
                    dataset_id: dataset.id,
                    title: "Low coverage PDF".to_string(),
                    object_key: "documents/low-coverage.pdf".to_string(),
                    content_type: "application/pdf".to_string(),
                    secret_binding_ids: Vec::new(),
                    owner_user_id: None,
                    metadata: json!({
                        "ingest": {
                            "parse_metadata": {
                                "parse_quality": {
                                    "status": "low_text_coverage_fallback_unavailable"
                                }
                            }
                        }
                    }),
                },
            )
            .await
            .expect("degraded document should be created");
        state
            .storage
            .documents()
            .update_state(
                state.tenant_id,
                degraded_document.id,
                DocumentLifecycle::Extracted,
                None,
                &json!({}),
                Utc::now(),
            )
            .await
            .expect("degraded document should be marked extracted");

        let evidence_state = build_assistant_run_evidence_state(
            &state,
            &json!({
                "mode": "user_selected",
                "datasets": [dataset.id],
            }),
            "这几份文档现在能正常用了吗？",
            None,
            &[],
            None,
        )
        .await
        .expect("evidence state should build");

        assert_eq!(evidence_state["status"], json!("supplied"));
        assert_eq!(evidence_state["supply_quality"]["status"], json!("partial"));
        assert_eq!(
            evidence_state["supply_quality"]["documentParseStatusCount"],
            json!(1)
        );
        assert_eq!(
            evidence_state["supply_quality"]["documentFailedCount"],
            json!(1)
        );
        assert_eq!(
            evidence_state["supply_quality"]["documentReparsingCount"],
            json!(1)
        );
        assert_eq!(
            evidence_state["supply_quality"]["documentDegradedParseCount"],
            json!(1)
        );
        assert_eq!(
            evidence_state["supply_quality"]["documentNotReadyCount"],
            json!(3)
        );
        let notes = evidence_state["supply_quality"]["notes"]
            .as_array()
            .expect("notes should be present");
        assert!(notes
            .iter()
            .any(|note| note.as_str() == Some("document_parse_status_available")));
        assert!(notes
            .iter()
            .any(|note| note.as_str() == Some("document_reparse_in_progress")));
        assert!(notes
            .iter()
            .any(|note| note.as_str() == Some("some_documents_failed_parse")));
        assert!(notes
            .iter()
            .any(|note| note.as_str() == Some("some_documents_parse_degraded")));

        let parse_status_item = evidence_state["supplied_items"]
            .as_array()
            .expect("supplied items should be present")
            .iter()
            .find(|item| item.get("type").and_then(Value::as_str) == Some("document_parse_status"))
            .expect("document parse status item should be supplied");
        assert_eq!(parse_status_item["failed_document_count"], json!(1));
        assert_eq!(parse_status_item["reparsing_document_count"], json!(1));
        assert_eq!(parse_status_item["degraded_parse_count"], json!(1));
        assert!(parse_status_item["summary"]
            .as_str()
            .unwrap_or_default()
            .contains("模型应据此说明解析状态"));
        let low_coverage_attention = parse_status_item["attention_documents"]
            .as_array()
            .expect("attention documents should be present")
            .iter()
            .find(|item| item.get("title").and_then(Value::as_str) == Some("Low coverage PDF"))
            .expect("degraded parse document should be listed");
        assert_eq!(
            low_coverage_attention["parse_quality_summary"]["status"],
            json!("low_text_coverage_fallback_unavailable")
        );
        let attention_statuses = parse_status_item["attention_documents"]
            .as_array()
            .expect("attention documents should be present")
            .iter()
            .filter_map(|item| item.get("model_status").and_then(Value::as_str))
            .collect::<BTreeSet<_>>();
        assert!(attention_statuses.contains("failed"));
        assert!(attention_statuses.contains("reparsing"));
        assert!(attention_statuses.contains("parse_degraded"));
        let external_ids = parse_status_item["attention_documents"]
            .as_array()
            .expect("attention documents should be present")
            .iter()
            .filter_map(|item| {
                item.pointer("/external_document/document_external_id")
                    .and_then(Value::as_str)
            })
            .collect::<BTreeSet<_>>();
        assert!(external_ids.contains("customer-pdf-1"));
        assert!(external_ids.contains("resume-pdf-2"));

        let reparsing_detail =
            load_document_detail_with_state(&state, reparsing_document.id, &[], None)
                .await
                .expect("reparsing document detail should load");
        assert_eq!(reparsing_detail.document.parse_status, "failed");
        assert_eq!(reparsing_detail.parse_state.model_status, "reparsing");
        assert_eq!(
            reparsing_detail
                .parse_state
                .workflow
                .as_ref()
                .and_then(|workflow| workflow.get("status"))
                .and_then(Value::as_str),
            Some("running")
        );

        let provider_input = build_assistant_run_provider_input_with_evidence(
            &CreateAssistantRunRequest {
                prompt: "这几份文档现在能正常用了吗？".to_string(),
                local_thread_id: Some("assistant-parse-status-thread".to_string()),
                startup_briefing: None,
                selected_scope: Some(json!({
                    "mode": "user_selected",
                    "datasets": [dataset.id],
                })),
                scope_candidates: Vec::new(),
                context_policy_hint: None,
                current_artifact: None,
                messages: Vec::new(),
            },
            Some(&evidence_state),
        );
        assert!(provider_input.contains("文档解析状态：有 3 份可见文档未完全就绪"));
        assert!(provider_input.contains("不要声称已经读到完整内容"));

        assert_eq!(failed_document.lifecycle, DocumentLifecycle::Failed);
    }

