    #[tokio::test]
    async fn external_document_parse_endpoint_downloads_and_enqueues_ingest() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping external document parse endpoint test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("external-document-parse-test-{}", Uuid::new_v4()),
                "External Document Parse Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        let dataset = state
            .storage
            .datasets()
            .create(
                state.tenant_id,
                NewDataset {
                    key: format!("external-parse-dataset-{}", Uuid::new_v4()),
                    title: "External Parse Dataset".to_string(),
                    description: Some("Third-party parse endpoint test.".to_string()),
                    owner_user_id: None,
                },
            )
            .await
            .expect("dataset should be created");
        sqlx::query(
            r#"
            insert into external_channel_connections (
                id, tenant_id, platform, connection_key, display_name, config_redacted, status
            )
            values ('generic-chat-main', $1, 'generic_chat', 'generic-chat-main', 'Generic Chat', $2, 'enabled')
            "#,
        )
        .bind(state.tenant_id.0)
        .bind(json!({
            "inbound_bearer_token": "parse-token",
            "default_source_id": "src-docs"
        }))
        .execute(state.storage.pool())
        .await
        .expect("external channel connection should be inserted");
        sqlx::query(
            r#"
            insert into external_source_connections (
                id, tenant_id, connector_kind, source_key, display_name, base_url_redacted,
                config_redacted, sync_mode, permission_mode
            )
            values ('src-docs', $1, 'document', 'src-docs', 'Third-party Docs',
                    'https://docs.example/[redacted]', '{}', 'push', 'source_acl_snapshot')
            "#,
        )
        .bind(state.tenant_id.0)
        .execute(state.storage.pool())
        .await
        .expect("external source connection should be inserted");
        let listener = TcpListener::bind("127.0.0.1:0").expect("listener");
        let url = format!(
            "http://{}/doc-alpha.md",
            listener.local_addr().expect("listener address")
        );
        let body = "# Alpha policy\n\nOrder delay risk should be reviewed.";
        let expected_sha256 = sha256_hex([body.as_bytes()]);
        let expected_size_bytes = body.len() as i64;
        let server_body = body.to_string();
        let server = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("accept");
            let request = read_http_request(&mut stream);
            assert!(request.starts_with("GET /doc-alpha.md HTTP/1.1"));
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/markdown\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                server_body.len(),
                server_body
            );
            stream.write_all(response.as_bytes()).expect("write");
        });

        let object_root =
            std::env::temp_dir().join(format!("aidp-v3-external-parse-{}", Uuid::new_v4()));
        std::env::set_var("PLATFORM_LOCAL_OBJECT_ROOT", &object_root);
        let mut headers = HeaderMap::new();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer parse-token"),
        );
        let (status, Json(response)) = create_external_document_parse(
            State(state.clone()),
            headers.clone(),
            Path("generic-chat-main".to_string()),
            Json(CreateExternalDocumentParseRequest {
                source_id: "src-docs".to_string(),
                dataset_id: Some(dataset.id),
                dataset_external_id: None,
                dataset_title: None,
                document_external_id: "doc-alpha".to_string(),
                revision_external_id: Some("rev-1".to_string()),
                title: Some("Alpha policy".to_string()),
                content_type: Some("text/markdown".to_string()),
                content_url: url,
                metadata: json!({"customer": "alpha"}),
                idempotency_key: Some("parse-doc-alpha-rev-1".to_string()),
                allow_http_loopback: true,
            }),
        )
        .await
        .expect("external document parse should be accepted");
        server.join().expect("server should finish");

        assert_eq!(status, StatusCode::ACCEPTED);
        assert_eq!(response.source_id, "src-docs");
        assert_eq!(response.document_external_id, "doc-alpha");
        assert_eq!(
            response.document.lifecycle,
            contracts::DocumentLifecycleView::Received
        );
        assert!(object_root.join("external-documents").exists());
        assert_eq!(response.workflow_execution.kind, WorkflowKind::UploadIngest);
        assert_eq!(response.document.parse_status, "received");
        assert_eq!(response.document.parse_status_camel, "received");
        let fingerprint_row = sqlx::query(
            r#"
            select content_sha256, content_size_bytes, canonical_document_id, dedup_state
            from documents
            where tenant_id = $1 and id = $2
            "#,
        )
        .bind(state.tenant_id.0)
        .bind(response.document.id.0)
        .fetch_one(state.storage.pool())
        .await
        .expect("document fingerprint row should be readable");
        assert_eq!(
            fingerprint_row.get::<Option<String>, _>("content_sha256"),
            Some(expected_sha256.clone())
        );
        assert_eq!(
            fingerprint_row.get::<Option<i64>, _>("content_size_bytes"),
            Some(expected_size_bytes)
        );
        assert_eq!(
            fingerprint_row
                .get::<Option<Uuid>, _>("canonical_document_id")
                .map(DocumentId),
            Some(response.document.id)
        );
        assert_eq!(fingerprint_row.get::<String, _>("dedup_state"), "canonical");
        let canonical_id = sqlx::query_scalar::<_, Uuid>(
            r#"
            select canonical_document_id
            from document_content_fingerprints
            where tenant_id = $1 and content_sha256 = $2
            "#,
        )
        .bind(state.tenant_id.0)
        .bind(&expected_sha256)
        .fetch_one(state.storage.pool())
        .await
        .expect("document content fingerprint should be stored");
        assert_eq!(DocumentId(canonical_id), response.document.id);

        let Json(detail) = get_external_document_parse_detail(
            State(state.clone()),
            headers.clone(),
            Path(("generic-chat-main".to_string(), "doc-alpha".to_string())),
            Query(BTreeMap::from([(
                "source_id".to_string(),
                "src-docs".to_string(),
            )])),
        )
        .await
        .expect("parse detail should be returned");
        assert_eq!(
            detail.latest.as_ref().unwrap().document_id,
            response.document.id
        );
        assert_eq!(
            detail
                .latest
                .as_ref()
                .unwrap()
                .revision_external_id
                .as_deref(),
            Some("rev-1")
        );
        assert_eq!(
            detail.lifecycle,
            Some(contracts::DocumentLifecycleView::Received)
        );
        assert_eq!(detail.chunk_count, Some(0));
        assert_eq!(detail.parse_status.as_deref(), Some("received"));
        assert_eq!(detail.parse_status_camel.as_deref(), Some("received"));
        assert_eq!(detail.model_status.as_deref(), Some("parsing"));
        assert_eq!(detail.model_status_camel.as_deref(), Some("parsing"));
        assert_eq!(detail.retrieval_evidence_count, Some(0));
        assert!(detail.ingest.as_ref().unwrap().is_object());
        assert_eq!(
            detail
                .workflow
                .as_ref()
                .and_then(|workflow| workflow.get("status"))
                .and_then(Value::as_str),
            Some("running")
        );
        assert_eq!(detail.latest.as_ref().unwrap().parse_status, "received");
        assert_eq!(detail.latest.as_ref().unwrap().model_status, "parsing");

        sqlx::query(
            r#"
            update external_channel_connections
            set config_redacted = $3
            where tenant_id = $1 and id = $2
            "#,
        )
        .bind(state.tenant_id.0)
        .bind("generic-chat-main")
        .bind(json!({
            "inbound_bearer_token": "parse-token"
        }))
        .execute(state.storage.pool())
        .await
        .expect("connection config should be updated");
        let Json(detail_without_source_query) = get_external_document_parse_detail(
            State(state.clone()),
            headers.clone(),
            Path(("generic-chat-main".to_string(), "doc-alpha".to_string())),
            Query(BTreeMap::new()),
        )
        .await
        .expect("parse detail should infer source_id from document_external_id");
        assert_eq!(detail_without_source_query.source_id, "src-docs");
        assert_eq!(
            detail_without_source_query
                .latest
                .as_ref()
                .unwrap()
                .document_id,
            response.document.id
        );

        let Json(detail_by_internal_id) = get_external_document_parse_detail(
            State(state),
            headers,
            Path((
                "generic-chat-main".to_string(),
                response.document.id.to_string(),
            )),
            Query(BTreeMap::from([(
                "source_id".to_string(),
                "src-docs".to_string(),
            )])),
        )
        .await
        .expect("parse detail should accept the DataMax document id as a compatibility key");
        assert_eq!(
            detail_by_internal_id.latest.as_ref().unwrap().document_id,
            response.document.id
        );
        assert_eq!(
            detail_by_internal_id.lifecycle,
            Some(contracts::DocumentLifecycleView::Received)
        );
    }

    #[tokio::test]
    async fn external_document_parse_endpoint_auto_creates_source_dataset_when_missing() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping external document parse dataset creation test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("external-document-parse-dataset-test-{}", Uuid::new_v4()),
                "External Document Parse Dataset Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        sqlx::query(
            r#"
            insert into external_channel_connections (
                id, tenant_id, platform, connection_key, display_name, config_redacted, status
            )
            values ('generic-chat-main', $1, 'generic_chat', 'generic-chat-main', 'Generic Chat', $2, 'enabled')
            "#,
        )
        .bind(state.tenant_id.0)
        .bind(json!({
            "inbound_bearer_token": "parse-token",
            "default_source_id": "src-auto-docs"
        }))
        .execute(state.storage.pool())
        .await
        .expect("external channel connection should be inserted");
        sqlx::query(
            r#"
            insert into external_source_connections (
                id, tenant_id, connector_kind, source_key, display_name, base_url_redacted,
                config_redacted, sync_mode, permission_mode
            )
            values ('src-auto-docs', $1, 'document', 'src-auto-docs', 'Third-party Auto Docs',
                    'https://docs.example/[redacted]', '{}', 'push', 'source_acl_snapshot')
            "#,
        )
        .bind(state.tenant_id.0)
        .execute(state.storage.pool())
        .await
        .expect("external source connection should be inserted");
        let legacy_public_dataset = state
            .storage
            .datasets()
            .create(
                state.tenant_id,
                NewDataset {
                    key: format!("legacy-public-external-docs-{}", Uuid::new_v4()),
                    title: "Legacy Public External Docs".to_string(),
                    description: None,
                    owner_user_id: None,
                },
            )
            .await
            .expect("legacy public dataset should be created");
        let legacy_public_document = state
            .storage
            .documents()
            .create(
                state.tenant_id,
                NewDocument {
                    dataset_id: legacy_public_dataset.id,
                    title: "Legacy public duplicate".to_string(),
                    object_key: "legacy/doc-auto.md".to_string(),
                    content_type: "text/markdown".to_string(),
                    secret_binding_ids: Vec::new(),
                    owner_user_id: None,
                    metadata: json!({
                        "external_source": {
                            "source_id": "src-auto-docs",
                            "document_external_id": "doc-auto"
                        }
                    }),
                },
            )
            .await
            .expect("legacy public duplicate should be created");

        let listener = TcpListener::bind("127.0.0.1:0").expect("listener");
        let url = format!(
            "http://{}/doc-auto.md",
            listener.local_addr().expect("listener address")
        );
        let server = std::thread::spawn(move || {
            let (mut stream, _) = listener.accept().expect("accept");
            let request = read_http_request(&mut stream);
            assert!(request.starts_with("GET /doc-auto.md HTTP/1.1"));
            let body = "# Auto dataset\n\nThe external parser should create a DataMax dataset.";
            let response = format!(
                "HTTP/1.1 200 OK\r\nContent-Type: text/markdown\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                body.len(),
                body
            );
            stream.write_all(response.as_bytes()).expect("write");
        });

        let object_root =
            std::env::temp_dir().join(format!("aidp-v3-external-parse-auto-{}", Uuid::new_v4()));
        std::env::set_var("PLATFORM_LOCAL_OBJECT_ROOT", &object_root);
        let mut headers = HeaderMap::new();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer parse-token"),
        );
        let (status, Json(response)) = create_external_document_parse(
            State(state.clone()),
            headers,
            Path("generic-chat-main".to_string()),
            Json(CreateExternalDocumentParseRequest {
                source_id: String::new(),
                dataset_id: None,
                dataset_external_id: Some("third-party-main".to_string()),
                dataset_title: Some("Third-party Main Docs".to_string()),
                document_external_id: "doc-auto".to_string(),
                revision_external_id: None,
                title: Some("Auto dataset".to_string()),
                content_type: Some("text/markdown".to_string()),
                content_url: url,
                metadata: json!({"customer": "auto"}),
                idempotency_key: Some("parse-doc-auto".to_string()),
                allow_http_loopback: true,
            }),
        )
        .await
        .expect("external document parse should create a dataset");
        server.join().expect("server should finish");

        assert_eq!(status, StatusCode::ACCEPTED);
        assert_eq!(response.source_id, "src-auto-docs");
        assert_eq!(response.document_external_id, "doc-auto");
        let created_dataset = state
            .storage
            .datasets()
            .get_by_id(state.tenant_id, response.document.dataset_id)
            .await
            .expect("dataset lookup should succeed")
            .expect("dataset should be created");
        assert_eq!(
            created_dataset.key,
            "external-source-src-auto-docs-dataset-third-party-main"
        );
        assert_eq!(created_dataset.title, "Third-party Main Docs");
        assert_eq!(created_dataset.visibility, DatasetVisibility::Private);
        let owner_user_id = created_dataset
            .owner_user_id
            .expect("external parse dataset should belong to the third-party system user");
        let owner_user = state
            .storage
            .users()
            .get_by_id(state.tenant_id, owner_user_id)
            .await
            .expect("system owner lookup should succeed")
            .expect("system owner should exist");
        assert_eq!(
            owner_user.email,
            external_system_user_email("channel", "generic-chat-main")
        );
        assert_eq!(
            created_dataset
                .metadata
                .get("external_source")
                .and_then(Value::as_object)
                .and_then(|source| source.get("source_id"))
                .and_then(Value::as_str),
            Some("src-auto-docs")
        );

        let document = state
            .storage
            .documents()
            .get_by_id(state.tenant_id, response.document.id)
            .await
            .expect("document lookup should succeed")
            .expect("document should be created");
        assert_eq!(document.owner_user_id, created_dataset.owner_user_id);
        let external_source = document
            .metadata
            .get("external_source")
            .and_then(Value::as_object)
            .expect("document should retain external source metadata");
        assert_eq!(
            external_source
                .get("dataset_external_id")
                .and_then(Value::as_str),
            Some("third-party-main")
        );
        assert_eq!(
            external_source.get("dataset_key").and_then(Value::as_str),
            Some("external-source-src-auto-docs-dataset-third-party-main")
        );
        let claimed_legacy_document = state
            .storage
            .documents()
            .get_by_id(state.tenant_id, legacy_public_document.id)
            .await
            .expect("legacy public duplicate lookup should succeed")
            .expect("legacy public duplicate should remain");
        assert_eq!(claimed_legacy_document.owner_user_id, Some(owner_user_id));
        let claimed_legacy_dataset = state
            .storage
            .datasets()
            .get_by_id(state.tenant_id, legacy_public_dataset.id)
            .await
            .expect("legacy public dataset lookup should succeed")
            .expect("legacy public dataset should remain");
        assert_eq!(claimed_legacy_dataset.owner_user_id, Some(owner_user_id));
        assert_eq!(
            claimed_legacy_dataset.visibility,
            DatasetVisibility::Private
        );
        let dataset_resolution = document
            .metadata
            .get("external_document_parse")
            .and_then(Value::as_object)
            .and_then(|metadata| metadata.get("dataset_resolution"))
            .and_then(Value::as_object)
            .expect("document should describe dataset resolution");
        assert_eq!(
            dataset_resolution.get("mode").and_then(Value::as_str),
            Some("source_dataset_created")
        );
        assert_eq!(
            dataset_resolution
                .get("auto_created")
                .and_then(Value::as_bool),
            Some(true)
        );
        let Json(listed_datasets) = list_datasets(State(state.clone()), HeaderMap::new())
            .await
            .expect("standard dataset list should load");
        assert!(!listed_datasets
            .iter()
            .any(|dataset| dataset.id == created_dataset.id));
        assert!(!listed_datasets
            .iter()
            .any(|dataset| dataset.id == legacy_public_dataset.id));
        let Json(listed_documents) = list_documents(State(state.clone()), HeaderMap::new())
            .await
            .expect("standard document list should load");
        assert!(!listed_documents
            .iter()
            .any(|document| document.id == legacy_public_document.id));

        let source = load_external_source_connection(&state, "src-auto-docs")
            .await
            .expect("source should load");
        let resolved_again = resolve_external_document_parse_dataset(
            &state,
            &CreateExternalDocumentParseRequest {
                source_id: "src-auto-docs".to_string(),
                dataset_id: None,
                dataset_external_id: Some("third-party-main".to_string()),
                dataset_title: None,
                document_external_id: "doc-auto-2".to_string(),
                revision_external_id: None,
                title: None,
                content_type: None,
                content_url: "https://third-party.example/doc-auto-2.md".to_string(),
                metadata: json!({}),
                idempotency_key: None,
                allow_http_loopback: false,
            },
            &source,
            &[],
            Some(owner_user_id),
        )
        .await
        .expect("source dataset should be reused");
        assert_eq!(resolved_again.dataset.id, created_dataset.id);
        assert_eq!(resolved_again.resolution_mode, "source_dataset_reused");
    }

    #[tokio::test]
    async fn external_document_dataset_update_moves_document_by_external_id() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping external document dataset move test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("external-document-move-test-{}", Uuid::new_v4()),
                "External Document Move Test",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        sqlx::query(
            r#"
            insert into external_channel_connections (
                id, tenant_id, platform, connection_key, display_name, config_redacted, status
            )
            values ('generic-chat-main', $1, 'generic_chat', 'generic-chat-main', 'Generic Chat', $2, 'enabled')
            "#,
        )
        .bind(state.tenant_id.0)
        .bind(json!({
            "inbound_bearer_token": "move-token",
            "default_source_id": "src-move-docs"
        }))
        .execute(state.storage.pool())
        .await
        .expect("external channel connection should be inserted");
        sqlx::query(
            r#"
            insert into external_source_connections (
                id, tenant_id, connector_kind, source_key, display_name, base_url_redacted,
                config_redacted, sync_mode, permission_mode
            )
            values ('src-move-docs', $1, 'document', 'src-move-docs', 'Move Docs',
                    'https://docs.example/[redacted]', '{}', 'push', 'source_acl_snapshot')
            "#,
        )
        .bind(state.tenant_id.0)
        .execute(state.storage.pool())
        .await
        .expect("external source connection should be inserted");

        let old_dataset = state
            .storage
            .datasets()
            .create(
                state.tenant_id,
                NewDataset {
                    key: format!("external-move-old-{}", Uuid::new_v4()),
                    title: "Old Group".to_string(),
                    description: None,
                    owner_user_id: None,
                },
            )
            .await
            .expect("old dataset should be created");
        let document = state
            .storage
            .documents()
            .create(
                state.tenant_id,
                NewDocument {
                    dataset_id: old_dataset.id,
                    title: "Move me".to_string(),
                    object_key: "external/move-me.md".to_string(),
                    content_type: "text/markdown".to_string(),
                    secret_binding_ids: Vec::new(),
                    owner_user_id: None,
                    metadata: json!({
                        "external_source": {
                            "source_id": "src-move-docs",
                            "source_display_name": "Move Docs",
                            "dataset_id": old_dataset.id,
                            "dataset_key": old_dataset.key,
                            "dataset_external_id": "old-group",
                            "document_external_id": "doc-move",
                            "revision_external_id": "rev-1"
                        }
                    }),
                },
            )
            .await
            .expect("document should be created");

        let mut headers = HeaderMap::new();
        headers.insert(
            header::AUTHORIZATION,
            HeaderValue::from_static("Bearer move-token"),
        );
        let Json(response) = update_external_document_dataset(
            State(state.clone()),
            headers.clone(),
            Path(("generic-chat-main".to_string(), "doc-move".to_string())),
            Json(UpdateExternalDocumentDatasetRequest {
                source_id: String::new(),
                dataset_id: None,
                dataset_external_id: Some("new-group".to_string()),
                dataset_title: Some("New Group".to_string()),
                revision_external_id: Some("rev-1".to_string()),
            }),
        )
        .await
        .expect("document dataset update should succeed");

        assert!(response.accepted);
        assert_eq!(response.source_id, "src-move-docs");
        assert_eq!(response.document_external_id, "doc-move");
        assert_eq!(response.revision_external_id.as_deref(), Some("rev-1"));
        assert_eq!(response.dataset_external_id.as_deref(), Some("new-group"));
        assert_eq!(response.moved_count, 1);
        assert_eq!(response.previous_dataset_ids, vec![old_dataset.id]);
        assert_eq!(response.documents[0].id, document.id);
        assert_eq!(response.documents[0].dataset_id, response.dataset_id);

        let moved_document = state
            .storage
            .documents()
            .get_by_id(state.tenant_id, document.id)
            .await
            .expect("document lookup should succeed")
            .expect("document should exist");
        assert_eq!(moved_document.dataset_id, response.dataset_id);
        let external_source = moved_document
            .metadata
            .get("external_source")
            .and_then(Value::as_object)
            .expect("external source metadata should be updated");
        assert_eq!(
            external_source
                .get("dataset_external_id")
                .and_then(Value::as_str),
            Some("new-group")
        );
        assert_eq!(
            external_source
                .get("previous_dataset_external_id")
                .and_then(Value::as_str),
            Some("old-group")
        );
        assert_eq!(
            external_source.get("dataset_key").and_then(Value::as_str),
            Some("external-source-src-move-docs-dataset-new-group")
        );

        let Json(detail) = get_external_document_parse_detail(
            State(state.clone()),
            headers,
            Path(("generic-chat-main".to_string(), "doc-move".to_string())),
            Query(BTreeMap::from([(
                "source_id".to_string(),
                "src-move-docs".to_string(),
            )])),
        )
        .await
        .expect("parse detail should still find moved document");
        assert_eq!(detail.latest.unwrap().dataset_id, response.dataset_id);
    }

    #[tokio::test]
    async fn assistant_run_ioa_supply_smoke_surfaces_expected_document_section() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        std::env::set_var("ASSISTANT_RUN_RUNTIME_MODE", "placeholder");
        std::env::remove_var("ASSISTANT_RUN_EVIDENCE_LIMIT");
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping assistant run IOA supply smoke: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("assistant-ioa-supply-smoke-{}", Uuid::new_v4()),
                "Assistant IOA Supply Smoke",
            )
            .await
            .expect("tenant should exist");
        let state = AppState::new(
            storage,
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        let dataset = state
            .storage
            .datasets()
            .create(
                state.tenant_id,
                NewDataset {
                    key: format!("xinshijie-ioa-supply-smoke-{}", Uuid::new_v4()),
                    title: "新世界 IOA 问答测试集".to_string(),
                    description: Some(
                        "用于验证 IOA 问答切片、段落标题和助手供料链路。".to_string(),
                    ),
                    owner_user_id: None,
                },
            )
            .await
            .expect("dataset should be created");

        let now = Utc::now();
        let fixtures = [
            (
                "用户手册3-固定资产",
                "documents/xinshijie/ioa/user-manual-3-fixed-asset.md",
                "提交固定资产申请单后，部门负责人审批，行政登记资产编号。",
                "固定资产申请",
            ),
            (
                "IOA系统Q&A",
                "documents/xinshijie/ioa/system-qa.md",
                "账号被锁定时先在登录页重置密码，再联系管理员确认账号状态。",
                "账号登录问题",
            ),
            (
                "iOA应用技巧",
                "documents/xinshijie/ioa/tips.md",
                "首页工作台可以查看待办、已办、抄送和常用应用入口。",
                "待办入口",
            ),
            (
                "行政制度汇编",
                "documents/xinshijie/admin/policy.md",
                "资产盘点和办公用品领用记录由行政定期复核。",
                "资产盘点",
            ),
        ];
        let mut fixed_asset_document_id = None;
        let mut fixed_asset_chunk_id = None;
        for (index, (title, object_key, content, section_title)) in fixtures.into_iter().enumerate()
        {
            let document = state
                .storage
                .documents()
                .create(
                    state.tenant_id,
                    NewDocument {
                        dataset_id: dataset.id,
                        title: title.to_string(),
                        object_key: object_key.to_string(),
                        content_type: "text/markdown".to_string(),
                        secret_binding_ids: Vec::new(),
                        owner_user_id: None,
                        metadata: json!({}),
                    },
                )
                .await
                .expect("IOA smoke document should be created");
            let chunks = state
                .storage
                .document_chunks()
                .replace_for_document(
                    state.tenant_id,
                    document.id,
                    &[storage::NewDocumentChunk {
                        dataset_id: dataset.id,
                        document_id: document.id,
                        chunk_index: index as i32,
                        content: content.to_string(),
                        token_count: 24,
                        metadata: json!({"section_title_hints": [section_title]}),
                        created_at: now,
                    }],
                )
                .await
                .expect("IOA smoke document chunk should be created");
            if index == 0 {
                fixed_asset_document_id = Some(document.id);
                fixed_asset_chunk_id = Some(chunks[0].id);
            }
        }
        let fixed_asset_document_id =
            fixed_asset_document_id.expect("fixed asset document should be tracked");
        let fixed_asset_chunk_id =
            fixed_asset_chunk_id.expect("fixed asset chunk should be tracked");

        let (status, Json(response)) = create_assistant_run(
            State(state.clone()),
            HeaderMap::new(),
            Json(CreateAssistantRunRequest {
                prompt: "固定资产申请怎么提交，需要走什么流程".to_string(),
                local_thread_id: Some("assistant-ioa-rag-smoke-thread".to_string()),
                startup_briefing: Some(json!({"visibleDatasetCount": 1})),
                selected_scope: Some(json!({
                    "mode": "user_selected",
                    "intent": "data_question",
                    "datasets": [dataset.id],
                    "supply_policy": {
                        "retrievalPolicy": "standard",
                        "preferDetail": false
                    }
                })),
                scope_candidates: Vec::new(),
                context_policy_hint: None,
                current_artifact: None,
                messages: Vec::new(),
            }),
        )
        .await
        .expect("assistant run should be created");

        assert_eq!(status, StatusCode::CREATED);
        assert_eq!(response.evidence_state["status"], json!("supplied"));
        assert_eq!(response.evidence_state["fallback_supply_count"], json!(4));
        assert_eq!(
            response.evidence_state["supply_quality"]["fallbackChunkCount"],
            json!(4)
        );
        let supplied_items = response.evidence_state["supplied_items"]
            .as_array()
            .expect("supplied items should be present");
        assert_eq!(supplied_items.len(), 4);
        let first_item = &supplied_items[0];
        assert_eq!(first_item["source"], json!("document_chunk_fallback"));
        assert_eq!(first_item["document_id"], json!(fixed_asset_document_id));
        assert_eq!(first_item["document_chunk_id"], json!(fixed_asset_chunk_id));
        assert_eq!(
            first_item["evidence_manifest"]["evidence"]["section_title_hints"],
            json!(["固定资产申请"])
        );
        assert!(first_item["summary"]
            .as_str()
            .unwrap_or_default()
            .contains("固定资产申请"));
        assert!(first_item["content_excerpt"]
            .as_str()
            .unwrap_or_default()
            .contains("提交固定资产申请单"));
        assert_eq!(
            response.evidence_state["detail_targets"][0]["document_id"],
            json!(fixed_asset_document_id)
        );
        assert_eq!(
            response.evidence_state["detail_targets"][0]["document_chunk_id"],
            json!(fixed_asset_chunk_id)
        );
    }

    fn test_dataset(
        visibility: DatasetVisibility,
        secret_binding_ids: Vec<SecretBindingId>,
    ) -> Dataset {
        Dataset {
            id: DatasetId::new(),
            tenant_id: TenantId::new(),
            owner_user_id: None,
            key: format!("dataset-{}", Uuid::new_v4()),
            title: "Dataset Visibility Test".to_string(),
            description: None,
            lifecycle: DatasetLifecycle::Active,
            visibility,
            default_secret_binding_ids: secret_binding_ids,
            metadata: BTreeMap::new(),
            created_at: Utc::now(),
            updated_at: Utc::now(),
        }
    }

    #[test]
    fn dataset_visibility_allows_public_without_secret() {
        let dataset = test_dataset(DatasetVisibility::Public, Vec::new());

        assert!(dataset_is_visible(&dataset, &[], None));
    }

    #[test]
    fn dataset_visibility_restricts_owned_public_dataset_to_owner() {
        let owner_user_id = UserId::new();
        let mut dataset = test_dataset(DatasetVisibility::Public, Vec::new());
        dataset.owner_user_id = Some(owner_user_id);

        assert!(dataset_is_visible(&dataset, &[], Some(owner_user_id)));
        assert!(!dataset_is_visible(&dataset, &[], Some(UserId::new())));
        assert!(!dataset_is_visible(&dataset, &[], None));
    }

    #[test]
    fn dataset_visibility_hides_private_without_matching_secret() {
        let secret_binding_id = SecretBindingId::new();
        let dataset = test_dataset(DatasetVisibility::Private, vec![secret_binding_id]);

        assert!(!dataset_is_visible(&dataset, &[], None));
        assert!(!dataset_is_visible(
            &dataset,
            &[SecretBindingId::new()],
            None
        ));
        assert!(dataset_is_visible(&dataset, &[secret_binding_id], None));
    }

