    #[test]
    fn static_page_dataset_list_can_show_public_template_baseline_without_owner() {
        let owner_user_id = UserId::new();
        let mut draft = StaticPageDraft {
            id: StaticPageDraftId::new(),
            tenant_id: TenantId::new(),
            assistant_run_id: AssistantRunId::new(),
            owner_user_id: Some(owner_user_id),
            title: "静态页：新百经营分析月报".to_string(),
            status: StaticPageDraftStatus::Rendered,
            selected_scope: json!({}),
            visibility_snapshot: json!({}),
            source_refs: json!({
                "artifact_stability": {
                    "baseline_status": "accepted",
                    "dataset_artifact_key": "v3-static-page|template:generated-static-page:fixture|dataset_external_id:xinbai-project-dataset"
                }
            }),
            draft_payload: json!({
                "finalPage": {
                    "status": "rendered",
                    "publicUrl": "https://v3.elepcloud.com/generated-artifacts/database-static-pages/xinbai/current/index.html"
                }
            }),
            created_at: Utc::now(),
            updated_at: Utc::now(),
        };

        assert!(!static_page_owner_is_visible(draft.owner_user_id, None));
        assert!(!static_page_draft_list_item_is_visible(&draft, None, false));
        assert!(static_page_draft_list_item_is_visible(&draft, None, true));

        draft.source_refs = json!({
            "artifact_stability": {
                "baseline_status": "accepted",
                "dataset_artifact_key": "v3-static-page|template:data-report|dataset_id:xinbai-operating-analysis"
            }
        });
        assert!(!static_page_public_template_baseline_is_visible(&draft));

        let retire_request = UpdateStaticPageDraftRequest {
            source_refs: Some(json!({
                "artifact_stability": {
                    "baseline_status": "retired"
                }
            })),
            ..Default::default()
        };
        assert!(static_page_public_template_update_is_safe(&retire_request));

        let dataset_default_request = UpdateStaticPageDraftRequest {
            source_refs: Some(json!({
                "artifact_stability": {
                    "baseline_status": "accepted",
                    "report_shelf_defaults": {
                        "31588c60-0885-47c4-81fe-4ff5c27de8e7": true
                    }
                }
            })),
            ..Default::default()
        };
        assert!(static_page_public_template_default_update_is_safe(
            &dataset_default_request
        ));
        let merged_source_refs = merge_public_template_default_source_refs(
            json!({
                "artifact_stability": {
                    "baseline_status": "retired",
                    "dataset_artifact_key": "v3-static-page|template:generated-static-page:fixture|dataset_external_id:xinbai-project-dataset"
                },
                "local_thread_id": "thread-1"
            }),
            dataset_default_request.source_refs.as_ref().unwrap(),
        );
        assert_eq!(
            merged_source_refs.pointer("/artifact_stability/baseline_status"),
            Some(&json!("accepted"))
        );
        assert_eq!(
            merged_source_refs.pointer(
                "/artifact_stability/report_shelf_defaults/31588c60-0885-47c4-81fe-4ff5c27de8e7"
            ),
            Some(&json!(true))
        );

        let unsafe_title_request = UpdateStaticPageDraftRequest {
            title: Some("随意改公开模板".to_string()),
            source_refs: Some(json!({
                "artifact_stability": {
                    "baseline_status": "retired"
                }
            })),
            ..Default::default()
        };
        assert!(!static_page_public_template_update_is_safe(
            &unsafe_title_request
        ));
    }

