    async fn issue_email_session_cookie(harness: &AuthApiTestHarness, email: &str) -> String {
        let prepared = auth_otp_service_for_test().prepare_challenge(
            email,
            AuthChallengePurpose::Login,
            Utc::now(),
        );
        harness
            .storage
            .email_verification_challenges()
            .create(harness.tenant_id, prepared.challenge)
            .await
            .expect("verification challenge should persist");

        let response = post_json_request(
            harness.app.clone(),
            "/v1/auth/email/verify",
            &VerifyEmailAuthRequest {
                email: email.to_string(),
                code: prepared.email.code,
                purpose: AuthChallengePurpose::Login,
                device_fingerprint: Some("test-browser".to_string()),
            },
            None,
        )
        .await;
        assert_eq!(response.status(), StatusCode::CREATED);
        cookie_pair_from_set_cookie(&response)
    }

    #[tokio::test]
    async fn gateway_limiter_rejects_when_lane_queue_is_full() {
        let limiter =
            GatewayRuntimeLimiter::for_test().with_lane_limit(MODEL_LANE_ASSISTANT_CHAT, 1, 0);

        let first = limiter
            .acquire_lane(MODEL_LANE_ASSISTANT_CHAT)
            .await
            .expect("first lane permit should be granted");
        let second = limiter.acquire_lane(MODEL_LANE_ASSISTANT_CHAT).await;

        assert!(matches!(second, Err(GatewayLimitError::QueueFull)));
        drop(first);
        assert!(limiter
            .acquire_lane(MODEL_LANE_ASSISTANT_CHAT)
            .await
            .is_ok());
    }

    #[test]
    fn gateway_limiter_skips_provider_during_circuit_breaker_cooldown() {
        let limiter = GatewayRuntimeLimiter::for_test()
            .with_profile_limit("openclaw-main", 1, 0)
            .with_circuit_breaker(2, StdDuration::from_secs(60));

        assert!(limiter.provider_available("openclaw-main").is_some());
        limiter.record_provider_failure("openclaw-main", "direct_reply_attempt_timeout");
        assert!(limiter.provider_available("openclaw-main").is_some());
        limiter.record_provider_failure("openclaw-main", "provider_error:429:rate_limit");

        assert!(limiter.provider_available("openclaw-main").is_none());
        let stats = limiter.provider_stats_snapshot("openclaw-main");
        assert!(stats.circuit_open);
        assert_eq!(stats.failure_count, 2);
        assert_eq!(stats.timeout_count, 1);
        assert_eq!(stats.rate_limit_count, 1);

        limiter.record_provider_success("openclaw-main", Some(42));
        let stats = limiter
            .provider_available("openclaw-main")
            .expect("success should close circuit");
        assert!(!stats.circuit_open);
        assert_eq!(stats.consecutive_failures, 0);
        assert_eq!(stats.success_count, 1);
        assert_eq!(stats.p50_latency_ms, Some(42));
    }

    #[test]
    fn gateway_limiter_enforces_profile_rpm_and_tpm_windows() {
        let limiter = GatewayRuntimeLimiter::for_test().with_profile_rate_limit(
            "limited-profile",
            Some(1),
            Some(10),
        );

        let first = limiter
            .reserve_profile_rate_budget("limited-profile", 4)
            .expect("first request should fit");
        limiter.record_profile_actual_token_usage(&first, 8);
        let snapshot = limiter.profile_rate_snapshot("limited-profile");
        assert_eq!(snapshot.request_count, 1);
        assert_eq!(snapshot.token_count, 8);

        assert!(matches!(
            limiter.would_throttle_lane_and_profile(
                MODEL_LANE_ASSISTANT_CHAT,
                "limited-profile",
                1
            ),
            Some(GatewayLimitError::RequestRateLimit)
        ));

        assert!(matches!(
            limiter.reserve_profile_rate_budget("limited-profile", 1),
            Err(GatewayLimitError::RequestRateLimit)
        ));

        let token_limiter = GatewayRuntimeLimiter::for_test().with_profile_rate_limit(
            "token-limited-profile",
            None,
            Some(5),
        );
        assert!(matches!(
            token_limiter.reserve_profile_rate_budget("token-limited-profile", 6),
            Err(GatewayLimitError::TokenRateLimit)
        ));
    }

