    #[tokio::test]
    async fn claim_local_data_assigns_unowned_private_dataset_to_session_user() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let Some(harness) = build_auth_api_test_harness().await else {
            return;
        };
        let fingerprint = "claim-local-fingerprint";
        let response = post_json_request(
            harness.app.clone(),
            "/v1/datasets",
            &CreateDatasetRequest {
                key: format!("claim-local-{}", Uuid::new_v4()),
                title: "Claim Local Dataset".to_string(),
                description: None,
                visibility: None,
                local_only: false,
                local_thread_id: None,
                secret_binding_ids: Vec::new(),
                secret_fingerprint: Some(fingerprint.to_string()),
                secret_label: Some("local-test".to_string()),
            },
            None,
        )
        .await;
        assert_eq!(response.status(), StatusCode::CREATED);
        let created: DatasetSummary = read_json_response(response).await;
        assert_eq!(created.visibility, DatasetVisibility::Private);

        let response = get_request(harness.app.clone(), "/v1/datasets", None).await;
        let anonymous_datasets: Vec<DatasetSummary> = read_json_response(response).await;
        assert!(!anonymous_datasets
            .iter()
            .any(|dataset| dataset.id == created.id));

        let owner_cookie = issue_email_session_cookie(&harness, "claim-owner@example.com").await;
        let response = post_json_request(
            harness.app.clone(),
            "/v1/auth/claim-local-data",
            &ClaimLocalDataRequest {
                fingerprint: fingerprint.to_string(),
            },
            Some(&owner_cookie),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        let claim: ClaimLocalDataResponse = read_json_response(response).await;
        assert_eq!(claim.claimed_datasets.len(), 1);
        assert_eq!(claim.claimed_datasets[0].id, created.id);
        assert_eq!(claim.active_secret_binding_ids, created.secret_binding_ids);
        assert_eq!(claim.skipped_owned_dataset_count, 0);

        let response = get_request(harness.app.clone(), "/v1/datasets", Some(&owner_cookie)).await;
        let owner_datasets: Vec<DatasetSummary> = read_json_response(response).await;
        assert!(owner_datasets
            .iter()
            .any(|dataset| dataset.id == created.id));

        let other_cookie = issue_email_session_cookie(&harness, "claim-other@example.com").await;
        let response = get_request(harness.app.clone(), "/v1/datasets", Some(&other_cookie)).await;
        let other_datasets: Vec<DatasetSummary> = read_json_response(response).await;
        assert!(!other_datasets
            .iter()
            .any(|dataset| dataset.id == created.id));
    }

    #[tokio::test]
    async fn register_document_records_local_content_fingerprint() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let Some(harness) = build_auth_api_test_harness().await else {
            return;
        };
        let dataset = harness
            .storage
            .datasets()
            .create_with_metadata(
                harness.tenant_id,
                NewDataset {
                    key: format!("fingerprint-upload-{}", Uuid::new_v4()),
                    title: "Fingerprint Upload Dataset".to_string(),
                    description: None,
                    owner_user_id: None,
                },
                json!({
                    "visibility": "public",
                    "default_secret_binding_ids": []
                }),
            )
            .await
            .expect("dataset should be created");
        let body = b"DataMax local document fingerprint fixture\n";
        let object_root =
            std::env::temp_dir().join(format!("datamax-register-fingerprint-{}", Uuid::new_v4()));
        fs::create_dir_all(&object_root).expect("temp object root should be created");
        let object_path = object_root.join("fixture.md");
        fs::write(&object_path, body).expect("fixture file should be written");
        let expected_sha256 = sha256_hex([&body[..]]);

        let response = post_json_request(
            harness.app.clone(),
            "/v1/documents",
            &RegisterDocumentRequest {
                dataset_id: dataset.id,
                title: "Fingerprint fixture".to_string(),
                object_key: object_path.to_string_lossy().to_string(),
                content_type: "text/markdown".to_string(),
                secret_binding_ids: Vec::new(),
                metadata: json!({}),
            },
            None,
        )
        .await;
        assert_eq!(response.status(), StatusCode::CREATED);
        let registered: RegisterDocumentResponse = read_json_response(response).await;

        let fingerprint_row = sqlx::query(
            r#"
            select content_sha256, content_size_bytes, canonical_document_id, dedup_state
            from documents
            where tenant_id = $1 and id = $2
            "#,
        )
        .bind(harness.tenant_id.0)
        .bind(registered.document.id.0)
        .fetch_one(harness.storage.pool())
        .await
        .expect("document fingerprint fields should load");
        assert_eq!(
            fingerprint_row.get::<Option<String>, _>("content_sha256"),
            Some(expected_sha256.clone())
        );
        assert_eq!(
            fingerprint_row.get::<Option<i64>, _>("content_size_bytes"),
            Some(body.len() as i64)
        );
        assert_eq!(
            fingerprint_row.get::<Option<Uuid>, _>("canonical_document_id"),
            Some(registered.document.id.0)
        );
        assert_eq!(
            fingerprint_row.get::<Option<String>, _>("dedup_state"),
            Some("canonical".to_string())
        );

        let canonical_document_id = sqlx::query_scalar::<_, Uuid>(
            r#"
            select canonical_document_id
            from document_content_fingerprints
            where tenant_id = $1 and content_sha256 = $2
            "#,
        )
        .bind(harness.tenant_id.0)
        .bind(&expected_sha256)
        .fetch_one(harness.storage.pool())
        .await
        .expect("content fingerprint should be recorded");
        assert_eq!(canonical_document_id, registered.document.id.0);
    }

