    #[tokio::test]
    async fn document_dataset_membership_endpoints_allow_main_site_public_document_moves() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping document dataset membership endpoint test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("membership-endpoint-test-{}", Uuid::new_v4()),
                "Membership Endpoint Test",
            )
            .await
            .expect("tenant should exist");
        let canonical_dataset = storage
            .datasets()
            .create(
                tenant.id,
                NewDataset {
                    key: format!("membership-canonical-{}", Uuid::new_v4()),
                    title: "Membership Canonical".to_string(),
                    description: None,
                    owner_user_id: None,
                },
            )
            .await
            .expect("canonical dataset should be created");
        let secondary_dataset = storage
            .datasets()
            .create(
                tenant.id,
                NewDataset {
                    key: format!("membership-secondary-{}", Uuid::new_v4()),
                    title: "Membership Secondary".to_string(),
                    description: None,
                    owner_user_id: None,
                },
            )
            .await
            .expect("secondary dataset should be created");
        let document = storage
            .documents()
            .create(
                tenant.id,
                NewDocument {
                    dataset_id: canonical_dataset.id,
                    title: "Membership Editable Document".to_string(),
                    object_key: "documents/membership-editable.md".to_string(),
                    content_type: "text/markdown".to_string(),
                    secret_binding_ids: Vec::new(),
                    owner_user_id: None,
                    metadata: json!({}),
                },
            )
            .await
            .expect("document should be created");
        let state = AppState::new(
            storage.clone(),
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );

        let Json(added) = add_document_dataset_membership(
            State(state.clone()),
            HeaderMap::new(),
            Path((document.id.to_string(), secondary_dataset.id.to_string())),
        )
        .await
        .expect("public document should join a second public dataset");
        assert_eq!(
            added.dataset_ids,
            vec![canonical_dataset.id, secondary_dataset.id]
        );

        let Json(removed_secondary) = remove_document_dataset_membership(
            State(state.clone()),
            HeaderMap::new(),
            Path((document.id.to_string(), secondary_dataset.id.to_string())),
        )
        .await
        .expect("public document should leave the secondary dataset");
        assert_eq!(removed_secondary.dataset_ids, vec![canonical_dataset.id]);

        let _ = add_document_dataset_membership(
            State(state.clone()),
            HeaderMap::new(),
            Path((document.id.to_string(), secondary_dataset.id.to_string())),
        )
        .await
        .expect("public document should rejoin the secondary dataset");
        let Json(promoted) = remove_document_dataset_membership(
            State(state.clone()),
            HeaderMap::new(),
            Path((document.id.to_string(), canonical_dataset.id.to_string())),
        )
        .await
        .expect("public document should leave its canonical dataset when another dataset remains");
        assert_eq!(promoted.canonical_dataset_id, secondary_dataset.id);
        assert_eq!(promoted.dataset_ids, vec![secondary_dataset.id]);
    }

    #[tokio::test]
    async fn request_workflow_retry_restarts_failed_execution_and_enqueues_task() {
        let _guard = shared_local_postgres_test_lock().lock().await;
        let storage = match local_postgres_storage().await {
            Ok(storage) => storage,
            Err(reason) => {
                eprintln!("skipping request_workflow_retry test: {reason}");
                return;
            }
        };
        reset_and_sync_test_storage(&storage).await;

        let tenant = storage
            .ensure_tenant(
                &format!("platform-api-test-{}", Uuid::new_v4()),
                "Platform API Test",
            )
            .await
            .expect("tenant should exist");
        let dataset = storage
            .datasets()
            .create(
                tenant.id,
                NewDataset {
                    key: format!("dataset-{}", Uuid::new_v4()),
                    title: "Retry Workflow Dataset".to_string(),
                    description: Some(
                        "Dataset used for workflow retry host-surface tests.".to_string(),
                    ),
                    owner_user_id: None,
                },
            )
            .await
            .expect("dataset should be created");
        let state = AppState::new(
            storage.clone(),
            workflow_definitions::catalog(),
            tenant.id,
            EventBus::Disabled,
        );
        let execution = build_initial_memory_directory_execution(&state, dataset.id, None)
            .expect("initial memory directory execution should build");
        storage
            .workflow_executions()
            .create(&execution)
            .await
            .expect("workflow execution should be created");

        let started = apply_workflow_signal(&state, execution.id, WorkflowSignal::Start)
            .await
            .expect("workflow should start");
        let failed = apply_workflow_signal(
            &state,
            execution.id,
            WorkflowSignal::StepFailed {
                task_key: started.enqueued_tasks[0].task_key.clone(),
                error: "transient worker error".to_string(),
            },
        )
        .await
        .expect("workflow should fail");
        assert_eq!(failed.execution.status, WorkflowStatus::Failed);

        let response = request_workflow_retry(
            storage.clone(),
            tenant.id,
            execution.id,
            RetryWorkflowExecutionRequest {
                reason: "retry after transient worker error".to_string(),
            },
        )
        .await
        .expect("workflow retry should succeed");

        assert_eq!(
            response.retry_transition.persisted_event.event_name,
            "workflow.retry_requested"
        );
        assert_eq!(
            response.retry_transition.execution.status,
            WorkflowStatus::Pending
        );
        assert_eq!(response.retry_transition.execution.stage, "queued");
        assert!(response.retry_transition.enqueued_tasks.is_empty());

        let restart = response
            .restart_transition
            .expect("retry should automatically restart the workflow");
        assert_eq!(restart.persisted_event.event_name, "workflow.started");
        assert_eq!(restart.execution.status, WorkflowStatus::Running);
        assert_eq!(restart.enqueued_tasks.len(), 1);

        let persisted_execution = storage
            .workflow_executions()
            .get_by_id(tenant.id, execution.id)
            .await
            .expect("workflow execution should load")
            .expect("workflow execution should exist");
        assert_eq!(persisted_execution.status, WorkflowStatus::Running);
        assert_eq!(persisted_execution.attempt, 2);
        assert_eq!(persisted_execution.context["retries_remaining"], json!(2));
        assert_eq!(
            persisted_execution.context["retry_reason"],
            json!("retry after transient worker error")
        );
    }

    #[tokio::test]
    async fn publish_workflow_transition_events_emits_execution_and_task_notifications() {
        let now = Utc::now();
        let event_bus = EventBus::in_memory();
        let execution = WorkflowExecution {
            id: WorkflowExecutionId::new(),
            tenant_id: TenantId::new(),
            dataset_id: Some(DatasetId::new()),
            report_plan_id: Some(ReportPlanId::new()),
            kind: WorkflowKind::ReportPlan,
            version: "0.1.0".to_string(),
            stage: "plan_report_ast".to_string(),
            status: WorkflowStatus::Running,
            attempt: 1,
            context: json!({}),
            created_at: now,
            updated_at: now,
        };
        let persisted_event = WorkflowEventRecord {
            id: domain_model::WorkflowEventId::new(),
            execution_id: execution.id,
            sequence_no: 2,
            event_name: "workflow.started".to_string(),
            payload: json!({ "task_key": "plan_report_ast" }),
            created_at: now,
        };
        let task = WorkflowTask {
            id: domain_model::WorkflowTaskId::new(),
            tenant_id: execution.tenant_id,
            execution_id: execution.id,
            queue: "report".to_string(),
            task_key: "plan_report_ast".to_string(),
            payload: json!({ "execution_id": execution.id }),
            status: domain_model::WorkflowTaskStatus::Queued,
            attempt: 0,
            max_attempts: 3,
            available_at: now,
            claimed_at: None,
            finished_at: None,
            error: None,
            created_at: now,
            updated_at: now,
        };

        publish_workflow_transition_events(
            &event_bus,
            &execution,
            &persisted_event,
            std::slice::from_ref(&task),
        )
        .await;

        let published = event_bus.published_events();
        assert_eq!(published.len(), 2);
        assert_eq!(
            published[0].subject,
            workflow_execution_transition_subject(execution.kind.as_str())
        );
        assert_eq!(
            published[0].payload["event_name"],
            json!("workflow.started")
        );
        assert_eq!(
            published[1].subject,
            workflow_task_enqueued_subject("report", "plan_report_ast")
        );
        assert_eq!(published[1].payload["task_id"], json!(task.id));
    }

